if (-not ('PowerClipImageEditor' -as [type])) {
    Add-Type -ReferencedAssemblies System.Windows.Forms, System.Drawing, System.Core -TypeDefinition @'
using System;
using System.Collections.Generic;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.Drawing.Imaging;
using System.Drawing.Text;
using System.Linq;
using System.Runtime.InteropServices;
using System.Windows.Forms;

// One drawn thing. Shapes stay editable (select, move, resize, restyle, delete) until the image is saved.
public class EdShape {
    public string Kind;                  // arrow darrow line rect ellipse highlight pen text step spotlight magnify callout
    public Point A, B;                   // endpoints or opposite corners (image pixels)
    public Point P;                      // magnify: bubble centre; callout: tail tip
    public List<Point> Pts = new List<Point>();
    public Color Ink;
    public float Width = 4, TextSize = 28;
    public bool Filled, Dashed;
    public string Text = "";
    public int Number;

    public EdShape Clone() {
        var s = (EdShape)MemberwiseClone();
        s.Pts = new List<Point>(Pts);
        return s;
    }

    public Rectangle Box { get { return Rectangle.FromLTRB(Math.Min(A.X, B.X), Math.Min(A.Y, B.Y), Math.Max(A.X, B.X), Math.Max(A.Y, B.Y)); } }
    public bool IsLine { get { return Kind == "arrow" || Kind == "darrow" || Kind == "line"; } }
    public bool IsBox { get { return Kind == "rect" || Kind == "ellipse" || Kind == "highlight" || Kind == "spotlight" || Kind == "magnify" || Kind == "callout"; } }

    public void Offset(int dx, int dy) {
        A.Offset(dx, dy); B.Offset(dx, dy); P.Offset(dx, dy);
        for (int i = 0; i < Pts.Count; i++) Pts[i] = new Point(Pts[i].X + dx, Pts[i].Y + dy);
    }
}

public class PowerClipImageEditor : Control {
    public Bitmap Image;                         // the picture under the shapes
    public List<EdShape> Shapes = new List<EdShape>();
    public EdShape SelectedShape;
    public string Tool = "arrow";
    public Color Ink = Color.FromArgb(232, 17, 35);
    public float Thickness = 4f;
    public float TextSize = 28f;
    public bool Filled, Dashed;
    public bool Fit = true;
    public float Zoom = 1f;
    public int StepNumber = 1;
    public Rectangle Selection = Rectangle.Empty;     // image area (select / crop marquee)
    public Point Pointer = new Point(-1, -1);
    public event EventHandler Changed;               // picture or shapes changed
    public event EventHandler ViewChanged;           // zoom / pointer / marquee
    public event EventHandler SelectionChanged;      // a shape got (de)selected
    public event EventHandler InkPicked;             // eyedropper took a colour

    class State { public Bitmap Image; public List<EdShape> Shapes; }
    readonly List<State> undo = new List<State>();
    readonly List<State> redo = new List<State>();
    string coalesceKey; DateTime coalesceAt;

    // mouse state
    string mode = "";            // draw, move, handle, marquee
    int handle = -1;
    Point downImg, lastImg;
    EdShape drawing;
    State before;
    EdShape original;            // shape as it was when a move / resize started
    TextBox textBox; EdShape editing; bool editingIsNew;
    ColorMatrix preview;         // brightness / contrast preview

    public PowerClipImageEditor() {
        SetStyle(ControlStyles.AllPaintingInWmPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.UserPaint | ControlStyles.ResizeRedraw | ControlStyles.Selectable, true);
        TabStop = true;
        Cursor = Cursors.Cross;
    }

    void Raise(EventHandler h) { if (h != null) h(this, EventArgs.Empty); }

    // ---- image and history ----------------------------------------------------------------------
    public void SetImage(Image img) {
        CommitText();
        Image = ToArgb(img);
        Shapes.Clear(); SelectedShape = null;
        undo.Clear(); redo.Clear();
        Selection = Rectangle.Empty; StepNumber = 1;
        UpdateSize();
        Raise(Changed); Raise(SelectionChanged);
    }

    static Bitmap ToArgb(Image img) {
        var b = new Bitmap(img.Width, img.Height, PixelFormat.Format32bppArgb);
        using (var g = Graphics.FromImage(b)) g.DrawImage(img, 0, 0, img.Width, img.Height);
        return b;
    }

    State Snapshot() { return new State { Image = Image, Shapes = Shapes.Select(s => s.Clone()).ToList() }; }

    void Restore(State s) {
        Image = s.Image;
        Shapes = s.Shapes.Select(x => x.Clone()).ToList();
        SelectedShape = null; Selection = Rectangle.Empty;
        UpdateSize(); Raise(Changed); Raise(SelectionChanged);
    }

    void Commit(State prev) {
        undo.Add(prev);
        if (undo.Count > 60) undo.RemoveAt(0);
        redo.Clear();
        coalesceKey = null;
        Raise(Changed);
    }

    // Many small changes in a row (e.g. dragging the size slider) become one undo step.
    void CommitCoalesced(State prev, string key) {
        if (key != null && key == coalesceKey && (DateTime.Now - coalesceAt).TotalSeconds < 1.5) { coalesceAt = DateTime.Now; Raise(Changed); return; }
        Commit(prev);
        coalesceKey = key; coalesceAt = DateTime.Now;
    }

    public bool CanUndo { get { return undo.Count > 0; } }
    public bool CanRedo { get { return redo.Count > 0; } }
    public void Undo() { CommitText(); if (undo.Count == 0) return; redo.Add(Snapshot()); var s = undo[undo.Count - 1]; undo.RemoveAt(undo.Count - 1); coalesceKey = null; Restore(s); }
    public void Redo() { CommitText(); if (redo.Count == 0) return; undo.Add(Snapshot()); var s = redo[redo.Count - 1]; redo.RemoveAt(redo.Count - 1); coalesceKey = null; Restore(s); }

    // ---- composite ---------------------------------------------------------------------------------
    public Bitmap Render() {
        var b = (Bitmap)Image.Clone();
        using (var g = Graphics.FromImage(b)) { Prep(g); foreach (var s in Ordered()) DrawShape(g, s, Image); }
        return b;
    }

    // Spotlights dim the picture, not the drawings, so they are drawn first.
    IEnumerable<EdShape> Ordered() { return Shapes.Where(x => x.Kind == "spotlight").Concat(Shapes.Where(x => x.Kind != "spotlight"));
    }
    public Bitmap Result() { CommitText(); return Render(); }

    // Burns the shapes into the picture (needed before rotate / flip / resize).
    void Flatten() { if (Shapes.Count == 0) return; Image = Render(); Shapes.Clear(); SelectedShape = null; }

    static void Prep(Graphics g) { g.SmoothingMode = SmoothingMode.AntiAlias; g.TextRenderingHint = TextRenderingHint.AntiAliasGridFit; g.PixelOffsetMode = PixelOffsetMode.HighQuality; }

    // ---- whole-picture operations -------------------------------------------------------------------
    public bool Crop() {
        CommitText();
        Rectangle r = Rectangle.Intersect(Selection, new Rectangle(0, 0, Image.Width, Image.Height));
        if (r.Width < 2 || r.Height < 2) return false;
        var prev = Snapshot();
        Image = Image.Clone(r, PixelFormat.Format32bppArgb);
        foreach (var s in Shapes) s.Offset(-r.X, -r.Y);
        Selection = Rectangle.Empty;
        UpdateSize(); Commit(prev);
        return true;
    }

    // Cuts away a plain border (the colour of the top-left pixel) around the picture.
    public bool AutoTrim(int tolerance) {
        CommitText();
        Rectangle r = ContentBounds(Image, tolerance);
        if (r.Width <= 0 || r.Height <= 0 || r.Size == Image.Size) return false;
        Selection = r;
        return Crop();
    }

    static Rectangle ContentBounds(Bitmap bmp, int tol) {
        var data = bmp.LockBits(new Rectangle(0, 0, bmp.Width, bmp.Height), ImageLockMode.ReadOnly, PixelFormat.Format32bppArgb);
        int w = bmp.Width, h = bmp.Height, stride = data.Stride;
        byte[] px = new byte[stride * h];
        Marshal.Copy(data.Scan0, px, 0, px.Length);
        bmp.UnlockBits(data);
        int b0 = px[0], g0 = px[1], r0 = px[2], a0 = px[3];
        Func<int, int, bool> differs = (x, y) => {
            int i = y * stride + x * 4;
            return Math.Abs(px[i] - b0) > tol || Math.Abs(px[i + 1] - g0) > tol || Math.Abs(px[i + 2] - r0) > tol || Math.Abs(px[i + 3] - a0) > tol;
        };
        int top = 0, bottom = h - 1, left = 0, right = w - 1;
        while (top < h && Enumerable.Range(0, w).All(x => !differs(x, top))) top++;
        if (top == h) return Rectangle.Empty;
        while (bottom > top && Enumerable.Range(0, w).All(x => !differs(x, bottom))) bottom--;
        while (left < w && Enumerable.Range(top, bottom - top + 1).All(y => !differs(left, y))) left++;
        while (right > left && Enumerable.Range(top, bottom - top + 1).All(y => !differs(right, y))) right--;
        return Rectangle.FromLTRB(left, top, right + 1, bottom + 1);
    }

    public void Rotate(bool clockwise) { CommitText(); var prev = Snapshot(); Flatten(); var b = (Bitmap)Image.Clone(); b.RotateFlip(clockwise ? RotateFlipType.Rotate90FlipNone : RotateFlipType.Rotate270FlipNone); Image = b; UpdateSize(); Commit(prev); }
    public void Flip(bool horizontal) { CommitText(); var prev = Snapshot(); Flatten(); var b = (Bitmap)Image.Clone(); b.RotateFlip(horizontal ? RotateFlipType.RotateNoneFlipX : RotateFlipType.RotateNoneFlipY); Image = b; UpdateSize(); Commit(prev); }

    public void ResizeImage(float factor) {
        CommitText();
        int w = Math.Max(1, (int)Math.Round(Image.Width * factor)), h = Math.Max(1, (int)Math.Round(Image.Height * factor));
        var prev = Snapshot(); Flatten();
        Image = Scaled(Image, w, h);
        UpdateSize(); Commit(prev);
    }

    // Compressed copy for email / chat (white behind transparent parts).
    public static byte[] Jpeg(Bitmap src, int quality) {
        using (var flat = new Bitmap(src.Width, src.Height, PixelFormat.Format24bppRgb)) {
            using (var g = Graphics.FromImage(flat)) { g.Clear(Color.White); g.DrawImageUnscaled(src, 0, 0); }
            var codec = ImageCodecInfo.GetImageEncoders().First(c => c.FormatID == ImageFormat.Jpeg.Guid);
            using (var ps = new EncoderParameters(1))
            using (var ms = new System.IO.MemoryStream()) {
                ps.Param[0] = new EncoderParameter(System.Drawing.Imaging.Encoder.Quality, (long)Math.Max(1, Math.Min(100, quality)));
                flat.Save(ms, codec, ps);
                return ms.ToArray();
            }
        }
    }

    public static Bitmap Scaled(Bitmap src, int w, int h) {
        var b = new Bitmap(w, h, PixelFormat.Format32bppArgb);
        using (var g = Graphics.FromImage(b)) {
            g.InterpolationMode = InterpolationMode.HighQualityBicubic; g.PixelOffsetMode = PixelOffsetMode.HighQuality;
            using (var ia = new ImageAttributes()) { ia.SetWrapMode(WrapMode.TileFlipXY); g.DrawImage(src, new Rectangle(0, 0, w, h), 0, 0, src.Width, src.Height, GraphicsUnit.Pixel, ia); }
        }
        return b;
    }

    public void AddBorder(int size, Color color) {
        CommitText();
        var prev = Snapshot();
        var b = new Bitmap(Image.Width + size * 2, Image.Height + size * 2, PixelFormat.Format32bppArgb);
        using (var g = Graphics.FromImage(b)) { g.Clear(color); g.DrawImageUnscaled(Image, size, size); }
        Image = b;
        foreach (var s in Shapes) s.Offset(size, size);
        UpdateSize(); Commit(prev);
    }

    // ---- adjustments (the picture only; drawn shapes keep their colours) ------------------------------
    public static ColorMatrix Grayscale() { return new ColorMatrix(new[] { new[] { .299f, .299f, .299f, 0, 0 }, new[] { .587f, .587f, .587f, 0, 0 }, new[] { .114f, .114f, .114f, 0, 0 }, new[] { 0f, 0, 0, 1, 0 }, new[] { 0f, 0, 0, 0, 1 } }); }
    public static ColorMatrix Sepia() { return new ColorMatrix(new[] { new[] { .393f, .349f, .272f, 0, 0 }, new[] { .769f, .686f, .534f, 0, 0 }, new[] { .189f, .168f, .131f, 0, 0 }, new[] { 0f, 0, 0, 1, 0 }, new[] { 0f, 0, 0, 0, 1 } }); }
    public static ColorMatrix Invert() { return new ColorMatrix(new[] { new[] { -1f, 0, 0, 0, 0 }, new[] { 0f, -1, 0, 0, 0 }, new[] { 0f, 0, -1, 0, 0 }, new[] { 0f, 0, 0, 1, 0 }, new[] { 1f, 1, 1, 0, 1 } }); }
    // brightness and contrast from -100 to 100
    public static ColorMatrix BrightnessContrast(float brightness, float contrast) {
        float c = (100f + contrast) / 100f; c *= c;
        float b = brightness / 100f;
        float t = 0.5f * (1f - c) + b;
        return new ColorMatrix(new[] { new[] { c, 0, 0, 0, 0 }, new[] { 0f, c, 0, 0, 0 }, new[] { 0f, 0, c, 0, 0 }, new[] { 0f, 0, 0, 1, 0 }, new[] { t, t, t, 0, 1 } });
    }

    public void ApplyMatrix(ColorMatrix m) {
        CommitText();
        var prev = Snapshot();
        var b = new Bitmap(Image.Width, Image.Height, PixelFormat.Format32bppArgb);
        using (var g = Graphics.FromImage(b)) using (var ia = new ImageAttributes()) {
            ia.SetColorMatrix(m);
            g.DrawImage(Image, new Rectangle(0, 0, b.Width, b.Height), 0, 0, Image.Width, Image.Height, GraphicsUnit.Pixel, ia);
        }
        Image = b; preview = null;
        Invalidate(); Commit(prev);
    }
    public void Preview(ColorMatrix m) { preview = m; Invalidate(); }

    // 3x3 convolution: sharpen or soften the whole picture.
    public void Convolve(bool sharpen) {
        CommitText();
        var prev = Snapshot();
        float[] k = sharpen ? new float[] { 0, -1, 0, -1, 5, -1, 0, -1, 0 } : new float[] { 1, 2, 1, 2, 4, 2, 1, 2, 1 };
        float div = sharpen ? 1 : 16;
        var src = Image;
        int w = src.Width, h = src.Height;
        var sd = src.LockBits(new Rectangle(0, 0, w, h), ImageLockMode.ReadOnly, PixelFormat.Format32bppArgb);
        int stride = sd.Stride;
        byte[] a = new byte[stride * h], o = new byte[stride * h];
        Marshal.Copy(sd.Scan0, a, 0, a.Length);
        src.UnlockBits(sd);
        for (int y = 0; y < h; y++) for (int x = 0; x < w; x++) {
            int i = y * stride + x * 4;
            for (int c = 0; c < 3; c++) {
                float sum = 0; int n = 0;
                for (int dy = -1; dy <= 1; dy++) for (int dx = -1; dx <= 1; dx++) {
                    int xx = Math.Min(w - 1, Math.Max(0, x + dx)), yy = Math.Min(h - 1, Math.Max(0, y + dy));
                    sum += a[yy * stride + xx * 4 + c] * k[n++];
                }
                o[i + c] = (byte)Math.Min(255, Math.Max(0, sum / div));
            }
            o[i + 3] = a[i + 3];
        }
        var b = new Bitmap(w, h, PixelFormat.Format32bppArgb);
        var bd = b.LockBits(new Rectangle(0, 0, w, h), ImageLockMode.WriteOnly, PixelFormat.Format32bppArgb);
        Marshal.Copy(o, 0, bd.Scan0, o.Length);
        b.UnlockBits(bd);
        Image = b;
        Invalidate(); Commit(prev);
    }

    // ---- styling: applies to the selected shape too --------------------------------------------------
    public void SetInk(Color c) { Ink = c; Restyle("ink", s => s.Ink = c); }
    public void SetThickness(float w) { Thickness = w; Restyle("width", s => s.Width = w); }
    public void SetTextSize(float t) { TextSize = t; Restyle("text", s => s.TextSize = t); RefreshTextBox(); }
    public void SetFilled(bool f) { Filled = f; Restyle("filled", s => s.Filled = f); }
    public void SetDashed(bool d) { Dashed = d; Restyle("dashed", s => s.Dashed = d); }

    void Restyle(string what, Action<EdShape> change) {
        if (SelectedShape == null) { RefreshTextBox(); Invalidate(); return; }
        var prev = Snapshot();
        change(SelectedShape);
        Invalidate();
        CommitCoalesced(prev, what + SelectedShape.GetHashCode());
        RefreshTextBox();
    }

    public void DeleteSelected() {
        if (SelectedShape == null) return;
        var prev = Snapshot();
        Shapes.Remove(SelectedShape); SelectedShape = null;
        Invalidate(); Commit(prev); Raise(SelectionChanged);
    }
    public void Deselect() { if (SelectedShape == null) return; SelectedShape = null; Invalidate(); Raise(SelectionChanged); }
    public void Nudge(int dx, int dy) {
        if (SelectedShape == null) return;
        var prev = Snapshot();
        SelectedShape.Offset(dx, dy);
        Invalidate(); CommitCoalesced(prev, "nudge" + SelectedShape.GetHashCode());
    }
    public void ShapeToFront() { if (SelectedShape == null) return; var prev = Snapshot(); Shapes.Remove(SelectedShape); Shapes.Add(SelectedShape); Invalidate(); Commit(prev); }

    // ---- view ----------------------------------------------------------------------------------------
    float ViewScale { get { return Image == null ? 1 : (Fit ? Math.Min(4f, Math.Min((Width - 20f) / Image.Width, (Height - 20f) / Image.Height)) : Zoom); } }
    PointF Offset0 { get { if (Image == null) return PointF.Empty; float s = ViewScale; return new PointF(Math.Max(0, (Width - Image.Width * s) / 2), Math.Max(0, (Height - Image.Height * s) / 2)); } }
    public float CurrentZoom { get { return ViewScale; } }

    public void UpdateSize() {
        if (Image != null && !Fit && Parent != null) {
            Dock = DockStyle.None;
            Size = new Size(Math.Max(Parent.ClientSize.Width, (int)(Image.Width * Zoom) + 20), Math.Max(Parent.ClientSize.Height, (int)(Image.Height * Zoom) + 20));
        } else Dock = DockStyle.Fill;
        Invalidate(); Raise(ViewChanged);
    }
    public void SetZoom(float z, bool fit) { CommitText(); Fit = fit; Zoom = Math.Max(0.05f, Math.Min(16f, z)); UpdateSize(); }

    Point ToImage(Point p) { float s = ViewScale; PointF o = Offset0; return new Point((int)Math.Floor((p.X - o.X) / s), (int)Math.Floor((p.Y - o.Y) / s)); }
    Point ToScreen(Point p) { float s = ViewScale; PointF o = Offset0; return new Point((int)(p.X * s + o.X), (int)(p.Y * s + o.Y)); }
    static Rectangle RectFrom(Point a, Point b) { return Rectangle.FromLTRB(Math.Min(a.X, b.X), Math.Min(a.Y, b.Y), Math.Max(a.X, b.X), Math.Max(a.Y, b.Y)); }

    // ---- hit testing -----------------------------------------------------------------------------------
    static float SegDist(Point p, Point a, Point b) {
        float dx = b.X - a.X, dy = b.Y - a.Y;
        float len = dx * dx + dy * dy;
        float t = len == 0 ? 0 : Math.Max(0, Math.Min(1, ((p.X - a.X) * dx + (p.Y - a.Y) * dy) / len));
        float x = a.X + t * dx - p.X, y = a.Y + t * dy - p.Y;
        return (float)Math.Sqrt(x * x + y * y);
    }

    Rectangle TextBounds(EdShape s) {
        using (var f = new Font("Segoe UI", s.TextSize, FontStyle.Bold, GraphicsUnit.Pixel)) {
            Size sz = TextRenderer.MeasureText(string.IsNullOrEmpty(s.Text) ? " " : s.Text, f);
            return new Rectangle(s.A.X, s.A.Y, sz.Width, sz.Height);
        }
    }
    Rectangle StepBounds(EdShape s) { int d = (int)(Math.Max(14f, s.TextSize * 1.15f) / 2 + 2); return new Rectangle(s.A.X - d, s.A.Y - d, d * 2, d * 2); }
    int BubbleRadius(EdShape s) { Rectangle r = s.Box; return Math.Max(30, Math.Min(240, (int)(Math.Max(r.Width, r.Height) * 0.7))); }

    EdShape HitShape(Point ip) {
        float tol = 5 / ViewScale;
        for (int i = Shapes.Count - 1; i >= 0; i--) {
            var s = Shapes[i];
            switch (s.Kind) {
                case "arrow": case "darrow": case "line": if (SegDist(ip, s.A, s.B) <= s.Width / 2 + tol) return s; break;
                case "pen": for (int k = 1; k < s.Pts.Count; k++) if (SegDist(ip, s.Pts[k - 1], s.Pts[k]) <= s.Width / 2 + tol) return s; break;
                case "text": if (TextBounds(s).Contains(ip)) return s; break;
                case "step": if (StepBounds(s).Contains(ip)) return s; break;
                case "magnify": {
                    Rectangle r = s.Box; r.Inflate((int)tol, (int)tol);
                    int rad = BubbleRadius(s);
                    if (r.Contains(ip) || Math.Pow(ip.X - s.P.X, 2) + Math.Pow(ip.Y - s.P.Y, 2) <= rad * rad) return s;
                    break;
                }
                case "callout": { Rectangle r = s.Box; r.Inflate((int)tol, (int)tol); if (r.Contains(ip) || SegDist(ip, s.P, new Point(r.X + r.Width / 2, r.Bottom)) < tol * 2) return s; break; }
                case "spotlight": {
                    Rectangle r = s.Box; r.Inflate((int)tol, (int)tol); Rectangle inner = s.Box; inner.Inflate(-(int)tol * 2, -(int)tol * 2);
                    if (r.Contains(ip) && !inner.Contains(ip)) return s;        // only its edge, so you can still click things inside it
                    break;
                }
                default: {
                    Rectangle r = s.Box; r.Inflate((int)(s.Width / 2 + tol), (int)(s.Width / 2 + tol));
                    if (r.Contains(ip)) return s;
                    break;
                }
            }
        }
        return null;
    }

    // handle positions (image coordinates) of a shape
    List<Point> Handles(EdShape s) {
        var h = new List<Point>();
        if (s.IsLine) { h.Add(s.A); h.Add(s.B); }
        else if (s.IsBox || s.Kind == "pen") {
            Rectangle r = s.Kind == "pen" ? PenBounds(s) : s.Box;
            h.Add(new Point(r.Left, r.Top)); h.Add(new Point(r.Right, r.Top)); h.Add(new Point(r.Right, r.Bottom)); h.Add(new Point(r.Left, r.Bottom));
            if (s.Kind == "magnify" || s.Kind == "callout") h.Add(s.P);
        }
        return h;
    }

    static Rectangle PenBounds(EdShape s) {
        if (s.Pts.Count == 0) return Rectangle.Empty;
        int l = s.Pts.Min(p => p.X), t = s.Pts.Min(p => p.Y), r = s.Pts.Max(p => p.X), b = s.Pts.Max(p => p.Y);
        return Rectangle.FromLTRB(l, t, Math.Max(r, l + 1), Math.Max(b, t + 1));
    }

    int HitHandle(EdShape s, Point screen) {
        var hs = Handles(s);
        for (int i = hs.Count - 1; i >= 0; i--) { Point p = ToScreen(hs[i]); if (Math.Abs(p.X - screen.X) <= 7 && Math.Abs(p.Y - screen.Y) <= 7) return i; }
        return -1;
    }

    // ---- mouse -----------------------------------------------------------------------------------------
    protected override void OnMouseDown(MouseEventArgs e) {
        base.OnMouseDown(e);
        Focus();
        if (Image == null || e.Button != MouseButtons.Left) return;
        if (textBox != null) { CommitText(); }
        Point ip = ToImage(e.Location);
        downImg = lastImg = ip;
        if (Tool == "picker") {
            using (var b = Render()) {
                if (ip.X >= 0 && ip.Y >= 0 && ip.X < b.Width && ip.Y < b.Height) { Ink = Color.FromArgb(255, b.GetPixel(ip.X, ip.Y)); Raise(InkPicked); }
            }
            return;
        }
        if (SelectedShape != null) {
            int h = HitHandle(SelectedShape, e.Location);
            if (h >= 0) { mode = "handle"; handle = h; before = Snapshot(); original = SelectedShape.Clone(); return; }
        }
        if (Tool == "select") {
            var hit = HitShape(ip);
            if (hit != null) {
                SelectShape(hit);
                mode = "move"; before = Snapshot(); original = hit.Clone();
                return;
            }
            SelectShape(null);
            mode = "marquee"; Selection = Rectangle.Empty;
            return;
        }
        if (Tool == "crop") { SelectShape(null); mode = "marquee"; Selection = Rectangle.Empty; return; }
        if (Tool == "text") {
            var hit = HitShape(ip);
            if (hit != null && (hit.Kind == "text" || hit.Kind == "callout")) { SelectShape(hit); StartText(hit, false); return; }
            var s = NewShape("text"); s.A = new Point(ip.X, ip.Y - (int)(TextSize * 0.7f));
            StartText(s, true);
            return;
        }
        if (Tool == "step") {
            var prev = Snapshot();
            var s = NewShape("step"); s.A = ip; s.Number = StepNumber++;
            Shapes.Add(s); SelectShape(s);
            Invalidate(); Commit(prev);
            return;
        }
        SelectShape(null);
        before = Snapshot();
        drawing = NewShape(Tool);
        drawing.A = drawing.B = ip;
        drawing.Pts.Add(ip);
        mode = "draw";
    }

    EdShape NewShape(string kind) {
        return new EdShape { Kind = kind, Ink = Ink, Width = Thickness, TextSize = TextSize, Filled = Filled, Dashed = Dashed };
    }

    void SelectShape(EdShape s) { if (SelectedShape == s) return; SelectedShape = s; Invalidate(); Raise(SelectionChanged); }

    Point Constrain(Point a, Point p, bool square) {
        if ((ModifierKeys & Keys.Shift) == 0) return p;
        int dx = p.X - a.X, dy = p.Y - a.Y;
        if (square) { int m = Math.Max(Math.Abs(dx), Math.Abs(dy)); return new Point(a.X + Math.Sign(dx) * m, a.Y + Math.Sign(dy) * m); }
        if (Math.Abs(dx) > Math.Abs(dy) * 2) dy = 0; else if (Math.Abs(dy) > Math.Abs(dx) * 2) dx = 0; else { int m = Math.Max(Math.Abs(dx), Math.Abs(dy)); dx = Math.Sign(dx) * m; dy = Math.Sign(dy) * m; }
        return new Point(a.X + dx, a.Y + dy);
    }

    protected override void OnMouseMove(MouseEventArgs e) {
        base.OnMouseMove(e);
        if (Image == null) return;
        Point ip = ToImage(e.Location);
        Pointer = ip;
        switch (mode) {
            case "draw":
                if (drawing.Kind == "pen") drawing.Pts.Add(ip);
                else drawing.B = Constrain(drawing.A, ip, drawing.IsBox);
                Invalidate();
                break;
            case "marquee":
                Selection = RectFrom(downImg, Constrain(downImg, ip, true));
                Invalidate();
                break;
            case "move": {
                var s = SelectedShape;
                int dx = ip.X - downImg.X, dy = ip.Y - downImg.Y;
                s.A = original.A; s.B = original.B; s.P = original.P; s.Pts = new List<Point>(original.Pts);
                s.Offset(dx, dy);
                Invalidate();
                break;
            }
            case "handle": DragHandle(ip); Invalidate(); break;
            default:
                if (SelectedShape != null) Cursor = HitHandle(SelectedShape, e.Location) >= 0 ? Cursors.SizeAll : (Tool == "text" ? Cursors.IBeam : Cursors.Cross);
                break;
        }
        lastImg = ip;
        Raise(ViewChanged);
    }

    void DragHandle(Point ip) {
        var s = SelectedShape; var o = original;
        if (s.IsLine) { if (handle == 0) s.A = Constrain(s.B, ip, false); else s.B = Constrain(s.A, ip, false); return; }
        if ((s.Kind == "magnify" || s.Kind == "callout") && handle == 4) { s.P = ip; return; }
        Rectangle r = s.Kind == "pen" ? PenBounds(o) : o.Box;
        int l = r.Left, t = r.Top, rr = r.Right, b = r.Bottom;
        switch (handle) { case 0: l = ip.X; t = ip.Y; break; case 1: rr = ip.X; t = ip.Y; break; case 2: rr = ip.X; b = ip.Y; break; case 3: l = ip.X; b = ip.Y; break; }
        Rectangle nr = RectFrom(new Point(l, t), new Point(rr, b));
        if (s.Kind == "pen") {
            float sx = r.Width == 0 ? 1 : (float)nr.Width / r.Width, sy = r.Height == 0 ? 1 : (float)nr.Height / r.Height;
            s.Pts = o.Pts.Select(p => new Point(nr.X + (int)((p.X - r.X) * sx), nr.Y + (int)((p.Y - r.Y) * sy))).ToList();
        } else { s.A = nr.Location; s.B = new Point(nr.Right, nr.Bottom); }
    }

    protected override void OnMouseUp(MouseEventArgs e) {
        base.OnMouseUp(e);
        string m = mode; mode = "";
        switch (m) {
            case "draw": {
                var s = drawing; drawing = null;
                bool tiny = s.Kind == "pen" ? s.Pts.Count < 2 && false : Math.Abs(s.A.X - s.B.X) < 3 && Math.Abs(s.A.Y - s.B.Y) < 3;
                if (tiny) { Invalidate(); return; }
                if (s.Kind == "blur") { BurnBlur(s.Box, before); return; }
                if (s.Kind == "magnify") { Rectangle r = s.Box; int rad = BubbleRadius(s); s.P = new Point(Math.Min(Image.Width - rad / 2, r.Right + rad + 20), r.Top + r.Height / 2); }
                if (s.Kind == "callout") { Rectangle r = s.Box; s.P = new Point(r.Left + Math.Min(40, r.Width / 3), r.Bottom + Math.Max(30, r.Height / 2)); }
                Shapes.Add(s); SelectShape(s);
                Invalidate(); Commit(before);
                if (s.Kind == "callout") StartText(s, false);
                break;
            }
            case "marquee":
                Selection = Rectangle.Intersect(Selection, new Rectangle(0, 0, Image.Width, Image.Height));
                if (Selection.Width < 2 || Selection.Height < 2) Selection = Rectangle.Empty;
                Invalidate(); Raise(ViewChanged);
                break;
            case "move": case "handle":
                if (downImg != lastImg) Commit(before);
                Invalidate();
                break;
        }
    }

    protected override void OnMouseDoubleClick(MouseEventArgs e) {
        base.OnMouseDoubleClick(e);
        var hit = HitShape(ToImage(e.Location));
        if (hit != null && (hit.Kind == "text" || hit.Kind == "callout")) { SelectShape(hit); StartText(hit, false); }
    }

    // Pixelation goes into the picture itself, so what is underneath really is gone.
    void BurnBlur(Rectangle r, State prev) {
        r = Rectangle.Intersect(r, new Rectangle(0, 0, Image.Width, Image.Height));
        if (r.Width < 2 || r.Height < 2) { Invalidate(); return; }
        var b = (Bitmap)Image.Clone();
        using (var g = Graphics.FromImage(b)) Pixelate(g, b, r);
        Image = b;
        Invalidate(); Commit(prev);
    }

    static void Pixelate(Graphics g, Bitmap src, Rectangle r) {
        int block = Math.Min(40, Math.Max(10, Math.Min(r.Width, r.Height) / 3));
        int sw = Math.Max(1, r.Width / block), sh = Math.Max(1, r.Height / block);
        using (var part = src.Clone(r, PixelFormat.Format32bppArgb))
        using (var small = new Bitmap(sw, sh, PixelFormat.Format32bppArgb)) {
            using (var gs = Graphics.FromImage(small)) { gs.InterpolationMode = InterpolationMode.HighQualityBilinear; gs.DrawImage(part, 0, 0, sw, sh); }
            g.InterpolationMode = InterpolationMode.NearestNeighbor; g.PixelOffsetMode = PixelOffsetMode.Half; g.SmoothingMode = SmoothingMode.None;
            g.DrawImage(small, r);
        }
    }

    // ---- drawing a shape (image coordinates) -------------------------------------------------------------
    void DrawShape(Graphics g, EdShape s, Bitmap underneath) {
        float w = s.Width;
        Func<Pen> pen = () => { var p = new Pen(s.Ink, w) { StartCap = LineCap.Round, EndCap = LineCap.Round, LineJoin = LineJoin.Round }; if (s.Dashed) p.DashStyle = DashStyle.Dash; return p; };
        switch (s.Kind) {
            case "arrow": case "darrow": {
                using (var p = pen()) {
                    float head = Math.Max(3f, 12f / (float)Math.Sqrt(w)) * 0.55f;
                    p.CustomEndCap = new AdjustableArrowCap(head + 2.5f, head + 3f, true);
                    if (s.Kind == "darrow") p.CustomStartCap = new AdjustableArrowCap(head + 2.5f, head + 3f, true);
                    g.DrawLine(p, s.A, s.B);
                }
                break;
            }
            case "line": using (var p = pen()) g.DrawLine(p, s.A, s.B); break;
            case "rect":
                if (s.Filled) using (var br = new SolidBrush(s.Ink)) g.FillRectangle(br, s.Box);
                else using (var p = pen()) { p.StartCap = LineCap.Flat; p.EndCap = LineCap.Flat; g.DrawRectangle(p, s.Box); }
                break;
            case "ellipse":
                if (s.Filled) using (var br = new SolidBrush(s.Ink)) g.FillEllipse(br, s.Box);
                else using (var p = pen()) g.DrawEllipse(p, s.Box);
                break;
            case "highlight": using (var br = new SolidBrush(Color.FromArgb(90, s.Ink))) g.FillRectangle(br, s.Box); break;
            case "pen":
                if (s.Pts.Count == 1) using (var br = new SolidBrush(s.Ink)) g.FillEllipse(br, s.Pts[0].X - w / 2, s.Pts[0].Y - w / 2, w, w);
                else using (var p = pen()) g.DrawLines(p, s.Pts.ToArray());
                break;
            case "blur": using (var br = new HatchBrush(HatchStyle.LargeCheckerBoard, Color.FromArgb(150, 90, 90, 90), Color.FromArgb(150, 160, 160, 160))) g.FillRectangle(br, s.Box); break;
            case "text": DrawText(g, s.Text, s.A, s.TextSize, s.Ink, 0); break;
            case "step": DrawStep(g, s); break;
            case "spotlight": {
                using (var region = new Region(new Rectangle(-10000, -10000, 30000, 30000))) {
                    region.Exclude(s.Box);
                    using (var br = new SolidBrush(Color.FromArgb(150, 0, 0, 0))) g.FillRegion(br, region);
                }
                using (var p = new Pen(Color.FromArgb(220, 255, 255, 255), Math.Max(1.5f, w / 2))) g.DrawRectangle(p, s.Box);
                break;
            }
            case "magnify": DrawMagnifier(g, s, underneath); break;
            case "callout": DrawCallout(g, s); break;
        }
    }

    static void DrawText(Graphics g, string text, Point at, float size, Color ink, int maxWidth) {
        if (string.IsNullOrEmpty(text)) return;
        using (var f = new Font("Segoe UI", size, FontStyle.Bold, GraphicsUnit.Pixel))
        using (var path = new GraphicsPath()) {
            if (maxWidth > 0) path.AddString(text, f.FontFamily, (int)FontStyle.Bold, f.Size, new RectangleF(at.X, at.Y, maxWidth, 10000), StringFormat.GenericTypographic);
            else path.AddString(text, f.FontFamily, (int)FontStyle.Bold, f.Size, new PointF(at.X, at.Y), StringFormat.GenericTypographic);
            Color halo = ink.GetBrightness() > 0.6f ? Color.FromArgb(160, 0, 0, 0) : Color.FromArgb(200, 255, 255, 255);
            if (maxWidth == 0) using (var p = new Pen(halo, Math.Max(2f, size / 7f)) { LineJoin = LineJoin.Round }) g.DrawPath(p, path);
            using (var br = new SolidBrush(ink)) g.FillPath(br, path);
        }
    }

    void DrawStep(Graphics g, EdShape s) {
        float d = Math.Max(14f, s.TextSize * 1.15f);
        Point c = s.A;
        using (var br = new SolidBrush(s.Ink)) g.FillEllipse(br, c.X - d / 2, c.Y - d / 2, d, d);
        using (var p = new Pen(Color.White, Math.Max(1.5f, d / 14))) g.DrawEllipse(p, c.X - d / 2, c.Y - d / 2, d, d);
        Color fore = s.Ink.GetBrightness() > 0.7f ? Color.Black : Color.White;
        using (var f = new Font("Segoe UI", d * 0.48f, FontStyle.Bold, GraphicsUnit.Pixel))
        using (var sf = new StringFormat { Alignment = StringAlignment.Center, LineAlignment = StringAlignment.Center })
        using (var br2 = new SolidBrush(fore))
            g.DrawString(s.Number.ToString(), f, br2, new RectangleF(c.X - d / 2, c.Y - d / 2 + 1, d, d), sf);
    }

    void DrawMagnifier(Graphics g, EdShape s, Bitmap underneath) {
        Rectangle src = Rectangle.Intersect(s.Box, new Rectangle(0, 0, underneath.Width, underneath.Height));
        if (src.Width < 2 || src.Height < 2) return;
        int rad = BubbleRadius(s);
        var bubble = new Rectangle(s.P.X - rad, s.P.Y - rad, rad * 2, rad * 2);
        float w = Math.Max(2f, s.Width / 1.5f);
        using (var p = new Pen(s.Ink, w)) {
            g.DrawRectangle(p, src);
            // connector from the area to the bubble
            var c1 = new PointF(src.X + src.Width / 2f, src.Y + src.Height / 2f);
            double ang = Math.Atan2(s.P.Y - c1.Y, s.P.X - c1.X);
            var edge = new PointF((float)(s.P.X - Math.Cos(ang) * rad), (float)(s.P.Y - Math.Sin(ang) * rad));
            g.DrawLine(p, c1, edge);
        }
        using (var path = new GraphicsPath()) {
            path.AddEllipse(bubble);
            var state = g.Save();
            g.SetClip(path);
            float scale = (rad * 2f) / Math.Max(src.Width, src.Height);
            var dest = new RectangleF(s.P.X - src.Width * scale / 2, s.P.Y - src.Height * scale / 2, src.Width * scale, src.Height * scale);
            using (var bg = new SolidBrush(Color.White)) g.FillPath(bg, path);
            g.InterpolationMode = InterpolationMode.HighQualityBicubic;
            g.DrawImage(underneath, dest, src, GraphicsUnit.Pixel);
            g.Restore(state);
            using (var p = new Pen(s.Ink, w * 1.5f)) g.DrawPath(p, path);
        }
    }

    void DrawCallout(Graphics g, EdShape s) {
        Rectangle r = s.Box;
        if (r.Width < 4 || r.Height < 4) return;
        float rad = Math.Min(14, Math.Min(r.Width, r.Height) / 3f);
        using (var path = new GraphicsPath()) {
            // rounded box with a tail towards P
            float d = rad * 2;
            path.AddArc(r.X, r.Y, d, d, 180, 90);
            path.AddArc(r.Right - d, r.Y, d, d, 270, 90);
            path.AddArc(r.Right - d, r.Bottom - d, d, d, 0, 90);
            float tailW = Math.Max(10, Math.Min(r.Width / 4f, 40));
            float baseX = Math.Max(r.X + rad + tailW, Math.Min(r.Right - rad, s.P.X + tailW / 2));
            path.AddLine(baseX, r.Bottom, s.P.X, s.P.Y);
            path.AddLine(s.P.X, s.P.Y, baseX - tailW, r.Bottom);
            path.AddArc(r.X, r.Bottom - d, d, d, 90, 90);
            path.CloseFigure();
            using (var br = new SolidBrush(s.Filled ? s.Ink : Color.White)) g.FillPath(br, path);
            using (var p = new Pen(s.Ink, Math.Max(1.5f, s.Width / 2))) { if (s.Dashed) p.DashStyle = DashStyle.Dash; g.DrawPath(p, path); }
        }
        Color textColor = s.Filled ? (s.Ink.GetBrightness() > 0.6f ? Color.Black : Color.White) : Color.FromArgb(25, 25, 25);
        int pad = (int)Math.Max(6, s.TextSize / 3);
        using (var f = new Font("Segoe UI", s.TextSize, FontStyle.Bold, GraphicsUnit.Pixel))
        using (var br = new SolidBrush(textColor))
        using (var sf = new StringFormat { Trimming = StringTrimming.EllipsisWord })
            g.DrawString(s.Text ?? "", f, br, new RectangleF(r.X + pad, r.Y + pad, r.Width - pad * 2, r.Height - pad * 2), sf);
    }

    // ---- text editing (text and callout shapes) -------------------------------------------------------
    void StartText(EdShape s, bool isNew) {
        editing = s; editingIsNew = isNew;
        textBox = new TextBox { BorderStyle = BorderStyle.FixedSingle, Multiline = true, AcceptsReturn = s.Kind == "callout", ForeColor = s.Kind == "callout" ? Color.Black : s.Ink, BackColor = Color.White, Text = s.Text ?? "" };
        // Text: Enter finishes. Callout: Enter starts a new line, Ctrl+Enter finishes. Esc cancels.
        textBox.KeyDown += (o, e) => {
            if (e.KeyCode == Keys.Enter && (editing.Kind != "callout" || e.Control)) { e.SuppressKeyPress = true; CommitText(); }
            else if (e.KeyCode == Keys.Escape) { e.SuppressKeyPress = true; CancelText(); }
        };
        textBox.TextChanged += (o, e) => { if (editing != null && editing.Kind == "text") RefreshTextBox(); };
        Controls.Add(textBox);
        RefreshTextBox();
        textBox.Focus();
        textBox.SelectAll();
        Invalidate();
    }

    public void RefreshTextBox() {
        if (textBox == null || editing == null) return;
        var s = editing;
        textBox.Font = new Font("Segoe UI", Math.Max(6f, s.TextSize * ViewScale), FontStyle.Bold, GraphicsUnit.Pixel);
        if (s.Kind == "callout") {
            Rectangle r = s.Box; Point a = ToScreen(r.Location), b = ToScreen(new Point(r.Right, r.Bottom));
            textBox.Bounds = Rectangle.FromLTRB(a.X + 4, a.Y + 4, Math.Max(a.X + 60, b.X - 4), Math.Max(a.Y + textBox.Font.Height + 8, b.Y - 4));
            textBox.ForeColor = Color.Black;
        } else {
            textBox.ForeColor = s.Ink;
            Point p = ToScreen(s.A);
            Size need = TextRenderer.MeasureText(textBox.Text + "    ", textBox.Font);
            textBox.Location = p;
            textBox.Size = new Size(Math.Max((int)(s.TextSize * ViewScale * 6), need.Width + 10), Math.Max(textBox.Font.Height + 8, need.Height + 8));
        }
    }

    void CancelText() {
        if (textBox == null) return;
        var t = textBox; textBox = null;
        var s = editing; editing = null;
        Controls.Remove(t); t.Dispose(); Focus();
        if (s != null && s.Kind == "callout" && string.IsNullOrEmpty(s.Text)) { }      // an empty callout box is still useful
        Invalidate();
    }

    public void CommitText() {
        if (textBox == null) return;
        string text = textBox.Text.Replace("\r", "");
        var s = editing; bool isNew = editingIsNew;
        CancelText();
        if (s == null) return;
        if (s.Kind == "text" && text.Trim().Length == 0) {
            if (!isNew && Shapes.Contains(s)) { var prev0 = Snapshot(); Shapes.Remove(s); SelectedShape = null; Commit(prev0); Raise(SelectionChanged); }
            Invalidate();
            return;
        }
        if (text == s.Text && !isNew) return;
        var prev = Snapshot();
        s.Text = text;
        if (isNew) { Shapes.Add(s); SelectShape(s); }
        Invalidate(); Commit(prev);
    }

    public bool IsTyping { get { return textBox != null; } }

    // ---- painting --------------------------------------------------------------------------------------
    protected override void OnPaint(PaintEventArgs e) {
        var g = e.Graphics;
        g.Clear(BackColor);
        if (Image == null) return;
        float s = ViewScale; PointF o = Offset0;
        var dest = new RectangleF(o.X, o.Y, Image.Width * s, Image.Height * s);
        using (var light = new SolidBrush(Color.FromArgb(235, 235, 235))) using (var dark = new SolidBrush(Color.FromArgb(205, 205, 205))) {
            g.FillRectangle(light, dest);
            int cell = 10;
            var clip = g.Clip; g.SetClip(dest);
            for (float y = dest.Top; y < dest.Bottom; y += cell) for (float x = dest.Left + (((int)((y - dest.Top) / cell)) % 2) * cell; x < dest.Right; x += cell * 2) g.FillRectangle(dark, x, y, cell, cell);
            g.Clip = clip;
        }
        g.InterpolationMode = s >= 2 ? InterpolationMode.NearestNeighbor : InterpolationMode.HighQualityBilinear;
        g.PixelOffsetMode = PixelOffsetMode.Half;
        if (preview != null) using (var ia = new ImageAttributes()) { ia.SetColorMatrix(preview); g.DrawImage(Image, Rectangle.Round(dest), 0, 0, Image.Width, Image.Height, GraphicsUnit.Pixel, ia); }
        else g.DrawImage(Image, dest);

        // shapes, in image coordinates
        var st = g.Save();
        g.TranslateTransform(o.X, o.Y); g.ScaleTransform(s, s);
        g.SetClip(new Rectangle(0, 0, Image.Width, Image.Height));
        Prep(g);
        foreach (var sh in Ordered()) if (sh != editing || sh.Kind == "callout") DrawShape(g, sh, Image);
        if (drawing != null) DrawShape(g, drawing, Image);
        g.Restore(st);

        // selected shape: dashed outline + handles
        if (SelectedShape != null && Shapes.Contains(SelectedShape)) {
            var sh = SelectedShape;
            Rectangle b = sh.IsLine ? RectFrom(sh.A, sh.B) : sh.Kind == "pen" ? PenBounds(sh) : sh.Kind == "text" ? TextBounds(sh) : sh.Kind == "step" ? StepBounds(sh) : sh.Box;
            Point a1 = ToScreen(b.Location), a2 = ToScreen(new Point(b.Right, b.Bottom));
            var sr = Rectangle.FromLTRB(a1.X - 4, a1.Y - 4, a2.X + 4, a2.Y + 4);
            if (!sh.IsLine) using (var p = new Pen(Color.FromArgb(0, 120, 212), 1) { DashStyle = DashStyle.Dash }) g.DrawRectangle(p, sr);
            foreach (var h in Handles(sh)) {
                Point hp = ToScreen(h);
                var hr = new Rectangle(hp.X - 5, hp.Y - 5, 10, 10);
                g.FillRectangle(Brushes.White, hr);
                using (var p = new Pen(Color.FromArgb(0, 120, 212), 2)) g.DrawRectangle(p, hr);
            }
        }
        // marquee
        if (!Selection.IsEmpty) {
            Point a = ToScreen(Selection.Location), b2 = ToScreen(new Point(Selection.Right, Selection.Bottom));
            var r = Rectangle.FromLTRB(a.X, a.Y, b2.X, b2.Y);
            if (Tool == "crop") using (var dim = new SolidBrush(Color.FromArgb(120, 0, 0, 0))) using (var region = new Region(Rectangle.Round(dest))) { region.Exclude(r); g.FillRegion(dim, region); }
            using (var p1 = new Pen(Color.White, 1)) g.DrawRectangle(p1, r);
            using (var p2 = new Pen(Color.Black, 1) { DashStyle = DashStyle.Dash }) g.DrawRectangle(p2, r);
        }
    }

    protected override void OnResize(EventArgs e) { base.OnResize(e); RefreshTextBox(); Invalidate(); Raise(ViewChanged); }
}

// A small window that never takes the focus (used for the paste-stack and timer indicators).
public class PowerClipToast : Form {
    public PowerClipToast() {
        FormBorderStyle = FormBorderStyle.None; ShowInTaskbar = false; TopMost = true; StartPosition = FormStartPosition.Manual;
    }
    protected override bool ShowWithoutActivation { get { return true; } }
    protected override CreateParams CreateParams {
        get { var cp = base.CreateParams; cp.ExStyle |= 0x08000000 /* WS_EX_NOACTIVATE */ | 0x00000080 /* WS_EX_TOOLWINDOW */; return cp; }
    }
}

// Top-level windows on screen (for "click a window" in the screenshot tool), front to back.
public static class PowerClipWindows {
    delegate bool EnumProc(IntPtr h, IntPtr l);
    [DllImport("user32.dll")] static extern bool EnumWindows(EnumProc cb, IntPtr l);
    [DllImport("user32.dll")] static extern bool IsWindowVisible(IntPtr h);
    [DllImport("user32.dll")] static extern bool IsIconic(IntPtr h);
    [DllImport("user32.dll")] static extern bool GetWindowRect(IntPtr h, out RECT r);
    [DllImport("user32.dll")] static extern int GetWindowTextLength(IntPtr h);
    [DllImport("dwmapi.dll")] static extern int DwmGetWindowAttribute(IntPtr h, int attr, out RECT r, int size);
    [DllImport("dwmapi.dll", EntryPoint = "DwmGetWindowAttribute")] static extern int DwmGetInt(IntPtr h, int attr, out int v, int size);
    struct RECT { public int L, T, R, B; }

    public static List<Rectangle> Visible(IntPtr exclude) {
        var list = new List<Rectangle>();
        EnumWindows((h, l) => {
            if (h == exclude || !IsWindowVisible(h) || IsIconic(h) || GetWindowTextLength(h) == 0) return true;
            int cloaked;
            if (DwmGetInt(h, 14, out cloaked, 4) == 0 && cloaked != 0) return true;       // hidden store apps / other desktops
            RECT r;
            if (DwmGetWindowAttribute(h, 9, out r, Marshal.SizeOf(typeof(RECT))) != 0) GetWindowRect(h, out r);   // frame without the shadow
            var rect = Rectangle.FromLTRB(r.L, r.T, r.R, r.B);
            if (rect.Width > 40 && rect.Height > 30) list.Add(rect);
            return true;
        }, IntPtr.Zero);
        return list;
    }
}
'@
}

# ---------------------------------------------------------------------------
# Single instance
# ---------------------------------------------------------------------------
# one DevTools per folder: copies in other folders (another data folder) can run side by side
$createdNew = $false
$instKey = [BitConverter]::ToString([System.Security.Cryptography.SHA1]::Create().ComputeHash([System.Text.Encoding]::UTF8.GetBytes((Split-Path -Parent $PSCommandPath).ToLowerInvariant()))).Replace('-', '').Substring(0, 12)
$mutex = New-Object System.Threading.Mutex($true, "Local\DevTools_SingleInstance_$instKey", [ref]$createdNew)
if (-not $createdNew) {
    [void][System.Windows.Forms.MessageBox]::Show('DevTools is already running. Press Ctrl+Shift+V to open it.', 'DevTools')
    return
}

[void][PowerClipHost]::SetProcessDPIAware()
[System.Windows.Forms.Application]::EnableVisualStyles()

# ---------------------------------------------------------------------------
# Storage (portable: everything lives next to the script)
# ---------------------------------------------------------------------------
$Root         = Split-Path -Parent $PSCommandPath
$DataDir      = Join-Path $Root 'data'
$HistoryFile  = Join-Path $DataDir 'history.json'
$SettingsFile = Join-Path $DataDir 'settings.json'
$ImagesDir    = Join-Path $DataDir 'images'
$FilesDir     = Join-Path $DataDir 'files'
$TextsDir     = Join-Path $DataDir 'texts'
foreach ($d in $DataDir, $ImagesDir, $FilesDir, $TextsDir) { if (-not (Test-Path $d)) { [void](New-Item -ItemType Directory -Path $d) } }
$FirstRun = -not (Test-Path $HistoryFile)

$script:Paused   = $false
$script:MaxItems = 500          # unpinned clips kept; pinned clips are never trimmed
$script:MaxFileMB = 10          # copied files/folders and images bigger than this are not saved
$script:MaxTextMB = 50          # copied text bigger than this is not saved
$script:TextSize = 'Medium'      # Small / Medium / Large (applies on restart)
$script:VaultLockMin = 5         # secrets lock after this many idle minutes
$script:VaultClearSec = 30       # copied secrets are cleared from the clipboard after this
# Nothing copied in these apps is saved (process names, without .exe). Password managers by default.
$script:BackupDir = ''              # '' = Documents\DevTools backups
$script:BackupHours = 0           # automatic backup interval (0 = off)
$script:BackupKeep = 10           # how many backups to keep
$script:BackupLast = $null
$script:HostInterval = 30         # host monitor: seconds between checks
$script:HostNotify = $true         # host monitor: notify when a host goes down / comes back
$script:SyncDir = ''                # sync between PCs: shared folder ('' = off)
$script:TimeZones = @('UTC', 'Pacific Standard Time', 'Eastern Standard Time', 'GMT Standard Time', 'Central Europe Standard Time', 'India Standard Time', 'Tokyo Standard Time')
$script:Pomodoro = @{ Work = 25; Short = 5; Long = 15; Every = 4 }
$script:Hotkeys = @{}               # global shortcuts: palette command title -> 'Ctrl+Alt+N'
$script:GitRepos = @()              # Git window: recently opened repositories
$script:MouseCfg = @{ Interval = 60; Mode = 'zero'; Awake = $true; OnlyIdle = $true; StopMin = 0; ClickMs = 500; Button = 'left'; Double = $false; Count = 0; Fixed = $false; X = 0; Y = 0; StopOnMove = $true }
$script:SyncLast = $null
$script:ExpiryRules = @('# Examples (remove the # to use them):', '# text:(?i)password 10', '# app:chrome 1440')
$script:IgnoreApps = @('KeePass', 'KeePassXC', '1Password', 'Bitwarden', 'LastPass', 'Dashlane', 'RoboForm', 'NordPass', 'Enpass', 'Keeper')
$script:Theme    = 'System'     # System, Light or Dark
$script:Accent   = 'Blue'
$BigText = 256KB                # text clips longer than this (chars) are kept in data\texts\ instead of history.json
$script:LineCache = @{}         # item Id -> @(text length, line count) for the picker rows
$script:IgnoreUntil = [datetime]::MinValue   # skip the clipboard change we cause ourselves
$script:Thumbs   = @{}          # item Id -> thumbnail bitmap
$script:Items    = New-Object System.Collections.Generic.List[object]   # newest first
$script:View     = New-Object System.Collections.Generic.List[object]   # what the list shows
$script:PasteTarget = [IntPtr]::Zero
$script:Modal    = $false
$script:Exiting  = $false

# Set the POWERCLIP_DEBUG environment variable to get a log in data\debug.log.
function Write-Log([string]$Message) {
    if ($env:POWERCLIP_DEBUG) {
        try { Add-Content -Path (Join-Path $DataDir 'debug.log') -Value "$(Get-Date -Format 'HH:mm:ss.fff')  $Message" } catch { }
    }
}

# Writes a data file safely (temp file, then swap). Encrypted when data encryption is on (see Test-ProtectPath).
function Write-JsonFile([string]$Path, [string]$Json) {
    $bytes = if (Test-ProtectPath $Path) { [PowerClipVault]::Seal($Json, $script:DataKey) } else { (New-Object System.Text.UTF8Encoding $false).GetBytes($Json) }
    $tmp = "$Path.tmp"
    [IO.File]::WriteAllBytes($tmp, $bytes)
    if (Test-Path $Path) { [IO.File]::Replace($tmp, $Path, [NullString]::Value) } else { [IO.File]::Move($tmp, $Path) }
}

# Kind is 'text', 'image' or 'files'.
#   text : Text holds the clip. Big texts are saved to TextFile (relative to data\); TextDirty means it needs rewriting.
#   image: Image is the PNG path relative to data\, Hash identifies duplicates.
#   files: Files are the saved copies (relative to data\); Text holds the original paths, one per line.
function New-ClipItem([string]$Kind = 'text', [string]$Text = '', [bool]$Pinned = $false, $Time = $null, [string]$Id = '') {
    $dt = Get-Date
    if ($Time -is [datetime]) { $dt = $Time }
    elseif ($Time) { try { $dt = [datetime]::Parse([string]$Time, $null, [Globalization.DateTimeStyles]::RoundtripKind).ToLocalTime() } catch { } }
    if (-not $Id) { $Id = [guid]::NewGuid().ToString('N') }
    [pscustomobject]@{
        Id = $Id; Kind = $Kind; Text = $Text; Pinned = $Pinned; Time = $dt
        Image = $null; Width = 0; Height = 0; Hash = $null; Files = @(); Bytes = [long]0
        TextFile = $null; TextDirty = $false; Source = ''
    }
}

# Big texts live in their own file so history.json stays small and quick to rewrite on every copy.
function Sync-TextFile($Item) {
    if ($Item.Kind -ne 'text') { return }
    if ($Item.Text.Length -gt $BigText) {
        if (-not $Item.TextFile) { $Item.TextFile = "texts\$($Item.Id).txt"; $Item.TextDirty = $true }
        if ($Item.TextDirty) {
            Write-JsonFile (Get-DataPath $Item.TextFile) $Item.Text
            $Item.TextDirty = $false
        }
    } elseif ($Item.TextFile) {     # edited down to a small text: keep it inline again
        Remove-Item -LiteralPath (Get-DataPath $Item.TextFile) -Force -ErrorAction SilentlyContinue
        $Item.TextFile = $null
    }
}

function Save-History {
    if ($script:NoSave) { return }
    $out = foreach ($i in $script:Items) {
        try { Sync-TextFile $i } catch { Write-Log "text file save failed: $_" }
        $text = if ($i.TextFile) { '' } else { $i.Text }
        $o = [ordered]@{ Id = $i.Id; Kind = $i.Kind; Text = $text; Pinned = [bool]$i.Pinned; Time = $i.Time.ToString('o') }
        if ($i.Source) { $o.Source = $i.Source }
        if ($i.TextFile) { $o.TextFile = $i.TextFile }
        if ($i.Kind -eq 'image') { $o.Image = $i.Image; $o.Width = $i.Width; $o.Height = $i.Height; $o.Hash = $i.Hash; $o.Bytes = $i.Bytes }
        if ($i.Kind -eq 'files') { $o.Files = @($i.Files); $o.Bytes = $i.Bytes }
        $o
    }
    $json = ConvertTo-Json -InputObject @($out) -Depth 4
    if (-not $json) { $json = '[]' }
    try { Write-JsonFile $HistoryFile $json } catch { }
}

function Save-Settings {
    if ($script:NoSave) { return }
    $json = ConvertTo-Json -InputObject ([ordered]@{
        Paused = $script:Paused; MaxItems = $script:MaxItems; MaxFileMB = $script:MaxFileMB; MaxTextMB = $script:MaxTextMB
        Theme = $script:Theme; Accent = $script:Accent; TextSize = $script:TextSize
        VaultLockMin = $script:VaultLockMin; VaultClearSec = $script:VaultClearSec; IgnoreApps = @($script:IgnoreApps)
        BackupDir = $script:BackupDir; BackupHours = $script:BackupHours; BackupKeep = $script:BackupKeep
        HostInterval = $script:HostInterval; HostNotify = $script:HostNotify
        SyncDir = $script:SyncDir; SyncLast = $(if ($script:SyncLast) { $script:SyncLast.ToString('o') } else { $null }); ExpiryRules = @($script:ExpiryRules)
        TimeZones = @($script:TimeZones); Pomodoro = $script:Pomodoro; Hotkeys = $script:Hotkeys; Mouse = $script:MouseCfg; GitRepos = @($script:GitRepos)
        BackupLast = $(if ($script:BackupLast) { $script:BackupLast.ToString('o') } else { $null }) })
    try { Write-JsonFile $SettingsFile $json } catch { }
}

function Get-DataPath([string]$Relative) { Join-Path $DataDir $Relative }

function Import-Data {
    if (Test-Path $SettingsFile) {
        try {
            $s = [IO.File]::ReadAllText($SettingsFile, [Text.Encoding]::UTF8) | ConvertFrom-Json
            if ($null -ne $s.Paused)  { $script:Paused = [bool]$s.Paused }
            if ([int]$s.MaxItems -gt 0) { $script:MaxItems = [int]$s.MaxItems }
            if ([double]$s.MaxFileMB -gt 0) { $script:MaxFileMB = [double]$s.MaxFileMB }
            if ([double]$s.MaxTextMB -gt 0) { $script:MaxTextMB = [double]$s.MaxTextMB }
            if ($s.Theme -in 'System', 'Light', 'Dark') { $script:Theme = [string]$s.Theme }
            if ($s.Accent) { $script:Accent = [string]$s.Accent }
            if ($s.TextSize -in 'Small', 'Medium', 'Large') { $script:TextSize = [string]$s.TextSize }
            if ([int]$s.VaultLockMin -gt 0) { $script:VaultLockMin = [int]$s.VaultLockMin }
            if ([int]$s.VaultClearSec -gt 0) { $script:VaultClearSec = [int]$s.VaultClearSec }
            if ($s.BackupDir) { $script:BackupDir = [string]$s.BackupDir }
            if ([int]$s.HostInterval -gt 0) { $script:HostInterval = [int]$s.HostInterval }
            if ($s.SyncDir) { $script:SyncDir = [string]$s.SyncDir }
            if ($s.SyncLast) { try { $script:SyncLast = [datetime]::Parse([string]$s.SyncLast, $null, [Globalization.DateTimeStyles]::RoundtripKind).ToLocalTime() } catch { } }
            if ($null -ne $s.ExpiryRules) { $script:ExpiryRules = @($s.ExpiryRules | ForEach-Object { [string]$_ }) }
            if ($null -ne $s.TimeZones) { $script:TimeZones = @($s.TimeZones | ForEach-Object { [string]$_ }) }
            if ($s.Mouse) { foreach ($p in $s.Mouse.PSObject.Properties) { if ($script:MouseCfg.ContainsKey($p.Name) -and $null -ne $p.Value) { $script:MouseCfg[$p.Name] = $p.Value } } }
            if ($null -ne $s.GitRepos) { $script:GitRepos = @($s.GitRepos | ForEach-Object { [string]$_ } | Where-Object { $_ }) }
            if ($s.Hotkeys) { $script:Hotkeys = @{}; foreach ($p in $s.Hotkeys.PSObject.Properties) { if ($p.Value) { $script:Hotkeys[$p.Name] = [string]$p.Value } } }
            if ($s.Pomodoro) { foreach ($k in 'Work', 'Short', 'Long', 'Every') { if ([int]$s.Pomodoro.$k -gt 0) { $script:Pomodoro[$k] = [int]$s.Pomodoro.$k } } }
            if ($null -ne $s.HostNotify) { $script:HostNotify = [bool]$s.HostNotify }
            if ($null -ne $s.BackupHours) { $script:BackupHours = [int]$s.BackupHours }
            if ([int]$s.BackupKeep -gt 0) { $script:BackupKeep = [int]$s.BackupKeep }
            if ($s.BackupLast) { try { $script:BackupLast = [datetime]::Parse([string]$s.BackupLast, $null, [Globalization.DateTimeStyles]::RoundtripKind).ToLocalTime() } catch { } }
            if ($null -ne $s.IgnoreApps) { $script:IgnoreApps = @($s.IgnoreApps | ForEach-Object { [string]$_ } | Where-Object { $_ }) }
        } catch { }
    }
}

function Import-History {
    if (Test-Path $HistoryFile) {
        try {
            $raw = Read-DataText $HistoryFile
            if ($raw.Trim()) {
                foreach ($x in (ConvertFrom-Json $raw)) {
                    $kind = if ($x.Kind) { [string]$x.Kind } else { 'text' }
                    $item = New-ClipItem $kind ([string]$x.Text) ([bool]$x.Pinned) $x.Time ([string]$x.Id)
                    $item.Source = [string]$x.Source
                    if ($kind -eq 'text') {
                        if ($x.TextFile) {
                            $path = Get-DataPath $x.TextFile
                            if (-not (Test-Path -LiteralPath $path)) { continue }
                            $item.Text = Read-DataText $path
                            $item.TextFile = [string]$x.TextFile
                        }
                        if (-not $item.Text) { continue }
                    } elseif ($kind -eq 'image') {
                        if (-not $x.Image -or -not (Test-Path (Get-DataPath $x.Image))) { continue }
                        $item.Image = [string]$x.Image; $item.Width = [int]$x.Width; $item.Height = [int]$x.Height
                        $item.Hash = [string]$x.Hash; $item.Bytes = [long]$x.Bytes
                    } elseif ($kind -eq 'files') {
                        $item.Files = @($x.Files | Where-Object { $_ -and (Test-Path -LiteralPath (Get-DataPath $_)) })
                        if ($item.Files.Count -eq 0) { continue }
                        $item.Bytes = [long]$x.Bytes
                    } else { continue }
                    $script:Items.Add($item)
                }
            }
        } catch {
            # Keep the unreadable file instead of overwriting it.
            Copy-Item $HistoryFile "$HistoryFile.corrupt-$(Get-Date -Format yyyyMMddHHmmss)" -ErrorAction SilentlyContinue
            return
        }
    }
    # Remove saved images/files that no clip refers to any more.
    $ids = @{}
    foreach ($i in $script:Items) { $ids[$i.Id] = $true }
    Get-ChildItem -LiteralPath $ImagesDir -File -ErrorAction SilentlyContinue |
        Where-Object { -not $ids.ContainsKey($_.BaseName) } | Remove-Item -Force -ErrorAction SilentlyContinue
    Get-ChildItem -LiteralPath $FilesDir -Directory -ErrorAction SilentlyContinue |
        Where-Object { -not $ids.ContainsKey($_.Name) } | Remove-Item -Recurse -Force -ErrorAction SilentlyContinue
    Get-ChildItem -LiteralPath $TextsDir -File -ErrorAction SilentlyContinue |
        Where-Object { -not $ids.ContainsKey($_.BaseName) } | Remove-Item -Force -ErrorAction SilentlyContinue
}

function Limit-History {
    $unpinned = @($script:Items | Where-Object { -not $_.Pinned })
    if ($unpinned.Count -gt $script:MaxItems) {
        foreach ($old in $unpinned[$script:MaxItems..($unpinned.Count - 1)]) { Remove-Clip $old.Id }
    }
}

# Removes a clip and the image/files saved for it.
function Remove-Clip([string]$Id) {
    Add-Tombstone $Id
    for ($n = 0; $n -lt $script:Items.Count; $n++) {
        $i = $script:Items[$n]
        if ($i.Id -ne $Id) { continue }
        $script:Items.RemoveAt($n)
        if ($script:Thumbs.ContainsKey($Id)) { $script:Thumbs[$Id].Dispose(); $script:Thumbs.Remove($Id) }
        $script:LineCache.Remove($Id)
        if ($i.TextFile) { Remove-Item -LiteralPath (Get-DataPath $i.TextFile) -Force -ErrorAction SilentlyContinue }
        if ($i.Kind -eq 'image') { Remove-Item -LiteralPath (Get-DataPath $i.Image) -Force -ErrorAction SilentlyContinue }
        if ($i.Kind -eq 'files') { Remove-Item -LiteralPath (Join-Path $FilesDir $Id) -Recurse -Force -ErrorAction SilentlyContinue }
        return
    }
}

# Moves an existing clip to the top.
function Move-ClipToTop($Item) {
    for ($n = 0; $n -lt $script:Items.Count; $n++) {
        if ($script:Items[$n].Id -eq $Item.Id) { $script:Items.RemoveAt($n); break }
    }
    $Item.Time = Get-Date
    $script:Items.Insert(0, $Item)
}

function Complete-Add($Item, [bool]$IsNew) {
    if ($script:CaptureSource) { $Item.Source = $script:CaptureSource }
    if ($IsNew) { $script:Items.Insert(0, $Item) } else { Move-ClipToTop $Item }
    if ($script:StackCollecting -and -not $script:Syncing) { Add-ToPasteStack $Item }
    Limit-History
    Save-History
    if ($form.Visible) { Update-List }
}

function Find-Clip([string]$Kind, [scriptblock]$Match) {
    foreach ($i in $script:Items) { if ($i.Kind -eq $Kind -and (& $Match $i)) { return $i } }
    $null
}

function Add-ClipText([string]$Text) {
    if ([string]::IsNullOrWhiteSpace($Text)) { return }
    if ($Text.Length -gt $script:MaxTextMB * 1MB) { Write-Log "text skipped: $($Text.Length) chars"; return }
    $existing = Find-Clip 'text' { param($i) $i.Text -ceq $Text }
    if ($existing) { Complete-Add $existing $false } else { Complete-Add (New-ClipItem 'text' $Text) $true }
}

function Add-ClipImage([System.Drawing.Image]$Image) {
    $ms = New-Object System.IO.MemoryStream
    $Image.Save($ms, [System.Drawing.Imaging.ImageFormat]::Png)
    $bytes = $ms.ToArray()
    $ms.Dispose()
    if ($bytes.Length -gt $script:MaxFileMB * 1MB) { Write-Log "image skipped: $($bytes.Length) bytes"; return }
    $sha = [System.Security.Cryptography.SHA1]::Create()
    $hash = [BitConverter]::ToString($sha.ComputeHash($bytes)).Replace('-', '')
    $sha.Dispose()

    $existing = Find-Clip 'image' { param($i) $i.Hash -eq $hash }
    if ($existing) { Complete-Add $existing $false; return }

    $item = New-ClipItem 'image'
    $item.Image  = "images\$($item.Id).png"
    $item.Width  = $Image.Width
    $item.Height = $Image.Height
    $item.Hash   = $hash
    $item.Bytes  = $bytes.Length
    [IO.File]::WriteAllBytes((Get-DataPath $item.Image), $bytes)
    Complete-Add $item $true
}

# Total size of the given files/folders, or -1 as soon as it passes $Limit (or a path can't be read).
function Measure-Paths([string[]]$Paths, [long]$Limit) {
    $total = [long]0
    try {
        foreach ($p in $Paths) {
            if ([IO.File]::Exists($p)) { $total += (New-Object IO.FileInfo $p).Length }
            elseif ([IO.Directory]::Exists($p)) {
                foreach ($f in [IO.Directory]::EnumerateFiles($p, '*', [IO.SearchOption]::AllDirectories)) {
                    $total += (New-Object IO.FileInfo $f).Length
                    if ($total -gt $Limit) { return -1 }
                }
            } else { return -1 }
            if ($total -gt $Limit) { return -1 }
        }
    } catch { return -1 }
    $total
}

function Add-ClipFiles([string[]]$Paths) {
    if (-not $Paths -or $Paths.Count -eq 0) { return }
    $key = $Paths -join "`n"
    $existing = Find-Clip 'files' { param($i) $i.Text -ceq $key }
    if ($existing) { Complete-Add $existing $false; return }

    # Only small files are kept: a saved copy means they still paste after the originals move or are deleted.
    $size = Measure-Paths $Paths ([long]($script:MaxFileMB * 1MB))
    if ($size -lt 0) { Write-Log "files skipped (over $($script:MaxFileMB) MB or unreadable): $key"; return }

    $item = New-ClipItem 'files' $key
    $dir = Join-Path $FilesDir $item.Id
    [void](New-Item -ItemType Directory -Path $dir)
    $saved = @()
    try {
        $n = 0
        foreach ($p in $Paths) {
            $name = Split-Path -Leaf $p
            $destDir = $dir
            if (Test-Path -LiteralPath (Join-Path $dir $name)) {   # same name from two folders
                $n++; $destDir = Join-Path $dir $n
                [void](New-Item -ItemType Directory -Path $destDir -Force)
            }
            Copy-Item -LiteralPath $p -Destination $destDir -Recurse -Force
            $saved += (Join-Path $destDir $name).Substring($DataDir.Length + 1)
        }
    } catch {
        Write-Log "files copy failed: $_"
        Remove-Item -LiteralPath $dir -Recurse -Force -ErrorAction SilentlyContinue
        return
    }
    $item.Files = $saved
    $item.Bytes = $size
    Complete-Add $item $true
}

# Name of the app that owns the clipboard ('' when unknown, or when it is DevTools itself).
function Get-ClipSourceApp {
    try {
        $id = [PowerClipHost]::ClipboardOwnerProcessId()
        if ($id -le 0 -or $id -eq $PID) { return '' }
        return (Get-Process -Id $id -ErrorAction Stop).ProcessName
    } catch { '' }
}

function Add-IgnoredApp([string]$Name) {
    if (-not $Name -or $script:IgnoreApps -contains $Name) { return }
    $script:IgnoreApps = @($script:IgnoreApps) + $Name
    Save-Settings
    if ($SetUI.Form -and -not $SetUI.Form.IsDisposed -and $SetUI.Ignore) { $SetUI.Ignore.Text = ($script:IgnoreApps -join "`r`n") }
}

# Reads the clipboard: files first, then text, then an image.
function Read-Clipboard {
    for ($n = 0; $n -lt 5; $n++) {
        try {
            $d = [System.Windows.Forms.Clipboard]::GetDataObject()
            if ($null -eq $d) { return $null }
            # Password managers mark secrets so clipboard tools skip them.
            if ($d.GetDataPresent('ExcludeClipboardContentFromMonitorProcessing') -or
                $d.GetDataPresent('Clipboard Viewer Ignore')) { return $null }
            if ($d.GetDataPresent([System.Windows.Forms.DataFormats]::FileDrop)) {
                return @{ Kind = 'files'; Files = [string[]]$d.GetData([System.Windows.Forms.DataFormats]::FileDrop) }
            }
            if ($d.GetDataPresent([System.Windows.Forms.DataFormats]::UnicodeText)) {
                return @{ Kind = 'text'; Text = [string]$d.GetData([System.Windows.Forms.DataFormats]::UnicodeText) }
            }
            if ($d.GetDataPresent([System.Windows.Forms.DataFormats]::Text)) {
                return @{ Kind = 'text'; Text = [string]$d.GetData([System.Windows.Forms.DataFormats]::Text) }
            }
            # Prefer the PNG format (keeps transparency); fall back to the plain bitmap.
            if ($d.GetDataPresent('PNG')) {
                $s = $d.GetData('PNG')
                if ($s -is [IO.Stream]) {
                    $tmp = [System.Drawing.Image]::FromStream($s)
                    $bmp = New-Object System.Drawing.Bitmap $tmp
                    $tmp.Dispose()
                    return @{ Kind = 'image'; Image = $bmp }
                }
            }
            if ($d.GetDataPresent([System.Windows.Forms.DataFormats]::Bitmap)) {
                $img = [System.Windows.Forms.Clipboard]::GetImage()
                if ($img) { return @{ Kind = 'image'; Image = $img } }
            }
            return $null
        } catch {
            Start-Sleep -Milliseconds 50   # clipboard is locked by another app, retry
        }
    }
    return $null
}

# ---------------------------------------------------------------------------
# Encrypted data files. One random data key encrypts the clip history (and big texts), API tester data,
# notes, snippets, monitored hosts and colours (AES-256 + HMAC). The key itself is stored twice in
# data\keys.dat: protected by your Windows account (opens silently on this PC) and by the Secrets master
# password (opens anywhere: another PC, another Windows account, a restored backup, someone you trust).
# Pictures, copied files and note attachments are not encrypted.
# ---------------------------------------------------------------------------
$KeysFile = Join-Path $DataDir 'keys.dat'
$script:DataKey = $null           # PowerClipVaultKey for data files, $null = files are plain text
$script:DataKeyBytes = $null
$PlainFiles = @('settings.json', 'keys.dat', 'sync-deleted.json', 'deleted.json', 'debug.log', 'vault.dat')

function Test-ProtectPath([string]$Path) { $script:DataKey -and ($PlainFiles -notcontains (Split-Path -Leaf $Path)) }

# Text of a data file, plain or encrypted.
function Read-DataText([string]$Path) {
    $bytes = [IO.File]::ReadAllBytes($Path)
    if ([PowerClipVault]::IsSealed($bytes)) {
        if (-not $script:DataKey) { throw "$(Split-Path -Leaf $Path) is encrypted and the data key is not unlocked." }
        return [PowerClipVault]::OpenWithKey($bytes, $script:DataKey)
    }
    $text = [Text.Encoding]::UTF8.GetString($bytes)
    if ($text.Length -and $text[0] -eq [char]0xFEFF) { $text = $text.Substring(1) }
    $text
}

function Save-DataKeys([byte[]]$Dek, [string]$Password, [string]$PasswordBlob = '') {
    $o = [ordered]@{
        Version  = 1
        KeyId    = (Get-DataKeyId $Dek)
        Note     = 'DevTools data key. Opens with your Windows account on this PC, or with the Secrets master password anywhere.'
        Windows  = [Convert]::ToBase64String([PowerClipVault]::ProtectForUser($Dek))
        Password = $(if ($Password) { [Convert]::ToBase64String([PowerClipVault]::Seal([Convert]::ToBase64String($Dek), [PowerClipVault]::NewKey($Password))) } else { $PasswordBlob })
    }
    $json = ConvertTo-Json -InputObject $o
    $tmp = "$KeysFile.tmp"
    [IO.File]::WriteAllText($tmp, $json, (New-Object System.Text.UTF8Encoding $false))
    if (Test-Path $KeysFile) { [IO.File]::Replace($tmp, $KeysFile, [NullString]::Value) } else { [IO.File]::Move($tmp, $KeysFile) }
}

function Get-DataKeyId([byte[]]$Dek) {
    $sha = [Security.Cryptography.SHA256]::Create()
    try { -join ($sha.ComputeHash($Dek)[0..7] | ForEach-Object { $_.ToString('x2') }) } finally { $sha.Dispose() }
}

function Use-DataKey([byte[]]$Dek) {
    $script:DataKeyBytes = $Dek
    $script:DataKey = [PowerClipVault]::KeyFromBytes($Dek)
}

# The data key from a keys file: with the Windows account, or with a password ($null when it doesn't open).
function Open-DataKeys([string]$Path, [string]$Password = '') {
    $k = ConvertFrom-Json ([IO.File]::ReadAllText($Path))
    if (-not $Password) {
        try { return ,[PowerClipVault]::UnprotectForUser([Convert]::FromBase64String([string]$k.Windows)) } catch { return $null }
    }
    try { $key = $null; $b64 = [PowerClipVault]::Open([Convert]::FromBase64String([string]$k.Password), $Password, [ref]$key); $key.Dispose(); return ,[Convert]::FromBase64String($b64) } catch { return $null }
}

function Read-PasswordDialog([string]$Title, [string]$Prompt, [switch]$Confirm, [string]$CancelText = 'Cancel') {
    $d = New-Object System.Windows.Forms.Form
    $d.Text = $Title; $d.FormBorderStyle = 'FixedDialog'; $d.MaximizeBox = $false; $d.MinimizeBox = $false; $d.StartPosition = 'CenterScreen'; $d.TopMost = $true
    $d.BackColor = $C.Panel; $d.ForeColor = $C.Fore; $d.Font = $FontMain
    $tbl = New-Object System.Windows.Forms.TableLayoutPanel
    $tbl.Dock = 'Fill'; $tbl.ColumnCount = 1; $tbl.Padding = New-Object System.Windows.Forms.Padding((Px 16))
    $l = New-Object System.Windows.Forms.Label; $l.Text = $Prompt; $l.AutoSize = $true; $l.MaximumSize = New-Object System.Drawing.Size((Px (420 * $TextZoom)), 0)
    $b1 = New-Object System.Windows.Forms.TextBox; $b1.UseSystemPasswordChar = $true; $b1.Dock = 'Fill'; $b1.BorderStyle = 'FixedSingle'; $b1.BackColor = $C.Bg; $b1.ForeColor = $C.Fore
    $b1.Margin = New-Object System.Windows.Forms.Padding(0, (Px 10), 0, (Px 4))
    $tbl.Controls.Add($l); $tbl.Controls.Add($b1)
    $b2 = $null
    if ($Confirm) {
        $l2 = New-Object System.Windows.Forms.Label; $l2.Text = 'Repeat it'; $l2.AutoSize = $true; $l2.ForeColor = $C.Dim
        $b2 = New-Object System.Windows.Forms.TextBox; $b2.UseSystemPasswordChar = $true; $b2.Dock = 'Fill'; $b2.BorderStyle = 'FixedSingle'; $b2.BackColor = $C.Bg; $b2.ForeColor = $C.Fore
        $tbl.Controls.Add($l2); $tbl.Controls.Add($b2)
    }
    $err = New-Object System.Windows.Forms.Label; $err.AutoSize = $true; $err.ForeColor = $C.Red
    $tbl.Controls.Add($err)
    $btns = New-Object System.Windows.Forms.FlowLayoutPanel; $btns.FlowDirection = 'RightToLeft'; $btns.Dock = 'Fill'; $btns.AutoSize = $true
    $cancel = New-Object PowerClipButton; $cancel.Text = $CancelText; $cancel.Font = $FontButton; $cancel.AutoSize = $true; $cancel.DialogResult = 'Cancel'
    $ok = New-Object PowerClipButton; $ok.Text = 'OK'; $ok.Variant = 1; $ok.Font = $FontButton; $ok.AutoSize = $true
    $btns.Controls.AddRange(@($cancel, $ok)); $tbl.Controls.Add($btns)
    $d.Controls.Add($tbl)
    $d.ClientSize = New-Object System.Drawing.Size((Px (460 * $TextZoom)), ($FontMain.Height * $(if ($Confirm) { 9 } else { 7 }) + (Px 70)))
    $d.Tag = @{ B1 = $b1; B2 = $b2; Err = $err; Confirm = [bool]$Confirm }
    $ok.add_Click({
        param($src, $e)
        $t = $src.FindForm().Tag
        if ($t.Confirm) {
            if ($t.B1.Text.Length -lt 8) { $t.Err.Text = 'Use at least 8 characters.'; return }
            if ($t.B1.Text -ne $t.B2.Text) { $t.Err.Text = 'The two passwords are different.'; return }
        } elseif (-not $t.B1.Text) { return }
        $src.FindForm().DialogResult = 'OK'
    })
    $d.AcceptButton = $ok; $d.CancelButton = $cancel
    try { Register-ThemedWindow $d } catch { }
    # DevTools starts with a hidden window style, which Windows applies to the first window shown; show it for real.
    $d.add_Load({ param($src, $e) [void]$src.BeginInvoke([Action]{ [PowerClipHost]::EnsureShown($src.Handle); [void][PowerClipHost]::SetForegroundWindow($src.Handle); $src.Activate() }.GetNewClosure()) })
    $d.add_Shown({ param($src, $e) [PowerClipHost]::EnsureShown($src.Handle); $src.Activate() })
    $script:Modal = $true
    try { $r = $d.ShowDialog() } finally { $script:Modal = $false }
    $pw = $b1.Text
    $d.Dispose()
    if ($r -eq 'OK') { $pw } else { $null }
}

# At start: open the data key (silently with Windows, else ask for the master password).
function Initialize-DataKey {
    if (-not (Test-Path $KeysFile)) { return }
    $dek = Open-DataKeys $KeysFile
    if ($dek) { Use-DataKey $dek; return }
    $msg = "Your DevTools data is encrypted and this Windows account can't open it on its own (another PC, another user, or a restored backup).`n`nEnter the Secrets master password to open it."
    for ($try = 0; $try -lt 5; $try++) {
        $pw = Read-PasswordDialog 'DevTools - encrypted data' $msg -CancelText 'Quit'
        if ($null -eq $pw) { [System.Windows.Forms.MessageBox]::Show('DevTools needs the master password to open your data. It will close now; nothing was changed.', 'DevTools') | Out-Null; [Environment]::Exit(0) }
        $dek = Open-DataKeys $KeysFile $pw
        if ($dek) {
            Use-DataKey $dek
            # from now on this Windows account opens it silently too
            $k = ConvertFrom-Json ([IO.File]::ReadAllText($KeysFile))
            Save-DataKeys $dek '' ([string]$k.Password)
            return
        }
        $msg = 'That password does not open it. Try again (it is the Secrets master password).'
    }
    [Environment]::Exit(0)
}

# Every data file that should be encrypted (or decrypted again).
function Get-ProtectedDataFiles {
    $list = @($HistoryFile, $SnippetsFile, $HostsFile, $ColorsFile, $NotesIndex, $NoteFoldersFile, $QuickFile)
    foreach ($sub in 'texts', 'api', 'notes') {
        $dir = Join-Path $DataDir $sub
        if (Test-Path $dir) { $list += @(Get-ChildItem -LiteralPath $dir -File | Where-Object { $_.Extension -in '.json', '.txt' } | ForEach-Object { $_.FullName }) }
    }
    @($list | Where-Object { $_ -and (Test-Path -LiteralPath $_) } | Sort-Object -Unique)
}

# Rewrites the data files with the current key state ($script:DataKey set = encrypted, $null = plain).
function Convert-DataFiles([object]$ReadKey) {
    $now = $script:DataKey
    $n = 0
    foreach ($f in Get-ProtectedDataFiles) {
        $script:DataKey = $ReadKey; $text = Read-DataText $f
        $script:DataKey = $now; Write-JsonFile $f $text
        $n++
    }
    $n
}

function Enable-DataEncryption($Owner = $null) {
    if ($script:DataKey) { return 'Your data files are already encrypted.' }
    $vaultExists = Test-Path $VaultFile
    if ($vaultExists) {
        $pw = Read-PasswordDialog 'Encrypt data files' 'Enter your Secrets master password. It will also open your data on another PC or for someone you give it to.'
        if ($null -eq $pw) { return 'Cancelled.' }
        try { $k = $null; [void][PowerClipVault]::Open([IO.File]::ReadAllBytes($VaultFile), $pw, [ref]$k); $k.Dispose() } catch { return 'That is not your Secrets master password - nothing was changed.' }
    } else {
        $pw = Read-PasswordDialog 'Encrypt data files' "Choose a master password (at least 8 characters). It opens your data on another PC or for someone you give it to, and it is also the password of Secrets.`nIt cannot be recovered." -Confirm
        if ($null -eq $pw) { return 'Cancelled.' }
        $vk = [PowerClipVault]::NewKey($pw)
        [IO.File]::WriteAllBytes($VaultFile, [PowerClipVault]::Seal('[]', $vk)); $vk.Dispose()
    }
    $dek = New-Object byte[] 64
    $rng = [Security.Cryptography.RandomNumberGenerator]::Create(); $rng.GetBytes($dek); $rng.Dispose()
    try { [void](Invoke-Backup -Quiet) } catch { }
    Save-History; Save-NotesIndex; Save-Snippets
    Save-DataKeys $dek $pw
    Use-DataKey $dek
    foreach ($i in $script:Items) { if ($i.TextFile) { $i.TextDirty = $true } }
    $n = Convert-DataFiles $null
    Save-History
    Write-Log "data encryption on ($n files)"
    "Encrypted $n data files. A backup of the unencrypted data was made first (Settings > Backup)."
}

function Disable-DataEncryption {
    if (-not $script:DataKey) { return 'Your data files are not encrypted.' }
    $key = $script:DataKey
    $script:DataKey = $null
    $n = Convert-DataFiles $key
    foreach ($i in $script:Items) { if ($i.TextFile) { $i.TextDirty = $true } }
    Save-History
    Remove-Item -LiteralPath $KeysFile -Force
    $script:DataKeyBytes = $null
    "Decrypted $n data files; they are plain text again."
}

# The master password changed (Secrets): wrap the data key with the new one.
function Update-DataKeyPassword([string]$NewPassword) {
    if ($script:DataKeyBytes -and (Test-Path $KeysFile)) { Save-DataKeys $script:DataKeyBytes $NewPassword }
}

# Sync with another PC that encrypts with its own key: take that key (needs the master password).
function Use-SyncDataKey {
    if (-not $script:SyncDir) { return 'Choose a sync folder first.' }
    $remote = Join-Path $script:SyncDir 'DevTools-sync\keys.dat'
    if (-not (Test-Path $remote)) { return 'The sync folder has no encryption key yet.' }
    $pw = Read-PasswordDialog 'Use the key from the sync folder' 'Enter the master password used on the other PC.'
    if ($null -eq $pw) { return 'Cancelled.' }
    $dek = Open-DataKeys $remote $pw
    if (-not $dek) { return 'That password does not open the key in the sync folder.' }
    $old = $script:DataKey
    Use-DataKey $dek
    $n = Convert-DataFiles $old
    foreach ($i in $script:Items) { if ($i.TextFile) { $i.TextDirty = $true } }
    Save-History
    Save-DataKeys $dek $pw
    "This PC now uses the same key as the sync folder ($n files re-encrypted)."
}

