[PowerClipTheme]::Scale = [float]$Scale
[PowerClipDiffView]::Zoom = [float]$TextZoom; [PowerClipNoteBlock]::Zoom = [float]$TextZoom
$Glyph = @{     # icon font code points (Segoe Fluent Icons / MDL2 Assets)
