$FontSearch = New-Object System.Drawing.Font($UiFont, (Fz 11))
$FontRowIcon = if ($IconFontName) { New-Object System.Drawing.Font($IconFontName, (Fz 13)) } else { $null }
$FontIconSmall = if ($IconFontName) { New-Object System.Drawing.Font($IconFontName, (Fz 10)) } else { $null }

