# Quick access: round bubbles on the left for the links, files and folders you set up.
# Click opens it; right-click edits; drop a file, folder or link onto the strip to add it.
$QuickFile = Join-Path $DataDir 'quicklinks.json'
$script:QuickLinks = New-Object System.Collections.Generic.List[object]

function Import-QuickLinks {
    $script:QuickLinks.Clear()
    if (-not (Test-Path $QuickFile)) { return }
    try { foreach ($x in @(ConvertFrom-Json (Read-DataText $QuickFile) | ForEach-Object { $_ })) { if ($x.Target) { $script:QuickLinks.Add([pscustomobject]@{ Name = [string]$x.Name; Target = [string]$x.Target }) } } }
    catch { Write-Log "quick links load failed: $_" }
}

function Save-QuickLinks {
    $json = ConvertTo-Json -InputObject @($script:QuickLinks.ToArray() | ForEach-Object { [ordered]@{ Name = $_.Name; Target = $_.Target } }) -Depth 3
    if (-not $json) { $json = '[]' }
    try { Write-JsonFile $QuickFile $json } catch { Write-Log "quick links save failed: $_" }
}

function Test-QuickUrl([string]$T) { $T -match '^(?i)(https?|ftp|mailto|file|ms-[\w-]+|steam|slack|vscode|teams)[:]' }

function Get-QuickName([string]$Target) {
    $t = $Target.Trim().Trim('"')
    if (Test-QuickUrl $t) {
        try { $u = [Uri]$t; if ($u.Host) { return ($u.Host -replace '^www\.', '') } } catch { }
        return $t
    }
    $leaf = Split-Path -Leaf $t.TrimEnd('\')
    if ($leaf) { $leaf } else { $t }
}

function Add-QuickLink([string]$Target, [string]$Name = '') {
    $t = $Target.Trim().Trim('"')
    if (-not $t) { return }
    foreach ($q in $script:QuickLinks) { if ($q.Target -eq $t) { return } }
    $script:QuickLinks.Add([pscustomobject]@{ Name = $(if ($Name) { $Name } else { Get-QuickName $t }); Target = $t })
    Save-QuickLinks
    Update-QuickBar
}

function Open-QuickLink($Q) {
    $t = [Environment]::ExpandEnvironmentVariables($Q.Target)
    if (-not (Test-QuickUrl $t) -and -not (Test-Path -LiteralPath $t)) { $status.Text = "Not found: $t"; $status.ForeColor = $C.Red; return }
    Hide-Picker
    try { Start-Process $t } catch { [void][System.Windows.Forms.MessageBox]::Show("Could not open $t`n$($_.Exception.Message)", 'Quick access') }
}

# A bubble's look: the program / file icon when there is one, else coloured initials.
function Get-QuickIcon([string]$Target) {
    $t = [Environment]::ExpandEnvironmentVariables($Target)
    if (Test-QuickUrl $t) { return $null }
    try {
        if (Test-Path -LiteralPath $t -PathType Leaf) { return [System.Drawing.Icon]::ExtractAssociatedIcon($t).ToBitmap() }
    } catch { }
    $null
}

function Get-QuickColor([string]$Name) {
    $palette = @('#2F80ED', '#9B51E0', '#27AE60', '#EB5757', '#F2994A', '#00A3A3', '#D6457A', '#5B6CFF')
    $h = 0; foreach ($ch in $Name.ToCharArray()) { $h = ($h * 31 + [int]$ch) % 1000003 }
    [System.Drawing.ColorTranslator]::FromHtml($palette[$h % $palette.Count])
}

function Get-QuickInitials([string]$Name) {
    $Name = $Name -replace '\.[A-Za-z]{2,6}$', ''           # github.com -> github
    $w = @($Name -split '[\s._\-/\\:]+' | Where-Object { $_ })
    if ($w.Count -ge 2) { return ("$($w[0][0])$($w[1][0])").ToUpper() }
    if ($Name.Length -ge 2) { return $Name.Substring(0, 2).ToUpper().Substring(0, 1) + $Name.Substring(1, 1).ToLower() }
    $Name.ToUpper()
}

function New-QuickBubble($Q, [switch]$Add) {
    $b = New-Object System.Windows.Forms.Panel
    $b.Size = New-Object System.Drawing.Size((Px 40), (Px 40))
    $b.Margin = New-Object System.Windows.Forms.Padding((Px 8), (Px 4), (Px 8), (Px 4))
    $b.BackColor = $C.Panel; $b.Cursor = 'Hand'
    $b.Tag = @{ Q = $Q; Add = [bool]$Add; Hot = $false; Icon = $(if ($Q) { Get-QuickIcon $Q.Target } else { $null }) }
    $b.GetType().GetProperty('DoubleBuffered', [Reflection.BindingFlags]'Instance, NonPublic').SetValue($b, $true, $null)
    $b.add_Paint({
        param($src, $e)
        $g = $e.Graphics; $g.SmoothingMode = 'AntiAlias'; $g.TextRenderingHint = 'AntiAliasGridFit'
        $t = $src.Tag
        $r = New-Object System.Drawing.RectangleF(1, 1, ($src.Width - 3), ($src.Height - 3))
        if ($t.Add) {
            $pen = New-Object System.Drawing.Pen($(if ($t.Hot) { $C.Accent } else { $C.Line }), [float](Px 1.5)); $pen.DashStyle = 'Dash'
            $g.DrawEllipse($pen, $r); $pen.Dispose()
            $sf = New-Object System.Drawing.StringFormat; $sf.Alignment = 'Center'; $sf.LineAlignment = 'Center'
            $f = if ($FontIconSmall) { $FontIconSmall } else { $FontMain }
            $br = New-Object System.Drawing.SolidBrush $(if ($t.Hot) { $C.Accent } else { $C.Dim })
            $g.DrawString($(if ($FontIconSmall) { $Glyph.Add } else { '+' }), $f, $br, $r, $sf); $br.Dispose()
            return
        }
        $q = $t.Q
        if ($t.Icon) {
            $bg = New-Object System.Drawing.SolidBrush $(if ($t.Hot) { $C.Sel } else { $C.Card })
            $g.FillEllipse($bg, $r); $bg.Dispose()
            $s = Px 22
            $g.InterpolationMode = 'HighQualityBicubic'
            $g.DrawImage($t.Icon, [int](($src.Width - $s) / 2), [int](($src.Height - $s) / 2), $s, $s)
        } else {
            $col = Get-QuickColor $q.Name
            if ($t.Hot) { $col = [PowerClipTheme]::Mix($col, [System.Drawing.Color]::White, 0.18) }
            $bg = New-Object System.Drawing.SolidBrush $col
            $g.FillEllipse($bg, $r); $bg.Dispose()
            $sf = New-Object System.Drawing.StringFormat; $sf.Alignment = 'Center'; $sf.LineAlignment = 'Center'
            $isFolder = -not (Test-QuickUrl $q.Target) -and (Test-Path -LiteralPath ([Environment]::ExpandEnvironmentVariables($q.Target)) -PathType Container)
            if ($FontIconSmall -and $isFolder) { $g.DrawString($Glyph.Folder, $FontIconSmall, [System.Drawing.Brushes]::White, $r, $sf) }
            else {
                $f = New-Object System.Drawing.Font($UiFont, (Fz 9), [System.Drawing.FontStyle]::Bold)
                $g.DrawString((Get-QuickInitials $q.Name), $f, [System.Drawing.Brushes]::White, $r, $sf); $f.Dispose()
            }
        }
        if ($t.Hot) { $pen = New-Object System.Drawing.Pen($C.Accent, [float](Px 2)); $g.DrawEllipse($pen, $r); $pen.Dispose() }
    })
    $b.add_MouseEnter({
        param($src, $e)
        $src.Tag.Hot = $true; $src.Invalidate()
        if ($src.Tag.Add) { $headerTitle.Text = 'Quick access'; $status.Text = 'Add a link, file or folder (or drop one onto this strip)' }
        else { $headerTitle.Text = $src.Tag.Q.Name; $status.Text = "$($src.Tag.Q.Target)   (right-click to edit)" }
        $headerTitle.ForeColor = $C.Accent; $status.ForeColor = $C.Accent
    })
    $b.add_MouseLeave({ param($src, $e) $src.Tag.Hot = $false; $src.Invalidate(); $headerTitle.Text = 'DevTools'; $headerTitle.ForeColor = $C.Fore; Update-Status })
    $b.add_MouseUp({
        param($src, $e)
        if ($src.Tag.Add) { Show-QuickAddMenu $src; return }
        if ($e.Button -eq 'Left') {
            if ([System.Windows.Forms.Control]::ModifierKeys -band [System.Windows.Forms.Keys]::Control) { try { [System.Windows.Forms.Clipboard]::SetText($src.Tag.Q.Target) } catch { }; $status.Text = 'Copied.'; return }
            Open-QuickLink $src.Tag.Q
        }
        elseif ($e.Button -eq 'Right') { Show-QuickMenu $src }
    })
    if ($Q) { $tooltip.SetToolTip($b, $Q.Name) }
    $b
}

function Update-QuickBar {
    if (-not $quickBar) { return }
    $quickBar.SuspendLayout()
    foreach ($c0 in @($quickBar.Controls)) { $quickBar.Controls.Remove($c0); if ($c0.Tag -and $c0.Tag.Icon) { $c0.Tag.Icon.Dispose() }; $c0.Dispose() }
    foreach ($q in $script:QuickLinks) { $quickBar.Controls.Add((New-QuickBubble $q)) }
    $quickBar.Controls.Add((New-QuickBubble $null -Add))
    $quickBar.ResumeLayout()
}

function Show-QuickAddMenu($Bubble) {
    $m = New-Object System.Windows.Forms.ContextMenuStrip -Property @{ Renderer = $MenuRenderer }
    [void](Add-MenuItem $m 'Add a link (URL)...' { $u = Read-TextDialog 'Quick access' 'Link (https://...)' 'https://' $form; if ($u -and $u -ne 'https://') { Add-QuickLink $u } } $Glyph.Globe)
    [void](Add-MenuItem $m 'Add a file...' {
        $d = New-Object System.Windows.Forms.OpenFileDialog; $d.Title = 'File or program for quick access'; $d.Multiselect = $true
        $script:Modal = $true
        try { if ($d.ShowDialog($form) -eq 'OK') { foreach ($f in $d.FileNames) { Add-QuickLink $f } } } finally { $script:Modal = $false; $d.Dispose() }
    } $Glyph.Document)
    [void](Add-MenuItem $m 'Add a folder...' {
        $d = New-Object System.Windows.Forms.FolderBrowserDialog; $d.Description = 'Folder for quick access'
        $script:Modal = $true
        try { if ($d.ShowDialog($form) -eq 'OK') { Add-QuickLink $d.SelectedPath } } finally { $script:Modal = $false; $d.Dispose() }
    } $Glyph.Folder)
    $clip = ''; try { $clip = [System.Windows.Forms.Clipboard]::GetText().Trim() } catch { }
    if ($clip -and $clip.IndexOf("`n") -lt 0 -and ((Test-QuickUrl $clip) -or ($clip.Length -lt 260 -and (Test-Path -LiteralPath $clip.Trim('"'))))) {
        $it = Add-MenuItem $m "Add from the clipboard: $(Get-Preview $clip)" { param($src, $e) Add-QuickLink $src.Tag } $Glyph.Paste
        $it.Tag = $clip
    }
    $m.Show($Bubble, (New-Object System.Drawing.Point($Bubble.Width, 0)))
}

function Show-QuickMenu($Bubble) {
    $q = $Bubble.Tag.Q
    $m = New-Object System.Windows.Forms.ContextMenuStrip -Property @{ Renderer = $MenuRenderer }
    $m.Tag = $q
    [void](Add-MenuItem $m 'Open' { param($src, $e) Open-QuickLink $src.Owner.Tag } $Glyph.Open)
    if (-not (Test-QuickUrl $q.Target)) { [void](Add-MenuItem $m 'Show in Explorer' { param($src, $e) $t = [Environment]::ExpandEnvironmentVariables($src.Owner.Tag.Target); Hide-Picker; Start-Process explorer.exe "/select,`"$t`"" } $Glyph.Folder) }
    [void](Add-MenuItem $m 'Copy link / path' { param($src, $e) try { [System.Windows.Forms.Clipboard]::SetText($src.Owner.Tag.Target) } catch { } } $Glyph.Copy 'Ctrl+click')
    [void](Add-MenuItem $m 'Rename...' { param($src, $e) $x = $src.Owner.Tag; $n = Read-TextDialog 'Quick access' 'Name' $x.Name $form; if ($n) { $x.Name = $n.Trim(); Save-QuickLinks; Update-QuickBar } } $Glyph.Edit)
    [void](Add-MenuItem $m 'Change the link / path...' { param($src, $e) $x = $src.Owner.Tag; $n = Read-TextDialog 'Quick access' 'Link or path' $x.Target $form; if ($n) { $x.Target = $n.Trim().Trim('"'); Save-QuickLinks; Update-QuickBar } } $Glyph.Edit)
    [void]$m.Items.Add('-')
    $i = $script:QuickLinks.IndexOf($q)
    $up = Add-MenuItem $m 'Move up' { param($src, $e) Move-QuickLink $src.Owner.Tag -1 } $Glyph.Undo; $up.Enabled = $i -gt 0
    $dn = Add-MenuItem $m 'Move down' { param($src, $e) Move-QuickLink $src.Owner.Tag 1 } ''; $dn.Enabled = $i -lt $script:QuickLinks.Count - 1
    [void]$m.Items.Add('-')
    [void](Add-MenuItem $m 'Remove' { param($src, $e) [void]$script:QuickLinks.Remove($src.Owner.Tag); Save-QuickLinks; Update-QuickBar } $Glyph.Delete)
    $m.Show($Bubble, (New-Object System.Drawing.Point($Bubble.Width, 0)))
}

function Move-QuickLink($Q, [int]$By) {
    $i = $script:QuickLinks.IndexOf($Q); $j = $i + $By
    if ($i -lt 0 -or $j -lt 0 -or $j -ge $script:QuickLinks.Count) { return }
    $script:QuickLinks.RemoveAt($i); $script:QuickLinks.Insert($j, $Q)
    Save-QuickLinks; Update-QuickBar
}

$quickBar = New-Object System.Windows.Forms.FlowLayoutPanel
$quickBar.Dock = 'Left'; $quickBar.Width = Px 56; $quickBar.FlowDirection = 'TopDown'; $quickBar.WrapContents = $false; $quickBar.AutoScroll = $true
$quickBar.BackColor = $C.Panel; $quickBar.AllowDrop = $true
$quickBar.Padding = New-Object System.Windows.Forms.Padding(0, (Px 8), 0, (Px 8))
