$headerTitle.Dock = 'Left'; $headerTitle.Width = [System.Windows.Forms.TextRenderer]::MeasureText('Compare folders', $FontTitle).Width + (Px 24); $headerTitle.TextAlign = 'MiddleLeft'
$headerTitle.Padding = New-Object System.Windows.Forms.Padding((Px 14), 0, 0, 0)
$headerTitle.BackColor = $C.Panel; $headerTitle.ForeColor = $C.Fore
$tools = New-Object System.Windows.Forms.FlowLayoutPanel
$tools.Dock = 'Right'; $tools.AutoSize = $true; $tools.AutoSizeMode = 'GrowAndShrink'; $tools.WrapContents = $false
$tools.BackColor = $C.Panel
