# Everything the palette can show right now.
function Get-PaletteItems {
    $items = New-Object System.Collections.Generic.List[object]
    foreach ($cx in $script:PaletteCommands) { $items.Add($cx) }
    foreach ($s in $script:Snippets) {
        $items.Add([pscustomobject]@{ Kind = 'Snippet'; Title = $s.Name; Sub = (Get-Preview $s.Text); Icon = $Glyph.Text; Words = ''; Data = $s
                                      Action = { param($it) Invoke-Snippet $it.Data $PalUI.Target } })
    }
    foreach ($n in @($script:Notes | Sort-Object Modified -Descending)) {
        $items.Add([pscustomobject]@{ Kind = 'Note'; Title = (Get-NoteTitle $n); Sub = $(if ($n.Folder) { $n.Folder } else { Format-Age $n.Modified }); Icon = $Glyph.Notes; Words = ''; Data = $n
                                      Action = { param($it) Show-Notes; Open-Note $it.Data; Update-NoteList } })
    }
    if ($ApiUI.Collections.Count -eq 0) { try { Import-ApiData } catch { } }
    foreach ($r in $ApiUI.Collections) {
        $items.Add([pscustomobject]@{ Kind = 'Request'; Title = "$($r.Method) $($r.Name)"; Sub = $(if ($r.Folder) { [string]$r.Folder } else { 'My requests' }); Icon = $Glyph.Globe; Words = [string]$r.Url; Data = $r
                                      Action = { param($it) Show-ApiTester; Set-ApiModel $it.Data -Bind } })
    }
    $k = 0
    foreach ($cx in $script:Items) {
        if ($cx.Kind -ne 'text') { continue }
        if (++$k -gt 40) { break }
        $items.Add([pscustomobject]@{ Kind = 'Clip'; Title = (Get-Preview $cx.Text); Sub = (Format-Age $cx.Time); Icon = $Glyph.Paste; Words = ''; Data = $cx
                                      Action = { param($it) Invoke-PasteText $it.Data.Text $PalUI.Target } })
    }
    $items
}

# Higher is better; -1 = no match. Prefix > word start > anywhere > letters in order (fuzzy).
function Get-PaletteScore([string]$Text, [string]$Query) {
    if (-not $Query) { return 1 }
    $t = $Text.ToLowerInvariant(); $q = $Query.ToLowerInvariant()
    if ($t.StartsWith($q)) { return 1000 - $t.Length }
    $i = $t.IndexOf($q)
    if ($i -gt 0) { if (" -_:/.(".IndexOf($t[$i - 1]) -ge 0) { return 800 - $i } else { return 600 - $i } }
    $words = $q.Split(' ', [StringSplitOptions]::RemoveEmptyEntries)
    if ($words.Count -gt 1) {
        $sum = 0
        foreach ($w in $words) { $ws = Get-PaletteScore $t $w; if ($ws -lt 0) { return -1 }; $sum += [Math]::Min($ws, 700) }
        return [int]($sum / $words.Count)
    }
    $pos = 0; $gaps = 0
    foreach ($ch in $q.ToCharArray()) {
        $j = $t.IndexOf($ch, $pos)
        if ($j -lt 0) { return -1 }
        $gaps += $j - $pos; $pos = $j + 1
    }
    [Math]::Max(1, 300 - $gaps * 5)
}

$KindOrder = @{ Command = 0; Snippet = 1; Note = 2; Request = 3; Clip = 4 }

function Update-PaletteList {
    $q = $PalUI.Box.Text.Trim()
    $scored = foreach ($it in $PalUI.Items) {
        $score = [Math]::Max((Get-PaletteScore $it.Title $q), $(if ($it.Words -and $q) { (Get-PaletteScore $it.Words $q) - 200 } else { -1 }))
        if ($score -lt 0) { continue }
        if (-not $q -and $it.Kind -eq 'Clip') { continue }     # recent clips only when searching
        [pscustomobject]@{ Item = $it; Raw = $score; Score = $score - 50 * $KindOrder[$it.Kind] }
    }
    # Letters-in-order matches only count when nothing contains the text as typed.
    if (@($scored | Where-Object { $_.Raw -ge 500 }).Count -gt 0) { $scored = @($scored | Where-Object { $_.Raw -ge 500 }) }
    $PalUI.View.Clear()
    foreach ($x in @($scored | Sort-Object Score -Descending | Select-Object -First 60)) { $PalUI.View.Add($x.Item) }
    $l = $PalUI.List
    $l.BeginUpdate(); $l.Items.Clear()
    for ($i = 0; $i -lt $PalUI.View.Count; $i++) { [void]$l.Items.Add($i) }
    if ($PalUI.View.Count) { $l.SelectedIndex = 0 }
    $l.EndUpdate()
}

function Invoke-PaletteItem {
    $i = $PalUI.List.SelectedIndex
    if ($i -lt 0 -or $i -ge $PalUI.View.Count) { return }
    $it = $PalUI.View[$i]
    $PalUI.Form.Hide()
    try { & $it.Action $it } catch { Write-Log "palette: $($it.Title): $_" }
}

function Show-Palette([switch]$FromHotkey) {
    $fg = [PowerClipHost]::GetForegroundWindow()
    if ($form.Visible) { $fg = $script:PasteTarget; Hide-Picker }
    if (-not $PalUI.Form -or $PalUI.Form.IsDisposed) { New-PaletteForm }
    if ($fg -ne $PalUI.Form.Handle) { $PalUI.Target = $fg }
    $PalUI.Items = Get-PaletteItems
    $PalUI.Box.Text = ''
    Update-PaletteList
    $scr = [System.Windows.Forms.Screen]::FromPoint([System.Windows.Forms.Cursor]::Position).WorkingArea
    $PalUI.Form.Location = New-Object System.Drawing.Point(($scr.Left + [int](($scr.Width - $PalUI.Form.Width) / 2)), ($scr.Top + [int]($scr.Height * 0.16)))
    $PalUI.Form.Show()
    [PowerClipHost]::EnsureShown($PalUI.Form.Handle)
    $PalUI.Form.Activate()
    [void][PowerClipHost]::SetForegroundWindow($PalUI.Form.Handle)
    [void]$PalUI.Box.Focus()
}

function New-PaletteForm {
    $f = New-Object System.Windows.Forms.Form
    $f.FormBorderStyle = 'None'; $f.ShowInTaskbar = $false; $f.TopMost = $true; $f.StartPosition = 'Manual'; $f.KeyPreview = $true
    $f.Size = New-Object System.Drawing.Size((Px (660 * $TextZoom)), (Px (440 * $TextZoom)))
    $f.BackColor = $C.Line; $f.ForeColor = $C.Fore; $f.Font = $FontMain
    $f.Padding = New-Object System.Windows.Forms.Padding(1)
    $f.Text = 'Command palette'
    $inner = New-Object System.Windows.Forms.Panel
    $inner.Dock = 'Fill'; $inner.BackColor = $C.Bg
    $f.Controls.Add($inner)
    $list = New-Object System.Windows.Forms.ListBox
    $list.Dock = 'Fill'; $list.BorderStyle = 'None'; $list.DrawMode = 'OwnerDrawFixed'; $list.IntegralHeight = $false
    $list.ItemHeight = $FontMain.Height + (Px 18); $list.BackColor = $C.Bg; $list.ForeColor = $C.Fore
    $list.add_DrawItem({
        param($src, $e)
        if ($e.Index -lt 0 -or $e.Index -ge $PalUI.View.Count) { return }
        $it = $PalUI.View[$e.Index]
        $g = $e.Graphics; $r = $e.Bounds
        $sel = ($e.State -band [System.Windows.Forms.DrawItemState]::Selected) -ne 0
        $b = New-Object System.Drawing.SolidBrush $C.Bg; $g.FillRectangle($b, $r); $b.Dispose()
        if ($sel) {
            $g.SmoothingMode = 'AntiAlias'
            $p = [PowerClipTheme]::Round((New-Object System.Drawing.RectangleF(($r.X + (Px 6)), ($r.Y + 1), ($r.Width - (Px 12)), ($r.Height - 2))), (Px 6))
            $b = New-Object System.Drawing.SolidBrush $C.Sel; $g.FillPath($b, $p); $b.Dispose(); $p.Dispose()
            $g.SmoothingMode = 'Default'
        }
        $x = $r.X + (Px 16)
        if ($FontIconSmall -and $it.Icon) {
            [System.Windows.Forms.TextRenderer]::DrawText($g, $it.Icon, $FontIconSmall, (New-Object System.Drawing.Rectangle($x, $r.Y, (Px 22), $r.Height)), $(if ($sel) { $C.Accent } else { $C.Dim }),
                [System.Windows.Forms.TextFormatFlags]'VerticalCenter, HorizontalCenter, NoPrefix, SingleLine, NoPadding')
            $x += Px 32
        }
        $kind = if ($it.Kind -eq 'Command') { $it.Sub } else { $it.Kind.ToLower() }
        $kw = if ($kind) { [System.Windows.Forms.TextRenderer]::MeasureText($kind, $FontSmall).Width + (Px 10) } else { 0 }
        $subText = if ($it.Kind -ne 'Command') { $it.Sub } else { '' }
        $titleW = [System.Windows.Forms.TextRenderer]::MeasureText($it.Title, $FontMain).Width
        $avail = $r.Right - $x - $kw - (Px 18)
        $tw = [Math]::Min($titleW, $avail)
        [System.Windows.Forms.TextRenderer]::DrawText($g, $it.Title, $FontMain, (New-Object System.Drawing.Rectangle($x, $r.Y, $tw, $r.Height)), $C.Fore, $TextFlags)
        if ($subText -and $avail - $tw -gt (Px 40)) {
            [System.Windows.Forms.TextRenderer]::DrawText($g, $subText, $FontSmall, (New-Object System.Drawing.Rectangle(($x + $tw + (Px 12)), $r.Y, ($avail - $tw - (Px 12)), $r.Height)), $C.Dim, $TextFlags)
        }
        if ($kind) { [System.Windows.Forms.TextRenderer]::DrawText($g, $kind, $FontSmall, (New-Object System.Drawing.Rectangle(($r.Right - $kw - (Px 12)), $r.Y, $kw, $r.Height)), $C.Dim, $TextFlags) }
    })
    $list.add_DoubleClick({ Invoke-PaletteItem })
    $inner.Controls.Add($list)
    $hint = New-Object System.Windows.Forms.Label
    $hint.Dock = 'Bottom'; $hint.Height = $FontSmall.Height + (Px 12); $hint.Font = $FontSmall; $hint.ForeColor = $C.Dim; $hint.BackColor = $C.Panel
    $hint.TextAlign = 'MiddleLeft'; $hint.Padding = New-Object System.Windows.Forms.Padding((Px 12), 0, 0, 0)
    $hint.Text = "Enter run   $Dot   Up / Down choose   $Dot   Esc close   $Dot   tools, actions, snippets, notes, API requests and recent clips"
    $inner.Controls.Add($hint)
    $boxWrap = New-Object System.Windows.Forms.Panel
    $boxWrap.Dock = 'Top'; $boxWrap.Height = $FontSearch.Height + (Px 30); $boxWrap.BackColor = $C.Bg
    $boxWrap.Padding = New-Object System.Windows.Forms.Padding((Px 18), (Px 14), (Px 14), (Px 6))
    $box = New-Object System.Windows.Forms.TextBox
    $box.Dock = 'Fill'; $box.BorderStyle = 'None'; $box.BackColor = $C.Bg; $box.ForeColor = $C.Fore
    $box.Font = New-Object System.Drawing.Font($UiFont, (Fz 13))
    $box.add_HandleCreated({ param($src, $e) [PowerClipHost]::SetCueBanner($src.Handle, 'Type a command, note, snippet or clip...') })
    $box.add_TextChanged({ Update-PaletteList })
    $boxWrap.Controls.Add($box)
    $boxWrap.add_Paint({ param($src, $e) $e.Graphics.DrawLine($LinePen, 0, ($src.Height - 1), $src.Width, ($src.Height - 1)) })
    $inner.Controls.Add($boxWrap)
    $PalUI.Box = $box; $PalUI.List = $list; $PalUI.Form = $f
    $f.add_KeyDown({
        param($src, $e)
        $l = $PalUI.List
        switch ($e.KeyCode) {
            'Escape' { $PalUI.Form.Hide(); $e.SuppressKeyPress = $true }
            'Return' { Invoke-PaletteItem; $e.SuppressKeyPress = $true }
            'Down'   { if ($l.SelectedIndex -lt $l.Items.Count - 1) { $l.SelectedIndex++ }; $e.SuppressKeyPress = $true }
            'Up'     { if ($l.SelectedIndex -gt 0) { $l.SelectedIndex-- }; $e.SuppressKeyPress = $true }
            'PageDown' { $l.SelectedIndex = [Math]::Min($l.Items.Count - 1, $l.SelectedIndex + 8); $e.SuppressKeyPress = $true }
            'PageUp' { $l.SelectedIndex = [Math]::Max(0, $l.SelectedIndex - 8); $e.SuppressKeyPress = $true }
        }
    })
    $f.add_Deactivate({ if (-not $script:Modal) { $PalUI.Form.Hide() } })
    $f.add_HandleCreated({ param($src, $e) [PowerClipTheme]::RoundCorners($src.Handle) })
    Register-ThemedWindow $f
}

# ---------------------------------------------------------------------------
# Markdown to HTML, code colouring, number bases, environment variables (Toolbox pages and Notes).
# ---------------------------------------------------------------------------
if (-not ('DevMarkdown' -as [type])) {
    Add-Type -ReferencedAssemblies System.Core, System.Numerics, System.Windows.Forms, System.Drawing -TypeDefinition @'
using System;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;
using System.Net;
using System.Numerics;
using System.Runtime.InteropServices;
using System.Text;
using System.Text.RegularExpressions;
using Microsoft.Win32;

// ---- Code colouring: token ranges for a language (used by the Markdown preview and by Notes) ----------
public static class DevCode {
    // kinds: 1 keyword, 2 string, 3 comment, 4 number, 5 type / tag / attribute name
    public const int Keyword = 1, Str = 2, Comment = 3, Number = 4, Type = 5;

    static readonly Dictionary<string, string> Aliases = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase) {
        {"cs","cs"},{"csharp","cs"},{"c#","cs"},{"js","js"},{"javascript","js"},{"jsx","js"},{"ts","js"},{"typescript","js"},{"tsx","js"},
        {"java","java"},{"kotlin","java"},{"kt","java"},{"c","c"},{"cpp","c"},{"c++","c"},{"h","c"},{"go","go"},{"rust","rust"},{"rs","rust"},
        {"py","py"},{"python","py"},{"ps","ps"},{"ps1","ps"},{"powershell","ps"},{"pwsh","ps"},{"sql","sql"},{"json","json"},
        {"xml","xml"},{"html","xml"},{"htm","xml"},{"xaml","xml"},{"svg","xml"},{"csproj","xml"},{"sh","sh"},{"bash","sh"},{"shell","sh"},{"zsh","sh"},
        {"yaml","yaml"},{"yml","yaml"},{"css","css"},{"scss","css"},{"php","php"},{"rb","rb"},{"ruby","rb"},{"swift","java"},{"dart","java"},
        {"bat","bat"},{"cmd","bat"},{"ini","ini"},{"toml","ini"},{"dockerfile","sh"}
    };

    static readonly Dictionary<string, string> Words = new Dictionary<string, string> {
        {"cs", "abstract as base bool break byte case catch char checked class const continue decimal default delegate do double else enum event explicit extern false finally fixed float for foreach goto if implicit in int interface internal is lock long namespace new null object operator out override params private protected public readonly ref return sbyte sealed short sizeof stackalloc static string struct switch this throw true try typeof uint ulong unchecked unsafe ushort using var virtual void volatile while async await yield get set value where record init dynamic nameof"},
        {"js", "break case catch class const continue debugger default delete do else export extends false finally for function if import in instanceof let new null return super switch this throw true try typeof undefined var void while with yield async await of static get set interface type enum implements private public protected readonly as from"},
        {"java", "abstract assert boolean break byte case catch char class const continue default do double else enum extends final finally float for goto if implements import instanceof int interface long native new null package private protected public return short static strictfp super switch synchronized this throw throws transient true false try void volatile while var val fun when object companion data sealed override open internal lateinit let func struct guard"},
        {"c", "auto break case char const continue default do double else enum extern float for goto if inline int long register restrict return short signed sizeof static struct switch typedef union unsigned void volatile while bool true false nullptr class namespace template typename public private protected virtual override new delete this using include define ifdef ifndef endif pragma"},
        {"go", "break case chan const continue default defer else fallthrough for func go goto if import interface map package range return select struct switch type var nil true false string int int64 float64 bool error byte rune"},
        {"rust", "as async await break const continue crate dyn else enum extern false fn for if impl in let loop match mod move mut pub ref return self Self static struct super trait true type unsafe use where while i32 i64 u8 u32 u64 usize f64 bool str String Vec Option Some None Result Ok Err"},
        {"py", "and as assert async await break class continue def del elif else except False finally for from global if import in is lambda None nonlocal not or pass raise return True try while with yield self print len range"},
        {"ps", "begin break catch class continue data default do dynamicparam else elseif end exit filter finally for foreach from function if in param process return switch throw trap try until using var while workflow -eq -ne -gt -ge -lt -le -like -notlike -match -notmatch -contains -notcontains -in -notin -and -or -not -is -isnot -as -replace -split -join -f $true $false $null"},
        {"sql", "select from where and or not in is null like between exists join inner left right full outer cross on group by order having limit offset top distinct as union all insert into values update set delete create table view index alter drop add column primary key foreign references default case when then else end asc desc with returning begin commit rollback transaction declare exec execute procedure function return if while merge using int varchar nvarchar char text date datetime bit decimal float bigint count sum avg min max coalesce cast convert"},
        {"sh", "if then else elif fi for while until do done case esac function return in local export echo exit set unset source alias cd sudo true false readonly shift"},
        {"php", "abstract and array as break callable case catch class clone const continue declare default do echo else elseif empty enddeclare endfor endforeach endif endswitch endwhile extends final finally fn for foreach function global goto if implements include instanceof interface isset list match namespace new null or print private protected public require return static switch throw trait try unset use var while yield true false"},
        {"rb", "alias and begin break case class def defined do else elsif end ensure false for if in module next nil not or redo rescue retry return self super then true undef unless until when while yield puts require attr_accessor"},
        {"bat", "echo set if else goto call exit for in do not exist defined errorlevel rem setlocal endlocal pause shift start cd copy del move"},
        {"css", "important"}
    };

    public static string Normalize(string lang) {
        string l; if (lang == null) return "";
        return Aliases.TryGetValue(lang.Trim(), out l) ? l : "";
    }

    // Guesses the language of a bit of code (for notes without a language).
    public static string Guess(string code) {
        string t = (code ?? "").TrimStart();
        if (t.StartsWith("{") || t.StartsWith("[")) return "json";
        if (t.StartsWith("<")) return "xml";
        if (Regex.IsMatch(t, @"^(?i)(select|insert|update|delete|create|alter|with)\b")) return "sql";
        if (Regex.IsMatch(code, @"\$\w+\s*=|\bfunction\s+\w+-\w+|\bparam\s*\(|-eq\b|Write-Host|Get-\w+")) return "ps";
        if (Regex.IsMatch(code, @"^\s*(def |import |from \w+ import|class \w+:)", RegexOptions.Multiline)) return "py";
        if (Regex.IsMatch(code, @"^#!.*sh|^\s*(echo|export|sudo) ", RegexOptions.Multiline)) return "sh";
        if (Regex.IsMatch(code, @"\b(public|private|namespace|using System)\b")) return "cs";
        if (Regex.IsMatch(code, @"\b(const|let|function|=>|console\.)")) return "js";
        return "";
    }

    public static List<int[]> Tokens(string code, string lang) {
        var list = new List<int[]>();
        code = code ?? "";
        lang = Normalize(lang);
        if (lang == "") lang = Guess(code);
        if (lang == "") return list;
        if (lang == "xml") { XmlTokens(code, list); return list; }
        string comment, str;
        switch (lang) {
            case "py": comment = @"#[^\n]*"; str = "\"\"\"[\\s\\S]*?\"\"\"|'''[\\s\\S]*?'''|[rbf]?\"(?:\\\\.|[^\"\\\\\\n])*\"|[rbf]?'(?:\\\\.|[^'\\\\\\n])*'"; break;
            case "ps": comment = @"<#[\s\S]*?#>|#[^\n]*"; str = "@\"[\\s\\S]*?\"@|@'[\\s\\S]*?'@|\"(?:`.|[^\"`])*\"|'(?:''|[^'])*'"; break;
            case "sql": comment = @"--[^\n]*|/\*[\s\S]*?\*/"; str = "'(?:''|[^'])*'"; break;
            case "sh": comment = @"(?<![\w$])#[^\n]*"; str = "\"(?:\\\\.|[^\"\\\\])*\"|'[^']*'"; break;
            case "rb": comment = @"#[^\n]*"; str = "\"(?:\\\\.|[^\"\\\\])*\"|'(?:\\\\.|[^'\\\\])*'"; break;
            case "bat": comment = @"(?im)^\s*(rem\b|::)[^\n]*"; str = "\"[^\"\\n]*\""; break;
            case "yaml": comment = @"(?<!\S)#[^\n]*"; str = "\"(?:\\\\.|[^\"\\\\])*\"|'(?:''|[^'])*'"; break;
            case "ini": comment = @"(?m)^\s*[;#][^\n]*"; str = "\"(?:\\\\.|[^\"\\\\])*\""; break;
            case "json": comment = @"//[^\n]*"; str = "\"(?:\\\\.|[^\"\\\\])*\""; break;
            case "css": comment = @"/\*[\s\S]*?\*/"; str = "\"(?:\\\\.|[^\"\\\\])*\"|'(?:\\\\.|[^'\\\\])*'"; break;
            case "rust": comment = @"//[^\n]*|/\*[\s\S]*?\*/"; str = "r#*\"[\\s\\S]*?\"#*|\"(?:\\\\.|[^\"\\\\])*\"|'(?:\\\\.|[^'\\\\])'"; break;
            case "cs": comment = @"//[^\n]*|/\*[\s\S]*?\*/"; str = "@\"(?:\"\"|[^\"])*\"|\\$?\"(?:\\\\.|[^\"\\\\\\n])*\"|'(?:\\\\.|[^'\\\\])'"; break;
            case "js": comment = @"//[^\n]*|/\*[\s\S]*?\*/"; str = "`(?:\\\\.|[^`\\\\])*`|\"(?:\\\\.|[^\"\\\\\\n])*\"|'(?:\\\\.|[^'\\\\\\n])*'"; break;
            default: comment = @"//[^\n]*|/\*[\s\S]*?\*/|#[^\n]*"; str = "\"(?:\\\\.|[^\"\\\\\\n])*\"|'(?:\\\\.|[^'\\\\\\n])*'"; break;
        }
        if (lang == "php" || lang == "c" || lang == "go" || lang == "java") comment = @"//[^\n]*|/\*[\s\S]*?\*/" + (lang == "php" ? @"|#[^\n]*" : "") + (lang == "c" ? @"|^\s*#\s*\w+" : "");
        string word = lang == "ps" ? @"\$[\w:]+|-[a-zA-Z]+\b|\b[\w-]+\b" : @"\$?\b[A-Za-z_][\w]*\b";
        string pattern = "(?<c>" + comment + ")|(?<s>" + str + ")|(?<n>\\b(?:0x[0-9a-fA-F]+|\\d+(?:\\.\\d+)?(?:[eE][+-]?\\d+)?)\\b)|(?<w>" + word + ")";
        if (lang == "yaml") pattern = "(?<c>" + comment + ")|(?<s>" + str + ")|(?<k>(?m)^\\s*-?\\s*[\\w.-]+(?=\\s*:))|(?<n>\\b\\d+(?:\\.\\d+)?\\b|\\b(?:true|false|null|yes|no)\\b)";
        if (lang == "json") pattern = "(?<k>\"(?:\\\\.|[^\"\\\\])*\"(?=\\s*:))|(?<s>" + str + ")|(?<n>-?\\b\\d+(?:\\.\\d+)?(?:[eE][+-]?\\d+)?\\b|\\b(?:true|false|null)\\b)|(?<c>" + comment + ")";
        if (lang == "css") pattern = "(?<c>" + comment + ")|(?<s>" + str + ")|(?<k>[\\w-]+(?=\\s*:[^{]*[;}]))|(?<t>[.#]?[\\w-]+(?=[^{}]*\\{))|(?<n>#[0-9a-fA-F]{3,8}\\b|\\b\\d+(?:\\.\\d+)?(?:px|em|rem|%|s|ms|vh|vw)?\\b)";
        if (lang == "ini") pattern = "(?<c>" + comment + ")|(?<t>(?m)^\\s*\\[[^\\]\\n]+\\])|(?<k>(?m)^\\s*[\\w.-]+(?=\\s*=))|(?<s>" + str + ")|(?<n>\\b\\d+(?:\\.\\d+)?\\b|\\b(?:true|false)\\b)";
        HashSet<string> kw = null;
        string w;
        if (Words.TryGetValue(lang, out w)) kw = new HashSet<string>(w.Split(' '), lang == "sql" || lang == "ps" || lang == "bat" ? StringComparer.OrdinalIgnoreCase : StringComparer.Ordinal);
        RegexOptions opts = RegexOptions.Multiline;
        foreach (Match m in Regex.Matches(code, pattern, opts)) {
            if (m.Groups["c"].Success) list.Add(new[] { m.Index, m.Length, Comment });
            else if (m.Groups["s"].Success) list.Add(new[] { m.Index, m.Length, Str });
            else if (m.Groups["n"].Success) list.Add(new[] { m.Index, m.Length, Number });
            else if (m.Groups["k"].Success) list.Add(new[] { m.Index, m.Length, Keyword });
            else if (m.Groups["t"].Success) list.Add(new[] { m.Index, m.Length, Type });
            else if (m.Groups["w"].Success) {
                string v = m.Value;
                if (kw != null && kw.Contains(v)) list.Add(new[] { m.Index, m.Length, Keyword });
                else if (lang == "ps" && v.StartsWith("$")) list.Add(new[] { m.Index, m.Length, Type });
                else if (lang == "ps" && Regex.IsMatch(v, @"^[A-Z][a-z]+-[A-Z]\w+$")) list.Add(new[] { m.Index, m.Length, Keyword });
                else if (lang != "sql" && v.Length > 1 && char.IsUpper(v[0]) && lang != "ps" && lang != "sh" && lang != "bat") list.Add(new[] { m.Index, m.Length, Type });
            }
        }
        return list;
    }

    static void XmlTokens(string code, List<int[]> list) {
        foreach (Match m in Regex.Matches(code, @"(?<c><!--[\s\S]*?-->)|(?<d><!\[CDATA\[[\s\S]*?\]\]>)|<(?<t>[/?!]?[\w:.-]+)(?<a>(?:\s+[\w:.-]+(?:\s*=\s*(?:""[^""]*""|'[^']*'|[^\s>]+))?)*)\s*/?\??>")) {
            if (m.Groups["c"].Success) { list.Add(new[] { m.Index, m.Length, Comment }); continue; }
            if (m.Groups["d"].Success) { list.Add(new[] { m.Index, m.Length, Str }); continue; }
            Group t = m.Groups["t"];
            list.Add(new[] { t.Index, t.Length, Keyword });
            Group a = m.Groups["a"];
            foreach (Match am in Regex.Matches(a.Value, @"([\w:.-]+)(?:\s*=\s*(""[^""]*""|'[^']*'|[^\s>]+))?")) {
                list.Add(new[] { a.Index + am.Groups[1].Index, am.Groups[1].Length, Type });
                if (am.Groups[2].Success) list.Add(new[] { a.Index + am.Groups[2].Index, am.Groups[2].Length, Str });
            }
        }
    }

    // HTML with <span class="k|s|c|n|t"> around the tokens.
    public static string Html(string code, string lang) {
        code = (code ?? "").Replace("\r\n", "\n");
        var sb = new StringBuilder();
        int pos = 0;
        string[] cls = { "", "k", "s", "c", "n", "t" };
        foreach (int[] t in Tokens(code, lang)) {
            if (t[0] < pos) continue;
            sb.Append(WebUtility.HtmlEncode(code.Substring(pos, t[0] - pos)));
            sb.Append("<span class=\"").Append(cls[t[2]]).Append("\">").Append(WebUtility.HtmlEncode(code.Substring(t[0], t[1]))).Append("</span>");
            pos = t[0] + t[1];
        }
        sb.Append(WebUtility.HtmlEncode(code.Substring(pos)));
        return sb.ToString();
    }
}

// ---- Markdown to HTML (CommonMark-ish: headings, lists, task lists, quotes, code, tables, links, images) ----
public static class DevMarkdown {
    public static string Page(string md, string title, bool dark) {
        string css = dark
            ? "body{background:#1e1f22;color:#dcdcdc}a{color:#6cb6ff}code,pre{background:#2b2d31}th,td{border-color:#444}blockquote{color:#aaa;border-color:#555}hr{border-color:#444}.k{color:#c586c0}.s{color:#ce9178}.c{color:#6a9955}.n{color:#b5cea8}.t{color:#4ec9b0}"
            : "body{background:#fff;color:#1f2328}a{color:#0969da}code,pre{background:#f3f4f6}th,td{border-color:#d0d7de}blockquote{color:#59636e;border-color:#d0d7de}hr{border-color:#d0d7de}.k{color:#8250df}.s{color:#0a3069}.c{color:#6e7781}.n{color:#0550ae}.t{color:#953800}";
        return "<!DOCTYPE html>\n<html><head><meta charset=\"utf-8\"><meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge\"><title>" + WebUtility.HtmlEncode(title ?? "") + "</title>\n<style>" +
            "body{font-family:'Segoe UI',sans-serif;font-size:15px;line-height:1.55;margin:24px 32px;max-width:900px}" +
            "h1,h2{border-bottom:1px solid;border-color:rgba(128,128,128,.3);padding-bottom:.25em}h1,h2,h3,h4{margin:1.2em 0 .5em}" +
            "code{font-family:Consolas,monospace;font-size:13.5px;padding:1px 4px;border-radius:4px}pre{padding:12px 14px;border-radius:6px;overflow:auto}pre code{padding:0;background:none}" +
            "blockquote{margin:0 0 1em;padding:0 1em;border-left:4px solid}table{border-collapse:collapse;margin:0 0 1em}th,td{border:1px solid;padding:5px 12px}th{font-weight:600}" +
            "img{max-width:100%}hr{border:0;border-top:1px solid;margin:1.5em 0}li.task{list-style:none;margin-left:-1.3em}ul,ol{padding-left:1.8em}" + css +
            "</style></head><body>\n" + ToHtml(md) + "\n</body></html>";
    }

    public static string ToHtml(string md) {
        var lines = (md ?? "").Replace("\r\n", "\n").Replace("\r", "\n").Replace("\t", "    ").Split('\n');
        var sb = new StringBuilder();
        Blocks(lines, 0, lines.Length, sb);
        return sb.ToString().TrimEnd();
    }

    static readonly Regex ListItem = new Regex(@"^( {0,3})([-*+]|\d{1,9}[.)])( +|$)(.*)$");
    static readonly Regex Fence = new Regex(@"^ {0,3}(`{3,}|~{3,})\s*([^`\s]*)");
    static readonly Regex Hr = new Regex(@"^ {0,3}((\*\s*){3,}|(-\s*){3,}|(_\s*){3,})$");
    static readonly Regex Heading = new Regex(@"^ {0,3}(#{1,6})(?:\s+(.*?))?\s*#*\s*$");
    static readonly Regex TableSep = new Regex(@"^\s*\|?\s*:?-{2,}:?\s*(\|\s*:?-{2,}:?\s*)*\|?\s*$");

    static void Blocks(string[] L, int from, int to, StringBuilder sb) {
        int i = from;
        var para = new List<string>();
        Action flush = delegate {
            if (para.Count == 0) return;
            var p = new StringBuilder();
            for (int k = 0; k < para.Count; k++) {
                string l = para[k];
                bool br = l.EndsWith("  ") || l.EndsWith("\\");
                p.Append(Inline(l.Trim().TrimEnd('\\')));
                if (k < para.Count - 1) p.Append(br ? "<br>\n" : "\n");
            }
            sb.Append("<p>").Append(p).Append("</p>\n");
            para.Clear();
        };
        while (i < to) {
            string line = L[i];
            if (line.Trim() == "") { flush(); i++; continue; }
            Match m = Fence.Match(line);
            if (m.Success) {
                flush();
                string marker = m.Groups[1].Value, lang = m.Groups[2].Value;
                var code = new StringBuilder();
                i++;
                while (i < to && !L[i].TrimStart().StartsWith(marker)) { code.Append(L[i]).Append('\n'); i++; }
                i++;
                string c = code.ToString().TrimEnd('\n');
                sb.Append("<pre><code").Append(lang != "" ? " class=\"language-" + WebUtility.HtmlEncode(lang) + "\"" : "").Append(">").Append(DevCode.Html(c, lang)).Append("</code></pre>\n");
                continue;
            }
            if (Hr.IsMatch(line) && !(para.Count > 0 && Regex.IsMatch(line, @"^ {0,3}-+\s*$"))) { flush(); sb.Append("<hr>\n"); i++; continue; }
            m = Heading.Match(line);
            if (m.Success) {
                flush();
                int lvl = m.Groups[1].Length;
                sb.Append("<h").Append(lvl).Append(" id=\"").Append(Slug(m.Groups[2].Value)).Append("\">").Append(Inline(m.Groups[2].Value)).Append("</h").Append(lvl).Append(">\n");
                i++; continue;
            }
            // setext headings: text underlined with === or ---
            if (para.Count > 0 && Regex.IsMatch(line, @"^ {0,3}(=+|-+)\s*$")) {
                int lvl = line.Trim()[0] == '=' ? 1 : 2;
                string text = string.Join(" ", para.Select(delegate(string x) { return x.Trim(); }).ToArray());
                para.Clear();
                sb.Append("<h").Append(lvl).Append(">").Append(Inline(text)).Append("</h").Append(lvl).Append(">\n");
                i++; continue;
            }
            if (line.TrimStart().StartsWith(">")) {
                flush();
                var inner = new List<string>();
                while (i < to && L[i].Trim() != "" && (L[i].TrimStart().StartsWith(">") || inner.Count > 0)) {
                    string t = L[i].TrimStart();
                    if (t.StartsWith(">")) { t = t.Substring(1); if (t.StartsWith(" ")) t = t.Substring(1); }
                    inner.Add(t); i++;
                }
                sb.Append("<blockquote>\n");
                Blocks(inner.ToArray(), 0, inner.Count, sb);
                sb.Append("</blockquote>\n");
                continue;
            }
            if (line.Contains("|") && i + 1 < to && TableSep.IsMatch(L[i + 1]) && para.Count == 0) {
                var head = Cells(line);
                var aligns = Cells(L[i + 1]).Select(delegate(string a) { a = a.Trim(); return a.StartsWith(":") && a.EndsWith(":") ? "center" : a.EndsWith(":") ? "right" : a.StartsWith(":") ? "left" : ""; }).ToList();
                sb.Append("<table>\n<thead><tr>");
                for (int k = 0; k < head.Count; k++) sb.Append("<th").Append(Align(aligns, k)).Append(">").Append(Inline(head[k].Trim())).Append("</th>");
                sb.Append("</tr></thead>\n<tbody>\n");
                i += 2;
                while (i < to && L[i].Trim() != "" && L[i].Contains("|")) {
                    var cells = Cells(L[i]);
                    sb.Append("<tr>");
                    for (int k = 0; k < head.Count; k++) sb.Append("<td").Append(Align(aligns, k)).Append(">").Append(k < cells.Count ? Inline(cells[k].Trim()) : "").Append("</td>");
                    sb.Append("</tr>\n");
                    i++;
                }
                sb.Append("</tbody></table>\n");
                continue;
            }
            m = ListItem.Match(line);
            if (m.Success && (para.Count == 0 || m.Groups[4].Value.Trim() != "")) {
                flush();
                bool ordered = char.IsDigit(m.Groups[2].Value[0]);
                int start = ordered ? int.Parse(m.Groups[2].Value.TrimEnd('.', ')')) : 1;
                sb.Append(ordered ? (start != 1 ? "<ol start=\"" + start + "\">\n" : "<ol>\n") : "<ul>\n");
                while (i < to) {
                    Match im = ListItem.Match(L[i]);
                    if (!im.Success || char.IsDigit(im.Groups[2].Value[0]) != ordered) break;
                    int indent = im.Groups[1].Length + im.Groups[2].Length + Math.Max(1, Math.Min(4, im.Groups[3].Length));
                    var item = new List<string> { im.Groups[4].Value };
                    i++;
                    bool loose = false;
                    while (i < to) {
                        string l = L[i];
                        if (l.Trim() == "") {
                            int k = i + 1; while (k < to && L[k].Trim() == "") k++;
                            // a blank line inside the item: only when the next text is indented under it
                            if (k < to && Lead(L[k]) >= indent) { loose = !ListItem.IsMatch(L[k].Substring(indent)) || loose; item.Add(""); i++; continue; }
                            break;
                        }
                        if (Lead(l) >= Math.Min(indent, 2)) { item.Add(l.Substring(Math.Min(Lead(l), indent))); i++; continue; }
                        if (ListItem.IsMatch(l) || Fence.IsMatch(l) || Heading.IsMatch(l) || l.TrimStart().StartsWith(">") || Hr.IsMatch(l)) break;
                        item.Add(l); i++;   // lazy continuation
                    }
                    string first = item[0];
                    string cls = "";
                    Match task = Regex.Match(first, @"^\[([ xX])\]\s+");
                    if (task.Success) {
                        first = "<input type=\"checkbox\" disabled" + (task.Groups[1].Value != " " ? " checked" : "") + "> " + first.Substring(task.Length);
                        cls = " class=\"task\"";
                    }
                    sb.Append("<li").Append(cls).Append(">");
                    bool simple = !loose && item.Skip(1).All(delegate(string x) { return !ListItem.IsMatch(x) && !Fence.IsMatch(x) && x.Trim() != ""; });
                    if (simple) {
                        sb.Append(task.Success ? first.Substring(0, first.IndexOf('>') + 2) + Inline(first.Substring(first.IndexOf('>') + 2)) : Inline(first));
                        foreach (string x in item.Skip(1)) sb.Append("\n").Append(Inline(x.Trim()));
                    } else {
                        var sub = new StringBuilder();
                        if (task.Success) { item[0] = first.Substring(first.IndexOf('>') + 2); sb.Append(first.Substring(0, first.IndexOf('>') + 2)); }
                        Blocks(item.ToArray(), 0, item.Count, sub);
                        string h = sub.ToString().TrimEnd();
                        if (!loose && h.StartsWith("<p>")) { int e = h.IndexOf("</p>"); h = h.Substring(3, e - 3) + h.Substring(e + 4); }
                        sb.Append(h);
                    }
                    sb.Append("</li>\n");
                    if (i < to && L[i].Trim() == "") { int k = i + 1; while (k < to && L[k].Trim() == "") k++; if (k < to && ListItem.IsMatch(L[k]) && char.IsDigit(ListItem.Match(L[k]).Groups[2].Value[0]) == ordered) i = k; }
                }
                sb.Append(ordered ? "</ol>\n" : "</ul>\n");
                continue;
            }
            if (para.Count == 0 && line.StartsWith("    ")) {     // indented code
                var code = new StringBuilder();
                while (i < to && (L[i].StartsWith("    ") || L[i].Trim() == "")) { code.Append(L[i].Length >= 4 ? L[i].Substring(4) : "").Append('\n'); i++; }
                sb.Append("<pre><code>").Append(WebUtility.HtmlEncode(code.ToString().TrimEnd('\n'))).Append("</code></pre>\n");
                continue;
            }
            if (para.Count == 0 && Regex.IsMatch(line, @"^\s*<(div|table|details|p|img|br|hr|h\d|section|center)\b", RegexOptions.IgnoreCase)) {
                while (i < to && L[i].Trim() != "") { sb.Append(L[i]).Append('\n'); i++; }   // raw HTML block
                continue;
            }
            para.Add(line);
            i++;
        }
        flush();
    }

    static int Lead(string s) { int n = 0; while (n < s.Length && s[n] == ' ') n++; return n; }
    static string Align(List<string> a, int k) { return k < a.Count && a[k] != "" ? " style=\"text-align:" + a[k] + "\"" : ""; }

    static List<string> Cells(string line) {
        string t = line.Trim();
        if (t.StartsWith("|")) t = t.Substring(1);
        if (t.EndsWith("|") && !t.EndsWith("\\|")) t = t.Substring(0, t.Length - 1);
        var cells = new List<string>();
        var cur = new StringBuilder();
        bool code = false;
        for (int i = 0; i < t.Length; i++) {
            char c = t[i];
            if (c == '\\' && i + 1 < t.Length && t[i + 1] == '|') { cur.Append('|'); i++; continue; }
            if (c == '`') code = !code;
            if (c == '|' && !code) { cells.Add(cur.ToString()); cur.Clear(); continue; }
            cur.Append(c);
        }
        cells.Add(cur.ToString());
        return cells;
    }

    public static string Slug(string s) {
        s = Regex.Replace((s ?? "").ToLowerInvariant(), @"[^\w\- ]", "").Trim();
        return Regex.Replace(s, @"\s+", "-");
    }

    // Inline markup. Code spans and links are swapped for placeholders first, so their insides are left alone.
    public static string Inline(string s) {
        var keep = new List<string>();
        Func<string, string> hold = delegate(string html) { keep.Add(html); return "\u0001" + (keep.Count - 1) + "\u0002"; };
        // code spans
        s = Regex.Replace(s, @"(`+)(.+?)\1", delegate(Match m) { return hold("<code>" + WebUtility.HtmlEncode(m.Groups[2].Value.Trim()) + "</code>"); });
        // escaped characters
        s = Regex.Replace(s, @"\\([\\`*_{}\[\]()#+\-.!|~<>])", delegate(Match m) { return hold(WebUtility.HtmlEncode(m.Groups[1].Value)); });
        // autolinks <http://...>
        s = Regex.Replace(s, @"<((?:https?|ftp|mailto):[^\s>]+)>", delegate(Match m) { string u = m.Groups[1].Value; return hold("<a href=\"" + Attr(u) + "\">" + WebUtility.HtmlEncode(u) + "</a>"); });
        // raw inline HTML tags stay as they are
        s = Regex.Replace(s, @"</?(b|i|u|em|strong|kbd|sub|sup|br|span|mark|s|del|small|img)\b[^>]*>", delegate(Match m) { return hold(m.Value); }, RegexOptions.IgnoreCase);
        // images and links
        s = Regex.Replace(s, @"!\[([^\]]*)\]\(\s*<?([^)\s>]+)>?(?:\s+""([^""]*)"")?\s*\)", delegate(Match m) {
            return hold("<img src=\"" + Attr(m.Groups[2].Value) + "\" alt=\"" + Attr(m.Groups[1].Value) + "\"" + (m.Groups[3].Success ? " title=\"" + Attr(m.Groups[3].Value) + "\"" : "") + ">");
        });
        s = Regex.Replace(s, @"\[((?:[^\[\]]|\[[^\]]*\])+)\]\(\s*<?([^)\s>]*)>?(?:\s+""([^""]*)"")?\s*\)", delegate(Match m) {
            return hold("<a href=\"" + Attr(m.Groups[2].Value) + "\"" + (m.Groups[3].Success ? " title=\"" + Attr(m.Groups[3].Value) + "\"" : "") + ">" + Emphasis(WebUtility.HtmlEncode(m.Groups[1].Value)) + "</a>");
        });
        // bare URLs
        s = Regex.Replace(s, @"(?<![""'=\w])(https?://[^\s<]+[^\s<.,;:!?""')\]])", delegate(Match m) { return hold("<a href=\"" + Attr(m.Value) + "\">" + WebUtility.HtmlEncode(m.Value) + "</a>"); });
        s = Emphasis(WebUtility.HtmlEncode(s));
        // put the held pieces back (they may nest)
        for (int pass = 0; pass < 3 && s.IndexOf('\u0001') >= 0; pass++)
            s = Regex.Replace(s, "\u0001(\\d+)\u0002", delegate(Match m) { return keep[int.Parse(m.Groups[1].Value)]; });
        return s;
    }

    static string Emphasis(string s) {
        s = Regex.Replace(s, @"(\*\*|__)(?=\S)(.+?)(?<=\S)\1", "<strong>$2</strong>");
        s = Regex.Replace(s, @"(?<![\w*])\*(?=\S)(.+?)(?<=\S)\*(?!\*)", "<em>$1</em>");
        s = Regex.Replace(s, @"(?<![\w_])_(?=\S)(.+?)(?<=\S)_(?![\w_])", "<em>$1</em>");
        s = Regex.Replace(s, @"~~(?=\S)(.+?)(?<=\S)~~", "<del>$1</del>");
        s = Regex.Replace(s, @"==(?=\S)(.+?)(?<=\S)==", "<mark>$1</mark>");
        return s;
    }

    static string Attr(string s) {
        if (Regex.IsMatch(s.Trim(), @"^(?i)(javascript|vbscript|data):") && !s.Trim().StartsWith("data:image/", StringComparison.OrdinalIgnoreCase)) s = "#";
        return WebUtility.HtmlEncode(s).Replace("\"", "&quot;");
    }
}

// ---- Number bases ------------------------------------------------------------------------------------
public static class DevNum {
    // base 0 = guess from the prefix (0x, 0b, 0o, #, h suffix), else decimal
    public static BigInteger Parse(string s, int b) {
        string t = (s ?? "").Trim().Replace("_", "").Replace(" ", "").Replace(",", "").Replace("'", "");
        bool neg = false;
        if (t.StartsWith("-")) { neg = true; t = t.Substring(1); }
        if (t == "") throw new FormatException("Type a number.");
        if (b == 0) {
            string l = t.ToLowerInvariant();
            if (l.StartsWith("0x")) { b = 16; t = t.Substring(2); }
            else if (l.StartsWith("&h")) { b = 16; t = t.Substring(2); }
            else if (l.StartsWith("#")) { b = 16; t = t.Substring(1); }
            else if (l.StartsWith("0b")) { b = 2; t = t.Substring(2); }
            else if (l.StartsWith("0o")) { b = 8; t = t.Substring(2); }
            else if (l.EndsWith("h") && Regex.IsMatch(l, "^[0-9a-f]+h$")) { b = 16; t = t.Substring(0, t.Length - 1); }
            else if (Regex.IsMatch(l, "[a-f]")) b = 16;
            else b = 10;
        } else {
            string l = t.ToLowerInvariant();
            if (b == 16 && (l.StartsWith("0x") || l.StartsWith("&h"))) t = t.Substring(2);
            else if (b == 16 && l.StartsWith("#")) t = t.Substring(1);
            else if (b == 2 && l.StartsWith("0b")) t = t.Substring(2);
            else if (b == 8 && l.StartsWith("0o")) t = t.Substring(2);
        }
        BigInteger v = BigInteger.Zero;
        foreach (char ch in t.ToLowerInvariant()) {
            int d = ch >= '0' && ch <= '9' ? ch - '0' : ch >= 'a' && ch <= 'z' ? ch - 'a' + 10 : 99;
            if (d >= b) throw new FormatException("'" + ch + "' is not a base-" + b + " digit.");
            v = v * b + d;
        }
        return neg ? -v : v;
    }

    public static string ToBase(BigInteger v, int b) {
        if (v.IsZero) return "0";
        bool neg = v.Sign < 0; if (neg) v = -v;
        var sb = new StringBuilder();
        const string digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ";
        while (!v.IsZero) { sb.Insert(0, digits[(int)(v % b)]); v /= b; }
        return (neg ? "-" : "") + sb;
    }

    static string Group(string s, int n, string sep) {
        var sb = new StringBuilder();
        int first = s.Length % n; if (first == 0) first = n;
        for (int i = 0; i < s.Length; i++) { if (i > 0 && (i - first) % n == 0 && i >= first) sb.Append(sep); sb.Append(s[i]); }
        return sb.ToString();
    }

    // Everything about a number, one "label<TAB>value" per line.
    public static string Describe(string input, int b) {
        BigInteger v = Parse(input, b);
        var sb = new StringBuilder();
        Action<string, string> row = delegate(string k, string x) { sb.Append(k).Append('\t').Append(x).Append('\n'); };
        row("Decimal", v.ToString("N0", CultureInfo.InvariantCulture).Replace(",", " ") + (BigInteger.Abs(v) >= 1000 ? "   (" + v.ToString() + ")" : ""));
        // negative numbers: two's complement in the smallest common width
        BigInteger u = v;
        int width = 0;
        if (v.Sign < 0) {
            foreach (int w in new[] { 8, 16, 32, 64, 128 }) { if (v >= -(BigInteger.One << (w - 1))) { width = w; break; } }
            if (width == 0) throw new FormatException("Too small.");
            u = (BigInteger.One << width) + v;
        }
        string hex = ToBase(u, 16), bin = ToBase(u, 2);
        if (width > 0) { hex = hex.PadLeft(width / 4, 'F'); bin = bin.PadLeft(width, '1'); }
        row("Hex", "0x" + Group(hex.Length % 2 == 1 ? "0" + hex : hex, 2, " ") + (width > 0 ? "   (" + width + "-bit two's complement)" : ""));
        string binP = bin.Length % 4 == 0 ? bin : bin.PadLeft(bin.Length + 4 - bin.Length % 4, width > 0 ? '1' : '0');
        row("Binary", Group(binP, 4, " "));
        row("Octal", "0o" + ToBase(u, 8));
        row("Base 36", ToBase(v, 36));
        int bits = 0; BigInteger t = u; while (!t.IsZero) { bits++; t >>= 1; }
        int ones = bin.Count(delegate(char ch) { return ch == '1'; });
        row("Bits", (v.IsZero ? 0 : bits) + " needed, " + ones + " set");
        if (v.Sign >= 0) {
            foreach (int w in new[] { 8, 16, 32, 64 }) {
                if (v < (BigInteger.One << w) && v >= (BigInteger.One << (w - 1))) row("As signed " + w + "-bit", (v - (BigInteger.One << w)).ToString());
            }
        }
        if (v.Sign >= 0 && v < (BigInteger.One << 64)) {
            ulong x = (ulong)v;
            byte[] le = BitConverter.GetBytes(x);
            int n = 8; while (n > 1 && le[n - 1] == 0) n--;
            if (n == 3) n = 4; else if (n > 4 && n < 8) n = 8;
            row("Bytes (big-endian)", string.Join(" ", le.Take(n).Reverse().Select(delegate(byte y) { return y.ToString("X2"); }).ToArray()));
            row("Bytes (little-endian)", string.Join(" ", le.Take(n).Select(delegate(byte y) { return y.ToString("X2"); }).ToArray()));
            if (x <= 0x10FFFF && (x < 0xD800 || x > 0xDFFF)) {
                string ch = char.ConvertFromUtf32((int)x);
                row("Character", (x < 32 || x == 127 ? "(control character)" : ch) + "   U+" + x.ToString("X4"));
            }
            if (x > 0 && x < 1UL << 40) {
                string[] units = { "bytes", "KB", "MB", "GB", "TB" };
                double d = x; int k = 0; while (d >= 1024 && k < 4) { d /= 1024; k++; }
                if (k > 0) row("As a size", d.ToString("0.##", CultureInfo.InvariantCulture) + " " + units[k] + "  (" + x.ToString("N0", CultureInfo.InvariantCulture) + " bytes)");
            }
            if (x >= 100000000UL && x < 100000000000UL) row("As Unix time", DateTimeOffset.FromUnixTimeSeconds((long)x).ToLocalTime().ToString("yyyy-MM-dd HH:mm:ss zzz"));
            else if (x >= 100000000000UL && x < 100000000000000UL) row("As Unix time (ms)", DateTimeOffset.FromUnixTimeMilliseconds((long)x).ToLocalTime().ToString("yyyy-MM-dd HH:mm:ss.fff zzz"));
            if (x <= 0xFFFFFFFFUL && x > 0xFFFFFF) {
                byte[] ip = BitConverter.GetBytes((uint)x);
                row("As IPv4", ip[3] + "." + ip[2] + "." + ip[1] + "." + ip[0]);
            }
            if (x <= 0xFFFFFFFF && input.Trim().StartsWith("#")) {
                uint c = (uint)x;
                row("As colour", x <= 0xFFFFFF ? "rgb(" + ((c >> 16) & 255) + ", " + ((c >> 8) & 255) + ", " + (c & 255) + ")" : "argb(" + (c >> 24) + ", " + ((c >> 16) & 255) + ", " + ((c >> 8) & 255) + ", " + (c & 255) + ")");
            }
        }
        return sb.ToString().TrimEnd();
    }
}

// ---- Environment variables: read / write the registry directly, keeping %VAR% references ------------
// ---- Mouse mover / clicker: zero-pixel moves (count as activity), clicks, idle time, stay awake ----
public static class DevMouse {
    [StructLayout(LayoutKind.Sequential)] struct MOUSEINPUT { public int dx, dy; public uint mouseData, dwFlags, time; public IntPtr dwExtraInfo; }
    [StructLayout(LayoutKind.Sequential)] struct INPUT { public uint type; public MOUSEINPUT mi; }
    [StructLayout(LayoutKind.Sequential)] struct LASTINPUTINFO { public uint cbSize, dwTime; }
    [StructLayout(LayoutKind.Sequential)] struct POINT { public int X, Y; }
    [DllImport("user32.dll", SetLastError = true)] static extern uint SendInput(uint n, INPUT[] inputs, int size);
    [DllImport("user32.dll")] static extern bool GetLastInputInfo(ref LASTINPUTINFO info);
    [DllImport("user32.dll")] static extern bool GetCursorPos(out POINT p);
    [DllImport("user32.dll")] static extern bool SetCursorPos(int x, int y);
    [DllImport("kernel32.dll")] static extern uint SetThreadExecutionState(uint flags);

    const uint MOVE = 0x1, LEFTDOWN = 0x2, LEFTUP = 0x4, RIGHTDOWN = 0x8, RIGHTUP = 0x10, MIDDLEDOWN = 0x20, MIDDLEUP = 0x40;

    // For testing: count what would be sent instead of sending it.
    public static bool DryRun;
    public static int DryMoves, DryClicks;

    static void Send(params uint[] flags) {
        var a = new INPUT[flags.Length];
        for (int i = 0; i < flags.Length; i++) { a[i].type = 0; a[i].mi.dwFlags = flags[i]; }
        SendInput((uint)a.Length, a, Marshal.SizeOf(typeof(INPUT)));
    }

    static void SendMove(int dx, int dy) {
        var a = new INPUT[1];
        a[0].type = 0; a[0].mi.dwFlags = MOVE; a[0].mi.dx = dx; a[0].mi.dy = dy;
        SendInput(1, a, Marshal.SizeOf(typeof(INPUT)));
    }

    // A relative move; 0, 0 is invisible but Windows (and Teams, Slack ...) count it as activity.
    public static void Move(int dx, int dy) {
        if (DryRun) { DryMoves++; return; }
        SendMove(dx, dy);
    }

    public static void Click(string button, bool twice) {
        if (DryRun) { DryClicks += twice ? 2 : 1; return; }
        uint down = LEFTDOWN, up = LEFTUP;
        if (button == "right") { down = RIGHTDOWN; up = RIGHTUP; }
        else if (button == "middle") { down = MIDDLEDOWN; up = MIDDLEUP; }
        if (twice) Send(down, up, down, up); else Send(down, up);
    }

    // Milliseconds since the last keyboard or mouse input anywhere.
    public static long IdleMs() {
        var li = new LASTINPUTINFO(); li.cbSize = (uint)Marshal.SizeOf(typeof(LASTINPUTINFO));
        if (!GetLastInputInfo(ref li)) return 0;
        return (long)unchecked((uint)Environment.TickCount - li.dwTime);
    }

    public static int[] Cursor() { POINT p; GetCursorPos(out p); return new[] { p.X, p.Y }; }
    public static void SetCursor(int x, int y) { if (!DryRun) SetCursorPos(x, y); }

    // Keeps the PC and the screen from sleeping (or lets them again).
    public static void KeepAwake(bool on) { SetThreadExecutionState(on ? 0x80000003u : 0x80000000u); }
}

// ---- API chains: request cards on a canvas, joined by arrows (drag from a card's right dot to another card) ----
public class ChainNode {
    public string Id = Guid.NewGuid().ToString("N"), Title = "", Method = "GET", Url = "", State = "", Info = "", Cond = "", Jumps = "";
    public bool Save;
    public float X, Y;
    public int Order;
}
public class ChainLink { public string From, To; }

// API chains canvas: cards joined by arrows. Click / Ctrl+click / double-click empty space and drag a box to select;
// drag selected cards together; drag from a card's right dot to another card to link; drag empty space (or wheel) scrolls.
public class DevChainCanvas : System.Windows.Forms.Panel {
    public List<ChainNode> Nodes = new List<ChainNode>();
    public List<ChainLink> Links = new List<ChainLink>();
    public List<ChainNode> Selection = new List<ChainNode>();
    public float UiScale = 1f;
    public System.Drawing.Color Back = System.Drawing.Color.White, GridDot = System.Drawing.Color.Gainsboro, Card = System.Drawing.Color.White,
        Fore = System.Drawing.Color.Black, Dim = System.Drawing.Color.Gray, Line = System.Drawing.Color.Silver, Accent = System.Drawing.Color.RoyalBlue,
        Green = System.Drawing.Color.SeaGreen, Red = System.Drawing.Color.Crimson, Yellow = System.Drawing.Color.Goldenrod;
    ChainNode primary;
    public ChainLink SelectedLink;
    public string RunningId;
    public System.Drawing.PointF Pan = new System.Drawing.PointF(0, 0);
    public float Zoom = 1f;                 // drawing scale; Pan and everything inside are in unzoomed units
    public event EventHandler SelectionChanged, Changed, NodeOpen;

    enum Mode { None, Drag, Link, Pan, Box }
    Mode mode = Mode.None;
    System.Drawing.PointF mouse, panStart, boxStart, dragStart;
    Dictionary<ChainNode, System.Drawing.PointF> dragFrom = new Dictionary<ChainNode, System.Drawing.PointF>();
    System.Drawing.Point downAt;
    ChainNode linkFrom;
    bool moved, boxAdd;

    public DevChainCanvas() {
        SetStyle(System.Windows.Forms.ControlStyles.AllPaintingInWmPaint | System.Windows.Forms.ControlStyles.OptimizedDoubleBuffer |
                 System.Windows.Forms.ControlStyles.UserPaint | System.Windows.Forms.ControlStyles.ResizeRedraw | System.Windows.Forms.ControlStyles.Selectable, true);
        TabStop = true;
    }

    // The card shown in the editor: the last one clicked (null when none, or the selection is empty).
    public ChainNode SelectedNode {
        get { return primary != null && Selection.Contains(primary) ? primary : (Selection.Count > 0 ? Selection[Selection.Count - 1] : null); }
        set { Selection.Clear(); primary = value; if (value != null) Selection.Add(value); SelectedLink = null; Invalidate(); }
    }

    float S(float v) { return v * UiScale; }
    public float NodeW { get { return S(240); } }
    public float NodeH { get { return S(74); } }

    public System.Drawing.PointF ToCanvas(System.Drawing.Point p) { return new System.Drawing.PointF(p.X / Zoom - Pan.X, p.Y / Zoom - Pan.Y); }
    System.Drawing.PointF V(int x, int y) { return new System.Drawing.PointF(x / Zoom, y / Zoom); }   // mouse pixels -> unzoomed

    // Zoom to z, keeping the point under the given pixel (default: the middle) where it is.
    public void SetZoom(float z) { SetZoom(z, new System.Drawing.Point(Width / 2, Height / 2)); }
    public void SetZoom(float z, System.Drawing.Point at) {
        z = Math.Max(0.25f, Math.Min(2.5f, z));
        if (Math.Abs(z - 1f) < 0.04f) z = 1f;
        float wx = at.X / Zoom - Pan.X, wy = at.Y / Zoom - Pan.Y;
        Zoom = z;
        Pan = new System.Drawing.PointF(at.X / Zoom - wx, at.Y / Zoom - wy);
        Invalidate();
    }

    // Shows every card (never bigger than 100%).
    public void ZoomToFit() {
        if (Nodes.Count == 0) { Zoom = 1f; Pan = new System.Drawing.PointF(0, 0); Invalidate(); return; }
        float x0 = Nodes.Min(n => n.X), y0 = Nodes.Min(n => n.Y), x1 = Nodes.Max(n => n.X) + NodeW, y1 = Nodes.Max(n => n.Y) + NodeH + S(80);
        float m = S(30);
        float z = Math.Min((Width - 2 * m) / Math.Max(1f, x1 - x0), (Height - 2 * m) / Math.Max(1f, y1 - y0));
        Zoom = Math.Max(0.25f, Math.Min(1f, z));
        Pan = new System.Drawing.PointF((Width / Zoom - (x1 - x0)) / 2 - x0, (Height / Zoom - (y1 - y0)) / 2 - y0);
        Invalidate();
    }

    // The zoom buttons in the bottom-right corner (pixels): out, percentage (= 100%), in, fit.
    System.Drawing.RectangleF[] ZoomButtons() {
        float h = S(28), y = Height - h - S(10), x = Width - S(10);
        float[] w = { S(40), S(30), S(58), S(30) };     // fit, +, %, - (right to left)
        var r = new System.Drawing.RectangleF[4];
        for (int i = 0; i < 4; i++) { x -= w[i]; r[3 - i] = new System.Drawing.RectangleF(x, y, w[i], h); }
        return r;                                         // [0] -, [1] %, [2] +, [3] fit
    }
    bool ZoomClick(System.Drawing.Point p) {
        var b = ZoomButtons();
        if (b[0].Contains(p)) SetZoom(Zoom / 1.2f);
        else if (b[1].Contains(p)) SetZoom(1f);
        else if (b[2].Contains(p)) SetZoom(Zoom * 1.2f);
        else if (b[3].Contains(p)) ZoomToFit();
        else return false;
        return true;
    }
    System.Drawing.RectangleF Box(ChainNode n) { return new System.Drawing.RectangleF(n.X + Pan.X, n.Y + Pan.Y, NodeW, NodeH); }
    System.Drawing.PointF OutPort(ChainNode n) { var r = Box(n); return new System.Drawing.PointF(r.Right, r.Y + r.Height / 2); }
    System.Drawing.PointF InPort(ChainNode n) { var r = Box(n); return new System.Drawing.PointF(r.X, r.Y + r.Height / 2); }
    public ChainNode Find(string id) { foreach (var n in Nodes) if (n.Id == id) return n; return null; }

    public ChainNode AddNode(string title, string method, string url, float x, float y) {
        var n = new ChainNode { Title = title, Method = method, Url = url, X = x, Y = y };
        Nodes.Add(n);
        Invalidate();
        return n;
    }

    void Fire() { Invalidate(); if (SelectionChanged != null) SelectionChanged(this, EventArgs.Empty); }

    public void SelectNode(ChainNode n) { SelectedNode = n; Fire(); }
    public void SelectAll() { Selection = new List<ChainNode>(Nodes); primary = Nodes.Count > 0 ? Nodes[Nodes.Count - 1] : null; SelectedLink = null; Fire(); }
    public void SelectIds(string[] ids) { var want = new HashSet<string>(ids ?? new string[0]); Selection = Nodes.Where(n => want.Contains(n.Id)).ToList(); primary = Selection.Count > 0 ? Selection[Selection.Count - 1] : null; SelectedLink = null; Fire(); }

    public void RemoveSelected() {
        if (Selection.Count > 0) {
            var ids = new HashSet<string>(Selection.Select(n => n.Id));
            Nodes.RemoveAll(n => ids.Contains(n.Id));
            Links.RemoveAll(l => ids.Contains(l.From) || ids.Contains(l.To));
            Selection.Clear(); primary = null;
        } else if (SelectedLink != null) { Links.Remove(SelectedLink); SelectedLink = null; }
        else return;
        Fire();
        if (Changed != null) Changed(this, EventArgs.Empty);
    }

    bool Reaches(string start, string target) {
        var seen = new HashSet<string>(); var stack = new Stack<string>(); stack.Push(start);
        while (stack.Count > 0) {
            var c = stack.Pop();
            if (c == target) return true;
            if (!seen.Add(c)) continue;
            foreach (var l in Links) if (l.From == c) stack.Push(l.To);
        }
        return false;
    }

    public bool Connect(string from, string to) {
        if (from == to || Links.Any(l => l.From == from && l.To == to) || Reaches(to, from)) return false;
        Links.Add(new ChainLink { From = from, To = to });
        Invalidate();
        if (Changed != null) Changed(this, EventArgs.Empty);
        return true;
    }

    ChainNode NodeAt(System.Drawing.PointF p) {
        for (int i = Nodes.Count - 1; i >= 0; i--) { var r = Box(Nodes[i]); r.Inflate(S(6), 0); if (r.Contains(p)) return Nodes[i]; }
        return null;
    }

    static float Dist(System.Drawing.PointF a, System.Drawing.PointF b) { float dx = a.X - b.X, dy = a.Y - b.Y; return (float)Math.Sqrt(dx * dx + dy * dy); }

    static System.Drawing.PointF Bez(System.Drawing.PointF a, System.Drawing.PointF b, System.Drawing.PointF c, System.Drawing.PointF d, float t) {
        float u = 1 - t;
        return new System.Drawing.PointF(u * u * u * a.X + 3 * u * u * t * b.X + 3 * u * t * t * c.X + t * t * t * d.X,
                                         u * u * u * a.Y + 3 * u * u * t * b.Y + 3 * u * t * t * c.Y + t * t * t * d.Y);
    }

    void Curve(System.Drawing.PointF a, System.Drawing.PointF d, out System.Drawing.PointF b, out System.Drawing.PointF c) {
        float dx = Math.Max(S(50), Math.Abs(d.X - a.X) / 2);
        b = new System.Drawing.PointF(a.X + dx, a.Y); c = new System.Drawing.PointF(d.X - dx, d.Y);
    }

    ChainLink LinkAt(System.Drawing.PointF p) {
        foreach (var l in Links) {
            var f = Find(l.From); var t = Find(l.To);
            if (f == null || t == null) continue;
            var a = OutPort(f); var d = InPort(t); System.Drawing.PointF b, c; Curve(a, d, out b, out c);
            for (int i = 0; i <= 30; i++) if (Dist(Bez(a, b, c, d, i / 30f), p) < S(7)) return l;
        }
        return null;
    }

    System.Drawing.RectangleF BoxRect() {
        return System.Drawing.RectangleF.FromLTRB(Math.Min(boxStart.X, mouse.X), Math.Min(boxStart.Y, mouse.Y), Math.Max(boxStart.X, mouse.X), Math.Max(boxStart.Y, mouse.Y));
    }

    protected override void OnMouseDown(System.Windows.Forms.MouseEventArgs e) {
        base.OnMouseDown(e);
        Focus();
        if (e.Button == System.Windows.Forms.MouseButtons.Left && ZoomClick(e.Location)) { mode = Mode.None; return; }
        var p = V(e.X, e.Y);
        downAt = e.Location; moved = false; mouse = p;
        bool ctrl = (ModifierKeys & System.Windows.Forms.Keys.Control) != 0, shift = (ModifierKeys & System.Windows.Forms.Keys.Shift) != 0;
        if (e.Button == System.Windows.Forms.MouseButtons.Middle) { mode = Mode.Pan; panStart = new System.Drawing.PointF(p.X - Pan.X, p.Y - Pan.Y); Cursor = System.Windows.Forms.Cursors.SizeAll; return; }
        var n = NodeAt(p);
        if (n != null && e.Button == System.Windows.Forms.MouseButtons.Left && Dist(OutPort(n), p) < S(12)) {
            mode = Mode.Link; linkFrom = n; return;
        }
        if (n != null) {
            if (ctrl && e.Button == System.Windows.Forms.MouseButtons.Left) {
                if (Selection.Contains(n)) { Selection.Remove(n); if (primary == n) primary = null; } else { Selection.Add(n); primary = n; }
                SelectedLink = null; Fire();
                return;
            }
            if (!Selection.Contains(n)) { Selection.Clear(); Selection.Add(n); }
            primary = n; SelectedLink = null; Fire();
            if (e.Button == System.Windows.Forms.MouseButtons.Left) {
                mode = Mode.Drag; dragStart = p; dragFrom.Clear();
                foreach (var s in Selection) dragFrom[s] = new System.Drawing.PointF(s.X, s.Y);
            }
            return;
        }
        var l = LinkAt(p);
        if (l != null) { Selection.Clear(); primary = null; SelectedLink = l; Fire(); return; }
        if (e.Button == System.Windows.Forms.MouseButtons.Left && (ctrl || shift || e.Clicks >= 2)) {
            // double-click and drag on empty space: a selection box (with Ctrl / Shift: adds to the selection)
            mode = Mode.Box; boxStart = p; boxAdd = ctrl || shift; Cursor = System.Windows.Forms.Cursors.Cross;
            if (!boxAdd && (Selection.Count > 0 || SelectedLink != null)) { Selection.Clear(); primary = null; SelectedLink = null; Fire(); }
        } else if (e.Button == System.Windows.Forms.MouseButtons.Left) {
            // plain drag on empty space moves the view; a plain click there clears the selection (on mouse up)
            mode = Mode.Pan; panStart = new System.Drawing.PointF(p.X - Pan.X, p.Y - Pan.Y); Cursor = System.Windows.Forms.Cursors.SizeAll;
        } else if (e.Button == System.Windows.Forms.MouseButtons.Right && Selection.Count > 0 && !ctrl) { Selection.Clear(); primary = null; SelectedLink = null; Fire(); }
    }

    protected override void OnMouseMove(System.Windows.Forms.MouseEventArgs e) {
        base.OnMouseMove(e);
        var p = V(e.X, e.Y);
        if (Math.Abs(e.X - downAt.X) + Math.Abs(e.Y - downAt.Y) > 3) moved = true;
        if (mode == Mode.Drag) {
            float dx = p.X - dragStart.X, dy = p.Y - dragStart.Y;
            foreach (var kv in dragFrom) { kv.Key.X = (float)Math.Round(kv.Value.X + dx); kv.Key.Y = (float)Math.Round(kv.Value.Y + dy); }
            Invalidate();
        }
        else if (mode == Mode.Link || mode == Mode.Box) { mouse = p; Invalidate(); }
        else if (mode == Mode.Pan) { Pan = new System.Drawing.PointF(p.X - panStart.X, p.Y - panStart.Y); Invalidate(); }
        else {
            var n = NodeAt(p);
            Cursor = n != null && Dist(OutPort(n), p) < S(12) ? System.Windows.Forms.Cursors.Cross : n != null ? System.Windows.Forms.Cursors.Hand : System.Windows.Forms.Cursors.Default;
        }
    }

    protected override void OnMouseUp(System.Windows.Forms.MouseEventArgs e) {
        base.OnMouseUp(e);
        var p = V(e.X, e.Y);
        if (mode == Mode.Link) {
            var t = NodeAt(p);
            if (t != null && t != linkFrom) Connect(linkFrom.Id, t.Id);
            Invalidate();
        } else if (mode == Mode.Drag && moved && Changed != null) Changed(this, EventArgs.Empty);
        else if (mode == Mode.Pan && !moved && e.Button == System.Windows.Forms.MouseButtons.Left && (Selection.Count > 0 || SelectedLink != null)) {
            Selection.Clear(); primary = null; SelectedLink = null; Fire(); Invalidate();
        }
        else if (mode == Mode.Box) {
            if (moved) {
                var r = BoxRect();
                var hit = Nodes.Where(n => r.IntersectsWith(Box(n))).ToList();
                if (!boxAdd) Selection.Clear();
                foreach (var n in hit) if (!Selection.Contains(n)) Selection.Add(n);
                primary = Selection.Count > 0 ? Selection[Selection.Count - 1] : null;
                Fire();
            }
            Invalidate();
        }
        mode = Mode.None; linkFrom = null; Cursor = System.Windows.Forms.Cursors.Default;
    }

    protected override void OnMouseWheel(System.Windows.Forms.MouseEventArgs e) {
        base.OnMouseWheel(e);
        if ((ModifierKeys & System.Windows.Forms.Keys.Control) != 0) { SetZoom(Zoom * (float)Math.Pow(1.1, e.Delta / 120.0), e.Location); return; }
        float step = e.Delta / 120f * S(60) / Zoom;
        if ((ModifierKeys & System.Windows.Forms.Keys.Shift) != 0) Pan = new System.Drawing.PointF(Pan.X + step, Pan.Y);
        else Pan = new System.Drawing.PointF(Pan.X, Pan.Y + step);
        Invalidate();
    }

    protected override void OnMouseDoubleClick(System.Windows.Forms.MouseEventArgs e) {
        base.OnMouseDoubleClick(e);
        if (ZoomButtons().Any(b => b.Contains(e.Location))) return;
        if (NodeAt(V(e.X, e.Y)) != null && NodeOpen != null) NodeOpen(this, EventArgs.Empty);
    }

    protected override bool IsInputKey(System.Windows.Forms.Keys k) { return k == System.Windows.Forms.Keys.Delete || base.IsInputKey(k); }
    protected override void OnKeyDown(System.Windows.Forms.KeyEventArgs e) {
        base.OnKeyDown(e);
        if (e.KeyCode == System.Windows.Forms.Keys.Delete) { RemoveSelected(); e.Handled = true; }
        else if (e.Control && e.KeyCode == System.Windows.Forms.Keys.A) { SelectAll(); e.Handled = true; }
        else if (e.Control && (e.KeyCode == System.Windows.Forms.Keys.Oemplus || e.KeyCode == System.Windows.Forms.Keys.Add)) { SetZoom(Zoom * 1.2f); e.Handled = true; }
        else if (e.Control && (e.KeyCode == System.Windows.Forms.Keys.OemMinus || e.KeyCode == System.Windows.Forms.Keys.Subtract)) { SetZoom(Zoom / 1.2f); e.Handled = true; }
        else if (e.Control && (e.KeyCode == System.Windows.Forms.Keys.D0 || e.KeyCode == System.Windows.Forms.Keys.NumPad0)) { SetZoom(1f); e.Handled = true; }
        else if (e.Control && e.KeyCode == System.Windows.Forms.Keys.D9) { ZoomToFit(); e.Handled = true; }
        else if (e.KeyCode == System.Windows.Forms.Keys.Escape && Selection.Count > 0) { SelectNode(null); e.Handled = true; }
    }

    System.Drawing.Color MethodColor(string m) {
        switch ((m ?? "").ToUpperInvariant()) {
            case "GET": return Green; case "POST": return System.Drawing.Color.FromArgb(230, 126, 34); case "PUT": return Accent;
            case "PATCH": return System.Drawing.Color.FromArgb(142, 68, 173); case "DELETE": return Red; default: return Dim;
        }
    }

    static System.Drawing.Drawing2D.GraphicsPath Round(System.Drawing.RectangleF r, float rad) {
        var p = new System.Drawing.Drawing2D.GraphicsPath(); float d = rad * 2;
        p.AddArc(r.X, r.Y, d, d, 180, 90); p.AddArc(r.Right - d, r.Y, d, d, 270, 90);
        p.AddArc(r.Right - d, r.Bottom - d, d, d, 0, 90); p.AddArc(r.X, r.Bottom - d, d, d, 90, 90); p.CloseFigure();
        return p;
    }

    // "go to" rules (Jumps = "targetId\x1fcondition" joined by \x1e): dashed arrows below the cards
    void DrawJumps(System.Drawing.Graphics g) {
        using (var f = new System.Drawing.Font(Font.FontFamily, Font.Size * 0.8f))
        using (var pen = new System.Drawing.Pen(Yellow, S(1.6f)))
        using (var br = new System.Drawing.SolidBrush(Yellow))
        using (var bg = new System.Drawing.SolidBrush(Back)) {
            pen.DashStyle = System.Drawing.Drawing2D.DashStyle.Dash;
            foreach (var n in Nodes) {
                if (string.IsNullOrEmpty(n.Jumps)) continue;
                var rules = n.Jumps.Split('\x1e');
                for (int i = 0; i < rules.Length; i++) {
                    var p = rules[i].Split('\x1f');
                    if (p.Length < 2) continue;
                    var r = Box(n);
                    float dip = S(46 + 20 * i);
                    var a = new System.Drawing.PointF(r.X + r.Width / 2 - S(10) * i, r.Bottom);
                    string label = p[1].Trim() == "" ? "always" : "if " + p[1].Trim();
                    if (label.Length > 34) label = label.Substring(0, 33) + "...";
                    System.Drawing.PointF mid;
                    if (p[0] == "end") {
                        var e = new System.Drawing.PointF(a.X, a.Y + dip * 0.6f);
                        g.DrawLine(pen, a, e);
                        g.FillRectangle(br, e.X - S(7), e.Y, S(14), S(3));
                        mid = new System.Drawing.PointF(e.X, e.Y + S(12));
                        label += "  -> end";
                    } else {
                        var t = Find(p[0]);
                        if (t == null) continue;
                        var tr = Box(t);
                        float dx = S(14) * (i + 1);
                        System.Drawing.PointF d, b, c;
                        int dir;                                   // which way the arrow head points: 1 = down, -1 = up
                        if (tr.Y > r.Bottom) {                     // target in a lower row: bottom of this card -> top of the target
                            a = new System.Drawing.PointF(r.X + r.Width / 2 - dx, r.Bottom);
                            d = new System.Drawing.PointF(tr.X + tr.Width / 2 - dx, tr.Y);
                            float h = (d.Y - a.Y) / 2;
                            b = new System.Drawing.PointF(a.X, a.Y + h); c = new System.Drawing.PointF(d.X, d.Y - h); dir = 1;
                        } else if (tr.Bottom < r.Y) {              // target in a higher row: top of this card -> bottom of the target
                            a = new System.Drawing.PointF(r.X + r.Width / 2 - dx, r.Y);
                            d = new System.Drawing.PointF(tr.X + tr.Width / 2 - dx, tr.Bottom);
                            float h = (a.Y - d.Y) / 2;
                            b = new System.Drawing.PointF(a.X, a.Y - h); c = new System.Drawing.PointF(d.X, d.Y + h); dir = -1;
                        } else {                                   // same row (or itself): a loop below both cards
                            d = new System.Drawing.PointF(tr.X + tr.Width / 2 + dx, tr.Bottom);
                            if (t == n) { a.X -= S(30); d.X = a.X + S(60); }
                            float low = Math.Max(a.Y, d.Y) + dip;
                            b = new System.Drawing.PointF(a.X, low); c = new System.Drawing.PointF(d.X, low); dir = -1;
                        }
                        float s = S(6);
                        var end = new System.Drawing.PointF(d.X, d.Y - dir * S(6));
                        g.DrawBezier(pen, a, b, c, end);
                        g.FillPolygon(br, new[] { d, new System.Drawing.PointF(d.X - s * 0.8f, d.Y - dir * s * 1.4f), new System.Drawing.PointF(d.X + s * 0.8f, d.Y - dir * s * 1.4f) });
                        mid = new System.Drawing.PointF((a.X + 3 * b.X + 3 * c.X + d.X) / 8, (a.Y + 3 * b.Y + 3 * c.Y + d.Y) / 8);
                    }
                    var sz = g.MeasureString(label, f);
                    var lr = new System.Drawing.RectangleF(mid.X - sz.Width / 2, mid.Y - sz.Height / 2, sz.Width, sz.Height);
                    g.FillRectangle(bg, lr);
                    g.DrawString(label, f, br, lr.X, lr.Y);
                }
            }
        }
    }

    void Arrow(System.Drawing.Graphics g, System.Drawing.PointF a, System.Drawing.PointF d, System.Drawing.Color col, float w) {
        System.Drawing.PointF b, c; Curve(a, d, out b, out c);
        using (var pen = new System.Drawing.Pen(col, w)) g.DrawBezier(pen, a, b, c, new System.Drawing.PointF(d.X - S(6), d.Y));
        var tip = d; float s = S(8);
        using (var br = new System.Drawing.SolidBrush(col))
            g.FillPolygon(br, new[] { tip, new System.Drawing.PointF(tip.X - s * 1.3f, tip.Y - s * 0.7f), new System.Drawing.PointF(tip.X - s * 1.3f, tip.Y + s * 0.7f) });
    }

    protected override void OnPaint(System.Windows.Forms.PaintEventArgs e) {
        var g = e.Graphics;
        g.Clear(Back);
        g.SmoothingMode = System.Drawing.Drawing2D.SmoothingMode.AntiAlias;
        g.TextRenderingHint = System.Drawing.Text.TextRenderingHint.ClearTypeGridFit;
        g.ScaleTransform(Zoom, Zoom);
        float vw = Width / Zoom, vh = Height / Zoom;
        float step = S(24);
        if (Zoom >= 0.45f) using (var dot = new System.Drawing.SolidBrush(GridDot)) {
            float ox = Pan.X % step, oy = Pan.Y % step;
            if (ox < 0) ox += step; if (oy < 0) oy += step;
            for (float x = ox; x < vw; x += step) for (float y = oy; y < vh; y += step) g.FillRectangle(dot, x, y, S(1.6f), S(1.6f));
        }
        if (Nodes.Count == 0) {
            using (var f = new System.Drawing.Font(Font.FontFamily, Font.Size * 1.1f))
            using (var br = new System.Drawing.SolidBrush(Dim)) {
                var sf = new System.Drawing.StringFormat { Alignment = System.Drawing.StringAlignment.Center, LineAlignment = System.Drawing.StringAlignment.Center };
                g.DrawString("Drag requests here from the list on the left (or right-click: Add a request).\nThen drag from a card's right dot to the next card to chain them.", f, br, new System.Drawing.RectangleF(0, 0, vw, vh), sf);
            }
        }
        foreach (var l in Links) {
            var f = Find(l.From); var t = Find(l.To);
            if (f == null || t == null) continue;
            var col = l == SelectedLink ? Accent : (t.State == "ok" && f.State == "ok") ? Green : Line;
            Arrow(g, OutPort(f), InPort(t), col, l == SelectedLink ? S(3) : S(2));
        }
        if (mode == Mode.Link && linkFrom != null) Arrow(g, OutPort(linkFrom), mouse, Accent, S(2));
        DrawJumps(g);

        using (var titleF = new System.Drawing.Font(Font.FontFamily, Font.Size, System.Drawing.FontStyle.Bold))
        using (var small = new System.Drawing.Font(Font.FontFamily, Font.Size * 0.85f))
        using (var badgeF = new System.Drawing.Font(Font.FontFamily, Font.Size * 0.75f, System.Drawing.FontStyle.Bold)) {
            foreach (var n in Nodes) {
                var r = Box(n);
                bool sel = Selection.Contains(n), run = n.Id == RunningId;
                var stateCol = run ? Accent : n.State == "ok" ? Green : n.State == "fail" ? Red : n.State == "skip" ? Yellow : Line;
                using (var path = Round(r, S(8))) {
                    using (var shadow = new System.Drawing.SolidBrush(System.Drawing.Color.FromArgb(28, 0, 0, 0))) { g.TranslateTransform(0, S(2)); g.FillPath(shadow, path); g.TranslateTransform(0, -S(2)); }
                    using (var br = new System.Drawing.SolidBrush(sel ? System.Drawing.Color.FromArgb(Card.A, (Card.R * 9 + Accent.R) / 10, (Card.G * 9 + Accent.G) / 10, (Card.B * 9 + Accent.B) / 10) : Card)) g.FillPath(br, path);
                    using (var pen = new System.Drawing.Pen(sel || run ? Accent : Line, sel || run ? S(2) : 1)) g.DrawPath(pen, path);
                }
                using (var br = new System.Drawing.SolidBrush(stateCol)) g.FillRectangle(br, r.X + S(1), r.Y + S(8), S(4), r.Height - S(16));
                if (n.Order > 0) using (var br = new System.Drawing.SolidBrush(Dim)) g.DrawString(n.Order.ToString(), small, br, r.Right - S(22), r.Y + S(6));
                // small marks: "if" = runs only when its condition is true, "save" = writes its response to a file
                float mx = r.Right - S(28);
                foreach (var mark in new[] { n.Save ? "save" : null, string.IsNullOrEmpty(n.Cond) ? null : "if" }) {
                    if (mark == null) continue;
                    var ms = g.MeasureString(mark, badgeF);
                    var mr = new System.Drawing.RectangleF(mx - ms.Width - S(4), r.Y + S(8), ms.Width + S(4), ms.Height);
                    using (var bp = Round(mr, S(3))) using (var br = new System.Drawing.SolidBrush(mark == "if" ? Yellow : Accent)) g.FillPath(br, bp);
                    g.DrawString(mark, badgeF, System.Drawing.Brushes.White, mr.X + S(2), mr.Y);
                    mx = mr.X - S(4);
                }
                var m = (n.Method ?? "GET").ToUpperInvariant();
                var bs = g.MeasureString(m, badgeF);
                var badge = new System.Drawing.RectangleF(r.X + S(12), r.Y + S(9), bs.Width + S(8), bs.Height + S(2));
                using (var bp = Round(badge, S(4))) using (var br = new System.Drawing.SolidBrush(MethodColor(m))) g.FillPath(br, bp);
                g.DrawString(m, badgeF, System.Drawing.Brushes.White, badge.X + S(4), badge.Y + S(1));
                var tf = new System.Drawing.StringFormat { Trimming = System.Drawing.StringTrimming.EllipsisCharacter, FormatFlags = System.Drawing.StringFormatFlags.NoWrap };
                using (var br = new System.Drawing.SolidBrush(Fore))
                    g.DrawString(n.Title == "" ? "(no name)" : n.Title, titleF, br, new System.Drawing.RectangleF(badge.Right + S(6), r.Y + S(7), r.Right - badge.Right - S(32), titleF.Height + 2), tf);
                using (var br = new System.Drawing.SolidBrush(Dim))
                    g.DrawString(n.Url, small, br, new System.Drawing.RectangleF(r.X + S(12), r.Y + S(31), r.Width - S(22), small.Height + 2), tf);
                if (n.Info != "") using (var br = new System.Drawing.SolidBrush(n.State == "fail" ? Red : n.State == "ok" ? Green : Dim))
                    g.DrawString(n.Info, small, br, new System.Drawing.RectangleF(r.X + S(12), r.Y + S(50), r.Width - S(22), small.Height + 2), tf);
                float pr = S(5);
                var ip = InPort(n); var op = OutPort(n);
                using (var br = new System.Drawing.SolidBrush(Card)) { g.FillEllipse(br, ip.X - pr, ip.Y - pr, pr * 2, pr * 2); g.FillEllipse(br, op.X - pr, op.Y - pr, pr * 2, pr * 2); }
                using (var pen = new System.Drawing.Pen(Dim, S(1.5f))) g.DrawEllipse(pen, ip.X - pr, ip.Y - pr, pr * 2, pr * 2);
                using (var br = new System.Drawing.SolidBrush(Accent)) g.FillEllipse(br, op.X - pr, op.Y - pr, pr * 2, pr * 2);
            }
        }
        if (mode == Mode.Box && moved) {
            var r = BoxRect();
            using (var br = new System.Drawing.SolidBrush(System.Drawing.Color.FromArgb(40, Accent))) g.FillRectangle(br, r);
            using (var pen = new System.Drawing.Pen(Accent, 1) { DashStyle = System.Drawing.Drawing2D.DashStyle.Dash }) g.DrawRectangle(pen, r.X, r.Y, r.Width, r.Height);
        }
        // zoom buttons (not zoomed themselves)
        g.ResetTransform();
        var zb = ZoomButtons();
        var all = System.Drawing.RectangleF.Union(zb[0], zb[3]);
        using (var path = Round(all, S(6)))
        using (var bg = new System.Drawing.SolidBrush(Card))
        using (var pen = new System.Drawing.Pen(Line)) { g.FillPath(bg, path); g.DrawPath(pen, path); }
        using (var f = new System.Drawing.Font(Font.FontFamily, Font.Size * 0.9f))
        using (var br = new System.Drawing.SolidBrush(Fore)) {
            var sf = new System.Drawing.StringFormat { Alignment = System.Drawing.StringAlignment.Center, LineAlignment = System.Drawing.StringAlignment.Center };
            string[] t = { "-", ((int)Math.Round(Zoom * 100)) + "%", "+", "Fit" };
            for (int i = 0; i < 4; i++) g.DrawString(t[i], f, br, zb[i], sf);
        }
    }
}

public class GitResult { public int Code; public string Out = "", Err = ""; public string Text { get { return (Out + (Err.Length > 0 && Out.Length > 0 ? "\n" : "") + Err).TrimEnd(); } } }

public class DevGit {
    public static string Find() {
        var paths = new List<string>();
        foreach (var dir in (Environment.GetEnvironmentVariable("PATH") ?? "").Split(';')) {
            try { if (dir.Trim() != "") paths.Add(System.IO.Path.Combine(dir.Trim().Trim('"'), "git.exe")); } catch { }
        }
        string pf = Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles), pf86 = Environment.GetFolderPath(Environment.SpecialFolder.ProgramFilesX86);
        string local = Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData);
        paths.Add(System.IO.Path.Combine(pf, @"Git\cmd\git.exe"));
        if (pf86 != "") paths.Add(System.IO.Path.Combine(pf86, @"Git\cmd\git.exe"));
        paths.Add(System.IO.Path.Combine(local, @"Programs\Git\cmd\git.exe"));
        try {
            var gd = System.IO.Path.Combine(local, "GitHubDesktop");
            if (System.IO.Directory.Exists(gd)) foreach (var d in System.IO.Directory.GetDirectories(gd, "app-*")) paths.Add(System.IO.Path.Combine(d, @"resources\app\git\cmd\git.exe"));
        } catch { }
        foreach (var p in paths) { try { if (System.IO.File.Exists(p)) return p; } catch { } }
        return null;
    }

    public string Exe, Dir;
    public DevGit(string exe, string dir) { Exe = exe; Dir = dir; }

    System.Diagnostics.Process Start(string args) {
        var psi = new System.Diagnostics.ProcessStartInfo(Exe, "-c core.quotepath=off -c color.ui=false " + args) {
            WorkingDirectory = Dir, UseShellExecute = false, CreateNoWindow = true,
            RedirectStandardOutput = true, RedirectStandardError = true, RedirectStandardInput = true,
            StandardOutputEncoding = new UTF8Encoding(false), StandardErrorEncoding = new UTF8Encoding(false)
        };
        psi.EnvironmentVariables["GIT_TERMINAL_PROMPT"] = "0";        // no hanging on a hidden password prompt
        psi.EnvironmentVariables["GIT_EDITOR"] = "true";              // merges / reverts keep their default message
        psi.EnvironmentVariables["LC_ALL"] = "C.UTF-8";
        var p = System.Diagnostics.Process.Start(psi);
        p.StandardInput.Close();
        return p;
    }

    // Quick commands: waits for the result.
    public GitResult Run(string args) {
        var r = new GitResult();
        using (var p = Start(args)) {
            var err = p.StandardError.ReadToEndAsync();
            r.Out = p.StandardOutput.ReadToEnd();
            p.WaitForExit();
            r.Err = err.Result;
            r.Code = p.ExitCode;
        }
        return r;
    }

    // Slow commands (fetch, pull, push, clone ...): run in the background, poll Done.
    public volatile bool Done = true;
    public GitResult Last;
    System.Diagnostics.Process job;
    public void RunAsync(string args) {
        Done = false; Last = null;
        var t = new System.Threading.Thread(delegate() {
            var r = new GitResult();
            try {
                using (var p = Start(args)) {
                    job = p;
                    var err = p.StandardError.ReadToEndAsync();
                    r.Out = p.StandardOutput.ReadToEnd();
                    p.WaitForExit();
                    r.Err = err.Result; r.Code = p.ExitCode;
                }
            } catch (Exception ex) { r.Code = -1; r.Err = ex.Message; }
            finally { job = null; Last = r; Done = true; }
        });
        t.IsBackground = true;
        t.Start();
    }
    public void Cancel() { try { if (job != null && !job.HasExited) job.Kill(); } catch { } }

    // "a b" -> a quoted argument for the command line
    public static string Q(string s) {
        if (s == null) return "\"\"";
        if (s.Length > 0 && s.IndexOfAny(new[] { ' ', '\t', '"' }) < 0) return s;
        var sb = new StringBuilder("\"");
        int bs = 0;
        foreach (char c in s) {
            if (c == '\\') { bs++; continue; }
            if (c == '"') { sb.Append('\\', bs * 2 + 1); bs = 0; sb.Append('"'); continue; }
            sb.Append('\\', bs); bs = 0; sb.Append(c);
        }
        sb.Append('\\', bs * 2).Append('"');
        return sb.ToString();
    }
}

public class GitCommit {
    public string Hash, Short, Author, Email, Date, Refs, Subject;
    public string[] Parents;
    public int Col;
    public string[] After;      // lanes after this row (hash expected next in each lane, or null)
    public bool IsHead;
}

public class DevGitGraph : System.Windows.Forms.Panel {
    public List<GitCommit> Commits = new List<GitCommit>();
    public float UiScale = 1f;
    public int Selected = -1;
    public string Filter = "";
    public System.Drawing.Color Back = System.Drawing.Color.White, Fore = System.Drawing.Color.Black, Dim = System.Drawing.Color.Gray,
        Sel = System.Drawing.Color.LightSteelBlue, Line = System.Drawing.Color.Gainsboro, Accent = System.Drawing.Color.RoyalBlue;
    public event EventHandler SelectionChanged, Open;
    static readonly System.Drawing.Color[] LaneColors = {
        System.Drawing.Color.FromArgb(47, 128, 237), System.Drawing.Color.FromArgb(39, 174, 96), System.Drawing.Color.FromArgb(235, 87, 87),
        System.Drawing.Color.FromArgb(242, 153, 74), System.Drawing.Color.FromArgb(155, 81, 224), System.Drawing.Color.FromArgb(0, 163, 163),
        System.Drawing.Color.FromArgb(214, 69, 122), System.Drawing.Color.FromArgb(120, 130, 60) };

    public DevGitGraph() {
        SetStyle(System.Windows.Forms.ControlStyles.AllPaintingInWmPaint | System.Windows.Forms.ControlStyles.OptimizedDoubleBuffer |
                 System.Windows.Forms.ControlStyles.UserPaint | System.Windows.Forms.ControlStyles.ResizeRedraw | System.Windows.Forms.ControlStyles.Selectable, true);
        AutoScroll = true; TabStop = true;
    }

    float S(float v) { return v * UiScale; }
    public int RowH { get { return (int)S(26); } }
    float LaneW { get { return S(14); } }

    // git log --format=%H%x1f%h%x1f%P%x1f%an%x1f%ae%x1f%ad%x1f%D%x1f%s  (records separated by \x1e)
    public void Load(string log, string head) {
        Commits.Clear();
        foreach (var rec in log.Split('\x1e')) {
            var r = rec.Trim('\n', '\r');
            if (r == "") continue;
            var f = r.Split('\x1f');
            if (f.Length < 8) continue;
            Commits.Add(new GitCommit { Hash = f[0], Short = f[1], Parents = f[2].Split(new[] { ' ' }, StringSplitOptions.RemoveEmptyEntries), Author = f[3], Email = f[4], Date = f[5], Refs = f[6], Subject = f[7], IsHead = f[0] == head });
        }
        BuildLanes();
        Selected = Commits.Count > 0 ? 0 : -1;
        AutoScrollPosition = new System.Drawing.Point(0, 0);
        UpdateSize();
        Invalidate();
    }

    void BuildLanes() {
        var lanes = new List<string>();
        foreach (var c in Commits) {
            int col = lanes.IndexOf(c.Hash);
            if (col < 0) { col = lanes.IndexOf(null); if (col < 0) { lanes.Add(c.Hash); col = lanes.Count - 1; } else lanes[col] = c.Hash; }
            for (int i = 0; i < lanes.Count; i++) if (i != col && lanes[i] == c.Hash) lanes[i] = null;     // branches that end here
            c.Col = col;
            if (c.Parents.Length == 0) lanes[col] = null;
            else {
                lanes[col] = c.Parents[0];
                for (int k = 1; k < c.Parents.Length; k++) {
                    if (lanes.Contains(c.Parents[k])) continue;
                    int free = lanes.IndexOf(null);
                    if (free < 0) lanes.Add(c.Parents[k]); else lanes[free] = c.Parents[k];
                }
            }
            while (lanes.Count > 0 && lanes[lanes.Count - 1] == null) lanes.RemoveAt(lanes.Count - 1);
            c.After = lanes.ToArray();
        }
    }

    public void UpdateSize() { AutoScrollMinSize = new System.Drawing.Size(0, Commits.Count * RowH + RowH); }

    int RowAt(int y) { int r = (y - AutoScrollPosition.Y) / RowH; return r >= 0 && r < Commits.Count ? r : -1; }

    public void SelectRow(int r) {
        if (r < 0 || r >= Commits.Count) return;
        Selected = r;
        int top = -AutoScrollPosition.Y, y = r * RowH;
        if (y < top) AutoScrollPosition = new System.Drawing.Point(0, y);
        else if (y + RowH > top + ClientSize.Height) AutoScrollPosition = new System.Drawing.Point(0, y + RowH - ClientSize.Height);
        Invalidate();
        if (SelectionChanged != null) SelectionChanged(this, EventArgs.Empty);
    }

    public int FindNext(string text, int from) {
        if (string.IsNullOrEmpty(text)) return -1;
        for (int k = 1; k <= Commits.Count; k++) {
            int i = (from + k) % Commits.Count; var c = Commits[i];
            if (c.Subject.IndexOf(text, StringComparison.OrdinalIgnoreCase) >= 0 || c.Hash.StartsWith(text, StringComparison.OrdinalIgnoreCase) ||
                c.Author.IndexOf(text, StringComparison.OrdinalIgnoreCase) >= 0 || c.Refs.IndexOf(text, StringComparison.OrdinalIgnoreCase) >= 0) return i;
        }
        return -1;
    }

    protected override void OnMouseDown(System.Windows.Forms.MouseEventArgs e) {
        base.OnMouseDown(e); Focus();
        int r = RowAt(e.Y); if (r >= 0) SelectRow(r);
    }
    protected override void OnMouseDoubleClick(System.Windows.Forms.MouseEventArgs e) { base.OnMouseDoubleClick(e); if (RowAt(e.Y) >= 0 && Open != null) Open(this, EventArgs.Empty); }
    protected override bool IsInputKey(System.Windows.Forms.Keys k) { return k == System.Windows.Forms.Keys.Up || k == System.Windows.Forms.Keys.Down || k == System.Windows.Forms.Keys.PageUp || k == System.Windows.Forms.Keys.PageDown || base.IsInputKey(k); }
    protected override void OnKeyDown(System.Windows.Forms.KeyEventArgs e) {
        base.OnKeyDown(e);
        int page = Math.Max(1, ClientSize.Height / RowH - 1);
        if (e.KeyCode == System.Windows.Forms.Keys.Down) SelectRow(Math.Min(Commits.Count - 1, Selected + 1));
        else if (e.KeyCode == System.Windows.Forms.Keys.Up) SelectRow(Math.Max(0, Selected - 1));
        else if (e.KeyCode == System.Windows.Forms.Keys.PageDown) SelectRow(Math.Min(Commits.Count - 1, Selected + page));
        else if (e.KeyCode == System.Windows.Forms.Keys.PageUp) SelectRow(Math.Max(0, Selected - page));
        else if (e.KeyCode == System.Windows.Forms.Keys.Enter && Open != null) Open(this, EventArgs.Empty);
    }

    float LX(int lane) { return S(12) + lane * LaneW; }

    protected override void OnPaint(System.Windows.Forms.PaintEventArgs e) {
        var g = e.Graphics;
        g.Clear(Back);
        if (Commits.Count == 0) return;
        g.SmoothingMode = System.Drawing.Drawing2D.SmoothingMode.AntiAlias;
        g.TextRenderingHint = System.Drawing.Text.TextRenderingHint.ClearTypeGridFit;
        int oy = AutoScrollPosition.Y, h = RowH;
        int first = Math.Max(0, -oy / h - 1), last = Math.Min(Commits.Count - 1, (-oy + ClientSize.Height) / h + 1);
        int maxLanes = 1;
        for (int i = first; i <= last; i++) maxLanes = Math.Max(maxLanes, Math.Max(Commits[i].Col + 1, Commits[i].After.Length));
        maxLanes = Math.Min(maxLanes, 24);
        float textX = LX(maxLanes) + S(8);
        // narrow window: drop the author, then the date, so the message keeps its room
        float hashW = S(64), dateW = Width > S(760) ? S(118) : 0, authorW = Width > S(980) ? S(120) : 0;
        float rightCols = dateW + authorW + hashW;
        using (var small = new System.Drawing.Font(Font.FontFamily, Font.Size * 0.85f))
        using (var bold = new System.Drawing.Font(Font, System.Drawing.FontStyle.Bold))
        using (var mono = new System.Drawing.Font("Consolas", Font.Size * 0.9f)) {
            var tf = new System.Drawing.StringFormat { Trimming = System.Drawing.StringTrimming.EllipsisCharacter, FormatFlags = System.Drawing.StringFormatFlags.NoWrap, LineAlignment = System.Drawing.StringAlignment.Center };
            for (int i = first; i <= last; i++) {
                var c = Commits[i];
                float y = oy + i * h, cy = y + h / 2f;
                if (i == Selected) using (var b = new System.Drawing.SolidBrush(Sel)) g.FillRectangle(b, 0, y, Width, h);
                // lines to the next row
                if (i + 1 < Commits.Count) {
                    var n = Commits[i + 1];
                    for (int l = 0; l < c.After.Length; l++) {
                        var hsh = c.After[l]; if (hsh == null) continue;
                        int start = Array.IndexOf(c.Parents, hsh) >= 0 ? c.Col : l;
                        int end = n.Hash == hsh ? n.Col : l;
                        var col = LaneColors[(Array.IndexOf(c.Parents, hsh) == 0 ? c.Col : l) % LaneColors.Length];
                        if (l < 24 || start < 24) using (var pen = new System.Drawing.Pen(col, S(2))) {
                            float x1 = LX(Math.Min(start, 23)), x2 = LX(Math.Min(end, 23)), y2 = cy + h;
                            if (Math.Abs(x1 - x2) < 0.5f) g.DrawLine(pen, x1, cy, x2, y2);
                            else g.DrawBezier(pen, x1, cy, x1, cy + h * 0.6f, x2, y2 - h * 0.6f, x2, y2);
                        }
                    }
                }
                // the dot
                float r = S(4.5f), x = LX(Math.Min(c.Col, 23));
                var dotCol = LaneColors[c.Col % LaneColors.Length];
                using (var b = new System.Drawing.SolidBrush(c.Parents.Length > 1 ? Back : dotCol)) g.FillEllipse(b, x - r, cy - r, r * 2, r * 2);
                using (var pen = new System.Drawing.Pen(dotCol, S(2))) g.DrawEllipse(pen, x - r, cy - r, r * 2, r * 2);
                if (c.IsHead) using (var pen = new System.Drawing.Pen(Fore, S(1.5f))) g.DrawEllipse(pen, x - r - S(3), cy - r - S(3), (r + S(3)) * 2, (r + S(3)) * 2);
                // ref badges
                float tx = textX;
                if (c.Refs != "") {
                    foreach (var raw in c.Refs.Split(new[] { ", " }, StringSplitOptions.RemoveEmptyEntries)) {
                        string name = raw; var bc = Accent;
                        bool head = false;
                        if (name.StartsWith("HEAD -> ")) { name = name.Substring(8); head = true; }
                        else if (name == "HEAD") { head = true; }
                        if (name.StartsWith("tag: ")) { name = name.Substring(5); bc = System.Drawing.Color.FromArgb(242, 153, 74); }
                        else if (name.Contains("/")) bc = System.Drawing.Color.FromArgb(120, 120, 130);
                        else bc = LaneColors[c.Col % LaneColors.Length];
                        var sz = g.MeasureString(name, small);
                        var br = new System.Drawing.RectangleF(tx, cy - sz.Height / 2 - S(1), sz.Width + S(6), sz.Height + S(2));
                        if (br.Right > Width - rightCols - S(90)) break;
                        using (var b = new System.Drawing.SolidBrush(bc)) g.FillRectangle(b, br);
                        if (head) using (var pen = new System.Drawing.Pen(Fore, S(1.5f))) g.DrawRectangle(pen, br.X, br.Y, br.Width, br.Height);
                        g.DrawString(name, small, System.Drawing.Brushes.White, br.X + S(3), br.Y + S(1));
                        tx = br.Right + S(5);
                    }
                }
                float subjW = Width - rightCols - tx - S(10);
                using (var b = new System.Drawing.SolidBrush(Fore)) g.DrawString(c.Subject, c.IsHead ? bold : Font, b, new System.Drawing.RectangleF(tx, y, Math.Max(10, subjW), h), tf);
                using (var b = new System.Drawing.SolidBrush(Dim)) {
                    float rx = Width - rightCols - S(4);
                    if (authorW > 0) g.DrawString(c.Author, small, b, new System.Drawing.RectangleF(rx, y, authorW, h), tf);
                    if (dateW > 0) g.DrawString(c.Date, small, b, new System.Drawing.RectangleF(rx + authorW, y, dateW, h), tf);
                    g.DrawString(c.Short, mono, b, new System.Drawing.RectangleF(rx + authorW + dateW, y, hashW, h), tf);
                }
            }
        }
    }
}

// ---- Test API: a tiny HTTP server on 127.0.0.1 to practise requests and chains (log in, token, cookie,
//      CSRF, CRUD). Plain TcpListener, so it needs no admin rights or URL reservation. Data is in memory.
public class DevTestApi {
    System.Net.Sockets.TcpListener listener;
    volatile bool running;
    public int Port { get; private set; }
    public bool Running { get { return running; } }
    readonly object gate = new object();
    readonly List<string> log = new List<string>();
    readonly Dictionary<string, int> tokens = new Dictionary<string, int>(), sessions = new Dictionary<string, int>();
    readonly HashSet<string> csrf = new HashSet<string>();
    SortedDictionary<int, string> items;    // id -> JSON object text
    int nextId;
    static readonly string[][] Users = { new[] { "1", "demo", "demo", "Demo User", "demo@example.com" }, new[] { "2", "ann", "secret", "Ann Smith", "ann@example.com" } };

    void Seed() {
        items = new SortedDictionary<int, string>();
        items[1] = "{\"id\":1,\"name\":\"Keyboard\",\"price\":49.9,\"owner\":1}";
        items[2] = "{\"id\":2,\"name\":\"Mouse\",\"price\":19.5,\"owner\":1}";
        items[3] = "{\"id\":3,\"name\":\"Monitor\",\"price\":199,\"owner\":2}";
        nextId = 4;
    }

    // Returns the port it listens on (tries a few), or -1.
    public int Start(int port) {
        if (running) return Port;
        lock (gate) { tokens.Clear(); sessions.Clear(); csrf.Clear(); Seed(); }
        for (int p = port; p < port + 20; p++) {
            try {
                listener = new System.Net.Sockets.TcpListener(System.Net.IPAddress.Loopback, p);
                listener.Start();
                Port = p; running = true;
                var t = new System.Threading.Thread(Accept); t.IsBackground = true; t.Start();
                return p;
            } catch { listener = null; }
        }
        return -1;
    }

    public void Stop() {
        running = false;
        try { if (listener != null) listener.Stop(); } catch { }
        listener = null;
    }

    public string[] TakeLog() { lock (log) { var a = log.ToArray(); log.Clear(); return a; } }

    void Accept() {
        while (running) {
            System.Net.Sockets.TcpClient c;
            try { c = listener.AcceptTcpClient(); } catch { break; }
            System.Threading.ThreadPool.QueueUserWorkItem(delegate { Serve(c); });
        }
    }

    class Req { public string Method, Path, Query = "", Body = ""; public Dictionary<string, string> Headers = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase); public Dictionary<string, string> Cookies = new Dictionary<string, string>(); }
    class Resp { public int Status = 200; public string Type = "application/json"; public string Body = ""; public List<string[]> Headers = new List<string[]>(); }

    void Serve(System.Net.Sockets.TcpClient c) {
        var sw = System.Diagnostics.Stopwatch.StartNew();
        string line = "";
        try {
            using (c) {
                c.ReceiveTimeout = 10000; c.SendTimeout = 10000;
                var s = c.GetStream();
                var buf = new List<byte>(); var one = new byte[4096]; int headEnd = -1;
                while (headEnd < 0) {
                    int n = s.Read(one, 0, one.Length); if (n <= 0) return;
                    for (int i = 0; i < n; i++) buf.Add(one[i]);
                    for (int i = Math.Max(0, buf.Count - n - 3); i + 3 < buf.Count; i++) if (buf[i] == 13 && buf[i + 1] == 10 && buf[i + 2] == 13 && buf[i + 3] == 10) { headEnd = i; break; }
                    if (buf.Count > 1 << 20) return;
                }
                var head = Encoding.ASCII.GetString(buf.ToArray(), 0, headEnd).Split(new[] { "\r\n" }, StringSplitOptions.None);
                var r = new Req();
                var first = head[0].Split(' ');
                if (first.Length < 2) return;
                r.Method = first[0].ToUpperInvariant();
                var target = first[1];
                int q = target.IndexOf('?');
                r.Path = Uri.UnescapeDataString(q >= 0 ? target.Substring(0, q) : target).TrimEnd('/');
                if (r.Path == "") r.Path = "/";
                if (q >= 0) r.Query = target.Substring(q + 1);
                for (int i = 1; i < head.Length; i++) { int k = head[i].IndexOf(':'); if (k > 0) r.Headers[head[i].Substring(0, k).Trim()] = head[i].Substring(k + 1).Trim(); }
                int len = 0; string cl; if (r.Headers.TryGetValue("Content-Length", out cl)) int.TryParse(cl, out len);
                var body = new List<byte>(); for (int i = headEnd + 4; i < buf.Count; i++) body.Add(buf[i]);
                while (body.Count < len) { int n = s.Read(one, 0, Math.Min(one.Length, len - body.Count)); if (n <= 0) break; for (int i = 0; i < n; i++) body.Add(one[i]); }
                r.Body = Encoding.UTF8.GetString(body.ToArray());
                string ck; if (r.Headers.TryGetValue("Cookie", out ck)) foreach (var part in ck.Split(';')) { int k = part.IndexOf('='); if (k > 0) r.Cookies[part.Substring(0, k).Trim()] = part.Substring(k + 1).Trim(); }
                line = r.Method + " " + target;
                Resp res;
                try { res = Handle(r); } catch (Exception ex) { res = Err(500, "server error: " + ex.Message); }
                var bytes = Encoding.UTF8.GetBytes(res.Body);
                var sb = new StringBuilder();
                sb.Append("HTTP/1.1 ").Append(res.Status).Append(' ').Append(Reason(res.Status)).Append("\r\n");
                sb.Append("Content-Type: ").Append(res.Type).Append("; charset=utf-8\r\n");
                sb.Append("Content-Length: ").Append(bytes.Length).Append("\r\n");
                sb.Append("Connection: close\r\nServer: DevTools-TestAPI\r\n");
                foreach (var h in res.Headers) sb.Append(h[0]).Append(": ").Append(h[1]).Append("\r\n");
                sb.Append("\r\n");
                var hb = Encoding.ASCII.GetBytes(sb.ToString());
                s.Write(hb, 0, hb.Length); s.Write(bytes, 0, bytes.Length); s.Flush();
                lock (log) { log.Add(DateTime.Now.ToString("HH:mm:ss") + "  " + res.Status + "  " + line + "  (" + sw.ElapsedMilliseconds + " ms)"); if (log.Count > 500) log.RemoveAt(0); }
            }
        } catch { }
    }

    static string Reason(int s) {
        switch (s) {
            case 200: return "OK"; case 201: return "Created"; case 204: return "No Content"; case 400: return "Bad Request"; case 401: return "Unauthorized";
            case 403: return "Forbidden"; case 404: return "Not Found"; case 405: return "Method Not Allowed"; case 418: return "I'm a teapot"; case 500: return "Internal Server Error";
            case 503: return "Service Unavailable"; default: return s >= 500 ? "Server Error" : s >= 400 ? "Client Error" : s >= 300 ? "Redirect" : "OK";
        }
    }

    static string J(string s) {
        var sb = new StringBuilder("\"");
        foreach (char ch in s ?? "") {
            if (ch == '"' || ch == '\\') sb.Append('\\').Append(ch);
            else if (ch == '\n') sb.Append("\\n"); else if (ch == '\r') sb.Append("\\r"); else if (ch == '\t') sb.Append("\\t");
            else if (ch < 32) sb.Append("\\u").Append(((int)ch).ToString("x4")); else sb.Append(ch);
        }
        return sb.Append('"').ToString();
    }

    static Resp Json(int status, string body) { return new Resp { Status = status, Body = body }; }
    static Resp Err(int status, string msg) { return Json(status, "{\"error\":" + J(msg) + ",\"status\":" + status + "}"); }

    static string Field(string json, string name) {
        var m = System.Text.RegularExpressions.Regex.Match(json ?? "", "\"" + System.Text.RegularExpressions.Regex.Escape(name) + "\"\\s*:\\s*(\"((?:\\\\.|[^\"\\\\])*)\"|(-?[\\d.]+|true|false|null))");
        if (!m.Success) return null;
        return m.Groups[2].Success && m.Groups[1].Value.StartsWith("\"") ? System.Text.RegularExpressions.Regex.Unescape(m.Groups[2].Value) : m.Groups[3].Value;
    }

    static string FormField(string body, string name) {
        foreach (var p in (body ?? "").Split('&')) { int k = p.IndexOf('='); if (k > 0 && Uri.UnescapeDataString(p.Substring(0, k).Replace('+', ' ')) == name) return Uri.UnescapeDataString(p.Substring(k + 1).Replace('+', ' ')); }
        return null;
    }

    static string[] FindUser(string user, string pass) { foreach (var u in Users) if (u[1] == user && u[2] == pass) return u; return null; }
    static string[] UserById(int id) { foreach (var u in Users) if (u[0] == id.ToString()) return u; return null; }
    static string UserJson(string[] u) { return "{\"id\":" + u[0] + ",\"username\":" + J(u[1]) + ",\"name\":" + J(u[3]) + ",\"email\":" + J(u[4]) + "}"; }

    // who is calling: a Bearer token or the session cookie; 0 = nobody
    int Caller(Req r, bool allowCookie) {
        string a; int id;
        if (r.Headers.TryGetValue("Authorization", out a) && a.StartsWith("Bearer ", StringComparison.OrdinalIgnoreCase) && tokens.TryGetValue(a.Substring(7).Trim(), out id)) return id;
        string s;
        if (allowCookie && r.Cookies.TryGetValue("session", out s) && sessions.TryGetValue(s, out id)) return id;
        return 0;
    }

    Resp LogIn(string user, string pass, bool giveToken) {
        var u = FindUser(user, pass);
        if (u == null) return Err(401, "wrong username or password (try demo / demo)");
        string tok = Guid.NewGuid().ToString("N"), ses = Guid.NewGuid().ToString("N").Substring(0, 16);
        lock (gate) { tokens[tok] = int.Parse(u[0]); sessions[ses] = int.Parse(u[0]); }
        var res = Json(200, giveToken ? "{\"token\":" + J(tok) + ",\"userId\":" + u[0] + ",\"name\":" + J(u[3]) + ",\"expiresIn\":3600}" : "{\"ok\":true,\"userId\":" + u[0] + ",\"name\":" + J(u[3]) + "}");
        res.Headers.Add(new[] { "Set-Cookie", "session=" + ses + "; Path=/; HttpOnly" });
        return res;
    }

    Resp Handle(Req r) {
        string p = r.Path, m = r.Method;
        if (p == "/" && m == "GET") return new Resp { Type = "text/plain", Body = Help() };
        if (p == "/login") {
            if (m != "POST") return Err(405, "use POST");
            return LogIn(Field(r.Body, "username"), Field(r.Body, "password"), true);
        }
        if (p == "/login-form") {
            if (m != "POST") return Err(405, "use POST");
            return LogIn(FormField(r.Body, "username"), FormField(r.Body, "password"), false);
        }
        if (p == "/logout") { string s; if (r.Cookies.TryGetValue("session", out s)) lock (gate) sessions.Remove(s); var res = Json(200, "{\"ok\":true}"); res.Headers.Add(new[] { "Set-Cookie", "session=; Path=/; Max-Age=0" }); return res; }
        if (p == "/me") {
            int id = Caller(r, true);
            if (id == 0) return Err(401, "send Authorization: Bearer <token> (from POST /login) or the session cookie");
            return Json(200, UserJson(UserById(id)));
        }
        if (p == "/csrf" && m == "GET") {
            var t = Guid.NewGuid().ToString("N").Substring(0, 20);
            lock (gate) csrf.Add(t);
            var res = new Resp { Type = "text/html", Body = "<html><body><form method=\"post\" action=\"/items\">\n  <input type=\"hidden\" name=\"csrf\" value=\"" + t + "\">\n</form></body></html>" };
            res.Headers.Add(new[] { "X-CSRF-Token", t });
            return res;
        }
        if (p.StartsWith("/status/")) { int code; if (!int.TryParse(p.Substring(8), out code) || code < 100 || code > 599) code = 400; return Json(code, "{\"status\":" + code + "}"); }
        if (p == "/slow") {
            int ms = 2000; foreach (var kv in r.Query.Split('&')) if (kv.StartsWith("ms=")) int.TryParse(kv.Substring(3), out ms);
            ms = Math.Max(0, Math.Min(ms, 15000));
            System.Threading.Thread.Sleep(ms);
            return Json(200, "{\"waited\":" + ms + "}");
        }
        if (p == "/echo") {
            var sb = new StringBuilder("{\"method\":" + J(m) + ",\"path\":" + J(p) + ",\"query\":" + J(r.Query) + ",\"headers\":{");
            bool f = true; foreach (var kv in r.Headers) { if (!f) sb.Append(','); f = false; sb.Append(J(kv.Key)).Append(':').Append(J(kv.Value)); }
            sb.Append("},\"cookies\":{"); f = true; foreach (var kv in r.Cookies) { if (!f) sb.Append(','); f = false; sb.Append(J(kv.Key)).Append(':').Append(J(kv.Value)); }
            sb.Append("},\"body\":").Append(J(r.Body)).Append('}');
            return Json(200, sb.ToString());
        }
        if (p == "/items" || p.StartsWith("/items/")) return Items(r);
        return Err(404, "no such endpoint: " + m + " " + p + " - GET / lists them");
    }

    Resp Items(Req r) {
        int who = Caller(r, true);
        if (who == 0) return Err(401, "log in first: send the session cookie or Authorization: Bearer <token>");
        string m = r.Method;
        lock (gate) {
            if (r.Path == "/items") {
                if (m == "GET") return Json(200, "{\"count\":" + items.Count + ",\"items\":[" + string.Join(",", items.Values.ToArray()) + "]}");
                if (m == "POST") {
                    var b = (r.Body ?? "").Trim();
                    if (!b.StartsWith("{") || !b.EndsWith("}")) return Err(400, "send a JSON object, e.g. {\"name\":\"Lamp\",\"price\":25}");
                    if (Field(b, "name") == null) return Err(400, "\"name\" is required");
                    int id = nextId++;
                    var inner = b.Substring(1, b.Length - 2).Trim();
                    inner = System.Text.RegularExpressions.Regex.Replace(inner, "\"(id|owner)\"\\s*:\\s*[^,}]+,?", "").Trim().TrimEnd(',');
                    items[id] = "{\"id\":" + id + (inner.Length > 0 ? "," + inner : "") + ",\"owner\":" + who + "}";
                    var res = Json(201, items[id]);
                    res.Headers.Add(new[] { "Location", "/items/" + id });
                    return res;
                }
                return Err(405, "use GET or POST");
            }
            int iid;
            if (!int.TryParse(r.Path.Substring(7), out iid)) return Err(400, "the id must be a number");
            if (!items.ContainsKey(iid)) return Err(404, "item " + iid + " not found");
            if (m == "GET") return Json(200, items[iid]);
            if (m == "PUT" || m == "PATCH") {
                var b = (r.Body ?? "").Trim();
                if (!b.StartsWith("{")) return Err(400, "send a JSON object");
                var name = Field(b, "name") ?? Field(items[iid], "name");
                var price = Field(b, "price") ?? Field(items[iid], "price") ?? "0";
                items[iid] = "{\"id\":" + iid + ",\"name\":" + J(name) + ",\"price\":" + price + ",\"owner\":" + who + "}";
                return Json(200, items[iid]);
            }
            if (m == "DELETE") {
                string t;
                if (!r.Headers.TryGetValue("X-CSRF-Token", out t) || !csrf.Contains(t)) return Err(403, "deleting needs the header X-CSRF-Token with a token from GET /csrf");
                csrf.Remove(t);
                items.Remove(iid);
                return new Resp { Status = 204, Body = "" };
            }
            return Err(405, "use GET, PUT, PATCH or DELETE");
        }
    }

    string Help() {
        return "DevTools Test API  -  http://127.0.0.1:" + Port + "\n\n" +
            "Users: demo / demo   and   ann / secret\n\n" +
            "POST /login        JSON {\"username\":\"demo\",\"password\":\"demo\"} -> {\"token\":...,\"userId\":1}  + cookie session=...\n" +
            "POST /login-form   form username=demo&password=demo -> cookie session=... (no token)\n" +
            "POST /logout       clears the session cookie\n" +
            "GET  /me           who you are (Bearer token or session cookie)\n" +
            "GET  /items        the list (needs the token or the cookie)\n" +
            "POST /items        JSON {\"name\":\"Lamp\",\"price\":25} -> 201 with the new id\n" +
            "GET  /items/{id}   one item (404 if missing)\n" +
            "PUT  /items/{id}   change it\n" +
            "DELETE /items/{id} needs header X-CSRF-Token from GET /csrf -> 204\n" +
            "GET  /csrf         a token in the X-CSRF-Token header and in the HTML (value=\"...\")\n" +
            "GET  /status/{code} answers with that status\n" +
            "GET  /slow?ms=2000 answers after a delay\n" +
            "ANY  /echo         sends back what you sent: method, query, headers, cookies, body\n";
    }
}

// An owner-drawn list box that paints into a back buffer (no flicker when it's redrawn often).
public class DevBufferedListBox : System.Windows.Forms.ListBox {
    public DevBufferedListBox() {
        SetStyle(System.Windows.Forms.ControlStyles.OptimizedDoubleBuffer | System.Windows.Forms.ControlStyles.AllPaintingInWmPaint |
                 System.Windows.Forms.ControlStyles.ResizeRedraw | System.Windows.Forms.ControlStyles.UserPaint, true);
        DrawMode = System.Windows.Forms.DrawMode.OwnerDrawFixed;
    }
    protected override void OnPaint(System.Windows.Forms.PaintEventArgs e) {
        using (var b = new System.Drawing.SolidBrush(BackColor)) e.Graphics.FillRectangle(b, e.ClipRectangle);
        for (int i = Math.Max(0, TopIndex); i < Items.Count; i++) {
            var r = GetItemRectangle(i);
            if (r.Top > ClientSize.Height) break;
            if (!e.ClipRectangle.IntersectsWith(r)) continue;
            var st = SelectedIndices.Contains(i) ? System.Windows.Forms.DrawItemState.Selected : System.Windows.Forms.DrawItemState.None;
            OnDrawItem(new System.Windows.Forms.DrawItemEventArgs(e.Graphics, Font, r, i, st, ForeColor, BackColor));
        }
    }
    protected override void OnSelectedIndexChanged(EventArgs e) { base.OnSelectedIndexChanged(e); Invalidate(); }
}

public static class DevEnv {
    const string MachineKey = @"SYSTEM\CurrentControlSet\Control\Session Manager\Environment";
    static RegistryKey Open(bool machine, bool write) {
        return machine ? Registry.LocalMachine.OpenSubKey(MachineKey, write) : Registry.CurrentUser.OpenSubKey("Environment", write);
    }

    // name -> raw value (unexpanded)
    public static SortedDictionary<string, string> List(bool machine) {
        var d = new SortedDictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        using (var k = Open(machine, false)) {
            if (k == null) return d;
            foreach (string n in k.GetValueNames()) d[n] = Convert.ToString(k.GetValue(n, "", RegistryValueOptions.DoNotExpandEnvironmentNames));
        }
        return d;
    }

    public static string Get(bool machine, string name) {
        using (var k = Open(machine, false)) return k == null ? null : (string)k.GetValue(name, null, RegistryValueOptions.DoNotExpandEnvironmentNames);
    }

    public static void Set(bool machine, string name, string value) {
        using (var k = Open(machine, true)) {
            if (k == null) throw new InvalidOperationException("Cannot open the environment key.");
            if (value == null) k.DeleteValue(name, false);
            else k.SetValue(name, value, value.Contains("%") || name.Equals("Path", StringComparison.OrdinalIgnoreCase) ? RegistryValueKind.ExpandString : RegistryValueKind.String);
        }
        Broadcast();
    }

    [DllImport("user32.dll", CharSet = CharSet.Unicode, SetLastError = true)]
    static extern IntPtr SendMessageTimeout(IntPtr hWnd, uint msg, IntPtr wParam, string lParam, uint flags, uint timeout, out IntPtr result);

    // Tells Explorer and other programs that the environment changed (new windows pick it up).
    public static void Broadcast() {
        IntPtr r;
        SendMessageTimeout((IntPtr)0xffff, 0x001A, IntPtr.Zero, "Environment", 0x0002, 3000, out r);
    }
}

// ---- Notes: rich text to Markdown, and code colouring inside a note's text box ---------------------
public static class DevNoteFormat {
    [DllImport("user32.dll")] static extern IntPtr SendMessage(IntPtr h, int msg, IntPtr w, IntPtr l);
    const int WM_SETREDRAW = 0x000B;

    static bool IsMono(System.Drawing.Font f) {
        string n = f.Name.ToLowerInvariant();
        return n.Contains("consolas") || n.Contains("courier") || n.Contains("mono") || n.Contains("cascadia") || n.Contains("lucida console");
    }

    // One text box of a note (RTF) as Markdown: headings, bullets, bold / italic / strike, code.
    public static string ToMarkdown(string rtf, string plain) {
        var r = new System.Windows.Forms.RichTextBox();
        try {
            try { if (!string.IsNullOrEmpty(rtf)) r.Rtf = rtf; else r.Text = plain ?? ""; } catch { r.Text = plain ?? ""; }
            string text = r.Text;
            int n = text.Length;
            var b = new bool[n]; var it = new bool[n]; var st = new bool[n]; var mono = new bool[n]; var size = new float[n];
            var sizes = new Dictionary<float, int>();
            for (int i = 0; i < n; i++) {
                r.Select(i, 1);
                var f = r.SelectionFont;
                if (f == null) continue;
                b[i] = f.Bold; it[i] = f.Italic; st[i] = f.Strikeout; mono[i] = IsMono(f); size[i] = f.Size;
                if (!char.IsWhiteSpace(text[i])) { int c; sizes.TryGetValue(f.Size, out c); sizes[f.Size] = c + 1; }
            }
            float baseSize = 0; int best = -1;
            foreach (var kv in sizes) if (kv.Value > best) { best = kv.Value; baseSize = kv.Key; }
            var sb = new StringBuilder();
            var code = new List<string>();
            int pos = 0;
            string prevKind = "";
            Action flushCode = delegate {
                if (code.Count == 0) return;
                string body = string.Join("\n", code.ToArray());
                if (sb.Length > 0 && !sb.ToString().EndsWith("\n\n")) sb.Append('\n');
                sb.Append("```").Append(DevCode.Guess(body)).Append('\n').Append(body).Append("\n```\n\n");
                code.Clear();
            };
            foreach (string line in text.Split('\n')) {
                int start = pos, len = line.Length;
                pos += len + 1;
                if (line.Trim() == "") { flushCode(); if (prevKind == "list") sb.Append('\n'); prevKind = ""; continue; }
                bool allMono = true; float maxSize = 0; bool allBold = true;
                for (int i = start; i < start + len; i++) {
                    if (char.IsWhiteSpace(text[i])) continue;
                    if (!mono[i]) allMono = false;
                    if (!b[i]) allBold = false;
                    if (size[i] > maxSize) maxSize = size[i];
                }
                if (allMono) { code.Add(line); continue; }
                flushCode();
                r.Select(start, 0);
                bool bullet = r.SelectionBullet;
                string prefix = "";
                bool heading = false;
                if (baseSize > 0 && maxSize >= baseSize * 1.8f) { prefix = "# "; heading = true; }
                else if (baseSize > 0 && maxSize >= baseSize * 1.3f) { prefix = "## "; heading = true; }
                else if (baseSize > 0 && maxSize > baseSize * 1.1f && allBold) { prefix = "### "; heading = true; }
                else if (bullet) prefix = "- ";
                string kind = heading ? "heading" : bullet ? "list" : "para";
                if (sb.Length > 0 && !(kind == "list" && prevKind == "list") && !sb.ToString().EndsWith("\n\n")) sb.Append('\n');
                sb.Append(prefix);
                // runs with the same style
                int k = start;
                while (k < start + len) {
                    int e = k + 1;
                    while (e < start + len && b[e] == b[k] && it[e] == it[k] && st[e] == st[k] && mono[e] == mono[k]) e++;
                    string run = text.Substring(k, e - k);
                    string core = run.Trim();
                    if (core == "") { sb.Append(run); k = e; continue; }
                    string lead = run.Substring(0, run.Length - run.TrimStart().Length), trail = run.Substring(run.TrimEnd().Length);
                    string m = core;
                    if (mono[k]) m = "`" + m + "`";
                    else {
                        if (b[k] && !heading) m = "**" + m + "**";
                        if (it[k]) m = "*" + m + "*";
                    }
                    if (st[k]) m = "~~" + m + "~~";
                    sb.Append(lead).Append(m).Append(trail);
                    k = e;
                }
                sb.Append('\n');
                prevKind = kind;
            }
            flushCode();
            return sb.ToString().Trim('\n');
        } finally { r.Dispose(); }
    }

    // Formats [start, start+len) of a text box as code: monospace, shaded, coloured by language.
    // colors: 0 = text, 1 keyword, 2 string, 3 comment, 4 number, 5 type; returns the language used.
    public static string Colorize(System.Windows.Forms.RichTextBox box, int start, int len, string lang, System.Drawing.Color[] colors, System.Drawing.Color back, float size) {
        if (len <= 0) return "";
        int selStart = box.SelectionStart, selLen = box.SelectionLength;
        string text = box.Text.Substring(start, len);
        if (string.IsNullOrEmpty(lang)) lang = DevCode.Guess(text);
        SendMessage(box.Handle, WM_SETREDRAW, IntPtr.Zero, IntPtr.Zero);
        try {
            box.Select(start, len);
            box.SelectionFont = new System.Drawing.Font("Consolas", size);
            box.SelectionColor = colors[0];
            box.SelectionBackColor = back;
            box.SelectionBullet = false;
            foreach (int[] t in DevCode.Tokens(text, lang)) {
                box.Select(start + t[0], t[1]);
                box.SelectionColor = colors[t[2]];
            }
            box.Select(selStart, selLen);
        } finally {
            SendMessage(box.Handle, WM_SETREDRAW, (IntPtr)1, IntPtr.Zero);
            box.Invalidate();
        }
        return lang;
    }

    // Back to normal text.
    public static void Plain(System.Windows.Forms.RichTextBox box, int start, int len, System.Drawing.Font font, System.Drawing.Color fore, System.Drawing.Color back) {
        int selStart = box.SelectionStart, selLen = box.SelectionLength;
        box.Select(start, len);
        box.SelectionFont = font; box.SelectionColor = fore; box.SelectionBackColor = back;
        box.Select(selStart, selLen);
    }
}
'@
}

# ---------------------------------------------------------------------------
# Toolbox: one window with developer tools as pages (JSON, JWT, Regex, Cron, Generators, QR code,
# Colour, File hash, Ports, Certificates, Host monitor, number bases, units, time zones, Markdown,
# environment & PATH, processes & services, timer). Pages are built the first time they are shown.
# ---------------------------------------------------------------------------
$TbUI = @{ Form = $null; Pages = [ordered]@{}; Current = $null }

function Register-ToolboxPage([string]$Key, [string]$Title, [string]$Icon, [string]$Words, [scriptblock]$Build) {
    $TbUI.Pages[$Key] = [pscustomobject]@{ Key = $Key; Title = $Title; Icon = $Icon; Build = $Build; Panel = $null; State = $null }
    $k = $Key
    Register-PaletteCommand $Title 'Toolbox' $Icon ([scriptblock]::Create("Show-Toolbox '$k'")) $Words
}

# ---- small builders shared by the pages ----------------------------------------------------------
function New-TbBox([switch]$Mono, [switch]$Multi, [switch]$ReadOnly, [string]$Cue = '') {
    $b = New-Object System.Windows.Forms.TextBox
    $b.BorderStyle = 'FixedSingle'; $b.BackColor = $(if ($ReadOnly) { $C.Card } else { $C.Bg }); $b.ForeColor = $C.Fore
    if ($Mono) { $b.Font = New-Object System.Drawing.Font('Consolas', (Fz 10.5)) }
    if ($Multi) { $b.Multiline = $true; $b.ScrollBars = 'Both'; $b.WordWrap = $false; $b.AcceptsReturn = $true; $b.AcceptsTab = $true; $b.MaxLength = 0 }
    if ($ReadOnly) { $b.ReadOnly = $true }
    if ($Cue) { $b.Tag = $Cue; $b.add_HandleCreated({ param($src, $e) [PowerClipHost]::SetCueBanner($src.Handle, [string]$src.Tag) }) }
    $b
}

function New-TbRtb([switch]$ReadOnly) {
    $r = New-Object System.Windows.Forms.RichTextBox
    $r.BorderStyle = 'None'; $r.BackColor = $C.Bg; $r.ForeColor = $C.Fore; $r.WordWrap = $false; $r.DetectUrls = $false
    $r.Font = New-Object System.Drawing.Font('Consolas', (Fz 10.5)); $r.HideSelection = $false
    if ($ReadOnly) { $r.ReadOnly = $true }
    $r
}

function New-TbBar($Parent, [string]$Dock = 'Top') {
    $bar = New-Object System.Windows.Forms.FlowLayoutPanel
    $bar.Dock = $Dock; $bar.AutoSize = $true; $bar.AutoSizeMode = 'GrowAndShrink'; $bar.WrapContents = $true; $bar.BackColor = $Parent.BackColor
    $bar.Padding = New-Object System.Windows.Forms.Padding(0, (Px 2), 0, (Px 6))
    $Parent.Controls.Add($bar)
    $bar
}

function New-TbLabel($Parent, [string]$Text, [switch]$Dim, [switch]$Title) {
    $l = New-Object System.Windows.Forms.Label
    $l.Text = $Text; $l.AutoSize = $true; $l.BackColor = $Parent.BackColor
    $l.ForeColor = $(if ($Dim) { $C.Dim } else { $C.Fore })
    if ($Title) { $l.Font = New-Object System.Drawing.Font($UiFont, (Fz 10.5), [System.Drawing.FontStyle]::Bold) }
    $l.Margin = New-Object System.Windows.Forms.Padding((Px 2), (Px 8), (Px 6), 0)
    $Parent.Controls.Add($l)
    $l
}

function New-TbCombo($Parent, [string[]]$Items, [int]$Width = 120) {
    $cx = New-Object System.Windows.Forms.ComboBox
    $cx.DropDownStyle = 'DropDownList'; $cx.FlatStyle = 'Flat'; $cx.BackColor = $C.Bg; $cx.ForeColor = $C.Fore; $cx.Width = Px ($Width * $TextZoom)
    $cx.Margin = New-Object System.Windows.Forms.Padding(0, (Px 4), (Px 6), 0)
    foreach ($i in $Items) { [void]$cx.Items.Add($i) }
    if ($Items.Count) { $cx.SelectedIndex = 0 }
    $Parent.Controls.Add($cx)
    $cx
}

function New-TbNumber($Parent, [int]$Value, [int]$Min, [int]$Max) {
    $n = New-Object System.Windows.Forms.NumericUpDown
    $n.Minimum = $Min; $n.Maximum = $Max; $n.Value = $Value; $n.Width = Px (70 * $TextZoom); $n.BorderStyle = 'FixedSingle'
    $n.BackColor = $C.Bg; $n.ForeColor = $C.Fore; $n.Margin = New-Object System.Windows.Forms.Padding(0, (Px 4), (Px 8), 0)
    $Parent.Controls.Add($n)
    $n
}

# A page: padded panel with a status line at the bottom.
function New-TbPage($Panel) {
    $Panel.Padding = New-Object System.Windows.Forms.Padding((Px 16), (Px 12), (Px 16), (Px 6))
    $status = New-Object System.Windows.Forms.Label
    $status.Dock = 'Bottom'; $status.AutoSize = $false; $status.Height = $FontMain.Height + (Px 10); $status.TextAlign = 'MiddleLeft'
    $status.ForeColor = $C.Dim; $status.BackColor = $Panel.BackColor
    $Panel.Controls.Add($status)
    $status
}

function Set-TbStatus($Label, [string]$Text, [string]$Kind = '') {
    $Label.Text = $Text
    $Label.ForeColor = switch ($Kind) { 'ok' { $C.Green } 'error' { $C.Red } 'warn' { $C.Yellow } default { $C.Dim } }
}

# Runs $Action a moment after the last keystroke.
function New-TbDebounce([int]$Ms, [scriptblock]$Action) {
    $t = New-Object System.Windows.Forms.Timer
    $t.Interval = $Ms
    $t.Tag = $Action
    $t.add_Tick({ param($src, $e) $src.Stop(); & $src.Tag })
    $t
}

function Copy-TbText([string]$Text) {
    if (-not $Text) { return }
    try { [System.Windows.Forms.Clipboard]::SetText($Text) } catch { }
}

function Show-Toolbox([string]$Page = '', $InputText = $null) {
    Hide-Picker
    if (-not $TbUI.Form -or $TbUI.Form.IsDisposed) { New-ToolboxForm }
    if (-not $Page) { $Page = if ($TbUI.Current) { $TbUI.Current } else { @($TbUI.Pages.Keys)[0] } }
    Select-ToolboxPage $Page
    if ($null -ne $InputText -and $TbUI.Pages[$Page].State.SetInput) { & $TbUI.Pages[$Page].State.SetInput ([string]$InputText) }
    if ($TbUI.Form.WindowState -eq 'Minimized') { $TbUI.Form.WindowState = 'Normal' }
    $TbUI.Form.Show()
    [PowerClipHost]::EnsureShown($TbUI.Form.Handle)
    $TbUI.Form.Activate()
}

# A control docked to Fill must be laid out after its Top / Bottom neighbours; bringing it to the
# front of the z-order does that, whatever order the page added its controls in.
function Repair-Docking($Ctl) {
    foreach ($cx in @($Ctl.Controls)) {
        if ($cx.Dock -eq 'Fill') { $cx.BringToFront() }
        if ($cx.Controls.Count -gt 0) { Repair-Docking $cx }
    }
}

function Select-ToolboxPage([string]$Key) {
    $p = $TbUI.Pages[$Key]
    if (-not $p) { return }
    if (-not $p.Panel) {
        $panel = New-Object System.Windows.Forms.Panel
        $panel.Dock = 'Fill'; $panel.BackColor = $C.Bg; $panel.Visible = $false
        $TbUI.Host.Controls.Add($panel)
        $p.Panel = $panel
        $p.State = @{}                       # exists before the page is built, so its event handlers can use it
        [void](& $p.Build $panel $p.State)
        Repair-Docking $panel
        if ($TbUI.Form.IsHandleCreated) { Set-ControlTheme $panel $null $script:IsDark }
    }
    foreach ($x in $TbUI.Pages.Values) { if ($x.Panel) { $x.Panel.Visible = ($x.Key -eq $Key) } }
    $TbUI.Current = $Key
    $idx = @($TbUI.Pages.Keys).IndexOf($Key)
    if ($TbUI.List.SelectedIndex -ne $idx) { $TbUI.List.SelectedIndex = $idx }
    $TbUI.Form.Text = "Toolbox  -  $($p.Title)"
    if ($p.State.Focus) { & $p.State.Focus }
}

function New-ToolboxForm {
    $f = New-Object System.Windows.Forms.Form
    $f.Text = 'Toolbox'; $f.Icon = $IconActive
    $f.Size = New-Object System.Drawing.Size((Px (1180 * $TextZoom)), (Px 780))
    $f.MinimumSize = New-Object System.Drawing.Size((Px 760), (Px 460))
    $f.StartPosition = 'CenterScreen'; $f.BackColor = $C.Bg; $f.ForeColor = $C.Fore; $f.Font = $FontMain; $f.KeyPreview = $true
    $TbUI.Form = $f
    $hostPanel = New-Object System.Windows.Forms.Panel
    $hostPanel.Dock = 'Fill'; $hostPanel.BackColor = $C.Bg
    $f.Controls.Add($hostPanel)
    $TbUI.Host = $hostPanel
    $list = New-Object System.Windows.Forms.ListBox
    $list.Dock = 'Left'; $list.Width = Px (210 * $TextZoom); $list.BorderStyle = 'None'; $list.DrawMode = 'OwnerDrawFixed'; $list.IntegralHeight = $false
    $list.ItemHeight = $FontMain.Height + (Px 18); $list.BackColor = $C.Panel; $list.ForeColor = $C.Fore
    foreach ($k in $TbUI.Pages.Keys) { [void]$list.Items.Add($k) }
    $list.add_DrawItem({
        param($src, $e)
        if ($e.Index -lt 0) { return }
        $p = $TbUI.Pages[[string]$src.Items[$e.Index]]
        $g = $e.Graphics; $r = $e.Bounds
        $sel = ($e.State -band [System.Windows.Forms.DrawItemState]::Selected) -ne 0
        $b = New-Object System.Drawing.SolidBrush $C.Panel; $g.FillRectangle($b, $r); $b.Dispose()
        if ($sel) {
            $g.SmoothingMode = 'AntiAlias'
            $path = [PowerClipTheme]::Round((New-Object System.Drawing.RectangleF(($r.X + (Px 6)), ($r.Y + (Px 2)), ($r.Width - (Px 12)), ($r.Height - (Px 4)))), (Px 6))
            $b = New-Object System.Drawing.SolidBrush $C.Sel; $g.FillPath($b, $path); $b.Dispose(); $path.Dispose()
            $g.SmoothingMode = 'Default'
            $bar = New-Object System.Drawing.SolidBrush $C.Accent; $g.FillRectangle($bar, ($r.X + (Px 6)), ($r.Y + (Px 9)), (Px 3), ($r.Height - (Px 18))); $bar.Dispose()
        }
        $x = $r.X + (Px 18)
        if ($FontIconSmall) {
            [System.Windows.Forms.TextRenderer]::DrawText($g, $p.Icon, $FontIconSmall, (New-Object System.Drawing.Rectangle($x, $r.Y, (Px 20), $r.Height)), $(if ($sel) { $C.Accent } else { $C.Dim }),
                [System.Windows.Forms.TextFormatFlags]'VerticalCenter, HorizontalCenter, NoPrefix, SingleLine, NoPadding')
            $x += Px 30
        }
        [System.Windows.Forms.TextRenderer]::DrawText($g, $p.Title, $FontMain, (New-Object System.Drawing.Rectangle($x, $r.Y, ($r.Right - $x), $r.Height)), $C.Fore, $TextFlags)
    })
    $list.add_SelectedIndexChanged({ param($src, $e) if ($src.SelectedIndex -ge 0) { $k = [string]$src.SelectedItem; if ($k -ne $TbUI.Current) { Select-ToolboxPage $k } } })
    $f.Controls.Add($list)
    $TbUI.List = $list
    $f.add_KeyDown({
        param($src, $e)
        if ($e.Control -and $e.KeyCode -eq 'PageDown') { $TbUI.List.SelectedIndex = ($TbUI.List.SelectedIndex + 1) % $TbUI.List.Items.Count; $e.SuppressKeyPress = $true }
        elseif ($e.Control -and $e.KeyCode -eq 'PageUp') { $TbUI.List.SelectedIndex = ($TbUI.List.SelectedIndex - 1 + $TbUI.List.Items.Count) % $TbUI.List.Items.Count; $e.SuppressKeyPress = $true }
    })
    $f.add_FormClosed({
        param($src, $e)
        foreach ($p in $TbUI.Pages.Values) { if ($p.State -and $p.State.Close) { try { & $p.State.Close } catch { } }; $p.Panel = $null; $p.State = $null }
        $TbUI.Form = $null; $TbUI.Current = $null
        $src.Dispose()
    })
    Register-ThemedWindow $f
}

# ======================================================================================
# JSON, YAML, CSV and XML: convert any to any, tree view with paths, JSONPath query, loop code helper.
# ======================================================================================
$DataFormats = [ordered]@{ 'Detect' = 'auto'; 'JSON' = 'json'; 'YAML' = 'yaml'; 'CSV' = 'csv'; 'Tab-separated' = 'tsv'; 'XML' = 'xml' }

function Get-JsonTreeText($Name, $Value) {
    $t = [DevJson]::TypeName($Value)
    if ($t -eq 'object' -or $t -eq 'array') { return "$Name  $([DevJson]::Short($Value, 60))" }
    "$Name : $([DevJson]::Short($Value, 120))"
}

# A path step: K = key, or I = array index.
function New-PathStep([string]$Key) {
    if ($Key -match '^\[(\d+)\]$') { [pscustomobject]@{ K = $null; I = [int]$Matches[1] } } else { [pscustomobject]@{ K = $Key; I = -1 } }
}

function Add-JsonTreeChildren($Nodes, $Value, $Steps = @()) {
    $n = 0
    foreach ($kv in [DevJson]::Children($Value)) {
        if (++$n -gt 2000) { [void]$Nodes.Add("... $(([DevJson]::Children($Value)).Count - 2000) more"); break }
        $node = New-Object System.Windows.Forms.TreeNode((Get-JsonTreeText $kv.Key $kv.Value))
        $node.Tag = [pscustomobject]@{ V = $kv.Value; Steps = @($Steps) + @(New-PathStep $kv.Key) }
        if ([DevJson]::Children($kv.Value).Count -gt 0) { [void]$node.Nodes.Add('') }
        [void]$Nodes.Add($node)
    }
}

Register-ToolboxPage 'json' 'JSON, YAML, CSV, XML' $Glyph.Code 'json yaml yml csv tsv tab separated delimited excel xml convert format pretty minify jsonpath tree validate path loop foreach code' {
    param($panel, $st)
    $st.Status = New-TbPage $panel
    $split = New-Object System.Windows.Forms.SplitContainer
    $split.Dock = 'Fill'; $split.BackColor = $C.Line; $split.SplitterWidth = 3
    $split.Panel1.BackColor = $C.Bg; $split.Panel2.BackColor = $C.Bg
    $panel.Controls.Add($split)
    $bar = New-TbBar $panel
    $st.Input = New-TbBox -Mono -Multi -Cue 'Paste JSON, YAML, CSV or XML here'
    $st.Input.Dock = 'Fill'
    $split.Panel1.Controls.Add($st.Input)
    $ibar = New-TbBar $split.Panel1
    New-TbLabel $ibar 'Input' -Title | Out-Null
    $st.From = New-TbCombo $ibar @($DataFormats.Keys) 100
    $st.Detected = New-TbLabel $ibar '' -Dim

    $tabs = New-TabSet $split.Panel2
    $outPanel = Add-ApiTab $tabs 'Output'
    $treePanel = Add-ApiTab $tabs 'Tree'
    $pathPanel = Add-ApiTab $tabs 'Path & loop code'
    $queryPanel = Add-ApiTab $tabs 'Query'
    $st.Output = New-TbRtb -ReadOnly; $st.Output.Dock = 'Fill'
    $outPanel.Controls.Add($st.Output)
    $st.Tree = New-Object System.Windows.Forms.TreeView
    $st.Tree.Dock = 'Fill'; $st.Tree.BorderStyle = 'None'; $st.Tree.BackColor = $C.Bg; $st.Tree.ForeColor = $C.Fore
    $st.Tree.Font = New-Object System.Drawing.Font('Consolas', (Fz 10)); $st.Tree.HideSelection = $false
    $st.Tree.add_BeforeExpand({
        param($src, $e)
        if ($e.Node.Nodes.Count -eq 1 -and $e.Node.Nodes[0].Text -eq '') { $e.Node.Nodes.Clear(); Add-JsonTreeChildren $e.Node.Nodes $e.Node.Tag.V $e.Node.Tag.Steps }
    })
    $st.Tree.add_AfterSelect({ param($src, $e) $s = $TbUI.Pages['json'].State; if ($e.Node.Tag) { Update-JsonPathHelp $s $e.Node.Tag } })
    $st.Tree.add_NodeMouseDoubleClick({ param($src, $e) $s = $TbUI.Pages['json'].State; if ($e.Node.Tag) { Update-JsonPathHelp $s $e.Node.Tag; Select-ApiTab $s.Tabs 'Path & loop code' } })
    $treePanel.Controls.Add($st.Tree)
    $tbar = New-TbBar $treePanel 'Bottom'
    New-TbLabel $tbar 'Click a value to see its path and the code to read it (or loop over its list). Double-click opens Path & loop code.' -Dim | Out-Null
    $st.Code = New-TbRtb -ReadOnly; $st.Code.Dock = 'Fill'
    $pathPanel.Controls.Add($st.Code)
    $pbar = New-TbBar $pathPanel
    New-TbLabel $pbar 'Code reads' -Dim | Out-Null
    $st.CodeFor = New-TbCombo $pbar @('the input as it is', 'the converted JSON') 170
    $st.CodeFor.add_SelectedIndexChanged({ $s = $TbUI.Pages['json'].State; if ($s.PathTag) { Update-JsonPathHelp $s $s.PathTag } })
    $st.Lang = New-TbCombo $pbar @('All languages', 'JavaScript', 'Python', 'C#', 'PowerShell', 'Command line') 150
    $st.Lang.add_SelectedIndexChanged({ $s = $TbUI.Pages['json'].State; if ($s.PathTag) { Update-JsonPathHelp $s $s.PathTag } })
    [void](New-Button 'Copy' 'Copy the selected text, or everything' { $s = $TbUI.Pages['json'].State; Copy-TbText $(if ($s.Code.SelectionLength) { $s.Code.SelectedText } else { $s.Code.Text }) } $pbar $Glyph.Copy 1)
    [void](New-Button 'Query every item' 'Run the [*] path in the Query tab' { $s = $TbUI.Pages['json'].State; if ($s.WildPath) { $s.Path.Text = $s.WildPath; Select-ApiTab $s.Tabs 'Query' } } $pbar $Glyph.Search 2)
    $qbar = New-TbBar $queryPanel
    New-TbLabel $qbar 'JSONPath' -Dim | Out-Null
    $st.Path = New-TbBox -Mono -Cue '$.items[*].name   $..id   $.list[0:3]'
    $st.Path.Width = Px (360 * $TextZoom); $st.Path.Margin = New-Object System.Windows.Forms.Padding(0, (Px 4), (Px 6), 0)
    $qbar.Controls.Add($st.Path)
    $st.QueryOut = New-TbRtb -ReadOnly; $st.QueryOut.Dock = 'Fill'
    $queryPanel.Controls.Add($st.QueryOut)
    $queryPanel.Controls.SetChildIndex($qbar, $queryPanel.Controls.Count - 1)
    Select-ApiTab $tabs 'Output'
    $st.Tabs = $tabs

    New-TbLabel $bar 'Convert to' -Dim | Out-Null
    $st.Mode = 'json'
    $st.ModeButtons = @()
    foreach ($m in @(@('JSON', 'json', 'Pretty JSON'), @('Minified', 'minify', 'JSON on one line'), @('Sorted keys', 'sort', 'JSON with the keys of every object in alphabetical order'),
                     @('YAML', 'yaml', 'YAML'), @('CSV', 'csv', 'CSV: a list of objects becomes rows; nested values become a.b columns'),
                     @('Tab-separated', 'tsv', 'Tab-separated rows (paste straight into Excel or Google Sheets)'),
                     @('XML', 'xml', 'XML: keys become elements, "@name" keys attributes, lists repeated elements'))) {
        $b = New-Button $m[0] $m[2] {
            param($src, $e)
            $s = $TbUI.Pages['json'].State; $s.Mode = $src.Tag
            foreach ($x in $s.ModeButtons) { $x.Selected = ($x.Tag -eq $s.Mode); $x.Invalidate() }
            Update-JsonTool $s; Select-ApiTab $s.Tabs 'Output'
        } $bar '' 2
        $b.Tag = $m[1]
        $b.Selected = ($m[1] -eq 'json')
        $st.ModeButtons += $b
    }
    $st.Indent = New-TbCombo $bar @('2 spaces', '4 spaces', 'Tab') 100
    [void](New-Button 'Copy' 'Copy the output' { $s = $TbUI.Pages['json'].State; Copy-TbText $(switch ($s.Tabs.Current) { 'Query' { $s.QueryOut.Text } 'Path & loop code' { $s.Code.Text } default { $s.Output.Text } }) } $bar $Glyph.Copy 1)
    [void](New-Button 'Use as input' 'Replace the input with the output' { $s = $TbUI.Pages['json'].State; if ($s.Output.Text) { $s.Input.Text = $s.Output.Text } } $bar $Glyph.Undo 2)
    [void](New-Button 'Compare...' 'Compare the input with the clipboard (any of the formats), ignoring key order and formatting' {
        $s = $TbUI.Pages['json'].State
        $clip = ''; try { $clip = [System.Windows.Forms.Clipboard]::GetText() } catch { }
        if (-not $s.Root) { Set-TbStatus $s.Status 'The input is not valid.' 'error'; return }
        $left = [DevJson]::Write($s.Root, 2, $true)
        $right = try { [DevJson]::Write([DevData]::Parse($clip, 'auto'), 2, $true) } catch { '' }
        if (-not $right) { Set-TbStatus $s.Status 'Copy the second document first; it is compared with the input (keys sorted, same formatting).' 'warn' }
        Show-Compare ([pscustomobject]@{ Kind = 'text'; Text = $left; Id = '' }) ([pscustomobject]@{ Kind = 'text'; Text = $right; Id = '' })
    } $bar $Glyph.Compare 2)

    $st.Timer = New-TbDebounce 300 { Update-JsonTool $TbUI.Pages['json'].State }
    $st.Input.add_TextChanged({ $s = $TbUI.Pages['json'].State; $s.Timer.Stop(); $s.Timer.Start() })
    $st.Indent.add_SelectedIndexChanged({ Update-JsonTool $TbUI.Pages['json'].State })
    $st.From.add_SelectedIndexChanged({ Update-JsonTool $TbUI.Pages['json'].State })
    $st.QTimer = New-TbDebounce 300 { Update-JsonQuery $TbUI.Pages['json'].State }
    $st.Path.add_TextChanged({ $s = $TbUI.Pages['json'].State; $s.QTimer.Stop(); $s.QTimer.Start() })
    $st.SetInput = { param($t) $s = $TbUI.Pages['json'].State; $s.Input.Text = $t; Update-JsonTool $s }
    $st.Focus = { $TbUI.Pages['json'].State.Input.Focus() }
    $st.Code.Text = Get-JsonPathCheatSheet
    Set-TbStatus $st.Status 'Paste JSON, YAML, CSV or XML on the left and pick what to convert it to. Click a value in the Tree for its path and loop code.'
    $st
}

function Update-JsonTool($St) {
    $text = $St.Input.Text
    if (-not $text.Trim()) { $St.Output.Text = ''; $St.Tree.Nodes.Clear(); $St.Root = $null; $St.Json = ''; $St.Detected.Text = ''; Set-TbStatus $St.Status 'Paste JSON, YAML, CSV or XML on the left.'; return }
    $indent = switch ($St.Indent.SelectedIndex) { 1 { 4 } 2 { 1 } default { 2 } }
    $from = $DataFormats[[string]$St.From.SelectedItem]
    if ($from -eq 'auto') { $from = [DevData]::Detect($text) }
    $St.Detected.Text = if ($St.From.SelectedIndex -eq 0) { "read as $($from.ToUpper())" } else { '' }
    $St.InFormat = $from
    $St.Sep = if ($from -eq 'tsv') { "`t" } elseif ($from -eq 'csv') { [string][DevData]::CsvSeparator($text) } else { '' }
    try {
        $root = [DevData]::Parse($text, $from)
        $St.Root = $root
        $St.Json = [DevJson]::Write($root, -1, $false)
        if ($St.PathTag) { $St.PathTag = $null; $St.WildPath = $null; $St.Code.Text = Get-JsonPathCheatSheet }
        $out = switch ($St.Mode) {
            'minify' { [DevJson]::Write($root, -1, $false) }
            'sort'   { [DevJson]::Write($root, $indent, $true) }
            'yaml'   { [DevData]::Write($root, 'yaml', $indent, $false) }
            'csv'    { [DevData]::Write($root, 'csv', $indent, $false) }
            'tsv'    { [DevData]::Write($root, 'tsv', $indent, $false) }
            'xml'    { [DevData]::Write($root, 'xml', $indent, $false) }
            default  { [DevJson]::Write($root, $indent, $false) }
        }
        if ($St.Indent.SelectedIndex -eq 2 -and $St.Mode -in 'json', 'sort') { $out = [regex]::Replace($out, '(?m)^( +)', { param($m) "`t" * $m.Groups[1].Value.Length }) }
        $St.Output.Text = $out
        $St.Tree.BeginUpdate(); $St.Tree.Nodes.Clear()
        $rootNode = New-Object System.Windows.Forms.TreeNode((Get-JsonTreeText '$' $root)); $rootNode.Tag = [pscustomobject]@{ V = $root; Steps = @() }
        [void]$St.Tree.Nodes.Add($rootNode)
        Add-JsonTreeChildren $rootNode.Nodes $root @()
        $rootNode.Expand()
        $St.Tree.EndUpdate()
        Set-TbStatus $St.Status "Valid $($from.ToUpper())  $Dot  $([DevJson]::TypeName($root)) $([DevJson]::Short($root, 30))  $Dot  $('{0:N0}' -f $text.Length) characters" 'ok'
        Update-JsonQuery $St
    } catch {
        $St.Root = $null; $St.Json = ''
        $ex = $_.Exception.InnerException
        if (-not $ex) { $ex = $_.Exception }
        Set-TbStatus $St.Status "Not valid $($from.ToUpper()): $($ex.Message)" 'error'
        if ($ex -is [DevJsonException] -and $St.Input.Focused -eq $false) { $St.Input.Select([Math]::Min($ex.Position, $St.Input.TextLength), 1); $St.Input.ScrollToCaret() }
    }
}

function Get-JsonPathCheatSheet {
@'
Click a value in the Tree tab: this page then shows its path and ready-to-use code
to read it, or to loop over the list it is in.

JSONPath in short (try them in the Query tab)
  $                     the whole document
  $.store.name          a key inside a key
  $['first name']       a key with spaces or odd characters
  $.items[0]            the first item of a list ([-1] = the last)
  $.items[*]            every item of a list
  $.items[*].name       the name of every item
  $.items[0:3]          items 0, 1 and 2
  $..id                 every "id", at any depth
  $.*                   every value of an object
'@
}

function Test-PlainKey([string]$K) { $K -match '^[A-Za-z_$][A-Za-z0-9_$]*$' }

# Code to reach the steps, for each language. $Var = the variable the steps start from.
function Get-StepCode([string]$Lang, $Steps, [string]$Var) {
    $s = $Var
    foreach ($p in $Steps) {
        $isIdx = $p.I -ge 0
        $s += switch ($Lang) {
            'js'   { if ($isIdx) { "[$($p.I)]" } elseif (Test-PlainKey $p.K) { ".$($p.K)" } else { "[$(ConvertTo-JsonString $p.K)]" } }
            'py'   { if ($isIdx) { "[$($p.I)]" } else { "[$(ConvertTo-JsonString $p.K)]" } }
            'cs'   { if ($isIdx) { "[$($p.I)]" } else { ".GetProperty($(ConvertTo-JsonString $p.K))" } }
            'ps'   { if ($isIdx) { "[$($p.I)]" } elseif ($p.K -match '^[A-Za-z_][A-Za-z0-9_]*$') { ".$($p.K)" } else { ".'$($p.K -replace "'", "''")'" } }
            'jq'   { if ($isIdx) { "[$($p.I)]" } elseif (Test-PlainKey $p.K) { ".$($p.K)" } else { ".[$(ConvertTo-JsonString $p.K)]" } }
            'csdyn' { if ($isIdx) { "[$($p.I)]" } else { "[$(ConvertTo-JsonString $p.K)]" } }
            'psxml' { if ($isIdx) { "[$($p.I)]" } elseif ($p.K -eq '#text') { ".'#text'" } else { $k2 = $p.K.TrimStart('@'); if ($k2 -match '^[A-Za-z_][A-Za-z0-9_]*$') { ".$k2" } else { ".'$($k2 -replace "'", "''")'" } } }
            'path' { if ($isIdx) { "[$($p.I)]" } elseif (Test-PlainKey $p.K) { ".$($p.K)" } else { "['$($p.K -replace "'", "\'")']" } }
        }
    }
    if ($Lang -eq 'jq' -and $s -eq '') { $s = '.' }
    $s
}

function ConvertTo-JsonString([string]$S) { [DevJson]::Quote($S) }

# "servers" -> "server", "entries" -> "entry"; something readable for a loop variable.
function Get-LoopName([string]$Key) {
    $k = if ($Key -and (Test-PlainKey $Key)) { $Key } else { 'item' }
    if ($k -match 'ies$') { return $k -replace 'ies$', 'y' }
    if ($k -match '(ss|us)$') { return "$($k)Item" }
    if ($k -match 's$' -and $k.Length -gt 2) { return $k.Substring(0, $k.Length - 1) }
    if ($k -match '^(data|items?|list|results?|rows?|records?)$') { return 'item' }
    if ($k -in 'class', 'for', 'in', 'of', 'if', 'default', 'function', 'new', 'var', 'let', 'const', 'string', 'int', 'object', 'type', 'from', 'import', 'return', 'switch', 'case') { return "$($k)Item" }
    $k
}

function Get-ValueAt($Root, $Steps) {
    $v = $Root
    foreach ($p in $Steps) {
        if ($p.I -ge 0) { $v = ([System.Collections.Generic.List[object]]$v)[$p.I] } else { $v = $v.Get($p.K) }
    }
    $v
}

function Update-JsonPathHelp($St, $Tag) {
    $St.PathTag = $Tag
    $steps = @($Tag.Steps)
    $root = $St.Root
    $v = $Tag.V
    $type = [DevJson]::TypeName($v)
    # the code reads the input as it is (XML, YAML, CSV ...), or the JSON it converts to
    $fmt = if ($St.CodeFor.SelectedIndex -eq 1) { 'json' } else { [string]$St.InFormat }
    if (-not $fmt) { $fmt = 'json' }
    $sb = New-Object System.Text.StringBuilder
    $line = { param($t = '') [void]$sb.AppendLine($t) }

    # the list to loop over: the selected list itself, else the nearest list above it
    $loopAt = -1
    if ($type -eq 'array') { $loopAt = $steps.Count }
    else { for ($k = $steps.Count - 1; $k -ge 0; $k--) { if ($steps[$k].I -ge 0) { $loopAt = $k; break } } }
    $listSteps = @(if ($loopAt -gt 0) { $steps[0..($loopAt - 1)] })
    $inner = @(if ($type -ne 'array' -and $loopAt -ge 0 -and $loopAt + 1 -lt $steps.Count) { $steps[($loopAt + 1)..($steps.Count - 1)] })
    $lastKey = @($listSteps | Where-Object { $_.K } | Select-Object -Last 1).K
    $it = if ($fmt -in 'csv', 'tsv') { 'row' } else { Get-LoopName $lastKey }
    $list = if ($loopAt -ge 0) { Get-ValueAt $root $listSteps } else { $null }
    $first = if ($list -and $list.Count) { $list[0] } else { $null }
    $fields = New-Object System.Collections.Generic.List[object]
    if ($inner.Count) { $fields.Add($inner) }
    elseif ($first -is [DevJsonObject]) { foreach ($kv in @($first | Select-Object -First 3)) { $fields.Add(@(New-PathStep $kv.Key)) } }
    $isObj = $type -eq 'object'

    $St.WildPath = $null
    if ($loopAt -ge 0) { $St.WildPath = '$' + (Get-StepCode 'path' $listSteps '') + '[*]' + (Get-StepCode 'path' $inner '') }
    $sel = switch ($fmt) {
        'xml'   { Get-XPath $steps }
        { $_ -in 'csv', 'tsv' } { if ($steps.Count -and $steps[0].I -ge 0) { "row $($steps[0].I + 1)$(if ($steps.Count -gt 1) { ', column ' + (Get-CsvColumn @($steps[1..($steps.Count - 1)])) })" } else { 'all rows' } }
        default { '$' + (Get-StepCode 'path' $steps '') }
    }
    & $line "Input      $(([string]$St.InFormat).ToUpper())$(if ($St.CodeFor.SelectedIndex -eq 1) { '   (the code reads it converted to JSON)' })"
    & $line "Selected   $sel"
    & $line "Type       $type   $([DevJson]::Short($v, 80))"
    if ($loopAt -ge 0) {
        $every = switch ($fmt) { 'xml' { (Get-XPath $listSteps -NoLastIndex) + $(if ($inner.Count) { '/' + (Get-XPath $inner -Relative) }) } { $_ -in 'csv', 'tsv' } { "every row$(if ($inner.Count) { ', column ' + (Get-CsvColumn $inner) })" } default { $St.WildPath } }
        & $line "Every item $every"
    }
    & $line

    $pick = [string]$St.Lang.SelectedItem
    $langs = [ordered]@{ 'JavaScript' = 'js'; 'Python' = 'py'; 'C#' = 'cs'; 'PowerShell' = 'ps'; 'Command line' = 'cli' }
    $ctx = @{ Steps = $steps; ListSteps = $listSteps; Inner = $inner; Fields = $fields; It = $it; LoopAt = $loopAt; IsObj = $isObj; Line = $line; Fmt = $fmt; Sep = $St.Sep; Text = $St.Input.Text }
    foreach ($name in $langs.Keys) {
        if ($pick -ne 'All languages' -and $pick -ne $name) { continue }
        & $line "---- $name $('-' * [math]::Max(4, 50 - $name.Length))"
        switch ($fmt) {
            'xml'   { Write-XmlCode $langs[$name] $ctx }
            'csv'   { Write-CsvCode $langs[$name] $ctx }
            'tsv'   { Write-CsvCode $langs[$name] $ctx }
            default { Write-TreeCode $langs[$name] $ctx }
        }
        & $line
    }
    $St.Code.Text = $sb.ToString().TrimEnd()
}

# ---- JSON and YAML: the same shape in every language, only loading differs
function Write-TreeCode([string]$L, $X) {
    $line = $X.Line; $steps = $X.Steps; $listSteps = $X.ListSteps; $fields = $X.Fields; $it = $X.It
    $yaml = $X.Fmt -eq 'yaml'
    switch ($L) {
        'js' {
            & $line $(if ($yaml) { "// npm install js-yaml`nconst yaml = require('js-yaml');`nconst data = yaml.load(fs.readFileSync('file.yaml', 'utf8'));" } else { "const data = JSON.parse(text);   // or: await (await fetch(url)).json()" })
            & $line "const value = $(Get-StepCode 'js' $steps 'data');"
            if ($X.LoopAt -ge 0) {
                & $line "for (const $it of $(Get-StepCode 'js' $listSteps 'data')) {"
                & $line "  console.log($(if ($fields.Count) { ($fields | ForEach-Object { Get-StepCode 'js' $_ $it }) -join ', ' } else { $it }));"
                & $line '}'
                if ($fields.Count) { & $line "const values = $(Get-StepCode 'js' $listSteps 'data').map($it => $(Get-StepCode 'js' $fields[0] $it));" }
            }
            if ($X.IsObj) { & $line "for (const [key, val] of Object.entries($(Get-StepCode 'js' $steps 'data'))) {`n  console.log(key, val);`n}" }
        }
        'py' {
            & $line $(if ($yaml) { "import yaml   # pip install pyyaml`nwith open('file.yaml', encoding='utf-8') as f:`n    data = yaml.safe_load(f)" } else { "import json`nwith open('file.json', encoding='utf-8') as f:`n    data = json.load(f)" })
            & $line "value = $(Get-StepCode 'py' $steps 'data')"
            if ($X.LoopAt -ge 0) {
                & $line "for $it in $(Get-StepCode 'py' $listSteps 'data'):"
                & $line "    print($(if ($fields.Count) { ($fields | ForEach-Object { Get-StepCode 'py' $_ $it }) -join ', ' } else { $it }))"
                if ($fields.Count) { & $line "values = [$(Get-StepCode 'py' $fields[0] $it) for $it in $(Get-StepCode 'py' $listSteps 'data')]" }
            }
            if ($X.IsObj) { & $line "for key, val in $(Get-StepCode 'py' $steps 'data').items():`n    print(key, val)" }
        }
        'cs' {
            if ($yaml) {
                & $line '// dotnet add package YamlDotNet'
                & $line 'var data = new YamlDotNet.Serialization.Deserializer().Deserialize<dynamic>(File.ReadAllText("file.yaml"));'
                & $line "var value = $(Get-StepCode 'csdyn' $steps 'data');"
                if ($X.LoopAt -ge 0) {
                    & $line "foreach (var $it in $(Get-StepCode 'csdyn' $listSteps 'data'))"
                    & $line "    Console.WriteLine($(if ($fields.Count) { ($fields | ForEach-Object { Get-StepCode 'csdyn' $_ $it }) -join ' + " " + ' } else { $it }));"
                }
                if ($X.IsObj) { & $line "foreach (var kv in $(Get-StepCode 'csdyn' $steps 'data'))`n    Console.WriteLine(kv.Key + `": `" + kv.Value);" }
            } else {
                & $line 'using System.Text.Json;'
                & $line 'using var doc = JsonDocument.Parse(File.ReadAllText("file.json"));'
                & $line 'var root = doc.RootElement;'
                & $line "var value = $(Get-StepCode 'cs' $steps 'root');"
                if ($X.LoopAt -ge 0) {
                    & $line "foreach (var $it in $(Get-StepCode 'cs' $listSteps 'root').EnumerateArray())"
                    & $line "    Console.WriteLine($(if ($fields.Count) { ($fields | ForEach-Object { (Get-StepCode 'cs' $_ $it) + '.ToString()' }) -join ' + " " + ' } else { $it }));"
                }
                if ($X.IsObj) { & $line "foreach (var prop in $(Get-StepCode 'cs' $steps 'root').EnumerateObject())`n    Console.WriteLine(prop.Name + `": `" + prop.Value);" }
            }
        }
        'ps' {
            & $line $(if ($yaml) { "# Install-Module powershell-yaml`n`$data = Get-Content file.yaml -Raw | ConvertFrom-Yaml" } else { "`$data = Get-Content file.json -Raw | ConvertFrom-Json   # or: Invoke-RestMethod <url>" })
            & $line "`$value = $(Get-StepCode 'ps' $steps '$data')"
            if ($X.LoopAt -ge 0) {
                & $line "foreach (`$$it in $(Get-StepCode 'ps' $listSteps '$data')) {"
                & $line "    $(if ($fields.Count) { ($fields | ForEach-Object { '"$(' + (Get-StepCode 'ps' $_ "`$$it") + ')"' }) -join ' + " " + ' } else { "`$$it" })"
                & $line '}'
                if ($fields.Count) { & $line "$(Get-StepCode 'ps' $listSteps '$data') | ForEach-Object { $(Get-StepCode 'ps' $fields[0] '$_') }" }
            }
            if ($X.IsObj) { & $line $(if ($yaml) { "$(Get-StepCode 'ps' $steps '$data').GetEnumerator() | ForEach-Object { `"`$(`$_.Key) = `$(`$_.Value)`" }" } else { "$(Get-StepCode 'ps' $steps '$data').PSObject.Properties | ForEach-Object { `"`$(`$_.Name) = `$(`$_.Value)`" }" }) }
        }
        'cli' {
            $tool = if ($yaml) { 'yq' } else { 'jq' }; $file = if ($yaml) { 'file.yaml' } else { 'file.json' }
            & $line "$tool '$(Get-StepCode 'jq' $steps '')' $file"
            if ($X.LoopAt -ge 0) {
                $pickF = if ($fields.Count) { ' | ' + (($fields | ForEach-Object { Get-StepCode 'jq' $_ '' }) -join ', ') } else { '' }
                & $line "$tool '$(Get-StepCode 'jq' $listSteps '')[]$pickF' $file"
            }
            if ($X.IsObj) { & $line "$tool '$(Get-StepCode 'jq' $steps '') | to_entries[] | `"\(.key) = \(.value)`"' $file" }
        }
    }
}

# ---- XML: XPath, DOM / ElementTree / LINQ to XML / [xml]
# the tree from XML: { root: { "@attr": ..., child: ..., "#text": ... } }, repeated elements are lists
function Get-XPath($Steps, [switch]$Relative, [switch]$NoLastIndex) {
    $parts = New-Object System.Collections.Generic.List[string]
    $arr = @($Steps)
    for ($k = 0; $k -lt $arr.Count; $k++) {
        $p = $arr[$k]
        if ($p.I -ge 0) { if ($parts.Count -and -not ($NoLastIndex -and $k -eq $arr.Count - 1)) { $parts[$parts.Count - 1] += "[$($p.I + 1)]" }; continue }
        if ($p.K -eq '#text') { $parts.Add('text()') } else { $parts.Add($p.K) }
    }
    $s = $parts -join '/'
    if ($Relative) { $s } else { "/$s" }
}

# the steps below one element, as an XPath relative to it
function Get-XmlRel($Steps) { Get-XPath $Steps -Relative }

function Get-CssPath($Steps) {
    $parts = New-Object System.Collections.Generic.List[string]
    foreach ($p in @($Steps)) {
        if ($p.I -ge 0) { if ($parts.Count) { $parts[$parts.Count - 1] += ":nth-of-type($($p.I + 1))" }; continue }
        if ($p.K -like '@*' -or $p.K -eq '#text') { continue }
        $parts.Add(($p.K -replace '([:.])', '\$1'))
    }
    $parts -join ' > '
}

function Write-XmlCode([string]$L, $X) {
    $line = $X.Line; $steps = @($X.Steps); $listSteps = @($X.ListSteps); $fields = $X.Fields; $it = $X.It
    $xp = Get-XPath $steps
    $last = if ($steps.Count) { $steps[$steps.Count - 1] } else { $null }
    $isAttr = $last -and $last.K -like '@*'
    $listXp = Get-XPath $listSteps -NoLastIndex
    switch ($L) {
        'js' {
            & $line 'const doc = new DOMParser().parseFromString(text, "application/xml");'
            & $line "const value = doc.evaluate(`"string($xp)`", doc, null, XPathResult.STRING_TYPE, null).stringValue;"
            if ($X.LoopAt -ge 0) {
                & $line "for (const $it of doc.querySelectorAll(`"$(Get-CssPath $listSteps)`")) {"
                $parts = foreach ($f in $fields) {
                    $fa = @($f); $fl = $fa[$fa.Count - 1]
                    if ($fl.K -like '@*') { $css = Get-CssPath @($fa[0..($fa.Count - 1)]); if ($css) { "$it.querySelector(`":scope > $css`")?.getAttribute(`"$($fl.K.Substring(1))`")" } else { "$it.getAttribute(`"$($fl.K.Substring(1))`")" } }
                    elseif ($fl.K -eq '#text') { "$it.textContent" }
                    else { "$it.querySelector(`":scope > $(Get-CssPath $fa)`")?.textContent" }
                }
                & $line "  console.log($(if ($parts) { @($parts) -join ', ' } else { "$it.textContent" }));"
                & $line '}'
            }
            if ($X.IsObj) { & $line "const el = doc.evaluate(`"$xp`", doc, null, XPathResult.FIRST_ORDERED_NODE_TYPE, null).singleNodeValue;`nfor (const a of el.attributes) console.log(a.name, a.value);`nfor (const child of el.children) console.log(child.tagName, child.textContent);" }
        }
        'py' {
            & $line 'import xml.etree.ElementTree as ET'
            & $line "root = ET.parse('file.xml').getroot()   # or: ET.fromstring(text)"
            # ElementTree paths start below the root element and can't end in @attr / text()
            $below = @($steps | Select-Object -Skip 1)
            if ($isAttr -or ($last -and $last.K -eq '#text')) {
                $owner = @($below | Select-Object -First ([math]::Max(0, $below.Count - 1)))
                $el = if ($owner.Count) { "root.find(`"$(Get-XmlRel $owner)`")" } else { 'root' }
                $tail = if ($isAttr) { '.get("' + $last.K.Substring(1) + '")' } else { '.text' }
                & $line ('value = ' + $el + $tail)
            } elseif ($below.Count) { & $line "value = root.findtext(`"$(Get-XmlRel $below)`")" }
            else { & $line 'value = root.text' }
            if ($X.LoopAt -ge 0) {
                $lb = @($listSteps | Select-Object -Skip 1)
                & $line "for $it in root.findall(`"$(if ($lb.Count) { Get-XPath $lb -Relative -NoLastIndex } else { '.' })`"):"
                $parts = foreach ($f in $fields) {
                    $fa = @($f); $fl = $fa[$fa.Count - 1]
                    if ($fl.K -like '@*') { $o = @($fa | Select-Object -First ($fa.Count - 1)); if ($o.Count) { "$it.find(`"$(Get-XmlRel $o)`").get(`"$($fl.K.Substring(1))`")" } else { "$it.get(`"$($fl.K.Substring(1))`")" } }
                    elseif ($fl.K -eq '#text') { "$it.text" }
                    else { "$it.findtext(`"$(Get-XmlRel $fa)`")" }
                }
                & $line "    print($(if ($parts) { @($parts) -join ', ' } else { "$it.text" }))"
            }
            if ($X.IsObj) {
                $find = if ($steps.Count -gt 1) { '.find("' + (Get-XmlRel @($steps | Select-Object -Skip 1)) + '")' } else { '' }
                & $line ('el = root' + $find + "`nprint(el.attrib)`nfor child in el:`n    print(child.tag, child.text)")
            }
        }
        'cs' {
            & $line 'using System.Xml.Linq; using System.Xml.XPath;'
            & $line 'var doc = XDocument.Load("file.xml");   // or: XDocument.Parse(text)'
            $get = if ($isAttr) { '(string)doc.XPathEvaluate("string(' + $xp + ')")' } else { '(string)doc.XPathSelectElement("' + $xp + '")' }
            & $line ('var value = ' + $get + ';')
            if ($X.LoopAt -ge 0) {
                & $line "foreach (var $it in doc.XPathSelectElements(`"$listXp`"))"
                $parts = foreach ($f in $fields) {
                    $fa = @($f); $fl = $fa[$fa.Count - 1]
                    $chain = $it
                    foreach ($p in $fa) {
                        if ($p.I -ge 0) { $chain = $chain -replace '\.Element\(("[^"]*")\)$', ".Elements(`$1).ElementAt($($p.I))" }
                        elseif ($p.K -like '@*') { $chain += ".Attribute(`"$($p.K.Substring(1))`")" }
                        elseif ($p.K -ne '#text') { $chain += ".Element(`"$($p.K)`")" }
                    }
                    "(string)$chain"
                }
                & $line "    Console.WriteLine($(if ($parts) { @($parts) -join ' + " " + ' } else { "(string)$it" }));"
            }
            if ($X.IsObj) { & $line "var el = doc.XPathSelectElement(`"$xp`");`nforeach (var a in el.Attributes()) Console.WriteLine(a.Name + `" = `" + a.Value);`nforeach (var child in el.Elements()) Console.WriteLine(child.Name + `": `" + child.Value);" }
        }
        'ps' {
            & $line '[xml]$xml = Get-Content file.xml -Raw'
            & $line "`$value = $(Get-StepCode 'psxml' $steps '$xml')"
            & $line "`$value = `$xml.SelectSingleNode('$xp')$(if ($isAttr) { '.Value' } else { '.InnerText' })   # the same with XPath"
            if ($X.LoopAt -ge 0) {
                & $line "foreach (`$$it in $(Get-StepCode 'psxml' $listSteps '$xml')) {"
                & $line "    $(if ($fields.Count) { ($fields | ForEach-Object { '"$(' + (Get-StepCode 'psxml' $_ "`$$it") + ')"' }) -join ' + " " + ' } else { "`$$it.InnerText" })"
                & $line '}'
                & $line "`$xml.SelectNodes('$listXp') | ForEach-Object { `$_.OuterXml }"
            }
            if ($X.IsObj) { & $line "`$el = `$xml.SelectSingleNode('$xp')`n`$el.Attributes | ForEach-Object { `"`$(`$_.Name) = `$(`$_.Value)`" }`n`$el.ChildNodes | ForEach-Object { `"`$(`$_.Name): `$(`$_.InnerText)`" }" }
        }
        'cli' {
            & $line "xmllint --xpath 'string($xp)' file.xml"
            if ($X.LoopAt -ge 0) {
                $rel = if ($fields.Count) { '/' + (Get-XmlRel @($fields[0])) } else { '' }
                & $line "xmllint --xpath '$listXp$rel' file.xml"
                & $line "# PowerShell one-liner: Select-Xml -Path file.xml -XPath '$listXp$rel' | ForEach-Object { `$_.Node.InnerText }"
            }
        }
    }
}

# ---- CSV / tab-separated: rows with named columns ("a.b" columns are one column in the file)
function Get-CsvColumn($Steps) { (@($Steps | Where-Object { $_.K } | ForEach-Object { $_.K })) -join '.' }

function Write-CsvCode([string]$L, $X) {
    $line = $X.Line; $steps = @($X.Steps)
    $tsv = $X.Fmt -eq 'tsv'
    $sepChar = if ($tsv) { "`t" } else { [string]$X.Sep }
    if (-not $sepChar) { $sepChar = ',' }
    $sepCode = if ($tsv) { '\t' } else { $sepChar }
    $file = if ($tsv) { 'file.tsv' } else { 'file.csv' }
    $rowIdx = if ($steps.Count -and $steps[0].I -ge 0) { $steps[0].I } else { -1 }
    $col = if ($steps.Count -gt 1) { Get-CsvColumn @($steps[1..($steps.Count - 1)]) } else { '' }
    $head = @()
    try { $rows = [DevData]::CsvRows($X.Text, [char]$sepChar); if ($rows.Count) { $head = @($rows[0] | ForEach-Object { $_.Trim() }) } } catch { }
    $cols = @(if ($col) { $col } else { $head | Select-Object -First 3 })
    $q = { param($c) [DevJson]::Quote($c) }
    switch ($L) {
        'js' {
            & $line '// npm install papaparse'
            $delim = if ($sepChar -ne ',') { ', delimiter: "' + $sepCode + '"' } else { '' }
            & $line ('const rows = Papa.parse(text, { header: true, skipEmptyLines: true' + $delim + ' }).data;')
            if ($rowIdx -ge 0 -and $col) { & $line "const value = rows[$rowIdx][$(& $q $col)];" } elseif ($rowIdx -ge 0) { & $line "const row = rows[$rowIdx];" }
            & $line 'for (const row of rows) {'
            & $line "  console.log($((@($cols | ForEach-Object { "row[$(& $q $_)]" })) -join ', '));"
            & $line '}'
            if ($cols) { & $line "const values = rows.map(row => row[$(& $q $cols[0])]);" }
        }
        'py' {
            & $line 'import csv'
            & $line "with open('$file', newline='', encoding='utf-8') as f:"
            & $line "    rows = list(csv.DictReader(f$(if ($sepChar -ne ',') { ", delimiter='$sepCode'" })))"
            if ($rowIdx -ge 0 -and $col) { & $line "value = rows[$rowIdx][$(& $q $col)]" } elseif ($rowIdx -ge 0) { & $line "row = rows[$rowIdx]" }
            & $line 'for row in rows:'
            & $line "    print($((@($cols | ForEach-Object { "row[$(& $q $_)]" })) -join ', '))"
            if ($cols) { & $line "values = [row[$(& $q $cols[0])] for row in rows]" }
        }
        'cs' {
            & $line "// no package needed (for quoted fields with $(if ($tsv) { 'tabs' } else { 'separators' }) inside, use the CsvHelper package)"
            & $line "var lines = File.ReadAllLines(`"$file`");"
            & $line "var head = lines[0].Split('$sepCode');"
            & $line "var rows = lines.Skip(1).Where(l => l.Length > 0).Select(l => { var c = l.Split('$sepCode'); return head.Select((h, i) => new { h, v = i < c.Length ? c[i] : `"`" }).ToDictionary(x => x.h, x => x.v); }).ToList();"
            if ($rowIdx -ge 0 -and $col) { & $line "var value = rows[$rowIdx][$(& $q $col)];" }
            & $line 'foreach (var row in rows)'
            & $line "    Console.WriteLine($((@($cols | ForEach-Object { "row[$(& $q $_)]" })) -join ' + " " + '));"
        }
        'ps' {
            $imp = "Import-Csv $file$(if ($tsv) { ' -Delimiter "`t"' } elseif ($sepChar -ne ',') { " -Delimiter '$sepChar'" })"
            & $line "`$rows = $imp     # or: `$text | ConvertFrom-Csv$(if ($tsv) { ' -Delimiter "`t"' } elseif ($sepChar -ne ',') { " -Delimiter '$sepChar'" })"
            $pc = { param($c) if ($c -match '^[A-Za-z_][A-Za-z0-9_]*$') { $c } else { "'$($c -replace "'", "''")'" } }
            if ($rowIdx -ge 0 -and $col) { & $line "`$value = `$rows[$rowIdx].$(& $pc $col)" } elseif ($rowIdx -ge 0) { & $line "`$row = `$rows[$rowIdx]" }
            & $line 'foreach ($row in $rows) {'
            & $line "    $((@($cols | ForEach-Object { '"$($row.' + (& $pc $_) + ')"' })) -join ' + " " + ')"
            & $line '}'
            if ($cols) { & $line "`$rows | Select-Object $((@($cols | ForEach-Object { & $pc $_ })) -join ', ') | Format-Table" }
            if ($col) { & $line "`$rows | Where-Object { `$_.$(& $pc $col) -eq 'some value' }   # filter rows" }
        }
        'cli' {
            $io = if ($tsv) { '--itsv' } else { '--icsv' }
            & $line "# Miller (mlr):"
            & $line "mlr $io --opprint cut -f $(@($cols) -join ',') $file"
            if ($rowIdx -ge 0) { & $line "mlr $io --ojson head -n $($rowIdx + 1) then tail -n 1 $file" }
            & $line "mlr $io --ojson cat $file   # the whole table as JSON"
        }
    }
}

function Update-JsonQuery($St) {
    $p = $St.Path.Text.Trim()
    if (-not $p) { $St.QueryOut.Text = (Get-JsonPathCheatSheet); return }
    if (-not $St.Json) { $St.QueryOut.Text = 'Fix the input first.'; return }
    try {
        $hits = [DevJson]::Query($St.Json, $p)
        $sb = New-Object System.Text.StringBuilder
        [void]$sb.AppendLine("$($hits.Count) match(es)`n")
        foreach ($h in $hits) { [void]$sb.AppendLine("$($h.Key)"); [void]$sb.AppendLine("  " + ([DevJson]::Write($h.Value, 2, $false) -replace "`n", "`n  ")); [void]$sb.AppendLine() }
        $St.QueryOut.Text = $sb.ToString()
    } catch {
        $ex = $_.Exception.InnerException; if (-not $ex) { $ex = $_.Exception }
        $St.QueryOut.Text = "Query error: $($ex.Message)"
    }
}

# ======================================================================================
# JWT: decode header and payload, show expiry, verify HS256/384/512 signatures with a secret.
# ======================================================================================
function ConvertFrom-Base64Url([string]$Text) {
    $s = $Text.Replace('-', '+').Replace('_', '/')
    switch ($s.Length % 4) { 2 { $s += '==' } 3 { $s += '=' } }
    [Convert]::FromBase64String($s)
}

function ConvertTo-Base64Url([byte[]]$Bytes) { [Convert]::ToBase64String($Bytes).TrimEnd('=').Replace('+', '-').Replace('/', '_') }

function Format-Relative([datetime]$When) {
    $span = $When - (Get-Date)
    $abs = [Math]::Abs($span.TotalSeconds)
    $txt = if ($abs -lt 90) { "$([int]$abs) s" } elseif ($abs -lt 5400) { "$([int]($abs / 60)) min" } elseif ($abs -lt 172800) { "$([Math]::Round($abs / 3600, 1)) h" } else { "$([Math]::Round($abs / 86400, 1)) days" }
    if ($span.TotalSeconds -ge 0) { "in $txt" } else { "$txt ago" }
}

Register-ToolboxPage 'jwt' 'JWT decoder' $Glyph.Lock 'jwt token bearer decode claims expiry signature' {
    param($panel, $st)
    $st.Status = New-TbPage $panel
    $split = New-Object System.Windows.Forms.SplitContainer
    $split.Dock = 'Fill'; $split.Orientation = 'Horizontal'; $split.BackColor = $C.Line; $split.SplitterWidth = 3
    $split.Panel1.BackColor = $C.Bg; $split.Panel2.BackColor = $C.Bg
    $panel.Controls.Add($split)
    $st.Input = New-TbBox -Mono -Multi -Cue 'Paste a JWT (eyJ...), with or without "Bearer "'
    $st.Input.Dock = 'Fill'; $st.Input.WordWrap = $true; $st.Input.ScrollBars = 'Vertical'
    $split.Panel1.Controls.Add($st.Input)
    $vbar = New-TbBar $split.Panel1 'Bottom'
    New-TbLabel $vbar 'Secret (HS256/384/512)' -Dim | Out-Null
    $st.Secret = New-TbBox -Cue 'optional - to check the signature'
    $st.Secret.Width = Px (300 * $TextZoom); $st.Secret.Margin = New-Object System.Windows.Forms.Padding(0, (Px 4), (Px 6), 0)
    $vbar.Controls.Add($st.Secret)
    $st.SecretB64 = New-CheckBox $vbar 'Secret is Base64' $false 'Tick when the secret is Base64-encoded bytes'
    $st.Output = New-TbRtb -ReadOnly; $st.Output.Dock = 'Fill'; $st.Output.WordWrap = $true
    $split.Panel2.Controls.Add($st.Output)
    $st.Timer = New-TbDebounce 250 { Update-JwtTool $TbUI.Pages['jwt'].State }
    foreach ($box in $st.Input, $st.Secret) { $box.add_TextChanged({ $s = $TbUI.Pages['jwt'].State; $s.Timer.Stop(); $s.Timer.Start() }) }
    $st.SecretB64.add_CheckedChanged({ Update-JwtTool $TbUI.Pages['jwt'].State })
    $st.SetInput = { param($t) $s = $TbUI.Pages['jwt'].State; $s.Input.Text = $t; Update-JwtTool $s }
    $st.Focus = { $TbUI.Pages['jwt'].State.Input.Focus() }
    $split.SplitterDistance = Px 120
    Set-TbStatus $st.Status 'Decoding happens here on your PC; the token is not sent anywhere.'
    $st
}

function Add-RtbLine($Rtb, [string]$Text, $Color = $null, [switch]$Bold) {
    $Rtb.SelectionStart = $Rtb.TextLength
    $Rtb.SelectionColor = if ($Color) { $Color } else { $C.Fore }
    $Rtb.SelectionFont = if ($Bold) { New-Object System.Drawing.Font($Rtb.Font, [System.Drawing.FontStyle]::Bold) } else { $Rtb.Font }
    $Rtb.AppendText($Text + "`n")
}

function Update-JwtTool($St) {
    $o = $St.Output
    $o.Clear()
    $tok = ($St.Input.Text -replace '\s', '') -replace '^(?i)bearer', ''
    if (-not $tok) { Set-TbStatus $St.Status 'Paste a token above.'; return }
    $parts = $tok.Split('.')
    if ($parts.Count -lt 2) { Set-TbStatus $St.Status 'A JWT has three parts separated by dots: header.payload.signature' 'error'; return }
    try {
        $hdrText = [Text.Encoding]::UTF8.GetString((ConvertFrom-Base64Url $parts[0]))
        $payText = [Text.Encoding]::UTF8.GetString((ConvertFrom-Base64Url $parts[1]))
    } catch { Set-TbStatus $St.Status "Not a valid JWT: $($_.Exception.Message)" 'error'; return }
    $hdr = $null; $pay = $null
    try { $hdr = [DevJson]::Parse($hdrText) } catch { }
    try { $pay = [DevJson]::Parse($payText) } catch { }
    Add-RtbLine $o 'HEADER' $C.Accent -Bold
    Add-RtbLine $o $(if ($hdr) { [DevJson]::Write($hdr, 2, $false) } else { $hdrText })
    Add-RtbLine $o ''
    Add-RtbLine $o 'PAYLOAD' $C.Accent -Bold
    Add-RtbLine $o $(if ($pay) { [DevJson]::Write($pay, 2, $false) } else { $payText })
    Add-RtbLine $o ''
    $summary = @()
    $kind = ''
    if ($pay -is [DevJsonObject]) {
        Add-RtbLine $o 'CLAIMS' $C.Accent -Bold
        $names = @{ iss = 'Issuer'; sub = 'Subject'; aud = 'Audience'; exp = 'Expires'; nbf = 'Not before'; iat = 'Issued at'; jti = 'Token id'; scope = 'Scope'; name = 'Name'; email = 'Email' }
        foreach ($k in 'iss', 'sub', 'aud', 'name', 'email', 'scope', 'iat', 'nbf', 'exp', 'jti') {
            if (-not $pay.Has($k)) { continue }
            $v = $pay.Get($k)
            $txt = if ($v -is [string]) { $v } else { [DevJson]::Write($v, -1, $false) }
            $color = $null
            if ($k -in 'exp', 'nbf', 'iat' -and $v -is [DevJsonNumber]) {
                $when = [DateTimeOffset]::FromUnixTimeSeconds([long][double]$v.Raw).LocalDateTime
                $txt = "$($v.Raw)  =  $($when.ToString('ddd yyyy-MM-dd HH:mm:ss'))  ($(Format-Relative $when))"
                if ($k -eq 'exp') { if ($when -lt (Get-Date)) { $color = $C.Red; $summary += "EXPIRED $(Format-Relative $when)"; $kind = 'error' } else { $color = $C.Green; $summary += "valid, expires $(Format-Relative $when)"; if (-not $kind) { $kind = 'ok' } } }
                if ($k -eq 'nbf' -and $when -gt (Get-Date)) { $color = $C.Yellow; $summary += "not valid yet ($(Format-Relative $when))"; $kind = 'warn' }
            }
            Add-RtbLine $o ("{0,-11} {1}" -f $names[$k], $txt) $color
        }
        Add-RtbLine $o ''
    }
    # signature
    $alg = if ($hdr -is [DevJsonObject] -and $hdr.Has('alg')) { [string]$hdr.Get('alg') } else { '' }
    Add-RtbLine $o 'SIGNATURE' $C.Accent -Bold
    if ($parts.Count -lt 3 -or -not $parts[2]) { Add-RtbLine $o 'none (unsigned token)' $C.Yellow; $summary += 'unsigned' }
    elseif ($alg -match '^HS(256|384|512)$') {
        if (-not $St.Secret.Text) { Add-RtbLine $o "$alg - enter the secret below to check it" $C.Dim }
        else {
            try {
                $key = if ($St.SecretB64.Checked) { [Convert]::FromBase64String($St.Secret.Text) } else { [Text.Encoding]::UTF8.GetBytes($St.Secret.Text) }
                $h = switch ($alg) { 'HS256' { New-Object Security.Cryptography.HMACSHA256(, $key) } 'HS384' { New-Object Security.Cryptography.HMACSHA384(, $key) } default { New-Object Security.Cryptography.HMACSHA512(, $key) } }
                $sig = ConvertTo-Base64Url ($h.ComputeHash([Text.Encoding]::ASCII.GetBytes("$($parts[0]).$($parts[1])")))
                $h.Dispose()
                if ($sig -eq $parts[2]) { Add-RtbLine $o "$alg - signature is VALID for this secret" $C.Green; $summary += 'signature valid' }
                else { Add-RtbLine $o "$alg - signature does NOT match this secret" $C.Red; $summary += 'signature invalid'; $kind = 'error' }
            } catch { Add-RtbLine $o "Could not check: $($_.Exception.Message)" $C.Red }
        }
    } else { Add-RtbLine $o "$alg - checking needs the issuer's public key (not supported here)" $C.Dim }
    $o.SelectionStart = 0; $o.ScrollToCaret()
    Set-TbStatus $St.Status ("JWT  $Dot  alg $(if ($alg) { $alg } else { '?' })" + $(if ($summary) { "  $Dot  " + ($summary -join "  $Dot  ") } else { '' })) $kind
}

# ======================================================================================
# Regex tester: live highlighting, groups, replace preview.
# ======================================================================================
Register-ToolboxPage 'regex' 'Regex tester' $Glyph.Search 'regular expression regex match replace groups test' {
    param($panel, $st)
    foreach ($kv in (@{ Busy = $false }).GetEnumerator()) { $st[$kv.Key] = $kv.Value }
    $st.Status = New-TbPage $panel
    $split = New-Object System.Windows.Forms.SplitContainer
    $split.Dock = 'Fill'; $split.Orientation = 'Horizontal'; $split.BackColor = $C.Line; $split.SplitterWidth = 3
    $split.Panel1.BackColor = $C.Bg; $split.Panel2.BackColor = $C.Bg
    $panel.Controls.Add($split)
    $st.Text = New-TbRtb; $st.Text.Dock = 'Fill'
    $split.Panel1.Controls.Add($st.Text)
    New-TbLabel (New-TbBar $split.Panel1) 'Test text  (matches are highlighted)' -Dim | Out-Null
    $tabs = New-TabSet $split.Panel2
    $mPanel = Add-ApiTab $tabs 'Matches'
    $rPanel = Add-ApiTab $tabs 'Replace'
    $cPanel = Add-ApiTab $tabs 'Code'
    $hPanel = Add-ApiTab $tabs 'Cheat sheet'
    $st.Code = New-TbRtb -ReadOnly; $st.Code.Dock = 'Fill'; $cPanel.Controls.Add($st.Code)
    $cbar = New-TbBar $cPanel
    New-TbLabel $cbar 'How to use this pattern in the chosen language (flags from the checkboxes)' -Dim | Out-Null
    [void](New-Button 'Copy code' 'Copy the code' { Copy-TbText $TbUI.Pages['regex'].State.Code.Text } $cbar $Glyph.Copy 1)
    $cPanel.Controls.SetChildIndex($cbar, $cPanel.Controls.Count - 1)
    $cs = New-Object System.Windows.Forms.ListView
    $cs.Dock = 'Fill'; $cs.View = 'Details'; $cs.FullRowSelect = $true; $cs.BorderStyle = 'None'; $cs.BackColor = $C.Bg; $cs.ForeColor = $C.Fore
    [void]$cs.Columns.Add('Write', (Px (170 * $TextZoom))); [void]$cs.Columns.Add('Means  (double-click to put it into the pattern)', (Px (620 * $TextZoom)))
    foreach ($row in $RegexCheatSheet) { $it = New-Object System.Windows.Forms.ListViewItem($row[0]); $it.Font = New-Object System.Drawing.Font('Consolas', (Fz 10)); $it.UseItemStyleForSubItems = $false; [void]$it.SubItems.Add($row[1]); [void]$cs.Items.Add($it) }
    $cs.add_ItemActivate({
        param($src, $e)
        if (-not $src.SelectedItems.Count) { return }
        $tok = ($src.SelectedItems[0].Text -split '  ')[0]
        if ($tok -match '^\$') { $b = $TbUI.Pages['regex'].State.Replace } else { $b = $TbUI.Pages['regex'].State.Pattern }
        $b.SelectedText = $tok; [void]$b.Focus()
    })
    $hPanel.Controls.Add($cs)
    $st.Matches = New-Object System.Windows.Forms.ListView
    $st.Matches.Dock = 'Fill'; $st.Matches.View = 'Details'; $st.Matches.FullRowSelect = $true; $st.Matches.BorderStyle = 'None'
    $st.Matches.BackColor = $C.Bg; $st.Matches.ForeColor = $C.Fore; $st.Matches.Font = New-Object System.Drawing.Font('Consolas', (Fz 10))
    foreach ($col in @(@('#', 50), @('At', 70), @('Match', 320), @('Groups', 520))) { [void]$st.Matches.Columns.Add($col[0], (Px ($col[1] * $TextZoom))) }
    $st.Matches.add_SelectedIndexChanged({
        $s = $TbUI.Pages['regex'].State
        if ($s.Matches.SelectedItems.Count -eq 0) { return }
        $m = $s.Matches.SelectedItems[0].Tag
        $s.Text.Select($m.Index, $m.Length); $s.Text.ScrollToCaret()
    })
    $mPanel.Controls.Add($st.Matches)
    $rbar = New-TbBar $rPanel
    New-TbLabel $rbar 'Replace with' -Dim | Out-Null
    $st.Replace = New-TbBox -Mono -Cue '$1, ${name}, $0 = whole match'
    $st.Replace.Width = Px (320 * $TextZoom); $st.Replace.Margin = New-Object System.Windows.Forms.Padding(0, (Px 4), (Px 6), 0)
    $rbar.Controls.Add($st.Replace)
    [void](New-Button 'Copy result' 'Copy the replaced text' { Copy-TbText $TbUI.Pages['regex'].State.Result.Text } $rbar $Glyph.Copy 1)
    $st.Result = New-TbRtb -ReadOnly; $st.Result.Dock = 'Fill'
    $rPanel.Controls.Add($st.Result)
    $rPanel.Controls.SetChildIndex($rbar, $rPanel.Controls.Count - 1)
    Select-ApiTab $tabs 'Matches'

    $pbar = New-TbBar $panel
    New-TbLabel $pbar 'Language' -Dim | Out-Null
    $st.Flavor = New-TbCombo $pbar @($RegexFlavors.Keys) 190
    $st.Flavor.add_SelectedIndexChanged({ Update-RegexTool $TbUI.Pages['regex'].State })
    [void](New-Button 'Examples' 'Ready-made patterns with sample text: email, URL, IP, dates, GUID, log lines, JSON ...' { param($src, $e) Show-RegexExampleMenu $src } $pbar $Glyph.Lightning 2)
    New-TbLabel $pbar 'Pattern' -Title | Out-Null
    $st.Pattern = New-TbBox -Mono -Cue '\b(\w+)@(\w+\.\w+)\b'
    $st.Pattern.Width = Px (460 * $TextZoom); $st.Pattern.Margin = New-Object System.Windows.Forms.Padding(0, (Px 4), (Px 10), 0)
    $pbar.Controls.Add($st.Pattern)
    $st.Opt = @{}
    foreach ($o in @(@('IgnoreCase', 'Ignore case', $true), @('Multiline', '^ $ per line', $true), @('Singleline', '. matches newline', $false), @('IgnorePatternWhitespace', 'Ignore spaces in pattern', $false))) {
        $cb = New-CheckBox $pbar $o[1] $o[2]
        $cb.add_CheckedChanged({ Update-RegexTool $TbUI.Pages['regex'].State })
        $st.Opt[$o[0]] = $cb
    }
    $st.Timer = New-TbDebounce 250 { Update-RegexTool $TbUI.Pages['regex'].State }
    foreach ($box in $st.Pattern, $st.Text, $st.Replace) { $box.add_TextChanged({ $s = $TbUI.Pages['regex'].State; if ($s.Busy) { return }; $s.Timer.Stop(); $s.Timer.Start() }) }
    $st.SetInput = { param($t) $s = $TbUI.Pages['regex'].State; $s.Text.Text = $t; Update-RegexTool $s }
    $st.Focus = { $TbUI.Pages['regex'].State.Pattern.Focus() }
    # Split half and half once the page has its real size.
    $split.Tag = $true
    $split.add_Resize({ param($src, $e) if ($src.Tag -and $src.Height -gt (Px 300)) { $src.Tag = $false; $src.SplitterDistance = [int]($src.Height * 0.5) } })
    $st.Text.Text = "Contact ann@example.com or bob@test.org`r`nOrder 1234 shipped on 2026-10-17"
    $st.Pattern.Text = '(\w+)@(\w+\.\w+)'
    Set-TbStatus $st.Status 'Pick the language you write the pattern for. Matching stops after 2 seconds, so a runaway pattern cannot hang the window.'
    $st
}

function Show-RegexExampleMenu($Button) {
    $m = New-Object System.Windows.Forms.ContextMenuStrip -Property @{ Renderer = $MenuRenderer }
    $ex = Get-RegexExamples
    foreach ($k in $ex.Keys) {
        $it = Add-MenuItem $m $k { param($src, $e) Set-RegexExample $src.Tag }
        $it.Tag = $k
    }
    $m.Show($Button, 0, $Button.Height)
}

function Set-RegexExample([string]$Name) {
            $x = (Get-RegexExamples)[$Name]
            $s = $TbUI.Pages['regex'].State
            $f = $RegexFlavors[[string]$s.Flavor.SelectedItem]
            $p = $x.P
            if ($f -in 'py', 'go') { $p = $p -replace '\(\?<(?![=!])', '(?P<' }
            $s.Busy = $true
            try {
                $s.Pattern.Text = $p; $s.Text.Text = $x.T
                $s.Opt.IgnoreCase.Checked = -not ($x.ContainsKey('I') -and -not $x.I)      # upper / lower case matters for some
                $s.Replace.Text = if ($x.ContainsKey('R')) { if ($f -eq 'py') { $x.R -replace '\$\{(\w+)\}', '\g<$1>' } elseif ($f -eq 'js') { $x.R -replace '\$\{(\w+)\}', '$$<$1>' } else { $x.R } } else { '' }
            } finally { $s.Busy = $false }
            Update-RegexTool $s
}

# ---- Regex flavours: the pattern is written the way the chosen language wants it; DevTools tests it
#      with .NET after translating the differences, and says what that language can't do.
$RegexFlavors = [ordered]@{
    '.NET (C#, PowerShell)'   = 'net'
    'JavaScript'              = 'js'
    'Python'                  = 'py'
    'Java / Kotlin'           = 'java'
    'PHP (PCRE)'              = 'php'
    'Go (RE2)'                = 'go'
    'grep -E / sed -E (POSIX)' = 'posix'
}

# -> @{ Pattern = .NET pattern; Flags = 'ims' taken from /.../flags; Notes = @(); Errors = @() }
function Convert-RegexToNet([string]$P, [string]$F) {
    $notes = New-Object System.Collections.Generic.List[string]
    $errors = New-Object System.Collections.Generic.List[string]
    $flags = ''
    # literals with delimiters: /abc/gi (JavaScript), #abc#i or /abc/i (PHP)
    if ($F -eq 'js' -and $P -match '^/(.+)/([dgimsuvy]*)$') { $P = $Matches[1] -replace '\\/', '/'; $flags = $Matches[2]; $notes.Add("flags /$flags taken from the literal") }
    elseif ($F -eq 'php' -and $P.Length -gt 2 -and $P[0] -match '[/#~@%!|+]') {
        $dl = [regex]::Escape([string]$P[0])
        if ($P -match "^$dl(.*)$dl([imsxuADSUXJn]*)$") { $P = $Matches[1]; $flags = $Matches[2]; if ($flags) { $notes.Add("flags $flags taken from the delimiters") } }
    }
    $ascii = $F -in 'js', 'java', 'php', 'go', 'posix'
    $sb = New-Object System.Text.StringBuilder
    $inClass = $false; $classStart = 0
    $i = 0
    $posix = @{ alpha = 'a-zA-Z'; digit = '0-9'; alnum = 'a-zA-Z0-9'; upper = 'A-Z'; lower = 'a-z'; space = '\s'; blank = ' \t'; xdigit = '0-9A-Fa-f'; punct = '!-/:-@\[-`{-~'; word = '\w'; cntrl = '\x00-\x1f'; print = '\x20-\x7e'; graph = '\x21-\x7e' }
    while ($i -lt $P.Length) {
        $ch = $P[$i]
        if ($ch -eq '\' -and $i + 1 -lt $P.Length) {
            $nx = [string]$P[$i + 1]
            $out = $null
            switch -CaseSensitive ($nx) {
                'd' { if ($ascii) { $out = $(if ($inClass) { '0-9' } else { '[0-9]' }) } }
                'D' { if ($ascii -and -not $inClass) { $out = '[^0-9]' } }
                'w' { if ($ascii) { $out = $(if ($inClass) { 'a-zA-Z0-9_' } else { '[a-zA-Z0-9_]' }) } }
                'W' { if ($ascii -and -not $inClass) { $out = '[^a-zA-Z0-9_]' } }
                'h' { if ($F -in 'php', 'java') { $out = $(if ($inClass) { ' \t' } else { '[ \t]' }) } }
                'R' { if ($F -in 'php', 'java') { $out = '(?:\r\n|[\n\r])' } }
                'K' { if ($F -eq 'php') { $errors.Add('\K (keep out) is PCRE only - can''t be tested here; use a lookbehind (?<=...)'); $out = '' } }
                'Z' { if ($F -eq 'py') { $out = '\z' } }
                'A' { if ($F -eq 'js') { $errors.Add('JavaScript has no \A - use ^ (without the m flag)') } }
                'z' { if ($F -eq 'js') { $errors.Add('JavaScript has no \z - use $ (without the m flag)') } }
                'G' { if ($F -in 'js', 'py', 'go') { $errors.Add("\G isn't supported in this language") } }
                default { if ($nx -match '^[1-9]$' -and $F -eq 'go') { $errors.Add('Go (RE2) has no back-references like \1') } }
            }
            if ($null -ne $out) { [void]$sb.Append($out) } else { [void]$sb.Append($ch).Append($nx) }
            $i += 2; continue
        }
        if ($inClass) {
            if ($ch -eq '[' -and $i + 1 -lt $P.Length -and $P[$i + 1] -eq ':') {
                $end = $P.IndexOf(':]', $i + 2)
                if ($end -gt 0) {
                    $name = $P.Substring($i + 2, $end - $i - 2)
                    if ($posix.ContainsKey($name)) { [void]$sb.Append($posix[$name]); $i = $end + 2; continue }
                }
            }
            if ($ch -eq ']' -and $i -gt $classStart) { $inClass = $false }
            [void]$sb.Append($ch); $i++; continue
        }
        if ($ch -eq '[') {
            $inClass = $true; [void]$sb.Append('['); $i++
            if ($i -lt $P.Length -and $P[$i] -eq '^') { [void]$sb.Append('^'); $i++ }
            if ($i -lt $P.Length -and $P[$i] -eq ']') { [void]$sb.Append('\]'); $i++ }
            $classStart = $i
            continue
        }
        if ($ch -eq '(' -and $i + 1 -lt $P.Length -and $P[$i + 1] -eq '?') {
            $rest = $P.Substring($i)
            if ($rest -match '^\(\?P<') { if ($F -in 'py', 'php', 'go') { [void]$sb.Append('(?<'); $i += 4; continue } else { $errors.Add('(?P<name>...) is Python / PHP / Go syntax - here write (?<name>...)') } }
            if ($rest -match '^\(\?P=(\w+)\)') { [void]$sb.Append("\k<$($Matches[1])>"); $i += $Matches[0].Length; if ($F -eq 'go') { $errors.Add('Go (RE2) has no back-references') }; continue }
            if ($rest -match '^\(\?(P>|R\)|\d+\)|&)') { $errors.Add('recursion ((?R), (?1), (?P>name)) is PCRE only - .NET can''t test it') }
            if ($rest -match '^\(\?(=|!|<=|<!)' -and $F -in 'go', 'posix') { $errors.Add("$(if ($F -eq 'go') { 'Go (RE2)' } else { 'POSIX ERE' }) has no lookahead / lookbehind ((?=...), (?!...), (?<=...), (?<!...))") }
            if ($rest -match '^\(\?>' -and $F -in 'js', 'go', 'posix') { $errors.Add('atomic groups (?>...) aren''t supported in this language') }
            if ($rest -match '^\(\?#' -and $F -in 'js', 'go', 'posix') { $errors.Add('comments (?#...) aren''t supported in this language') }
            if ($rest -match '^\(\?[imsx-]+[):]' -and $F -in 'js', 'posix') { $errors.Add('inline flags like (?i) aren''t supported here - use the checkboxes (flags)') }
            if ($rest -match '^\(\?<\w+>' -and $F -eq 'posix') { $errors.Add('POSIX ERE has no named groups') }
            if ($rest -match '^\(\?:' -and $F -eq 'posix') { $errors.Add('POSIX ERE has no (?:...) - use (...)') }
        }
        # quantifier modifiers: possessive (Java, PHP) / lazy (not in POSIX)
        if ($ch -match '[*+?}]' -and $i + 1 -lt $P.Length -and -not ($ch -eq '?' -and $i -gt 0 -and $P[$i - 1] -eq '(')) {
            $nx = $P[$i + 1]
            if ($nx -eq '+' -and $F -in 'java', 'php') { [void]$sb.Append($ch); $i += 2; if (-not ($notes | Where-Object { $_ -like 'possessive*' })) { $notes.Add('possessive quantifiers (x++, x*+) are tested as normal greedy ones') }; continue }
            if ($nx -eq '?' -and $F -eq 'posix') { $errors.Add('POSIX ERE has no lazy quantifiers (*?, +?)') }
        }
        [void]$sb.Append($ch); $i++
    }
    if ($F -eq 'posix' -and $P -match '\\[dws]') { $notes.Add('grep -E / sed -E don''t know \d \w \s everywhere - [[:digit:]] [[:alnum:]_] [[:space:]] always work') }
    if ($F -eq 'go' -and $P -match '\(\?<\w+>') { $notes.Add('older Go versions need (?P<name>...)') }
    @{ Pattern = $sb.ToString(); Flags = $flags; Notes = @($notes); Errors = @($errors) }
}

# The replacement as the language writes it -> .NET ($1, ${name}, $0)
function Convert-RegexReplacement([string]$R, [string]$F) {
    switch ($F) {
        'js'    { $R = $R -replace '\$&', '$$0' -replace '\$<(\w+)>', '$${$1}' }
        'py'    { $R = $R.Replace('$', '$$') -replace '\\g<(\w+)>', '$${$1}' -replace '\\(\d)', '$$$1' }
        'php'   { $R = $R -replace '\\(\d)', '$$$1' }
        'go'    { $R = $R -replace '\$([A-Za-z_]\w*)', '$${$1}' }
        'posix' { $R = $R.Replace('$', '$$') -replace '(?<!\\)&', '$$0' -replace '\\&', '&' -replace '\\(\d)', '$$$1' }
    }
    $R
}

# Code that uses the pattern in the chosen language.
function Get-RegexCode([string]$F, [string]$P, [string]$R, [bool]$I, [bool]$M, [bool]$S, [bool]$X) {
    $q1 = { param($t) "'" + $t.Replace("'", "''") + "'" }                                   # PowerShell
    $dq = { param($t) '"' + $t.Replace('\', '\\').Replace('"', '\"') + '"' }               # Java-style string
    switch ($F) {
        'net' {
            $o = @(); if ($I) { $o += 'IgnoreCase' }; if ($M) { $o += 'Multiline' }; if ($S) { $o += 'Singleline' }; if ($X) { $o += 'IgnorePatternWhitespace' }
            $cs = if ($o) { ($o | ForEach-Object { "RegexOptions.$_" }) -join ' | ' } else { 'RegexOptions.None' }
            $ps = if ($o) { "'" + ($o -join ', ') + "'" } else { "'None'" }
            @"
// C#   (using System.Text.RegularExpressions;)
var rx = new Regex(@"$($P.Replace('"', '""'))", $cs);
foreach (Match m in rx.Matches(text))
    Console.WriteLine(m.Value + "  group 1: " + m.Groups[1].Value);
string replaced = rx.Replace(text, @"$($R.Replace('"', '""'))");

# PowerShell
`$rx = [regex]::new($(& $q1 $P), $ps)
foreach (`$m in `$rx.Matches(`$text)) { `$m.Value; `$m.Groups[1].Value }
`$replaced = `$rx.Replace(`$text, $(& $q1 $R))
if (`$text -match $(& $q1 $P)) { `$Matches[0] }      # -match ignores case by default (-cmatch doesn't)
"@
        }
        'js' {
            $fl = 'g' + $(if ($I) { 'i' }) + $(if ($M) { 'm' }) + $(if ($S) { 's' })
            $lit = $P -replace '(?<!\\)/', '\/'
            if ($P -match '^/(.+)/([a-z]*)$') { $lit = $Matches[1]; $fl = $Matches[2]; if ($fl -notmatch 'g') { $fl = 'g' + $fl } }
            @"
const re = /$lit/$fl;$(if ($X) { '        // JavaScript has no x flag: remove the spaces / comments' })
for (const m of text.matchAll(re)) {
  console.log(m[0], 'group 1:', m[1], 'at', m.index);   // named: m.groups.name
}
const replaced = text.replace(re, '$($R.Replace("'", "\'"))');    // `$1, `$<name>, `$& = whole match
const first = text.match(new RegExp(re.source, re.flags.replace('g', '')));
"@
        }
        'py' {
            $o = @(); if ($I) { $o += 're.IGNORECASE' }; if ($M) { $o += 're.MULTILINE' }; if ($S) { $o += 're.DOTALL' }; if ($X) { $o += 're.VERBOSE' }
            $qq = if ($P.Contains("'") -and -not $P.Contains('"')) { '"' } else { "'" }
            $pp = if ($P.EndsWith('\') -or ($P.Contains("'") -and $P.Contains('"'))) { & $dq $P } else { "r$qq$P$qq" }
            @"
import re

rx = re.compile($pp$(if ($o) { ', ' + ($o -join ' | ') }))
for m in rx.finditer(text):
    print(m.group(0), 'group 1:', m.group(1) if rx.groups else None, 'at', m.start())   # named: m.group('name')
replaced = rx.sub(r'$($R.Replace("'", "\'"))', text)      # \1, \g<name>, \g<0> = whole match
first = rx.search(text)
"@
        }
        'java' {
            $o = @(); if ($I) { $o += 'Pattern.CASE_INSENSITIVE' }; if ($M) { $o += 'Pattern.MULTILINE' }; if ($S) { $o += 'Pattern.DOTALL' }; if ($X) { $o += 'Pattern.COMMENTS' }
            @"
// import java.util.regex.*;
Pattern p = Pattern.compile($(& $dq $P)$(if ($o) { ', ' + ($o -join ' | ') }));
Matcher m = p.matcher(text);
while (m.find()) {
    System.out.println(m.group() + "  group 1: " + (m.groupCount() > 0 ? m.group(1) : null));   // named: m.group("name")
}
String replaced = p.matcher(text).replaceAll($(& $dq $R));   // `$1, `${name}, `$0
"@
        }
        'php' {
            $body = $P; $fl = $(if ($I) { 'i' }) + $(if ($M) { 'm' }) + $(if ($S) { 's' }) + $(if ($X) { 'x' }) + 'u'
            $lit = if ($P.Length -gt 2 -and $P[0] -match '[/#~@%!|+]' -and $P -match ('^' + [regex]::Escape([string]$P[0]) + '.*' + [regex]::Escape([string]$P[0]) + '[a-zA-Z]*$')) { $P } else { '/' + ($body -replace '(?<!\\)/', '\/') + '/' + $fl }
            @"
<?php
preg_match_all('$($lit.Replace('\', '\\').Replace("'", "\'"))', `$text, `$matches, PREG_SET_ORDER);
foreach (`$matches as `$m) {
    echo `$m[0], ' group 1: ', `$m[1] ?? '', PHP_EOL;     // named: `$m['name']
}
`$replaced = preg_replace('$($lit.Replace('\', '\\').Replace("'", "\'"))', '$($R.Replace('\', '\\').Replace("'", "\'"))', `$text);   // `$1, `${1}, \1
"@
        }
        'go' {
            $fl = $(if ($I) { 'i' }) + $(if ($M) { 'm' }) + $(if ($S) { 's' })
            $pp = $(if ($fl) { "(?$fl)" }) + $P
            $lit = if ($pp.Contains('`')) { & $dq $pp } else { '`' + $pp + '`' }
            @"
// import "regexp"
re := regexp.MustCompile($lit)$(if ($X) { '   // Go has no x flag: remove the spaces' })
for _, m := range re.FindAllStringSubmatch(text, -1) {
    fmt.Println(m[0], "group 1:", m[1:])          // named: re.SubexpIndex("name")
}
replaced := re.ReplaceAllString(text, $(if ($R.Contains('`')) { & $dq $R } else { '`' + $R + '`' }))   // `$1, `${1}, `${name}
"@
        }
        'posix' {
            $sq = { param($t) "'" + $t.Replace("'", "'\''") + "'" }
            $ci = if ($I) { ' -i' } else { '' }
            $sedP = $P.Replace('/', '\/'); $sedR = $R.Replace('/', '\/')
            @"
# lines that match / only the matching parts
grep -E$ci $(& $sq $P) file.txt
grep -E -o$ci $(& $sq $P) file.txt

# replace (GNU sed; \1 = group 1, & = whole match)
sed -E $(& $sq "s/$sedP/$sedR/g$(if ($I) { 'I' })") file.txt
"@
        }
    }
}

# Ready-made patterns (written so they work in most languages; named groups are adapted when chosen).
function Get-RegexExamples {
    [ordered]@{
        'Email address'          = @{ P = '[\w.+-]+@[\w-]+(\.[\w-]+)+'; T = "Write to ann.smith@example.com or bob+news@mail.test.org`r`nNot an email: ann@ or @test.org" }
        'URL (http / https)'     = @{ P = 'https?://[^\s/$.?#][^\s]*'; T = "Docs: https://example.com/docs?page=2#top and http://localhost:8080/api`r`nnot: ftp://x.org" }
        'IPv4 address'           = @{ P = '\b((25[0-5]|2[0-4]\d|1?\d?\d)\.){3}(25[0-5]|2[0-4]\d|1?\d?\d)\b'; T = "Servers 10.0.0.1, 192.168.1.254 and 8.8.8.8`r`nInvalid: 256.1.1.1 and 1.2.3" }
        'Date YYYY-MM-DD (reorder to DD.MM.YYYY)' = @{ P = '\b(?<y>\d{4})-(?<m>\d{2})-(?<d>\d{2})\b'; T = "Released 2026-10-17, patched 2026-11-02."; R = '${d}.${m}.${y}' }
        'Time HH:MM(:SS)'        = @{ P = '\b([01]\d|2[0-3]):[0-5]\d(:[0-5]\d)?\b'; T = "Start 09:30, end 17:45:10, invalid 25:61" }
        'GUID / UUID'            = @{ P = '\b[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}\b'; T = "id=3f2504e0-4f89-11d3-9a0c-0305e82c3301 and 00000000-0000-0000-0000-000000000000" }
        'Phone number'           = @{ P = '\+?\d{1,3}[ -]?\(?\d{2,4}\)?[ -]?\d{3,4}[ -]?\d{3,4}'; T = "Call +359 88 123 4567 or (555) 123-4567 or 0888123456" }
        'Number (int / decimal)' = @{ P = '-?\b\d+(\.\d+)?\b'; T = "Totals: 42, -7, 3.14 and 1000.50" }
        'Hex colour'             = @{ P = '#([0-9a-fA-F]{3}){1,2}\b'; T = "color: #fff; background: #1E90FF; border: #12345" }
        'Words in quotes'        = @{ P = '"([^"\\]|\\.)*"|''([^''\\]|\\.)*'''; T = "say ""hello"" and 'bye', even ""with \""escape\"""" " }
        'Repeated word'          = @{ P = '\b(\w+)\s+\1\b'; T = "This is is a test of the the repeated words." }
        'Key = value pairs'      = @{ P = '^\s*(?<key>[\w.-]+)\s*[=:]\s*(?<value>.*?)\s*$'; T = "host = localhost`r`nport: 5432`r`n# comment`r`nuser=admin" }
        'Log line (time, level, message)' = @{ P = '^(?<time>\d{4}-\d{2}-\d{2}[ T][\d:.]+)\s+\[?(?<level>INFO|WARN|ERROR|DEBUG)\]?\s+(?<msg>.*)$'; T = "2026-10-17 09:12:01.123 INFO Service started`r`n2026-10-17 09:12:05.456 [ERROR] Connection refused`r`nrandom line" }
        'HTML tag'               = @{ P = '<(?<tag>[a-zA-Z][\w-]*)(?<attrs>[^>]*)>'; T = '<div class="box"><a href="/home">Home</a><br/></div>' }
        'JSON "key": value'      = @{ P = '"(?<key>[^"]+)"\s*:\s*(?<value>"[^"]*"|-?\d+(\.\d+)?|true|false|null)'; T = '{"name": "Ann", "age": 31, "admin": false, "city": null}' }
        'Strong password (lookaheads)' = @{ P = '^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[^\w\s]).{8,}$'; T = "weakpass`r`nStr0ng!Pass`r`nNoDigits!!`r`nGood#Pass99"; I = $false }
        'Trailing spaces (remove)' = @{ P = '[ \t]+$'; T = "line with spaces   `r`nclean line`r`ntabs`t`t"; R = '' }
        'Empty lines (remove)'   = @{ P = '^\s*$\r?\n'; T = "first`r`n`r`n   `r`nsecond`r`n`r`nthird"; R = '' }
        'Between two words'      = @{ P = '(?<=START).*?(?=END)'; T = "xxSTART the part you want ENDyy" }
        'camelCase -> snake_case' = @{ P = '(?<=[a-z0-9])(?=[A-Z])'; T = "userName orderIdValue parseHTTPResponse"; R = '_'; I = $false }
    }
}

# Tokens for the cheat sheet (double-click one to put it into the pattern).
$RegexCheatSheet = @(
    @('.', 'any character (except a newline, unless "dot matches newline")'), @('\d  \D', 'a digit / not a digit'),
    @('\w  \W', 'a word character (letter, digit, _) / not one'), @('\s  \S', 'white space / not white space'),
    @('[abc]', 'one of a, b, c'), @('[^abc]', 'anything except a, b, c'), @('[a-z0-9]', 'a range'),
    @('^  $', 'start / end of the text (of each line with "^ $ per line")'), @('\b', 'word boundary'),
    @('*  +  ?', '0 or more / 1 or more / 0 or 1'), @('{3}  {2,5}  {2,}', 'exactly 3 / 2 to 5 / 2 or more'),
    @('*?  +?', 'lazy: as few as possible'), @('(abc)', 'group (captured as $1 ...)'), @('(?:abc)', 'group without capturing'),
    @('(?<name>abc)', 'named group (Python / Go: (?P<name>abc))'), @('\1  \k<name>', 'the same text as group 1 / group "name" again'),
    @('a|b', 'a or b'), @('(?=abc)', 'followed by abc (lookahead)'), @('(?!abc)', 'not followed by abc'),
    @('(?<=abc)', 'preceded by abc (lookbehind)'), @('(?<!abc)', 'not preceded by abc'),
    @('\.  \*  \\', 'a literal . * \ (escape special characters)'), @('\t  \n  \r', 'tab / newline / carriage return'),
    @('\uFFFF  \x41', 'a character by its code'), @('(?i)', 'ignore case from here (not in JavaScript)'),
    @('$1  ${name}  $0', 'in Replace: group 1 / group "name" / the whole match')
)

function Update-RegexTool($St) {
    $St.Busy = $true
    $rtb = $St.Text
    $selStart = $rtb.SelectionStart; $selLen = $rtb.SelectionLength
    [PowerClipTheme]::Redraw($rtb.Handle, $false)
    try {
        $rtb.SelectAll(); $rtb.SelectionBackColor = $C.Bg; $rtb.SelectionColor = $C.Fore
        $St.Matches.BeginUpdate(); $St.Matches.Items.Clear()
        $pattern = $St.Pattern.Text
        $flv = if ($St.Flavor) { $RegexFlavors[[string]$St.Flavor.SelectedItem] } else { 'net' }
        $lang = [string]$St.Flavor.SelectedItem
        if ($St.Code) { $St.Code.Text = if ($pattern) { Get-RegexCode $flv $pattern $St.Replace.Text $St.Opt.IgnoreCase.Checked $St.Opt.Multiline.Checked $St.Opt.Singleline.Checked $St.Opt.IgnorePatternWhitespace.Checked } else { '' } }
        if (-not $pattern) { $St.Result.Text = $rtb.Text; Set-TbStatus $St.Status 'Type a pattern.'; return }
        $cvt = Convert-RegexToNet $pattern $flv
        $pattern = $cvt.Pattern
        $opts = [System.Text.RegularExpressions.RegexOptions]::None
        foreach ($k in $St.Opt.Keys) { if ($St.Opt[$k].Checked) { $opts = $opts -bor [System.Text.RegularExpressions.RegexOptions]$k } }
        if ($cvt.Flags) {             # flags from /.../gi: they decide i, m, s, x
            $opts = [System.Text.RegularExpressions.RegexOptions]::None
            if ($cvt.Flags -cmatch 'i') { $opts = $opts -bor 'IgnoreCase' }; if ($cvt.Flags -cmatch 'm') { $opts = $opts -bor 'Multiline' }
            if ($cvt.Flags -cmatch 's') { $opts = $opts -bor 'Singleline' }; if ($cvt.Flags -cmatch 'x') { $opts = $opts -bor 'IgnorePatternWhitespace' }
        }
        try { $rx = New-Object System.Text.RegularExpressions.Regex($pattern, $opts, [TimeSpan]::FromSeconds(2)) }
        catch { Set-TbStatus $St.Status "Pattern error: $($_.Exception.InnerException.Message)" 'error'; return }
        $text = $rtb.Text
        try {
            $ms = $rx.Matches($text)
            $count = $ms.Count
            $hl = @([PowerClipTheme]::Mix($C.Bg, $C.Yellow, 0.35), [PowerClipTheme]::Mix($C.Bg, $C.Accent, 0.30))
            $n = 0
            foreach ($m in $ms) {
                if ($n -lt 2000 -and $m.Length -gt 0) { $rtb.Select($m.Index, $m.Length); $rtb.SelectionBackColor = $hl[$n % 2] }
                if ($n -lt 1000) {
                    $groups = @()
                    for ($g = 1; $g -lt $m.Groups.Count; $g++) {
                        $name = $rx.GroupNameFromNumber($g)
                        $groups += "$(if ($name -ne [string]$g) { $name } else { $g })=$($m.Groups[$g].Value)"
                    }
                    $it = New-Object System.Windows.Forms.ListViewItem([string]($n + 1))
                    [void]$it.SubItems.Add([string]$m.Index); [void]$it.SubItems.Add($m.Value); [void]$it.SubItems.Add($groups -join '   ')
                    $it.Tag = $m
                    [void]$St.Matches.Items.Add($it)
                }
                $n++
            }
            $St.Result.Text = $rx.Replace($text, (Convert-RegexReplacement $St.Replace.Text $flv))
            $msg = "$count match$(if ($count -ne 1) { 'es' })$(if ($count -gt 1000) { '  (first 1000 listed)' })"
            if ($cvt.Errors.Count) { $msg += "  -  Not valid in ${lang}: $($cvt.Errors -join '; ')" }
            elseif ($cvt.Notes.Count) { $msg += "  -  $($cvt.Notes -join '; ')" }
            Set-TbStatus $St.Status $msg $(if ($cvt.Errors.Count) { 'warn' } elseif ($count) { 'ok' } else { 'warn' })
        } catch [System.Text.RegularExpressions.RegexMatchTimeoutException] {
            Set-TbStatus $St.Status 'Stopped: the pattern took longer than 2 seconds (catastrophic backtracking?)' 'error'
        } catch {
            $ex = $_.Exception; while ($ex.InnerException) { $ex = $ex.InnerException }
            Set-TbStatus $St.Status $(if ($ex -is [System.Text.RegularExpressions.RegexMatchTimeoutException]) { 'Stopped: the pattern took longer than 2 seconds (catastrophic backtracking?)' } else { "Error: $($ex.Message)" }) 'error'
        }
    } finally {
        $St.Matches.EndUpdate()
        $rtb.Select($selStart, $selLen)
        [PowerClipTheme]::Redraw($rtb.Handle, $true)
        $rtb.Invalidate()
        $St.Busy = $false
    }
}

# ======================================================================================
# Cron: explain an expression and list the next runs.
# ======================================================================================
Register-ToolboxPage 'cron' 'Cron expressions' $Glyph.History 'cron schedule crontab next run quartz' {
    param($panel, $st)
    $st.Status = New-TbPage $panel
    $st.Runs = New-TbRtb -ReadOnly; $st.Runs.Dock = 'Fill'
    $panel.Controls.Add($st.Runs)
    $desc = New-Object System.Windows.Forms.Label
    $desc.Dock = 'Top'; $desc.AutoSize = $false; $desc.Height = $FontTitle.Height * 2 + (Px 20); $desc.ForeColor = $C.Accent; $desc.BackColor = $C.Bg
    $desc.Font = New-Object System.Drawing.Font($UiFont, (Fz 13), [System.Drawing.FontStyle]::Bold); $desc.Padding = New-Object System.Windows.Forms.Padding(0, (Px 8), 0, 0)
    $panel.Controls.Add($desc)
    $st.Desc = $desc
    $pre = New-TbBar $panel
    New-TbLabel $pre 'Examples' -Dim | Out-Null
    foreach ($x in @(@('Every 5 min', '*/5 * * * *'), @('Hourly', '0 * * * *'), @('Daily 09:00', '0 9 * * *'), @('Weekdays 09:00', '0 9 * * 1-5'),
                     @('Mon 08:30', '30 8 * * MON'), @('1st of month', '0 0 1 * *'), @('Every 15 s', '*/15 * * * * *'))) {
        $b = New-Button $x[0] $x[1] { param($src, $e) $TbUI.Pages['cron'].State.Expr.Text = $src.Tag } $pre '' 2
        $b.Tag = $x[1]
    }
    $bar = New-TbBar $panel
    New-TbLabel $bar 'Expression' -Title | Out-Null
    $st.Expr = New-TbBox -Mono -Cue 'minute hour day month weekday   e.g.  */15 9-17 * * 1-5'
    $st.Expr.Width = Px (360 * $TextZoom); $st.Expr.Font = New-Object System.Drawing.Font('Consolas', (Fz 13)); $st.Expr.Margin = New-Object System.Windows.Forms.Padding(0, (Px 2), (Px 10), 0)
    $bar.Controls.Add($st.Expr)
    New-TbLabel $bar 'minute  hour  day-of-month  month  weekday   (6 fields = seconds first; @daily, @hourly ...)' -Dim | Out-Null
    $st.Expr.add_TextChanged({ Update-CronTool $TbUI.Pages['cron'].State })
    $st.SetInput = { param($t) $TbUI.Pages['cron'].State.Expr.Text = $t.Trim() }
    $st.Focus = { $TbUI.Pages['cron'].State.Expr.Focus() }
    $st.Expr.Text = '*/15 9-17 * * 1-5'
    $st
}

function Update-CronTool($St) {
    $e = $St.Expr.Text.Trim()
    $St.Runs.Clear()
    if (-not $e) { $St.Desc.Text = ''; Set-TbStatus $St.Status 'Type a cron expression.'; return }
    try {
        $cx = [DevCron]::Parse($e)
        $St.Desc.Text = $cx.Describe()
        $St.Desc.ForeColor = $C.Accent
        Add-RtbLine $St.Runs 'NEXT RUNS (your local time)' $C.Accent -Bold
        $now = Get-Date
        foreach ($t in $cx.NextRuns($now, 12)) { Add-RtbLine $St.Runs ("{0}    {1}" -f $t.ToString('ddd  yyyy-MM-dd  HH:mm:ss'), (Format-Relative $t)) }
        Set-TbStatus $St.Status 'Valid expression' 'ok'
    } catch {
        $ex = $_.Exception; while ($ex.InnerException) { $ex = $ex.InnerException }
        $St.Desc.Text = 'Not a valid cron expression'; $St.Desc.ForeColor = $C.Red
        Set-TbStatus $St.Status $ex.Message 'error'
    }
}

# ======================================================================================
# Generators: GUIDs, passwords, lorem ipsum, random test data.
# ======================================================================================
$TestData = @{
    First = 'Olivia Liam Emma Noah Ava Elijah Sophia James Isabella William Mia Benjamin Charlotte Lucas Amelia Henry Harper Alexander Evelyn Daniel Maria Ivan Elena Georgi Petar Yana Mateo Sofia Hiro Aiko Priya Arjun Fatima Omar Lena Jonas'.Split(' ')
    Last  = 'Smith Johnson Williams Brown Jones Garcia Miller Davis Rodriguez Martinez Hernandez Lopez Wilson Anderson Thomas Taylor Moore Jackson Martin Lee Petrov Ivanova Dimitrov Schmidt Muller Rossi Silva Tanaka Kim Nguyen Patel Novak Kowalski'.Split(' ')
    City  = 'Springfield Riverton Lakeside Fairview Greenville Madison Georgetown Franklin Clinton Salem Sofia Plovdiv Varna Berlin Munich Vienna Prague Lisbon Porto Dublin Austin Denver Portland Seattle Toronto'.Split(' ')
    Street = 'Main Oak Pine Maple Cedar Elm Washington Lake Hill Park Church High Station Mill River Sunset Forest Meadow'.Split(' ')
    Country = 'United States|Canada|United Kingdom|Germany|France|Bulgaria|Spain|Italy|Netherlands|Austria|Japan|Australia|Brazil|India'.Split('|')
    Company = 'Acme|Globex|Initech|Umbrella|Stark Industries|Wayne Enterprises|Hooli|Vandelay|Soylent|Tyrell|Cyberdyne|Wonka|Pied Piper|Northwind|Contoso|Fabrikam'.Split('|')
    Domain = 'example.com example.org example.net test.io mail.test demo.dev'.Split(' ')
    Lorem = 'lorem ipsum dolor sit amet consectetur adipiscing elit sed do eiusmod tempor incididunt ut labore et dolore magna aliqua enim ad minim veniam quis nostrud exercitation ullamco laboris nisi aliquip ex ea commodo consequat duis aute irure in reprehenderit voluptate velit esse cillum fugiat nulla pariatur excepteur sint occaecat cupidatat non proident sunt culpa qui officia deserunt mollit anim id est laborum'.Split(' ')
}
$Rng = New-Object System.Random

function Get-RandomItem($List) { $List[$Rng.Next($List.Count)] }

function New-LoremSentence {
    $n = $Rng.Next(6, 15)
    $w = 1..$n | ForEach-Object { Get-RandomItem $TestData.Lorem }
    $s = ($w -join ' ')
    $s.Substring(0, 1).ToUpper() + $s.Substring(1) + '.'
}

function New-TestRow([string[]]$Fields, [int]$Index) {
    $first = Get-RandomItem $TestData.First; $last = Get-RandomItem $TestData.Last
    $o = [ordered]@{}
    foreach ($f in $Fields) {
        $o[$f] = switch ($f) {
            'id'      { $Index }
            'name'    { "$first $last" }
            'email'   { "$($first.ToLower()).$($last.ToLower())$($Rng.Next(1, 99))@$(Get-RandomItem $TestData.Domain)" }
            'phone'   { '+1 555 {0:000} {1:0000}' -f $Rng.Next(100, 999), $Rng.Next(0, 9999) }
            'address' { "$($Rng.Next(1, 999)) $(Get-RandomItem $TestData.Street) Street" }
            'city'    { Get-RandomItem $TestData.City }
            'country' { Get-RandomItem $TestData.Country }
            'company' { Get-RandomItem $TestData.Company }
            'date'    { (Get-Date).AddDays(-$Rng.Next(0, 3650)).ToString('yyyy-MM-dd') }
            'amount'  { [Math]::Round($Rng.NextDouble() * 1000, 2) }
            'active'  { $Rng.Next(2) -eq 1 }
            'guid'    { [guid]::NewGuid().ToString() }
        }
    }
    $o
}

Register-ToolboxPage 'gen' 'Generators' $Glyph.Refresh 'generate guid uuid password lorem ipsum test data fake random' {
    param($panel, $st)
    $st.Status = New-TbPage $panel
    $st.Output = New-TbBox -Mono -Multi -ReadOnly
    $st.Output.Dock = 'Fill'
    $panel.Controls.Add($st.Output)
    $obar = New-TbBar $panel
    [void](New-Button 'Generate' 'Generate again (F5)' { New-GeneratorOutput $TbUI.Pages['gen'].State } $obar $Glyph.Refresh 1)
    [void](New-Button 'Copy' 'Copy the output' { Copy-TbText $TbUI.Pages['gen'].State.Output.Text } $obar $Glyph.Copy)
    $opts = New-TbBar $panel
    $kind = New-TbBar $panel
    New-TbLabel $kind 'Generate' -Title | Out-Null
    $st.Kind = New-TbCombo $kind @('GUIDs', 'Passwords', 'Lorem ipsum', 'Test data') 150
    New-TbLabel $kind 'How many' -Dim | Out-Null
    $st.Count = New-TbNumber $kind 5 1 10000
    $st.OptsBar = $opts
    $st.Kind.add_SelectedIndexChanged({ $s = $TbUI.Pages['gen'].State; Build-GeneratorOptions $s; New-GeneratorOutput $s })
    $st.Count.add_ValueChanged({ New-GeneratorOutput $TbUI.Pages['gen'].State })
    $st.Focus = { $TbUI.Pages['gen'].State.Kind.Focus() }
    Build-GeneratorOptions $st
    New-GeneratorOutput $st
    $st
}

function Build-GeneratorOptions($St) {
    $bar = $St.OptsBar
    $bar.Controls.Clear()
    $St.O = @{}
    $regen = { New-GeneratorOutput $TbUI.Pages['gen'].State }
    switch ($St.Kind.SelectedItem) {
        'GUIDs' {
            New-TbLabel $bar 'Format' -Dim | Out-Null
            $St.O.Format = New-TbCombo $bar @('lower case', 'UPPER CASE', 'no dashes', '{braces}', 'C# new Guid("...")') 180
            $St.O.Format.add_SelectedIndexChanged($regen)
        }
        'Passwords' {
            New-TbLabel $bar 'Length' -Dim | Out-Null
            $St.O.Length = New-TbNumber $bar 20 4 256; $St.O.Length.add_ValueChanged($regen)
            foreach ($x in @(@('Upper', 'A-Z'), @('Lower', 'a-z'), @('Digits', '0-9'), @('Symbols', '!@#...'))) {
                $St.O[$x[0]] = New-CheckBox $bar $x[1] $true; $St.O[$x[0]].add_CheckedChanged($regen)
            }
            New-TbLabel $bar 'Similar-looking characters (O 0 l 1 I) are left out.' -Dim | Out-Null
        }
        'Lorem ipsum' {
            New-TbLabel $bar 'Unit' -Dim | Out-Null
            $St.O.Unit = New-TbCombo $bar @('paragraphs', 'sentences', 'words') 130
            $St.O.Unit.add_SelectedIndexChanged($regen)
            $St.O.Classic = New-CheckBox $bar 'Start with "Lorem ipsum dolor sit amet"' $true; $St.O.Classic.add_CheckedChanged($regen)
        }
        'Test data' {
            New-TbLabel $bar 'As' -Dim | Out-Null
            $St.O.Format = New-TbCombo $bar @('JSON', 'CSV', 'SQL INSERT') 120
            $St.O.Format.add_SelectedIndexChanged($regen)
            $St.O.Fields = @{}
            foreach ($f in 'id', 'name', 'email', 'phone', 'address', 'city', 'country', 'company', 'date', 'amount', 'active', 'guid') {
                $on = $f -in 'id', 'name', 'email', 'city', 'date'
                $St.O.Fields[$f] = New-CheckBox $bar $f $on; $St.O.Fields[$f].add_CheckedChanged($regen)
            }
        }
    }
    Set-ControlTheme $bar $null $script:IsDark
}

function New-GeneratorOutput($St) {
    $n = [int]$St.Count.Value
    $out = switch ($St.Kind.SelectedItem) {
        'GUIDs' {
            $fmt = $St.O.Format.SelectedIndex
            (1..$n | ForEach-Object {
                $g = [guid]::NewGuid()
                switch ($fmt) { 1 { $g.ToString().ToUpper() } 2 { $g.ToString('N') } 3 { $g.ToString('B') } 4 { "new Guid(`"$g`")" } default { $g.ToString() } }
            }) -join "`r`n"
        }
        'Passwords' {
            (1..$n | ForEach-Object { [PowerClipVault]::Generate([int]$St.O.Length.Value, $St.O.Upper.Checked, $St.O.Lower.Checked, $St.O.Digits.Checked, $St.O.Symbols.Checked) }) -join "`r`n"
        }
        'Lorem ipsum' {
            $unit = $St.O.Unit.SelectedItem
            $classic = $St.O.Classic.Checked
            $txt = switch ($unit) {
                'words' { (1..$n | ForEach-Object { Get-RandomItem $TestData.Lorem }) -join ' ' }
                'sentences' { (1..$n | ForEach-Object { New-LoremSentence }) -join ' ' }
                default { (1..$n | ForEach-Object { (1..$Rng.Next(4, 8) | ForEach-Object { New-LoremSentence }) -join ' ' }) -join "`r`n`r`n" }
            }
            if ($classic) {
                $start = 'Lorem ipsum dolor sit amet, consectetur adipiscing elit'
                if ($unit -eq 'words') { $txt = (($start -replace ',', '').Split(' ') + $txt.Split(' '))[0..($n - 1)] -join ' ' }
                else { $txt = $start + '. ' + $txt }
            }
            $txt
        }
        'Test data' {
            $fields = @($St.O.Fields.Keys | Where-Object { $St.O.Fields[$_].Checked } | Sort-Object { @('id', 'name', 'email', 'phone', 'address', 'city', 'country', 'company', 'date', 'amount', 'active', 'guid').IndexOf($_) })
            if (-not $fields) { $fields = @('name') }
            $rows = foreach ($i in 1..$n) { New-TestRow $fields $i }
            switch ($St.O.Format.SelectedItem) {
                'CSV' {
                    $lines = @($fields -join ',')
                    foreach ($r in $rows) { $lines += (($fields | ForEach-Object { $v = [string]$r[$_]; if ($v -match '[,"]') { '"' + $v.Replace('"', '""') + '"' } else { $v } }) -join ',') }
                    $lines -join "`r`n"
                }
                'SQL INSERT' {
                    ($rows | ForEach-Object {
                        $r = $_
                        $vals = $fields | ForEach-Object { $v = $r[$_]; if ($v -is [bool]) { [int]$v } elseif ($v -is [int] -or $v -is [double]) { [string]$v } else { "'" + ([string]$v).Replace("'", "''") + "'" } }
                        "INSERT INTO people ($($fields -join ', ')) VALUES ($($vals -join ', '));"
                    }) -join "`r`n"
                }
                default { ConvertTo-Json -InputObject @($rows | ForEach-Object { [pscustomobject]$_ }) -Depth 3 }
            }
        }
    }
    $St.Output.Text = [string]$out
    Set-TbStatus $St.Status "$($St.Kind.SelectedItem): $n generated  $Dot  random values from a cryptographic generator (passwords, GUIDs)"
}

# ======================================================================================
# QR code
# ======================================================================================
Register-ToolboxPage 'qr' 'QR code' $Glyph.Apps 'qr code barcode generate image' {
    param($panel, $st)
    foreach ($kv in (@{ Bitmap = $null }).GetEnumerator()) { $st[$kv.Key] = $kv.Value }
    $st.Status = New-TbPage $panel
    $st.Picture = New-Object System.Windows.Forms.PictureBox
    $st.Picture.Dock = 'Fill'; $st.Picture.SizeMode = 'Zoom'; $st.Picture.BackColor = $C.Bg
    $panel.Controls.Add($st.Picture)
    $bar = New-TbBar $panel
    New-TbLabel $bar 'Error correction' -Dim | Out-Null
    $st.Level = New-TbCombo $bar @('L - 7%', 'M - 15%', 'Q - 25%', 'H - 30%') 110
    $st.Level.SelectedIndex = 1
    [void](New-Button 'Copy image' 'Copy the QR code as a picture' { $s = $TbUI.Pages['qr'].State; if ($s.Bitmap) { [System.Windows.Forms.Clipboard]::SetImage($s.Bitmap) } } $bar $Glyph.Copy 1)
    [void](New-Button 'Save PNG...' 'Save the QR code as a PNG file' {
        $s = $TbUI.Pages['qr'].State
        if (-not $s.Bitmap) { return }
        $d = New-Object System.Windows.Forms.SaveFileDialog; $d.Filter = 'PNG image|*.png'; $d.FileName = 'qr.png'
        if ($d.ShowDialog($TbUI.Form) -eq 'OK') { $s.Bitmap.Save($d.FileName, [System.Drawing.Imaging.ImageFormat]::Png) }
        $d.Dispose()
    } $bar $Glyph.Save)
    $st.Text = New-TbBox -Multi -Cue 'Text or link to encode'
    $st.Text.Dock = 'Top'; $st.Text.Height = $FontMain.Height * 4; $st.Text.WordWrap = $true; $st.Text.ScrollBars = 'Vertical'
    $panel.Controls.Add($st.Text)
    $st.Text.add_TextChanged({ Update-QrTool $TbUI.Pages['qr'].State })
    $st.Level.add_SelectedIndexChanged({ Update-QrTool $TbUI.Pages['qr'].State })
    $st.SetInput = { param($t) $TbUI.Pages['qr'].State.Text.Text = $t }
    $st.Focus = { $TbUI.Pages['qr'].State.Text.Focus() }
    $st.Close = { $s = $TbUI.Pages['qr'].State; if ($s.Bitmap) { $s.Bitmap.Dispose() } }
    $st.Text.Text = 'https://example.com'
    $st
}

function Update-QrTool($St) {
    $t = $St.Text.Text
    if ($St.Bitmap) { $St.Picture.Image = $null; $St.Bitmap.Dispose(); $St.Bitmap = $null }
    if (-not $t) { Set-TbStatus $St.Status 'Type text or a link.'; return }
    try {
        $m = [DevQr]::Encode($t, $St.Level.SelectedIndex)
        $St.Bitmap = [DevQr]::ToBitmap($m, 10, 4, [System.Drawing.Color]::Black, [System.Drawing.Color]::White)
        $St.Picture.Image = $St.Bitmap
        $bytes = [Text.Encoding]::UTF8.GetByteCount($t)
        Set-TbStatus $St.Status "$($m.GetLength(0)) x $($m.GetLength(0)) modules  $Dot  $bytes bytes  $Dot  scans with any phone camera" 'ok'
    } catch {
        $ex = $_.Exception; while ($ex.InnerException) { $ex = $ex.InnerException }
        Set-TbStatus $St.Status $ex.Message 'error'
    }
}

# ======================================================================================
# Colour: pick from the screen, convert between formats, shades, contrast.
# ======================================================================================
$ColorsFile = Join-Path $DataDir 'colors.json'

function ConvertFrom-ColorText([string]$Text) {
    $t = $Text.Trim()
    if (-not $t) { return $null }
    if ($t -match '^#?([0-9a-f]{3}|[0-9a-f]{4}|[0-9a-f]{6}|[0-9a-f]{8})$') {
        $h = $Matches[1]
        if ($h.Length -le 4) { $h = -join ($h.ToCharArray() | ForEach-Object { "$_$_" }) }
        $v = [Convert]::ToUInt32($h, 16)
        if ($h.Length -eq 6) { return [System.Drawing.Color]::FromArgb([int](($v -shr 16) -band 255), [int](($v -shr 8) -band 255), [int]($v -band 255)) }
        return [System.Drawing.Color]::FromArgb([int]($v -band 255), [int](($v -shr 24) -band 255), [int](($v -shr 16) -band 255), [int](($v -shr 8) -band 255))
    }
    if ($t -match '^rgba?\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)\s*(?:,\s*([\d.]+%?)\s*)?\)$') {
        $a = 255
        if ($Matches[4]) { $a = if ($Matches[4].EndsWith('%')) { [int]([double]$Matches[4].TrimEnd('%') * 2.55) } else { [int]([double]$Matches[4] * 255) } }
        return [System.Drawing.Color]::FromArgb([Math]::Min(255, $a), [Math]::Min(255, [int]$Matches[1]), [Math]::Min(255, [int]$Matches[2]), [Math]::Min(255, [int]$Matches[3]))
    }
    if ($t -match '^hsla?\(\s*([\d.]+)\s*,\s*([\d.]+)%\s*,\s*([\d.]+)%') { return ConvertFrom-Hsl ([double]$Matches[1]) ([double]$Matches[2] / 100) ([double]$Matches[3] / 100) }
    if ($t -match '^(\d{1,3})\s*[, ]\s*(\d{1,3})\s*[, ]\s*(\d{1,3})$') { return [System.Drawing.Color]::FromArgb([Math]::Min(255, [int]$Matches[1]), [Math]::Min(255, [int]$Matches[2]), [Math]::Min(255, [int]$Matches[3])) }
    $named = [System.Drawing.Color]::FromName($t)
    if ($named.IsKnownColor) { return [System.Drawing.Color]::FromArgb($named.A, $named.R, $named.G, $named.B) }
    $null
}

function ConvertFrom-Hsl([double]$H, [double]$S, [double]$L) {
    $cx = (1 - [Math]::Abs(2 * $L - 1)) * $S
    $hp = ($H % 360) / 60
    $x = $cx * (1 - [Math]::Abs($hp % 2 - 1))
    $r, $g, $b = switch ([int][Math]::Floor($hp)) { 0 { $cx, $x, 0 } 1 { $x, $cx, 0 } 2 { 0, $cx, $x } 3 { 0, $x, $cx } 4 { $x, 0, $cx } default { $cx, 0, $x } }
    $m = $L - $cx / 2
    [System.Drawing.Color]::FromArgb([int][Math]::Round(($r + $m) * 255), [int][Math]::Round(($g + $m) * 255), [int][Math]::Round(($b + $m) * 255))
}

function Get-ColorFormats([System.Drawing.Color]$Col) {
    $hex = '#{0:X2}{1:X2}{2:X2}' -f $Col.R, $Col.G, $Col.B
    $h = [int][Math]::Round($Col.GetHue()); $s = [int][Math]::Round($Col.GetSaturation() * 100); $l = [int][Math]::Round($Col.GetBrightness() * 100)
    $max = [Math]::Max($Col.R, [Math]::Max($Col.G, $Col.B)) / 255.0; $min = [Math]::Min($Col.R, [Math]::Min($Col.G, $Col.B)) / 255.0
    $sv = if ($max -eq 0) { 0 } else { [int][Math]::Round(($max - $min) / $max * 100) }
    $k = 1 - $max
    $cmyk = if ($k -ge 1) { 'cmyk(0%, 0%, 0%, 100%)' } else { 'cmyk({0}%, {1}%, {2}%, {3}%)' -f [int][Math]::Round((1 - $Col.R / 255.0 - $k) / (1 - $k) * 100), [int][Math]::Round((1 - $Col.G / 255.0 - $k) / (1 - $k) * 100), [int][Math]::Round((1 - $Col.B / 255.0 - $k) / (1 - $k) * 100), [int][Math]::Round($k * 100) }
    [ordered]@{
        'HEX' = $hex
        'RGB' = "rgb($($Col.R), $($Col.G), $($Col.B))"
        'HSL' = "hsl($h, $s%, $l%)"
        'HSV' = "hsv($h, $sv%, $([int][Math]::Round($max * 100))%)"
        'CMYK' = $cmyk
        'C#' = "Color.FromArgb($($Col.R), $($Col.G), $($Col.B))"
        'Integer' = [string](([int]$Col.R -shl 16) -bor ([int]$Col.G -shl 8) -bor [int]$Col.B)
    }
}

function Get-Luminance([System.Drawing.Color]$Col) {
    $f = { param($v) $cx = $v / 255.0; if ($cx -le 0.03928) { $cx / 12.92 } else { [Math]::Pow(($cx + 0.055) / 1.055, 2.4) } }
    0.2126 * (& $f $Col.R) + 0.7152 * (& $f $Col.G) + 0.0722 * (& $f $Col.B)
}

function Get-Contrast($A, $B) { $la = Get-Luminance $A; $lb = Get-Luminance $B; ([Math]::Max($la, $lb) + 0.05) / ([Math]::Min($la, $lb) + 0.05) }

Register-ToolboxPage 'color' 'Colour picker' $Glyph.Color 'colour color picker eyedropper hex rgb hsl contrast screen' {
    param($panel, $st)
    foreach ($kv in (@{ Color = [System.Drawing.Color]::FromArgb(15, 108, 189); History = (New-Object System.Collections.Generic.List[string]) }).GetEnumerator()) { $st[$kv.Key] = $kv.Value }
    $st.Status = New-TbPage $panel
