        $p = [PowerClipTheme]::Round($r, (Px 12))
        $b = New-Object System.Drawing.SolidBrush $s.Color; $g.FillPath($b, $p); $b.Dispose()
        $pen = New-Object System.Drawing.Pen $C.Line; $g.DrawPath($pen, $p); $pen.Dispose(); $p.Dispose()
        $txt = (Get-ColorFormats $s.Color).HEX
        $fore = if ((Get-Contrast $s.Color ([System.Drawing.Color]::White)) -ge (Get-Contrast $s.Color ([System.Drawing.Color]::Black))) { [System.Drawing.Color]::White } else { [System.Drawing.Color]::Black }
        $f = New-Object System.Drawing.Font($UiFont, (Fz 16), [System.Drawing.FontStyle]::Bold)
        [System.Windows.Forms.TextRenderer]::DrawText($g, $txt, $f, [System.Drawing.Rectangle]::Round($r), $fore, [System.Windows.Forms.TextFormatFlags]'HorizontalCenter, VerticalCenter')
        $f.Dispose()
    })
    $st.Swatch = $swatch
    $body.Controls.Add($swatch, 0, 0)
    $right = New-Object System.Windows.Forms.FlowLayoutPanel
    $right.Dock = 'Fill'; $right.FlowDirection = 'TopDown'; $right.WrapContents = $false; $right.AutoScroll = $true; $right.BackColor = $C.Bg
    $body.Controls.Add($right, 1, 0)
    $st.Values = [ordered]@{}
    foreach ($k in (Get-ColorFormats $st.Color).Keys) {
        $row = New-Object System.Windows.Forms.FlowLayoutPanel
        $row.AutoSize = $true; $row.WrapContents = $false; $row.BackColor = $C.Bg; $row.Margin = New-Object System.Windows.Forms.Padding(0)
        $l = New-TbLabel $row $k -Dim; $l.AutoSize = $false; $l.Width = Px (70 * $TextZoom)
        $v = New-TbBox -Mono -ReadOnly; $v.Width = Px (300 * $TextZoom); $v.Margin = New-Object System.Windows.Forms.Padding(0, (Px 4), (Px 6), 0)
        $row.Controls.Add($v)
        $b = New-Button '' "Copy $k" { param($src, $e) Copy-TbText $src.Tag.Text } $row $Glyph.Copy 2
        $b.Tag = $v
        $right.Controls.Add($row)
        $st.Values[$k] = $v
    }
    $st.Contrast = New-TbLabel $right '' -Dim
    $st.Shades = New-Object System.Windows.Forms.Panel
    $st.Shades.Size = New-Object System.Drawing.Size((Px (420 * $TextZoom)), (Px 40)); $st.Shades.Margin = New-Object System.Windows.Forms.Padding(0, (Px 10), 0, 0); $st.Shades.Cursor = 'Hand'
    $st.Shades.add_Paint({
        param($src, $e)
        $s = $TbUI.Pages['color'].State
        $w = $src.Width / 9
        for ($i = 0; $i -lt 9; $i++) {
            $cx = if ($i -lt 4) { [PowerClipTheme]::Mix($s.Color, [System.Drawing.Color]::White, (4 - $i) * 0.2) } elseif ($i -gt 4) { [PowerClipTheme]::Mix($s.Color, [System.Drawing.Color]::Black, ($i - 4) * 0.2) } else { $s.Color }
            $b = New-Object System.Drawing.SolidBrush $cx; $e.Graphics.FillRectangle($b, [float]($i * $w), 0, [float]($w + 1), $src.Height); $b.Dispose()
        }
        $pen = New-Object System.Drawing.Pen $C.Fore, 2; $e.Graphics.DrawRectangle($pen, [float](4 * $w), 1, [float]$w, ($src.Height - 2)); $pen.Dispose()
    })
    $st.Shades.add_MouseClick({
        param($src, $e)
        $s = $TbUI.Pages['color'].State
        $i = [int][Math]::Floor($e.X / ($src.Width / 9))
        $cx = if ($i -lt 4) { [PowerClipTheme]::Mix($s.Color, [System.Drawing.Color]::White, (4 - $i) * 0.2) } elseif ($i -gt 4) { [PowerClipTheme]::Mix($s.Color, [System.Drawing.Color]::Black, ($i - 4) * 0.2) } else { $s.Color }
        Set-ToolColor $s $cx
    })
    $tooltip.SetToolTip($st.Shades, 'Lighter and darker shades - click one to use it')
    $right.Controls.Add($st.Shades)
    New-TbLabel $right 'Recent' -Dim | Out-Null
    $st.HistoryPanel = New-Object System.Windows.Forms.Panel
    $st.HistoryPanel.Size = New-Object System.Drawing.Size((Px (420 * $TextZoom)), (Px 34)); $st.HistoryPanel.Cursor = 'Hand'
    $st.HistoryPanel.add_Paint({
        param($src, $e)
        $s = $TbUI.Pages['color'].State
        $e.Graphics.SmoothingMode = 'AntiAlias'
        for ($i = 0; $i -lt [Math]::Min(12, $s.History.Count); $i++) {
            $cx = ConvertFrom-ColorText $s.History[$i]
            if (-not $cx) { continue }
            $b = New-Object System.Drawing.SolidBrush $cx; $e.Graphics.FillEllipse($b, ($i * (Px 34) + (Px 2)), (Px 2), (Px 28), (Px 28)); $b.Dispose()
            $pen = New-Object System.Drawing.Pen $C.Line; $e.Graphics.DrawEllipse($pen, ($i * (Px 34) + (Px 2)), (Px 2), (Px 28), (Px 28)); $pen.Dispose()
        }
    })
    $st.HistoryPanel.add_MouseClick({
        param($src, $e)
        $s = $TbUI.Pages['color'].State
        $i = [int][Math]::Floor($e.X / (Px 34))
        if ($i -lt $s.History.Count) { Set-ToolColor $s (ConvertFrom-ColorText $s.History[$i]) -NoHistory }
    })
    $right.Controls.Add($st.HistoryPanel)

    $bar = New-TbBar $panel
    [void](New-Button 'Pick from screen' 'Click anywhere on the screen to take its colour (Esc cancels)' { Start-ScreenColorPick } $bar $Glyph.Color 1)
    New-TbLabel $bar 'or type a colour' -Dim | Out-Null
    $st.Input = New-TbBox -Mono -Cue '#1e90ff   rgb(30,144,255)   hsl(210,100%,56%)   DodgerBlue'
    $st.Input.Width = Px (340 * $TextZoom); $st.Input.Margin = New-Object System.Windows.Forms.Padding(0, (Px 4), (Px 6), 0)
    $bar.Controls.Add($st.Input)
    $st.Input.add_TextChanged({
        $s = $TbUI.Pages['color'].State
        $cx = ConvertFrom-ColorText $s.Input.Text
        if ($cx) { Set-ToolColor $s $cx -NoHistory -KeepInput } elseif ($s.Input.Text.Trim()) { Set-TbStatus $s.Status 'Not a colour I understand (try #rrggbb, rgb(...), hsl(...) or a name)' 'warn' }
    })
    $st.SetInput = { param($t) $TbUI.Pages['color'].State.Input.Text = $t.Trim() }
    $st.Focus = { $TbUI.Pages['color'].State.Input.Focus() }
    Set-ToolColor $st $st.Color -NoHistory
    $st
}

function Set-ToolColor($St, $Col, [switch]$NoHistory, [switch]$KeepInput) {
    if (-not $Col) { return }
    $St.Color = [System.Drawing.Color]::FromArgb(255, $Col.R, $Col.G, $Col.B)
    $fmt = Get-ColorFormats $St.Color
    foreach ($k in $fmt.Keys) { $St.Values[$k].Text = $fmt[$k] }
    $cw = Get-Contrast $St.Color ([System.Drawing.Color]::White); $cb = Get-Contrast $St.Color ([System.Drawing.Color]::Black)
    $grade = { param($r) if ($r -ge 7) { 'AAA' } elseif ($r -ge 4.5) { 'AA' } elseif ($r -ge 3) { 'AA large text' } else { 'fails' } }
    $St.Contrast.Text = "Contrast with white text {0:N1}:1 ({1})   $Dot   with black text {2:N1}:1 ({3})" -f $cw, (& $grade $cw), $cb, (& $grade $cb)
    if (-not $NoHistory) {
        [void]$St.History.Remove($fmt.HEX); $St.History.Insert(0, $fmt.HEX)
        while ($St.History.Count -gt 24) { $St.History.RemoveAt($St.History.Count - 1) }
        try { Write-JsonFile $ColorsFile (ConvertTo-Json -InputObject $St.History.ToArray()) } catch { }
    }
    $St.Swatch.Invalidate(); $St.Shades.Invalidate(); $St.HistoryPanel.Invalidate()
    Set-TbStatus $St.Status "$($fmt.HEX)  $Dot  $($fmt.RGB)  $Dot  $($fmt.HSL)" 'ok'
}

# Full-screen eyedropper: shows a frozen screenshot with a magnifier; click to pick, Esc to cancel.
function Start-ScreenColorPick {
    $vs = [System.Windows.Forms.SystemInformation]::VirtualScreen
    $shot = New-Object System.Drawing.Bitmap $vs.Width, $vs.Height
    $g = [System.Drawing.Graphics]::FromImage($shot); $g.CopyFromScreen($vs.Left, $vs.Top, 0, 0, $shot.Size); $g.Dispose()
    if ($TbUI.Form) { $TbUI.Form.Hide() }
    Start-Sleep -Milliseconds 120
    $pf = New-Object System.Windows.Forms.Form
    $pf.FormBorderStyle = 'None'; $pf.StartPosition = 'Manual'; $pf.Bounds = $vs; $pf.TopMost = $true; $pf.ShowInTaskbar = $false
    $pf.Cursor = [System.Windows.Forms.Cursors]::Cross; $pf.KeyPreview = $true
    $pf.Tag = @{ Shot = $shot; Pos = [System.Windows.Forms.Cursor]::Position; Origin = $vs.Location }
    $pf.GetType().GetProperty('DoubleBuffered', [Reflection.BindingFlags]'Instance, NonPublic').SetValue($pf, $true, $null)
    $pf.add_Paint({
        param($src, $e)
        $t = $src.Tag
        $gg = $e.Graphics
        $gg.DrawImageUnscaled($t.Shot, 0, 0)
        $px = $t.Pos.X - $t.Origin.X; $py = $t.Pos.Y - $t.Origin.Y
        $zoom = 12; $n = 11; $size = $zoom * $n
        $lx = $px + 24; $ly = $py + 24
        if ($lx + $size + 8 -gt $src.Width) { $lx = $px - $size - 24 }
        if ($ly + $size + 40 -gt $src.Height) { $ly = $py - $size - 56 }
        $gg.InterpolationMode = 'NearestNeighbor'; $gg.PixelOffsetMode = 'Half'
        $srcRect = New-Object System.Drawing.Rectangle(($px - 5), ($py - 5), $n, $n)
        $gg.FillRectangle([System.Drawing.Brushes]::Black, ($lx - 2), ($ly - 2), ($size + 4), ($size + 34))
        $gg.DrawImage($t.Shot, (New-Object System.Drawing.Rectangle($lx, $ly, $size, $size)), $srcRect, [System.Drawing.GraphicsUnit]::Pixel)
        $gg.DrawRectangle([System.Drawing.Pens]::White, ($lx + 5 * $zoom), ($ly + 5 * $zoom), $zoom, $zoom)
        $col = if ($px -ge 0 -and $py -ge 0 -and $px -lt $t.Shot.Width -and $py -lt $t.Shot.Height) { $t.Shot.GetPixel($px, $py) } else { [System.Drawing.Color]::Black }
        $hex = '#{0:X2}{1:X2}{2:X2}' -f $col.R, $col.G, $col.B
        $b = New-Object System.Drawing.SolidBrush $col; $gg.FillRectangle($b, $lx, ($ly + $size + 4), 26, 26); $b.Dispose()
        $font = New-Object System.Drawing.Font($UiFont, 10, [System.Drawing.FontStyle]::Bold)
        $gg.DrawString($hex, $font, [System.Drawing.Brushes]::White, ($lx + 32), ($ly + $size + 7)); $font.Dispose()
    })
    $pf.add_MouseMove({ param($src, $e) $src.Tag.Pos = [System.Windows.Forms.Cursor]::Position; $src.Invalidate() })
    $pf.add_MouseUp({ param($src, $e) Complete-ScreenColorPick $src ($e.Button -eq 'Left') })
    $pf.add_KeyDown({
        param($src, $e)
        $t = $src.Tag
        switch ($e.KeyCode) {
            'Escape' { Complete-ScreenColorPick $src $false; return }
            'Return' { Complete-ScreenColorPick $src $true; return }
            'Left'  { [System.Windows.Forms.Cursor]::Position = New-Object System.Drawing.Point(($t.Pos.X - 1), $t.Pos.Y) }
            'Right' { [System.Windows.Forms.Cursor]::Position = New-Object System.Drawing.Point(($t.Pos.X + 1), $t.Pos.Y) }
            'Up'    { [System.Windows.Forms.Cursor]::Position = New-Object System.Drawing.Point($t.Pos.X, ($t.Pos.Y - 1)) }
            'Down'  { [System.Windows.Forms.Cursor]::Position = New-Object System.Drawing.Point($t.Pos.X, ($t.Pos.Y + 1)) }
        }
        $t.Pos = [System.Windows.Forms.Cursor]::Position; $src.Invalidate()
    })
    $pf.Show()
    $pf.Activate()
}

function Complete-ScreenColorPick($Form, [bool]$Pick) {
    $t = $Form.Tag
    if ($t.Finished) { return }
    $t.Finished = $true
    $col = $null
    if ($Pick) {
        $px = $t.Pos.X - $t.Origin.X; $py = $t.Pos.Y - $t.Origin.Y
        if ($px -ge 0 -and $py -ge 0 -and $px -lt $t.Shot.Width -and $py -lt $t.Shot.Height) { $col = $t.Shot.GetPixel($px, $py) }
    }
    $Form.Close(); $t.Shot.Dispose()
    Show-Toolbox 'color'
    if ($col) { Set-ToolColor $TbUI.Pages['color'].State $col; Copy-TbText ('#{0:X2}{1:X2}{2:X2}' -f $col.R, $col.G, $col.B) }
}

# ======================================================================================
# File hash: MD5 / SHA-1 / SHA-256 / SHA-512, compare with an expected value.
# ======================================================================================
Register-ToolboxPage 'hash' 'File hash' $Glyph.Document 'hash checksum md5 sha1 sha256 sha512 file verify download' {
    param($panel, $st)
    foreach ($kv in (@{ Job = $null }).GetEnumerator()) { $st[$kv.Key] = $kv.Value }
    $st.Status = New-TbPage $panel
    $panel.AllowDrop = $true
    $body = New-Object System.Windows.Forms.FlowLayoutPanel
    $body.Dock = 'Fill'; $body.FlowDirection = 'TopDown'; $body.WrapContents = $false; $body.BackColor = $C.Bg; $body.AllowDrop = $true
    $panel.Controls.Add($body)
    $drop = New-Object System.Windows.Forms.Label
    $drop.AutoSize = $false; $drop.Size = New-Object System.Drawing.Size((Px (760 * $TextZoom)), (Px 90)); $drop.TextAlign = 'MiddleCenter'
    $drop.Text = 'Drop a file here, or click to choose one'; $drop.ForeColor = $C.Dim; $drop.BackColor = $C.Card; $drop.Cursor = 'Hand'; $drop.AllowDrop = $true
    $drop.add_Paint({ param($src, $e) $pen = New-Object System.Drawing.Pen $C.Line; $pen.DashStyle = 'Dash'; $e.Graphics.DrawRectangle($pen, 0, 0, ($src.Width - 1), ($src.Height - 1)); $pen.Dispose() })
    $drop.add_Click({ $d = New-Object System.Windows.Forms.OpenFileDialog; $d.Title = 'File to hash'; if ($d.ShowDialog($TbUI.Form) -eq 'OK') { Start-FileHashJob $TbUI.Pages['hash'].State $d.FileName }; $d.Dispose() })
    $body.Controls.Add($drop)
    $st.Drop = $drop
    $st.File = New-TbLabel $body '' -Title
    $st.Progress = New-Object System.Windows.Forms.ProgressBar
    $st.Progress.Width = Px (760 * $TextZoom); $st.Progress.Height = Px 8; $st.Progress.Visible = $false
    $body.Controls.Add($st.Progress)
    $st.Rows = [ordered]@{}
    foreach ($k in 'MD5', 'SHA-1', 'SHA-256', 'SHA-512') {
        $row = New-Object System.Windows.Forms.FlowLayoutPanel
        $row.AutoSize = $true; $row.WrapContents = $false; $row.BackColor = $C.Bg
        $l = New-TbLabel $row $k -Dim; $l.AutoSize = $false; $l.Width = Px (80 * $TextZoom)
        $v = New-TbBox -Mono -ReadOnly; $v.Width = Px (640 * $TextZoom); $v.Margin = New-Object System.Windows.Forms.Padding(0, (Px 4), (Px 6), 0)
        $row.Controls.Add($v)
        $b = New-Button '' "Copy $k" { param($src, $e) Copy-TbText $src.Tag.Text } $row $Glyph.Copy 2
        $b.Tag = $v
        $body.Controls.Add($row)
        $st.Rows[$k] = $v
    }
    $cmp = New-Object System.Windows.Forms.FlowLayoutPanel
    $cmp.AutoSize = $true; $cmp.WrapContents = $false; $cmp.BackColor = $C.Bg; $cmp.Margin = New-Object System.Windows.Forms.Padding(0, (Px 14), 0, 0)
    $l = New-TbLabel $cmp 'Expected' -Dim; $l.AutoSize = $false; $l.Width = Px (80 * $TextZoom)
    $st.Expected = New-TbBox -Mono -Cue 'paste the checksum from the download page to compare'
    $st.Expected.Width = Px (640 * $TextZoom); $st.Expected.Margin = New-Object System.Windows.Forms.Padding(0, (Px 4), (Px 6), 0)
    $cmp.Controls.Add($st.Expected)
    $body.Controls.Add($cmp)
    $st.Verdict = New-TbLabel $body '' -Title
    $st.Expected.add_TextChanged({ Update-HashVerdict $TbUI.Pages['hash'].State })
    $dragEnter = { param($src, $e) $e.Effect = if ($e.Data.GetDataPresent([System.Windows.Forms.DataFormats]::FileDrop)) { 'Copy' } else { 'None' } }
    $dragDrop = { param($src, $e) $f = @($e.Data.GetData([System.Windows.Forms.DataFormats]::FileDrop))[0]; if ($f -and (Test-Path -LiteralPath $f -PathType Leaf)) { Start-FileHashJob $TbUI.Pages['hash'].State $f } }
    foreach ($cx in $panel, $body, $drop) { $cx.add_DragEnter($dragEnter); $cx.add_DragDrop($dragDrop) }
    $st.Timer = New-Object System.Windows.Forms.Timer
    $st.Timer.Interval = 100
    $st.Timer.add_Tick({ Update-FileHashJob $TbUI.Pages['hash'].State })
    $st.SetInput = { param($t) $s = $TbUI.Pages['hash'].State; $t = $t.Trim().Trim('"'); if (Test-Path -LiteralPath $t -PathType Leaf) { Start-FileHashJob $s $t } else { $s.Expected.Text = $t } }
    $st.Close = { $s = $TbUI.Pages['hash'].State; $s.Timer.Stop(); $s.Timer.Dispose(); if ($s.Job) { $s.Job.Cancel = $true } }
    Set-TbStatus $st.Status 'All four hashes are computed in one pass. Big files are fine; it runs in the background.'
    $st
}

function Start-FileHashJob($St, [string]$Path) {
    if ($St.Job -and -not $St.Job.Done) { $St.Job.Cancel = $true }
    foreach ($v in $St.Rows.Values) { $v.Text = '' }
    $St.File.Text = $Path
    $St.Progress.Value = 0; $St.Progress.Visible = $true
    $St.Job = [DevFileHash]::Start($Path)
    $St.Timer.Start()
    Set-TbStatus $St.Status 'Hashing...'
}

function Update-FileHashJob($St) {
    $j = $St.Job
    if (-not $j) { $St.Timer.Stop(); return }
    if ($j.Size -gt 0) { $St.Progress.Value = [int][Math]::Min(100, $j.Read * 100 / $j.Size) }
    if (-not $j.Done) { return }
    $St.Timer.Stop(); $St.Progress.Visible = $false
    if ($j.Error) { Set-TbStatus $St.Status $j.Error 'error'; return }
    $St.Rows['MD5'].Text = $j.Md5; $St.Rows['SHA-1'].Text = $j.Sha1; $St.Rows['SHA-256'].Text = $j.Sha256; $St.Rows['SHA-512'].Text = $j.Sha512
    $St.File.Text = "$($j.Path)   ($(Format-Size $j.Size))"
    Set-TbStatus $St.Status 'Done' 'ok'
    Update-HashVerdict $St
}

function Update-HashVerdict($St) {
    $want = ($St.Expected.Text -replace '[\s:-]', '').ToLower()
    foreach ($v in $St.Rows.Values) { $v.BackColor = $C.Card }
    if (-not $want) { $St.Verdict.Text = ''; return }
    $hit = $null
    foreach ($k in $St.Rows.Keys) { if ($St.Rows[$k].Text -and $St.Rows[$k].Text -eq $want) { $hit = $k } }
    if ($hit) { $St.Rows[$hit].BackColor = [PowerClipTheme]::Mix($C.Bg, $C.Green, 0.25); $St.Verdict.Text = "Match: the $hit is identical."; $St.Verdict.ForeColor = $C.Green }
    elseif (($St.Rows.Values | Where-Object { $_.Text }).Count -eq 0) { $St.Verdict.Text = 'Choose a file to compare.'; $St.Verdict.ForeColor = $C.Dim }
    else { $St.Verdict.Text = 'No match - the file is different (or the checksum is for another file).'; $St.Verdict.ForeColor = $C.Red }
}

# ======================================================================================
# Ports: what is listening / connected, with the process behind it.
# ======================================================================================
Register-ToolboxPage 'ports' 'Ports' $Glyph.Network 'ports listening netstat process kill tcp udp who uses port' {
    param($panel, $st)
    foreach ($kv in (@{ Rows = @() }).GetEnumerator()) { $st[$kv.Key] = $kv.Value }
    $st.Status = New-TbPage $panel
    $lv = New-Object System.Windows.Forms.ListView
    $lv.Dock = 'Fill'; $lv.View = 'Details'; $lv.FullRowSelect = $true; $lv.BorderStyle = 'None'; $lv.HideSelection = $false
    $lv.BackColor = $C.Bg; $lv.ForeColor = $C.Fore
    foreach ($col in @(@('Proto', 70), @('Local address', 170), @('Port', 70), @('Remote', 210), @('State', 120), @('PID', 70), @('Process', 200))) { [void]$lv.Columns.Add($col[0], (Px ($col[1] * $TextZoom))) }
    $lv.add_ColumnClick({ param($src, $e) $s = $TbUI.Pages['ports'].State; $s.SortCol = $e.Column; $s.SortDesc = -not $s.SortDesc; Update-PortsList $s })
    $panel.Controls.Add($lv)
    $st.List = $lv
    $menu = New-Object System.Windows.Forms.ContextMenuStrip -Property @{ Renderer = $MenuRenderer }
    [void](Add-MenuItem $menu 'Copy row' { $s = $TbUI.Pages['ports'].State; if ($s.List.SelectedItems.Count) { $it = $s.List.SelectedItems[0]; Copy-TbText (($it.SubItems | ForEach-Object { $_.Text }) -join "`t") } } $Glyph.Copy)
    [void](Add-MenuItem $menu 'Show the program file' { $s = $TbUI.Pages['ports'].State; if ($s.List.SelectedItems.Count) { $p = Get-Process -Id ([int]$s.List.SelectedItems[0].SubItems[5].Text) -ErrorAction SilentlyContinue; if ($p -and $p.Path) { Start-Process explorer.exe "/select,`"$($p.Path)`"" } } } $Glyph.Open)
    [void](Add-MenuItem $menu 'Test this port in Network tools' { $s = $TbUI.Pages['ports'].State; if ($s.List.SelectedItems.Count) { $it = $s.List.SelectedItems[0]; $st2 = Show-Network '127.0.0.1'; if ($st2 -and $st2.PortBox) { $st2.PortBox.Text = $it.SubItems[2].Text } } } $Glyph.Network)
    [void]$menu.Items.Add('-')
    [void](Add-MenuItem $menu 'End this process...' {
        $s = $TbUI.Pages['ports'].State
        if (-not $s.List.SelectedItems.Count) { return }
        $it = $s.List.SelectedItems[0]
        $procId = [int]$it.SubItems[5].Text; $name = $it.SubItems[6].Text
        if ($procId -le 4) { [void][System.Windows.Forms.MessageBox]::Show($TbUI.Form, 'That is a Windows system process.', 'Ports'); return }
        if ([System.Windows.Forms.MessageBox]::Show($TbUI.Form, "End $name (PID $procId)? Unsaved work in it is lost.", 'Ports', 'YesNo', 'Warning') -ne 'Yes') { return }
        try { Stop-Process -Id $procId -Force -ErrorAction Stop; Set-TbStatus $s.Status "Ended $name ($procId)." 'ok' } catch { Set-TbStatus $s.Status "Could not end it: $($_.Exception.Message) (try running DevTools as administrator)" 'error' }
        Start-Sleep -Milliseconds 300
        Update-PortsList $s -Reload
    } $Glyph.Delete)
    $lv.ContextMenuStrip = $menu
    $bar = New-TbBar $panel
    New-TbLabel $bar 'Filter' -Dim | Out-Null
    $st.Filter = New-TbBox -Cue 'port, process or address  (e.g. 8080, node, 443)'
    $st.Filter.Width = Px (300 * $TextZoom); $st.Filter.Margin = New-Object System.Windows.Forms.Padding(0, (Px 4), (Px 8), 0)
    $bar.Controls.Add($st.Filter)
    $st.Listening = New-CheckBox $bar 'Listening only' $true 'Hide outgoing connections'
    [void](New-Button 'Refresh' 'Read the port table again (F5)' { Update-PortsList $TbUI.Pages['ports'].State -Reload } $bar $Glyph.Refresh 1)
    $st.Filter.add_TextChanged({ Update-PortsList $TbUI.Pages['ports'].State })
    $st.Listening.add_CheckedChanged({ Update-PortsList $TbUI.Pages['ports'].State })
    $st.SetInput = { param($t) $s = $TbUI.Pages['ports'].State; $s.Filter.Text = $t.Trim(); Update-PortsList $s -Reload }
    $st.Focus = { $s = $TbUI.Pages['ports'].State; Update-PortsList $s -Reload; $s.Filter.Focus() }
    $st.SortCol = 2; $st.SortDesc = $false
    $st
}

function Update-PortsList($St, [switch]$Reload) {
    if ($Reload -or -not $St.Rows) {
        $names = @{}
        foreach ($p in Get-Process) { $names[$p.Id] = $p.ProcessName }
        $St.Rows = foreach ($e in [DevPorts]::List()) {
            [pscustomobject]@{ Proto = $e.Proto; Local = $e.LocalAddress; Port = $e.LocalPort; Remote = $(if ($e.RemoteAddress -and $e.RemotePort) { "$($e.RemoteAddress):$($e.RemotePort)" } else { '' })
                               State = $e.State; Pid = $e.Pid; Process = $(if ($names.ContainsKey($e.Pid)) { $names[$e.Pid] } elseif ($e.Pid -eq 4) { 'System' } else { '?' }) }
        }
        $St.Loaded = Get-Date
    }
    $q = $St.Filter.Text.Trim()
    $rows = @($St.Rows | Where-Object {
        (-not $St.Listening.Checked -or $_.State -eq 'LISTENING' -or $_.Proto -like 'UDP*') -and
        (-not $q -or [string]$_.Port -eq $q -or $_.Process -like "*$q*" -or $_.Local -like "*$q*" -or $_.Remote -like "*$q*" -or [string]$_.Pid -eq $q)
    })
    $prop = @('Proto', 'Local', 'Port', 'Remote', 'State', 'Pid', 'Process')[$St.SortCol]
    $rows = @($rows | Sort-Object -Property @{ Expression = $prop; Descending = [bool]$St.SortDesc }, Port)
    $lv = $St.List
    $lv.BeginUpdate(); $lv.Items.Clear()
    foreach ($r in $rows | Select-Object -First 2000) {
        $it = New-Object System.Windows.Forms.ListViewItem($r.Proto)
        foreach ($v in $r.Local, $r.Port, $r.Remote, $r.State, $r.Pid, $r.Process) { [void]$it.SubItems.Add([string]$v) }
        [void]$lv.Items.Add($it)
    }
    $lv.EndUpdate()
    Set-TbStatus $St.Status "$($rows.Count) shown of $(@($St.Rows).Count)  $Dot  read at $($St.Loaded.ToString('HH:mm:ss'))  $Dot  right-click a row to end its process" $(if ($q -and $rows.Count -eq 0) { 'warn' } else { '' })
}

# ======================================================================================
# Certificates: TLS certificate of a server (expiry, names, chain, protocol).
# ======================================================================================
Register-ToolboxPage 'cert' 'Certificates' $Glyph.Lock 'ssl tls certificate https expiry expires chain san check' {
    param($panel, $st)
    foreach ($kv in (@{ Job = $null }).GetEnumerator()) { $st[$kv.Key] = $kv.Value }
    $st.Status = New-TbPage $panel
    $st.Out = New-TbRtb -ReadOnly; $st.Out.Dock = 'Fill'; $st.Out.WordWrap = $true
    $panel.Controls.Add($st.Out)
    $bar = New-TbBar $panel
    New-TbLabel $bar 'Host' -Title | Out-Null
    $st.HostBox = New-TbBox -Cue 'example.com  or  https://example.com:8443/path'
    $st.HostBox.Width = Px (340 * $TextZoom); $st.HostBox.Margin = New-Object System.Windows.Forms.Padding(0, (Px 4), (Px 8), 0)
    $bar.Controls.Add($st.HostBox)
    New-TbLabel $bar 'Port' -Dim | Out-Null
    $st.Port = New-TbNumber $bar 443 1 65535
    [void](New-Button 'Check' 'Connect and read the certificate (Enter)' { Start-CertCheck $TbUI.Pages['cert'].State } $bar $Glyph.Lock 1)
    $st.HostBox.add_KeyDown({ param($src, $e) if ($e.KeyCode -eq 'Return') { Start-CertCheck $TbUI.Pages['cert'].State; $e.SuppressKeyPress = $true } })
    $st.Timer = New-Object System.Windows.Forms.Timer
    $st.Timer.Interval = 150
    $st.Timer.add_Tick({ Update-CertCheck $TbUI.Pages['cert'].State })
    $st.SetInput = { param($t) $s = $TbUI.Pages['cert'].State; $s.HostBox.Text = $t.Trim(); Start-CertCheck $s }
    $st.Focus = { $TbUI.Pages['cert'].State.HostBox.Focus() }
    $st.Close = { $s = $TbUI.Pages['cert'].State; $s.Timer.Stop(); $s.Timer.Dispose() }
    Set-TbStatus $st.Status 'Only the TLS handshake is done; nothing else is sent to the server.'
    $st
}

function Start-CertCheck($St) {
    $t = $St.HostBox.Text.Trim()
    if (-not $t) { return }
    $port = [int]$St.Port.Value
    if ($t -match '^(?:[a-z]+://)?([^/:\s]+)(?::(\d+))?') {
        $h = $Matches[1]
        if ($Matches[2]) { $port = [int]$Matches[2]; $St.Port.Value = $port }
    } else { return }
    $St.Out.Clear()
    Add-RtbLine $St.Out "Connecting to $h`:$port ..." $C.Dim
    $St.Job = [DevCertCheck]::Start($h, $port, 8000)
    $St.Timer.Start()
    Set-TbStatus $St.Status 'Checking...'
}

function Update-CertCheck($St) {
    $j = $St.Job
    if (-not $j -or -not $j.Done) { return }
    $St.Timer.Stop()
    $o = $St.Out; $o.Clear()
    $cx = $j.Certificate
    if (-not $cx) { Add-RtbLine $o "Could not get a certificate from $($j.Host):$($j.Port)" $C.Red -Bold; Add-RtbLine $o $j.Error; Set-TbStatus $St.Status 'Failed' 'error'; return }
    $days = [Math]::Floor(($cx.NotAfter - (Get-Date)).TotalDays)
    $ok = -not $j.PolicyErrors -and $days -ge 0
    if ($days -lt 0) { Add-RtbLine $o "EXPIRED $(-$days) days ago" $C.Red -Bold }
    elseif ($j.PolicyErrors) { Add-RtbLine $o "PROBLEM: $($j.PolicyErrors)" $C.Red -Bold }
    elseif ($days -lt 21) { Add-RtbLine $o "Valid, but expires in $days days" $C.Yellow -Bold }
    else { Add-RtbLine $o "Valid  -  expires in $days days" $C.Green -Bold }
    Add-RtbLine $o ''
    $rows = [ordered]@{
        'Host'        = "$($j.Host):$($j.Port)"
        'Subject'     = $cx.Subject
        'Issuer'      = $cx.Issuer
        'Valid from'  = $cx.NotBefore.ToString('yyyy-MM-dd HH:mm')
        'Valid until' = "$($cx.NotAfter.ToString('yyyy-MM-dd HH:mm'))   ($days days)"
        'Names (SAN)' = ([DevCertCheck]::SubjectAltNames($cx) -join ', ')
        'Key'         = "$($cx.PublicKey.Oid.FriendlyName) $(try { $cx.PublicKey.Key.KeySize } catch { '' }) bit"
        'Signature'   = $cx.SignatureAlgorithm.FriendlyName
        'Serial'      = $cx.SerialNumber
        'SHA-1 thumbprint' = $cx.Thumbprint
        'Protocol'    = $j.Protocol
        'Cipher'      = $j.Cipher
        'Handshake'   = "$($j.ElapsedMs) ms"
    }
    foreach ($k in $rows.Keys) { if ($rows[$k]) { Add-RtbLine $o ("{0,-17} {1}" -f $k, $rows[$k]) } }
    if ($j.Error) { Add-RtbLine $o ''; Add-RtbLine $o "Note: $($j.Error)" $C.Yellow }
    Add-RtbLine $o ''
    Add-RtbLine $o 'CHAIN' $C.Accent -Bold
    $i = 0
    foreach ($el in $j.Chain) {
        Add-RtbLine $o ("{0}{1}" -f ('  ' * $i), $el[0]) $(if ($el[3]) { $C.Red } else { $null })
        Add-RtbLine $o ("{0}  until {1}{2}" -f ('  ' * $i), $el[2], $(if ($el[3]) { "  -  $($el[3])" } else { '' })) $C.Dim
        $i++
    }
    $o.SelectionStart = 0; $o.ScrollToCaret()
    Set-TbStatus $St.Status $(if ($ok) { "Certificate OK, $days days left" } else { 'Certificate has problems' }) $(if ($ok) { if ($days -lt 21) { 'warn' } else { 'ok' } } else { 'error' })
}

# ======================================================================================
# Host monitor: keeps an eye on servers (ping or TCP port) and tells you when one goes down.
# ======================================================================================
$HostsFile = Join-Path $DataDir 'hosts.json'
$HostMon = New-Object DevHostMonitor
$script:HostTargets = New-Object System.Collections.Generic.List[object]

function Import-MonitoredHosts {
    if (-not (Test-Path $HostsFile)) { return }
    try {
        foreach ($x in @(ConvertFrom-Json (Read-DataText $HostsFile))) {
            if (-not $x.Host) { continue }
            $t = New-Object DevHostTarget
            $t.Id = if ($x.Id) { [string]$x.Id } else { [guid]::NewGuid().ToString('N') }
            $t.Name = [string]$x.Name; $t.Host = [string]$x.Host; $t.Port = [int]$x.Port
            if ($x.SilencedUntil) { try { $script:HostSilence[$t.Id] = [datetime]::Parse([string]$x.SilencedUntil, $null, [Globalization.DateTimeStyles]::RoundtripKind) } catch { } }
            $script:HostTargets.Add($t)
        }
    } catch { Write-Log "hosts load failed: $_" }
}

# ---- Host alerts: a popup in the bottom-right corner for a few seconds; hosts can be silenced.
$script:HostSilence = @{}              # host id -> silenced until (DateTime.MaxValue = until turned back on)
$script:HostAlerts = New-Object System.Collections.Generic.List[object]

function Test-HostSilenced($T) {
    $u = $script:HostSilence[$T.Id]
    if (-not $u) { return $false }
    if ($u -le (Get-Date)) { $script:HostSilence.Remove($T.Id); Save-MonitoredHosts; return $false }
    $true
}

function Set-HostSilence($T, $Until) {
    if ($Until) { $script:HostSilence[$T.Id] = $Until } else { $script:HostSilence.Remove($T.Id) }
    Save-MonitoredHosts
    $p = $TbUI.Pages['hosts']; if ($p -and $p.State) { $p.State.List.Invalidate() }
}

function Get-HostSilenceText($T) {
    $u = $script:HostSilence[$T.Id]
    if (-not $u) { return '' }
    if ($u -eq [datetime]::MaxValue) { 'alerts off' } else { "silenced until $($u.ToString('HH:mm'))" }
}

# Moves the open alerts up from the bottom-right corner, newest at the bottom.
function Set-HostAlertPositions {
    $wa = [System.Windows.Forms.Screen]::PrimaryScreen.WorkingArea
    $y = $wa.Bottom - (Px 12)
    for ($i = $script:HostAlerts.Count - 1; $i -ge 0; $i--) {
        $f = $script:HostAlerts[$i]
        $y -= $f.Height
        $f.Location = New-Object System.Drawing.Point(($wa.Right - $f.Width - (Px 12)), $y)
        $y -= Px 8
    }
}

function Close-HostAlert($F) {
    if (-not $F -or $F.IsDisposed) { return }
    [void]$script:HostAlerts.Remove($F)
    $F.Tag.Timer.Dispose()
    $F.Close(); $F.Dispose()
    Set-HostAlertPositions
}

function Show-HostAlert($T, [bool]$Down) {
    $label = if ($T.Name) { $T.Name } else { $T.Host }
    $target = "$($T.Host)$(if ($T.Port) { ":$($T.Port)" } else { ' (ping)' })"
    $accent = if ($Down) { $C.Red } else { $C.Green }
    $f = New-Object PowerClipToast
    $f.BackColor = $C.Card; $f.ForeColor = $C.Fore; $f.Font = $FontMain
    $f.Size = New-Object System.Drawing.Size((Px 380), (Px 112))
    $f.Padding = New-Object System.Windows.Forms.Padding((Px 18), (Px 10), (Px 10), (Px 8))
    $title = New-Object System.Windows.Forms.Label
    $title.AutoSize = $false; $title.Dock = 'Top'; $title.Height = $FontTitle.Height + (Px 4)
    $title.Font = New-Object System.Drawing.Font($UiFont, (Fz 11), [System.Drawing.FontStyle]::Bold); $title.ForeColor = $accent
    $title.Text = if ($Down) { "$label is DOWN" } else { "$label is back up" }
    $body = New-Object System.Windows.Forms.Label
    $body.AutoSize = $false; $body.Dock = 'Top'; $body.Font = $FontSmall; $body.ForeColor = $C.Dim
    $body.Text = if ($Down) { "$target - $($T.Detail)`n$((Get-Date).ToString('HH:mm:ss'))" } else { "$target answers again ($($T.LatencyMs) ms)`n$((Get-Date).ToString('HH:mm:ss'))" }
    $bodyW = (Px 380) - (Px 28)
    $body.Height = [System.Windows.Forms.TextRenderer]::MeasureText($body.Text, $FontSmall, (New-Object System.Drawing.Size($bodyW, 0)), [System.Windows.Forms.TextFormatFlags]'WordBreak').Height + (Px 6)
    $btns = New-Object System.Windows.Forms.FlowLayoutPanel
    $btns.Dock = 'Bottom'; $btns.Height = $FontButton.Height + (Px 12); $btns.WrapContents = $false; $btns.BackColor = $C.Card
    $btns.Margin = New-Object System.Windows.Forms.Padding(0)
    $f.Controls.AddRange(@($btns, $body, $title))      # docked from the last: title at the top, buttons at the bottom
    $ctx = @{ Host = $T; Timer = $null; Left = 9000 }
    $f.Tag = $ctx
    $mk = {
        param($text, $tip, $action, $variant)
        $b = New-Button $text $tip $action $btns '' $variant
        $b.Margin = New-Object System.Windows.Forms.Padding(0, 0, (Px 4), 0)
        $b.Tag = $f
        $b
    }
    [void](& $mk 'Silence 1 hour' 'No alerts for this host for an hour' { param($src, $e) $x = $src.Tag; Set-HostSilence $x.Tag.Host ((Get-Date).AddHours(1)); Close-HostAlert $x } 2)
    [void](& $mk 'Silence' 'No more alerts for this host until you turn them back on (Host monitor, right-click)' { param($src, $e) $x = $src.Tag; Set-HostSilence $x.Tag.Host ([datetime]::MaxValue); Close-HostAlert $x } 2)
    [void](& $mk 'Open' 'Open the host monitor' { param($src, $e) $x = $src.Tag; Close-HostAlert $x; Show-Toolbox 'hosts' } 2)
    [void](& $mk 'Close' '' { param($src, $e) Close-HostAlert $src.Tag } 2)
    # tall enough for the title, the text and the buttons (nothing cut off)
    $bh = 0; foreach ($bb in $btns.Controls) { $bh = [Math]::Max($bh, $bb.PreferredSize.Height + $bb.Margin.Vertical) }
    $btns.Height = $bh + (Px 2)
    $f.ClientSize = New-Object System.Drawing.Size($f.ClientSize.Width, ($f.Padding.Top + $title.Height + $body.Height + (Px 6) + $btns.Height + $f.Padding.Bottom))
    $f.add_Paint({
        param($src, $e)
        $b = New-Object System.Drawing.SolidBrush $(if ($src.Tag.Down) { $C.Red } else { $C.Green })
        $e.Graphics.FillRectangle($b, 0, 0, (Px 6), $src.Height); $b.Dispose()
        $p = New-Object System.Drawing.Pen $C.Line; $e.Graphics.DrawRectangle($p, 0, 0, ($src.Width - 1), ($src.Height - 1)); $p.Dispose()
    })
    $ctx.Down = $Down
    # closes by itself after a few seconds; pointing at it keeps it open
    $tm = New-Object System.Windows.Forms.Timer
    $tm.Interval = 250
    $tm.Tag = $f
    $tm.add_Tick({
        param($src, $e)
        $x = $src.Tag
        if (-not $x -or $x.IsDisposed) { $src.Stop(); return }
        if ($x.Bounds.Contains([System.Windows.Forms.Cursor]::Position)) { return }
        $x.Tag.Left -= $src.Interval
        if ($x.Tag.Left -le 0) { $src.Stop(); Close-HostAlert $x }
    })
    $ctx.Timer = $tm
    # one alert per host: a newer one replaces the older
    foreach ($old in @($script:HostAlerts.ToArray())) { if ($old.Tag.Host.Id -eq $T.Id) { Close-HostAlert $old } }
    $script:HostAlerts.Add($f)
    while ($script:HostAlerts.Count -gt 5) { Close-HostAlert $script:HostAlerts[0] }
    Set-HostAlertPositions
    $f.Show()
    $tm.Start()
    if ($Down) { [System.Media.SystemSounds]::Exclamation.Play() }
    $f
}

function Save-MonitoredHosts {
    if ($script:NoSave) { return }
    $json = ConvertTo-Json -InputObject @($script:HostTargets | ForEach-Object {
        $u = $script:HostSilence[$_.Id]
        [ordered]@{ Id = $_.Id; Name = $_.Name; Host = $_.Host; Port = $_.Port; SilencedUntil = $(if ($u) { $u.ToString('o') } else { $null }) } }) -Depth 3
    try { Write-JsonFile $HostsFile $json } catch { Write-Log "hosts save failed: $_" }
}

function Sync-HostMonitor {
    $list = New-Object 'System.Collections.Generic.List[DevHostTarget]'
    foreach ($t in $script:HostTargets) { $list.Add($t) }
    $HostMon.IntervalSec = $script:HostInterval
    $HostMon.Set($list)
    if ($list.Count -gt 0) { $HostMon.Start() } else { $HostMon.Stop() }
}

Import-MonitoredHosts
Sync-HostMonitor

# Watches for hosts going down / coming back, and refreshes the page.
$HostWatch = New-Object System.Windows.Forms.Timer
$HostWatch.Interval = 1500
$HostWatch.add_Tick({
    foreach ($t in $HostMon.TakeChanges()) {
        $label = if ($t.Name) { $t.Name } else { $t.Host }
        Write-Log "host $label is $($t.Status)"
        if ($script:HostNotify -and -not (Test-HostSilenced $t)) {
            try { [void](Show-HostAlert $t ($t.Status -eq 'down')) } catch { Write-Log "host alert failed: $_" }
        }
    }
    $p = $TbUI.Pages['hosts']
    if ($p -and $p.State -and $p.Panel.Visible) {
        # redraw only the rows whose state changed since the last look
        $l = $p.State.List
        if (-not $p.State.Sig) { $p.State.Sig = @{} }
        for ($i = 0; $i -lt $script:HostTargets.Count -and $i -lt $l.Items.Count; $i++) {
            $t = $script:HostTargets[$i]
            $sig = "$($t.Status)|$($t.LatencyMs)|$($t.LastCheck.Ticks)|$($t.Recent.Count)|$(Get-HostSilenceText $t)"
            if ($p.State.Sig[$t.Id] -ne $sig) { $p.State.Sig[$t.Id] = $sig; $l.Invalidate($l.GetItemRectangle($i)) }
        }
    }
})
$HostWatch.Start()

function Show-HostDialog($Target) {
    $d = New-Object System.Windows.Forms.Form
    $d.Text = $(if ($Target) { 'Edit host' } else { 'Add host' }); $d.FormBorderStyle = 'FixedDialog'; $d.MaximizeBox = $false; $d.MinimizeBox = $false
    $d.StartPosition = 'CenterParent'; $d.ShowInTaskbar = $false; $d.BackColor = $C.Panel; $d.ForeColor = $C.Fore; $d.Font = $FontMain
    $d.ClientSize = New-Object System.Drawing.Size((Px (440 * $TextZoom)), ($FontMain.Height * 3 + (Px 150)))
    $tbl = New-Object System.Windows.Forms.TableLayoutPanel
    $tbl.Dock = 'Fill'; $tbl.ColumnCount = 2; $tbl.Padding = New-Object System.Windows.Forms.Padding((Px 14))
    [void]$tbl.ColumnStyles.Add((New-Object System.Windows.Forms.ColumnStyle('AutoSize')))
    [void]$tbl.ColumnStyles.Add((New-Object System.Windows.Forms.ColumnStyle('Percent', 100)))
    $boxes = @{}
    $r = 0
    foreach ($f in @(@('Name', 'e.g. Web server'), @('Host', 'server name or IP'), @('Port', '0 = ping; or a TCP port like 443'))) {
        $l = New-Object System.Windows.Forms.Label; $l.Text = $f[0]; $l.AutoSize = $true; $l.Margin = New-Object System.Windows.Forms.Padding(0, (Px 8), (Px 10), 0)
        $b = New-TbBox -Cue $f[1]; $b.Dock = 'Fill'; $b.Margin = New-Object System.Windows.Forms.Padding(0, (Px 4), 0, (Px 4))
        $tbl.Controls.Add($l, 0, $r); $tbl.Controls.Add($b, 1, $r); $boxes[$f[0]] = $b; $r++
    }
    if ($Target) { $boxes.Name.Text = $Target.Name; $boxes.Host.Text = $Target.Host; $boxes.Port.Text = [string]$Target.Port } else { $boxes.Port.Text = '0' }
    $btns = New-Object System.Windows.Forms.FlowLayoutPanel
    $btns.FlowDirection = 'RightToLeft'; $btns.Dock = 'Fill'
    $cancel = New-Object PowerClipButton; $cancel.Text = 'Cancel'; $cancel.Font = $FontButton; $cancel.AutoSize = $true; $cancel.DialogResult = 'Cancel'
    $ok = New-Object PowerClipButton; $ok.Text = 'Save'; $ok.Variant = 1; $ok.Font = $FontButton; $ok.AutoSize = $true; $ok.DialogResult = 'OK'
    $btns.Controls.AddRange(@($cancel, $ok))
    $tbl.Controls.Add($btns, 1, $r)
    $d.Controls.Add($tbl)
    $d.AcceptButton = $ok; $d.CancelButton = $cancel
    Register-ThemedWindow $d
    $script:Modal = $true
    try { $res = $d.ShowDialog($TbUI.Form) } finally { $script:Modal = $false }
    $out = $null
    if ($res -eq 'OK' -and $boxes.Host.Text.Trim()) {
        $hostText = $boxes.Host.Text.Trim(); $port = 0
        if ($hostText -match '^(?:[a-z]+://)?([^/:\s]+)(?::(\d+))?') { $hostText = $Matches[1]; if ($Matches[2]) { $port = [int]$Matches[2] } }
        [int]::TryParse($boxes.Port.Text.Trim(), [ref]$port) | Out-Null
        $out = @{ Name = $boxes.Name.Text.Trim(); Host = $hostText; Port = [Math]::Max(0, [Math]::Min(65535, $port)) }
    }
    $d.Dispose()
    $out
}

Register-ToolboxPage 'hosts' 'Host monitor' $Glyph.Globe 'monitor uptime ping servers dashboard status up down' {
    param($panel, $st)
    $st.Status = New-TbPage $panel
    $list = New-Object DevBufferedListBox
    $list.Dock = 'Fill'; $list.BorderStyle = 'None'; $list.DrawMode = 'OwnerDrawFixed'; $list.IntegralHeight = $false
    $list.ItemHeight = $FontMain.Height + $FontSmall.Height + (Px 22); $list.BackColor = $C.Bg; $list.ForeColor = $C.Fore
    $list.add_DrawItem({
        param($src, $e)
        if ($e.Index -lt 0 -or $e.Index -ge $script:HostTargets.Count) { return }
        $t = $script:HostTargets[$e.Index]
        $g = $e.Graphics; $r = $e.Bounds
        $sel = ($e.State -band [System.Windows.Forms.DrawItemState]::Selected) -ne 0
        $b = New-Object System.Drawing.SolidBrush $(if ($sel) { $C.Sel } else { $C.Bg }); $g.FillRectangle($b, $r); $b.Dispose()
        $g.SmoothingMode = 'AntiAlias'
        $dotColor = switch ($t.Status) { 'up' { $C.Green } 'down' { $C.Red } default { $C.Dim } }
        $b = New-Object System.Drawing.SolidBrush $dotColor; $d = Px 12
        $g.FillEllipse($b, ($r.X + (Px 14)), ($r.Y + [int](($r.Height - $d) / 2)), $d, $d); $b.Dispose()
        $x = $r.X + (Px 38)
        $name = if ($t.Name) { $t.Name } else { $t.Host }
        $target = "$($t.Host)$(if ($t.Port) { ":$($t.Port)" } else { '  (ping)' })"
        [System.Windows.Forms.TextRenderer]::DrawText($g, $name, $FontMain, (New-Object System.Drawing.Rectangle($x, ($r.Y + (Px 6)), (Px 300), ($FontMain.Height + 2))), $C.Fore, $TextFlags)
        # latency + state text
        $state = switch ($t.Status) { 'up' { "$($t.LatencyMs) ms" } 'down' { "DOWN  $($t.Detail)" } default { 'checking...' } }
        $since = if ($t.LastChange -gt [datetime]::MinValue -and $t.Status -ne 'unknown') { "$(if ($t.Status -eq 'up') { 'up' } else { 'down' }) since $($t.LastChange.ToString('HH:mm'))" } else { '' }
        $mute = Get-HostSilenceText $t
        if ($mute) { $target += "   - $mute" }
        [System.Windows.Forms.TextRenderer]::DrawText($g, $target, $FontSmall, (New-Object System.Drawing.Rectangle($x, ($r.Y + (Px 8) + $FontMain.Height), (Px 300), ($FontSmall.Height + 2))), $(if ($mute) { $C.Yellow } else { $C.Dim }), $TextFlags)
        $sx = $r.X + (Px 350)
        [System.Windows.Forms.TextRenderer]::DrawText($g, $state, $FontMain, (New-Object System.Drawing.Rectangle($sx, ($r.Y + (Px 6)), (Px 220), ($FontMain.Height + 2))), $dotColor, $TextFlags)
        [System.Windows.Forms.TextRenderer]::DrawText($g, $since, $FontSmall, (New-Object System.Drawing.Rectangle($sx, ($r.Y + (Px 8) + $FontMain.Height), (Px 220), ($FontSmall.Height + 2))), $C.Dim, $TextFlags)
        # sparkline of recent latencies (red ticks = failures)
        $hist = @($t.Recent.ToArray())
        $gx = $r.X + (Px 590); $gw = [Math]::Max((Px 80), $r.Right - $gx - (Px 16)); $gy = $r.Y + (Px 8); $gh = $r.Height - (Px 16)
        if ($hist.Count -gt 1 -and $gw -gt 20) {
            $max = [Math]::Max(10, ($hist | Measure-Object -Maximum).Maximum)
            $step = $gw / 39.0
            $pts = New-Object System.Collections.Generic.List[System.Drawing.PointF]
            for ($i = 0; $i -lt $hist.Count; $i++) {
                $px = $gx + ($i + 40 - $hist.Count) * $step
                if ($hist[$i] -lt 0) { $pen = New-Object System.Drawing.Pen $C.Red, 2; $g.DrawLine($pen, [float]$px, [float]$gy, [float]$px, [float]($gy + $gh)); $pen.Dispose(); continue }
                $pts.Add((New-Object System.Drawing.PointF([float]$px, [float]($gy + $gh - $hist[$i] / $max * $gh))))
            }
            if ($pts.Count -gt 1) { $pen = New-Object System.Drawing.Pen $C.Accent, ([float](Px 2)); $g.DrawLines($pen, $pts.ToArray()); $pen.Dispose() }
        }
        $g.SmoothingMode = 'Default'
        $g.DrawLine($LinePen, $r.X, $r.Bottom - 1, $r.Right, $r.Bottom - 1)
    })
    $list.add_DoubleClick({ Edit-MonitoredHost })
    $hm = New-Object System.Windows.Forms.ContextMenuStrip -Property @{ Renderer = $MenuRenderer }
    $hm.add_Opening({
        param($src, $e)
        $src.Items.Clear()
        $i = $TbUI.Pages['hosts'].State.List.SelectedIndex
        if ($i -lt 0) { $e.Cancel = $true; return }
        $t = $script:HostTargets[$i]
        $src.Tag = $t
        if (Test-HostSilenced $t) { [void](Add-MenuItem $src "Turn alerts back on ($(Get-HostSilenceText $t))" { param($s2, $e2) Set-HostSilence $s2.Owner.Tag $null } $Glyph.Play) }
        else {
            [void](Add-MenuItem $src 'Silence for 1 hour' { param($s2, $e2) Set-HostSilence $s2.Owner.Tag ((Get-Date).AddHours(1)) } $Glyph.Pause)
            [void](Add-MenuItem $src 'Silence until tomorrow 8:00' { param($s2, $e2) Set-HostSilence $s2.Owner.Tag ((Get-Date).Date.AddDays(1).AddHours(8)) } $Glyph.Pause)
            [void](Add-MenuItem $src 'Silence (until I turn it back on)' { param($s2, $e2) Set-HostSilence $s2.Owner.Tag ([datetime]::MaxValue) } $Glyph.Pause)
        }
        [void](Add-MenuItem $src 'Show a test alert' { param($s2, $e2) [void](Show-HostAlert $s2.Owner.Tag ($s2.Owner.Tag.Status -ne 'up')) } $Glyph.View)
        [void]$src.Items.Add('-')
        [void](Add-MenuItem $src 'Edit...' { Edit-MonitoredHost } $Glyph.Edit)
    })
    $list.ContextMenuStrip = $hm
    $list.add_MouseDown({ param($src, $e) if ($e.Button -eq 'Right') { $i = $src.IndexFromPoint($e.Location); if ($i -ge 0) { $src.SelectedIndex = $i } } })
    $panel.Controls.Add($list)
    $st.List = $list
    $bar = New-TbBar $panel
    [void](New-Button 'Add' 'Add a server to watch' {
        $r = Show-HostDialog $null
        if (-not $r) { return }
        $t = New-Object DevHostTarget; $t.Id = [guid]::NewGuid().ToString('N'); $t.Name = $r.Name; $t.Host = $r.Host; $t.Port = $r.Port
        $script:HostTargets.Add($t); Save-MonitoredHosts; Sync-HostMonitor; Update-HostsPage
    } $bar $Glyph.Add 1)
    [void](New-Button 'Edit' 'Edit the selected server' { Edit-MonitoredHost } $bar $Glyph.Edit)
    [void](New-Button 'Remove' 'Stop watching the selected server' {
        $s = $TbUI.Pages['hosts'].State; $i = $s.List.SelectedIndex
        if ($i -lt 0) { return }
        $script:HostTargets.RemoveAt($i); Save-MonitoredHosts; Sync-HostMonitor; Update-HostsPage
    } $bar $Glyph.Delete)
    [void](New-Button 'Check now' 'Check every server right away' { $HostMon.CheckNow = $true } $bar $Glyph.Refresh 2)
    New-TbLabel $bar 'Every' -Dim | Out-Null
    $st.Every = New-TbCombo $bar @('10 seconds', '30 seconds', '1 minute', '5 minutes') 120
    $st.Every.SelectedIndex = switch ($script:HostInterval) { 10 { 0 } 60 { 2 } 300 { 3 } default { 1 } }
    $st.Every.add_SelectedIndexChanged({ param($src, $e) $script:HostInterval = @(10, 30, 60, 300)[$src.SelectedIndex]; Sync-HostMonitor; Save-Settings })
    $st.Notify = New-CheckBox $bar 'Alert me when one goes down or comes back (right-click a host to silence it)' $script:HostNotify
    $st.Notify.add_CheckedChanged({ param($src, $e) $script:HostNotify = $src.Checked; Save-Settings })
    $st.SetInput = { param($t) $r = $t.Trim(); if ($r) { $x = New-Object DevHostTarget; $x.Id = [guid]::NewGuid().ToString('N'); if ($r -match '^(?:[a-z]+://)?([^/:\s]+)(?::(\d+))?') { $x.Host = $Matches[1]; $x.Port = [int]$Matches[2] }; $script:HostTargets.Add($x); Save-MonitoredHosts; Sync-HostMonitor; Update-HostsPage } }
    Update-HostsPage $st
    $st
}

function Update-HostsPage($St = $null) {
    if (-not $St) { $St = $TbUI.Pages['hosts'].State }
    if (-not $St) { return }
    $l = $St.List
    $l.BeginUpdate(); $l.Items.Clear()
    foreach ($t in $script:HostTargets) { [void]$l.Items.Add($t.Host) }
    $l.EndUpdate()
    $n = $script:HostTargets.Count
    Set-TbStatus $St.Status $(if ($n) { "Watching $n server(s) in the background, also while this window is closed." } else { 'Add the servers you care about; they are checked in the background and you get a notification when one goes down.' })
}

function Edit-MonitoredHost {
    $s = $TbUI.Pages['hosts'].State; $i = $s.List.SelectedIndex
    if ($i -lt 0) { return }
    $t = $script:HostTargets[$i]
    $r = Show-HostDialog $t
    if (-not $r) { return }
    $t.Name = $r.Name; $t.Host = $r.Host; $t.Port = $r.Port; $t.Status = 'unknown'; $t.Recent.Clear()
    Save-MonitoredHosts; Sync-HostMonitor; Update-HostsPage
}

# ======================================================================================
# Number bases: decimal / hex / binary / octal, two's complement, bytes, as time / IP / colour.
# ======================================================================================
Register-ToolboxPage 'numbers' 'Number bases' $Glyph.Code 'number base convert hex binary octal decimal two complement bits bytes endian' {
    param($panel, $st)
    $st.Status = New-TbPage $panel
    $st.Output = New-TbRtb -ReadOnly; $st.Output.Dock = 'Fill'
    $st.Output.Font = New-Object System.Drawing.Font('Consolas', (Fz 12))
    $panel.Controls.Add($st.Output)
    $bar = New-TbBar $panel
    New-TbLabel $bar 'Number' -Dim | Out-Null
    $st.Input = New-TbBox -Mono -Cue '255   0xFF   0b1010   0o17   -1   #ff8800'
    $st.Input.Width = Px (320 * $TextZoom); $st.Input.Margin = New-Object System.Windows.Forms.Padding(0, (Px 4), (Px 8), 0)
    $st.Input.Font = New-Object System.Drawing.Font('Consolas', (Fz 12))
    $bar.Controls.Add($st.Input)
    New-TbLabel $bar 'is in' -Dim | Out-Null
    $st.Base = New-TbCombo $bar @('Auto (0x, 0b, 0o prefix)', 'Decimal', 'Hex', 'Binary', 'Octal') 190
    [void](New-Button 'Copy' 'Copy the selected line, or everything' {
        $s = $TbUI.Pages['numbers'].State
        $t = if ($s.Output.SelectionLength -gt 0) { $s.Output.SelectedText } else { $s.Output.Text }
        Copy-TbText $t
    } $bar $Glyph.Copy 1)
    $st.Input.add_TextChanged({ Update-NumberTool $TbUI.Pages['numbers'].State })
    $st.Base.add_SelectedIndexChanged({ Update-NumberTool $TbUI.Pages['numbers'].State })
    $st.SetInput = { param($t) $s = $TbUI.Pages['numbers'].State; $s.Input.Text = $t.Trim() }
    $st.Focus = { $TbUI.Pages['numbers'].State.Input.Focus() }
    Set-TbStatus $st.Status 'Type a number in any base. Negative numbers show their two''s complement. Big numbers are fine.'
    $st
}

function Update-NumberTool($St) {
    $t = $St.Input.Text
    if (-not $t.Trim()) { $St.Output.Text = ''; return }
    $b = @(0, 10, 16, 2, 8)[$St.Base.SelectedIndex]
    try {
        $rows = [DevNum]::Describe($t, $b) -split "`n"
        $w = ($rows | ForEach-Object { ($_ -split "`t")[0].Length } | Measure-Object -Maximum).Maximum + 3
        $St.Output.Text = ($rows | ForEach-Object { $p = $_ -split "`t", 2; $p[0].PadRight($w) + $p[1] }) -join "`n"
        Set-TbStatus $St.Status 'Select a line and press Copy (or Ctrl+C) to copy just that value.'
    } catch {
        $m = if ($_.Exception.InnerException) { $_.Exception.InnerException.Message } else { $_.Exception.Message }
        $St.Output.Text = ''; Set-TbStatus $St.Status $m 'error'
    }
}

# ======================================================================================
# Units: length, weight, data size, time, speed, area, volume, temperature, pressure, energy.
# ======================================================================================
$UnitTable = [ordered]@{
    'Length'      = [ordered]@{ 'mm' = 0.001; 'cm' = 0.01; 'm' = 1; 'km' = 1000; 'in' = 0.0254; 'ft' = 0.3048; 'yd' = 0.9144; 'mi' = 1609.344; 'nautical mi' = 1852 }
    'Weight'      = [ordered]@{ 'mg' = 0.000001; 'g' = 0.001; 'kg' = 1; 't' = 1000; 'oz' = 0.028349523125; 'lb' = 0.45359237; 'st' = 6.35029318 }
    'Data size'   = [ordered]@{ 'bit' = 0.125; 'B' = 1; 'KB' = 1e3; 'MB' = 1e6; 'GB' = 1e9; 'TB' = 1e12; 'KiB' = 1024; 'MiB' = 1048576; 'GiB' = 1073741824; 'TiB' = 1099511627776 }
    'Data rate'   = [ordered]@{ 'bit/s' = 1; 'kbit/s' = 1e3; 'Mbit/s' = 1e6; 'Gbit/s' = 1e9; 'B/s' = 8; 'KB/s' = 8e3; 'MB/s' = 8e6; 'GB/s' = 8e9 }
    'Time'        = [ordered]@{ 'ms' = 0.001; 's' = 1; 'min' = 60; 'h' = 3600; 'day' = 86400; 'week' = 604800; 'month' = 2629746; 'year' = 31556952 }
    'Speed'       = [ordered]@{ 'm/s' = 1; 'km/h' = (1 / 3.6); 'mph' = 0.44704; 'knot' = (1852 / 3600); 'ft/s' = 0.3048 }
    'Area'        = [ordered]@{ 'mm2' = 1e-6; 'cm2' = 1e-4; 'm2' = 1; 'ha' = 1e4; 'km2' = 1e6; 'in2' = 0.00064516; 'ft2' = 0.09290304; 'acre' = 4046.8564224; 'mi2' = 2589988.110336 }
    'Volume'      = [ordered]@{ 'ml' = 0.001; 'l' = 1; 'm3' = 1000; 'tsp' = 0.00492892159; 'tbsp' = 0.0147867648; 'fl oz (US)' = 0.0295735296; 'cup (US)' = 0.2365882365; 'pint (US)' = 0.473176473; 'gallon (US)' = 3.785411784; 'gallon (UK)' = 4.54609 }
    'Temperature' = [ordered]@{ 'C' = 1; 'F' = 1; 'K' = 1 }
    'Pressure'    = [ordered]@{ 'Pa' = 1; 'kPa' = 1000; 'bar' = 1e5; 'psi' = 6894.757293; 'atm' = 101325; 'mmHg' = 133.322387 }
    'Energy'      = [ordered]@{ 'J' = 1; 'kJ' = 1000; 'cal' = 4.184; 'kcal' = 4184; 'Wh' = 3600; 'kWh' = 3.6e6; 'BTU' = 1055.05585 }
}

function Convert-Unit([string]$Category, [double]$Value, [string]$From, [string]$To) {
    if ($Category -eq 'Temperature') {
        $k = switch ($From) { 'C' { $Value + 273.15 } 'F' { ($Value - 32) * 5 / 9 + 273.15 } default { $Value } }
        return $(switch ($To) { 'C' { $k - 273.15 } 'F' { ($k - 273.15) * 9 / 5 + 32 } default { $k } })
    }
    $u = $UnitTable[$Category]
    $Value * $u[$From] / $u[$To]
}

function Format-UnitNumber([double]$V) {
    if ($V -eq 0) { return '0' }
    $a = [math]::Abs($V)
    if ($a -ge 1e15 -or $a -lt 1e-6) { return $V.ToString('0.######E+0', [Globalization.CultureInfo]::InvariantCulture) }
    $r = [math]::Round($V, [math]::Max(0, 9 - [int][math]::Floor([math]::Log10($a))))
    $r.ToString('#,0.##########', [Globalization.CultureInfo]::InvariantCulture).Replace(',', ' ')
}

Register-ToolboxPage 'units' 'Units' $Glyph.Refresh 'unit convert length weight data size mb gb mib time speed area volume temperature celsius fahrenheit pressure energy' {
    param($panel, $st)
    $st.Status = New-TbPage $panel
    $lv = New-Object System.Windows.Forms.ListView
    $lv.Dock = 'Fill'; $lv.View = 'Details'; $lv.FullRowSelect = $true; $lv.BorderStyle = 'None'; $lv.HideSelection = $false
    $lv.BackColor = $C.Bg; $lv.ForeColor = $C.Fore; $lv.Font = New-Object System.Drawing.Font('Consolas', (Fz 12))
    [void]$lv.Columns.Add('Value', (Px (320 * $TextZoom)), 'Right'); [void]$lv.Columns.Add('Unit', (Px (200 * $TextZoom)))
    $lv.add_DoubleClick({ param($src, $e) if ($src.SelectedItems.Count) { Copy-TbText ($src.SelectedItems[0].Text -replace ' ', ''); Set-TbStatus $TbUI.Pages['units'].State.Status "Copied $($src.SelectedItems[0].Text) $($src.SelectedItems[0].SubItems[1].Text)" 'ok' } })
    $panel.Controls.Add($lv)
    $st.List = $lv
    $bar = New-TbBar $panel
    $st.Cat = New-TbCombo $bar @($UnitTable.Keys) 140
    $st.Input = New-TbBox -Mono -Cue '1.5   or   5 km   or   100 F'
    $st.Input.Width = Px (200 * $TextZoom); $st.Input.Margin = New-Object System.Windows.Forms.Padding(0, (Px 4), (Px 8), 0)
    $st.Input.Font = New-Object System.Drawing.Font('Consolas', (Fz 12))
    $bar.Controls.Add($st.Input)
    $st.From = New-TbCombo $bar @() 140
    $st.Cat.add_SelectedIndexChanged({
        $s = $TbUI.Pages['units'].State
        $s.From.Items.Clear(); foreach ($u in $UnitTable[[string]$s.Cat.SelectedItem].Keys) { [void]$s.From.Items.Add($u) }
        $s.From.SelectedIndex = [math]::Min(1, $s.From.Items.Count - 1)
    })
    $st.From.add_SelectedIndexChanged({ Update-UnitTool $TbUI.Pages['units'].State })
    $st.Input.add_TextChanged({ Update-UnitTool $TbUI.Pages['units'].State -FromText })
    $st.Cat.SelectedIndex = 1; $st.Cat.SelectedIndex = 0
    $st.SetInput = { param($t) $TbUI.Pages['units'].State.Input.Text = $t.Trim() }
    $st.Focus = { $TbUI.Pages['units'].State.Input.Focus() }
    $st
}

function Update-UnitTool($St, [switch]$FromText) {
    $t = $St.Input.Text.Trim()
    $St.List.BeginUpdate(); $St.List.Items.Clear()
    try {
        if (-not $t) { Set-TbStatus $St.Status 'Type a number. You can add a unit ("5 km", "100 F", "3 GiB") and it is picked for you. Double-click a result to copy it.'; return }
        $m = [regex]::Match($t, '^\s*([-+]?[\d\s.,]*\d(?:[eE][-+]?\d+)?|[-+]?\.\d+)\s*(.*)$')
        if (-not $m.Success) { Set-TbStatus $St.Status 'That is not a number.' 'error'; return }
        $num = $m.Groups[1].Value -replace '\s', ''
        if ($num -match '^\d{1,3}(,\d{3})+(\.\d+)?$') { $num = $num -replace ',', '' } else { $num = $num -replace ',', '.' }
        $v = 0.0
        if (-not [double]::TryParse($num, [Globalization.NumberStyles]::Float, [Globalization.CultureInfo]::InvariantCulture, [ref]$v)) { Set-TbStatus $St.Status 'That is not a number.' 'error'; return }
        $unitText = $m.Groups[2].Value.Trim() -replace "^(deg|$([char]0xB0))\s*", '' -replace [string][char]0xB2, '2' -replace [string][char]0xB3, '3'
        if ($FromText -and $unitText) {
            foreach ($cat in $UnitTable.Keys) {
                $hit = @($UnitTable[$cat].Keys) | Where-Object { $_ -ceq $unitText } | Select-Object -First 1
                if (-not $hit) { $hit = @($UnitTable[$cat].Keys) | Where-Object { $_ -eq $unitText -or ($_ -replace ' \(.*\)$', '') -eq $unitText -or "$($_)s" -eq $unitText } | Select-Object -First 1 }
                if ($hit) {
                    if ([string]$St.Cat.SelectedItem -ne $cat) { $St.Cat.SelectedItem = $cat }
                    if ([string]$St.From.SelectedItem -ne $hit) { $St.From.SelectedItem = $hit; return }   # that change refreshes the list
                    break
                }
            }
        }
        $cat = [string]$St.Cat.SelectedItem; $from = [string]$St.From.SelectedItem
        $St.List.Items.Clear()                 # picking the unit above may have filled it already
        foreach ($u in $UnitTable[$cat].Keys) {
            $r = Convert-Unit $cat $v $from $u
            $it = New-Object System.Windows.Forms.ListViewItem((Format-UnitNumber $r))
            [void]$it.SubItems.Add($(if ($cat -eq 'Temperature') { "$([char]0xB0)$u" -replace "$([char]0xB0)K", 'K' } else { $u }))
            if ($u -eq $from) { $it.ForeColor = $C.Accent }
            [void]$St.List.Items.Add($it)
        }
        Set-TbStatus $St.Status "$(Format-UnitNumber $v) $from in every $($cat.ToLower()) unit. Double-click a row to copy the number."
    } finally { $St.List.EndUpdate() }
}

# ======================================================================================
# Time: Unix timestamps, ISO dates, time zones.
# ======================================================================================

function ConvertTo-DateTimeOffset([string]$Text, [TimeZoneInfo]$Zone) {
    $t = $Text.Trim()
    $inv = [Globalization.CultureInfo]::InvariantCulture
    if (-not $t -or $t -eq 'now') { return [DateTimeOffset]::Now }
    if ($t -match '^/Date\((-?\d+)') { return [DateTimeOffset]::FromUnixTimeMilliseconds([long]$Matches[1]) }
    if ($t -match '^-?\d{1,11}(\.\d+)?$') { return [DateTimeOffset]::FromUnixTimeMilliseconds([long]([double]::Parse($t, $inv) * 1000)) }
    if ($t -match '^-?\d{12,14}$') { return [DateTimeOffset]::FromUnixTimeMilliseconds([long]$t) }
    if ($t -match '^\d{15,17}$') { return [DateTimeOffset]::FromUnixTimeMilliseconds([long]([long]$t / 1000)) }       # microseconds
    if ($t -match '^\d{18,19}$') { return (New-Object DateTimeOffset([long]$t, [TimeSpan]::Zero)) }                        # .NET ticks
    $hasZone = $t -match '(Z|[+-]\d\d:?\d\d|\b(GMT|UTC))$'
    $styles = [Globalization.DateTimeStyles]::AllowWhiteSpaces
    $dto = [DateTimeOffset]::MinValue
    if ($hasZone) {
        if ([DateTimeOffset]::TryParse(($t -replace '\bUTC$', 'Z'), $inv, $styles, [ref]$dto)) { return $dto }
        if ([DateTimeOffset]::TryParse($t, [Globalization.CultureInfo]::CurrentCulture, $styles, [ref]$dto)) { return $dto }
    }
    $dt = [datetime]::MinValue
    if (-not [datetime]::TryParse($t, [Globalization.CultureInfo]::CurrentCulture, $styles, [ref]$dt) -and
        -not [datetime]::TryParse($t, $inv, $styles, [ref]$dt)) { throw "Can't read that as a date or a timestamp." }
    $dt = [datetime]::SpecifyKind($dt, 'Unspecified')
    $utc = [TimeZoneInfo]::ConvertTimeToUtc($dt, $Zone)
    [TimeZoneInfo]::ConvertTime((New-Object DateTimeOffset($utc, [TimeSpan]::Zero)), $Zone)
}

function Format-Offset([TimeSpan]$O) { '{0}{1:00}:{2:00}' -f $(if ($O -lt [TimeSpan]::Zero) { '-' } else { '+' }), [math]::Abs($O.Hours), [math]::Abs($O.Minutes) }

Register-ToolboxPage 'time' 'Time & time zones' $Glyph.History 'time date timestamp unix epoch iso 8601 timezone time zone utc convert world clock' {
    param($panel, $st)
    $st.Status = New-TbPage $panel
    $split = New-Object System.Windows.Forms.SplitContainer
    $split.Dock = 'Fill'; $split.Orientation = 'Horizontal'; $split.BackColor = $C.Line; $split.SplitterWidth = 3
    $split.Panel1.BackColor = $C.Bg; $split.Panel2.BackColor = $C.Bg
    $panel.Controls.Add($split)
    $st.Output = New-TbRtb -ReadOnly; $st.Output.Dock = 'Fill'; $st.Output.Font = New-Object System.Drawing.Font('Consolas', (Fz 11.5))
    $split.Panel1.Controls.Add($st.Output)
    $lv = New-Object System.Windows.Forms.ListView
    $lv.Dock = 'Fill'; $lv.View = 'Details'; $lv.FullRowSelect = $true; $lv.BorderStyle = 'None'; $lv.HideSelection = $false
    $lv.BackColor = $C.Bg; $lv.ForeColor = $C.Fore
    foreach ($col in @(@('Time zone', 330), @('Time', 190), @('Offset', 80), @('Compared with you', 170))) { [void]$lv.Columns.Add($col[0], (Px ($col[1] * $TextZoom))) }
    $zm = New-Object System.Windows.Forms.ContextMenuStrip -Property @{ Renderer = $MenuRenderer }
    [void](Add-MenuItem $zm 'Copy time' { $s = $TbUI.Pages['time'].State; if ($s.Zones.SelectedItems.Count) { Copy-TbText $s.Zones.SelectedItems[0].SubItems[1].Text } } $Glyph.Copy)
    [void](Add-MenuItem $zm 'Remove from the list' {
        $s = $TbUI.Pages['time'].State
        if (-not $s.Zones.SelectedItems.Count) { return }
        $id = [string]$s.Zones.SelectedItems[0].Tag
        $script:TimeZones = @($script:TimeZones | Where-Object { $_ -ne $id }); Save-Settings; Update-TimeTool $s
    } $Glyph.Delete)
    $lv.ContextMenuStrip = $zm
    $split.Panel2.Controls.Add($lv)
    $st.Zones = $lv
    $zbar = New-TbBar $split.Panel2
    New-TbLabel $zbar 'Same moment around the world' -Title | Out-Null
    $all = [TimeZoneInfo]::GetSystemTimeZones()
    $st.AllZones = $all
    $st.AddZone = New-TbCombo $zbar @($all | ForEach-Object { $_.DisplayName }) 360
    [void](New-Button 'Add' 'Add this time zone to the list' {
        $s = $TbUI.Pages['time'].State
        $z = $s.AllZones[$s.AddZone.SelectedIndex]
        if ($script:TimeZones -notcontains $z.Id) { $script:TimeZones = @($script:TimeZones) + $z.Id; Save-Settings }
        Update-TimeTool $s
    } $zbar $Glyph.Add 2)

    $bar = New-TbBar $panel
    New-TbLabel $bar 'Date or timestamp' -Dim | Out-Null
    $st.Input = New-TbBox -Mono -Cue 'now   1760000000   2026-10-17 14:30   2026-10-17T11:30:00Z'
    $st.Input.Width = Px (330 * $TextZoom); $st.Input.Margin = New-Object System.Windows.Forms.Padding(0, (Px 4), (Px 8), 0)
    $bar.Controls.Add($st.Input)
    New-TbLabel $bar 'in' -Dim | Out-Null
    $st.Zone = New-TbCombo $bar @(@("Your time zone ($([TimeZoneInfo]::Local.StandardName))") + @($all | ForEach-Object { $_.DisplayName })) 300
    [void](New-Button 'Now' 'Show the current time (it keeps ticking)' { $s = $TbUI.Pages['time'].State; $s.Input.Text = '' ; Update-TimeTool $s } $bar $Glyph.History 2)
    [void](New-Button 'Copy' 'Copy the selected line, or everything' {
        $s = $TbUI.Pages['time'].State
        Copy-TbText $(if ($s.Output.SelectionLength -gt 0) { $s.Output.SelectedText } else { $s.Output.Text })
    } $bar $Glyph.Copy 1)
    $st.Input.add_TextChanged({ Update-TimeTool $TbUI.Pages['time'].State })
    $st.Zone.add_SelectedIndexChanged({ Update-TimeTool $TbUI.Pages['time'].State })
    $st.Tick = New-Object System.Windows.Forms.Timer
    $st.Tick.Interval = 1000
    $st.Tick.add_Tick({ $s = $TbUI.Pages['time'].State; if ($s -and $s.Panel.Visible -and $s.Input.Text.Trim() -in '', 'now') { Update-TimeTool $s } })
    $st.Panel = $panel
    $st.Tick.Start()
    $st.Close = { $TbUI.Pages['time'].State.Tick.Dispose() }
    $st.SetInput = { param($t) $TbUI.Pages['time'].State.Input.Text = $t.Trim() }
    $st.Focus = { $s = $TbUI.Pages['time'].State; Update-TimeTool $s; $s.Input.Focus() }
    $st.Split = $split
    $split.add_SizeChanged({ param($src, $e) if (-not $src.Tag -and $src.Height -gt (Px 420)) { $src.Tag = 1; try { $src.SplitterDistance = Px 300 } catch { } } })
    $st
}

function Update-TimeTool($St) {
    $zone = if ($St.Zone.SelectedIndex -le 0) { [TimeZoneInfo]::Local } else { $St.AllZones[$St.Zone.SelectedIndex - 1] }
    try { $d = ConvertTo-DateTimeOffset $St.Input.Text $zone }
    catch { $St.Output.Text = ''; Set-TbStatus $St.Status $_.Exception.Message 'error'; return }
    $inv = [Globalization.CultureInfo]::InvariantCulture
    $d = [TimeZoneInfo]::ConvertTime($d, $zone)          # shown in the zone you picked
    $local = $d.ToLocalTime(); $utc = $d.ToUniversalTime()
    $diff = [DateTimeOffset]::Now - $d
    $ago = $diff.Duration()
    $span = if ($ago.TotalSeconds -lt 60) { "$([int]$ago.TotalSeconds) seconds" } elseif ($ago.TotalMinutes -lt 60) { "$([int]$ago.TotalMinutes) minutes" } elseif ($ago.TotalHours -lt 48) { '{0:0.#} hours' -f $ago.TotalHours } elseif ($ago.TotalDays -lt 365) { '{0:0.#} days' -f $ago.TotalDays } else { '{0:0.##} years' -f ($ago.TotalDays / 365.2425) }
    $rel = if ($ago.TotalSeconds -lt 1) { 'now' } elseif ($diff.Ticks -gt 0) { "$span ago" } else { "in $span" }
    $cal = [Globalization.CultureInfo]::InvariantCulture.Calendar
    $isoWeek = $cal.GetWeekOfYear($local.DateTime.AddDays(3 - ((([int]$local.DayOfWeek) + 6) % 7)), 'FirstFourDayWeek', 'Monday')
    $rows = [ordered]@{
        'Your time'     = "$($local.ToString('dddd, d MMMM yyyy  HH:mm:ss'))  ($(Format-Offset $local.Offset))"
        'UTC'           = $utc.ToString('yyyy-MM-dd HH:mm:ss', $inv)
        'ISO 8601'      = $d.ToString('yyyy-MM-ddTHH:mm:ss.fffzzz', $inv)
        'ISO 8601 UTC'  = $utc.ToString('yyyy-MM-ddTHH:mm:ss.fff', $inv) + 'Z'
        'RFC 1123'      = $utc.ToString('r', $inv)
        'Unix seconds'  = [string]$d.ToUnixTimeSeconds()
        'Unix ms'       = [string]$d.ToUnixTimeMilliseconds()
        'Relative'      = $rel
        'Day / week'    = "day $($local.DayOfYear) of the year, ISO week $isoWeek, $($local.DayOfWeek)"
        'Excel / OLE'   = $local.DateTime.ToOADate().ToString('0.#####', $inv)
        '.NET ticks'    = [string]$utc.Ticks
    }
    $St.Output.Text = ($rows.GetEnumerator() | ForEach-Object { $_.Key.PadRight(15) + $_.Value }) -join "`n"
    $lv = $St.Zones
    $sel = if ($lv.SelectedItems.Count) { [string]$lv.SelectedItems[0].Tag } else { '' }
    $lv.BeginUpdate(); $lv.Items.Clear()
    foreach ($id in $script:TimeZones) {
        $z = try { [TimeZoneInfo]::FindSystemTimeZoneById($id) } catch { $null }
        if (-not $z) { continue }
        $t = [TimeZoneInfo]::ConvertTime($d, $z)
        $it = New-Object System.Windows.Forms.ListViewItem($z.DisplayName)
        $it.Tag = $id
        [void]$it.SubItems.Add($t.ToString('ddd d MMM  HH:mm'))
        [void]$it.SubItems.Add((Format-Offset $t.Offset))
        $h = ($t.Offset - $local.Offset).TotalHours
        [void]$it.SubItems.Add($(if ($h -eq 0) { 'same as you' } elseif ($h -gt 0) { "{0:0.##} h ahead" -f $h } else { "{0:0.##} h behind" -f (-$h) }))
        if ($id -eq $sel) { $it.Selected = $true }
        [void]$lv.Items.Add($it)
    }
    $lv.EndUpdate()
    Set-TbStatus $St.Status $(if ($St.Input.Text.Trim()) { "Read as $($d.ToString('yyyy-MM-dd HH:mm:ss zzz'))." } else { 'Showing the current time. Type a Unix timestamp (seconds or ms) or a date to convert it.' })
}

# ======================================================================================
# Markdown: live preview, export to HTML.
# ======================================================================================
function Get-MarkdownPage([string]$Markdown, [string]$Title = 'Markdown') { [DevMarkdown]::Page($Markdown, $Title, [bool]$script:IsDark) }

function Save-MarkdownHtml([string]$Markdown, [string]$Name, $Owner) {
    $d = New-Object System.Windows.Forms.SaveFileDialog
    $d.Filter = 'Web page (*.html)|*.html|Markdown (*.md)|*.md'
    $d.FileName = (($Name -replace '[\\/:*?"<>|]', '_').Trim() -replace '^$', 'document') + '.html'
    $script:Modal = $true
    try {
        if ($d.ShowDialog($Owner) -ne 'OK') { return $null }
        $text = if ($d.FilterIndex -eq 2) { $Markdown } else { [DevMarkdown]::Page($Markdown, $Name, $false) }
        [IO.File]::WriteAllText($d.FileName, $text, (New-Object System.Text.UTF8Encoding $false))
        $d.FileName
    } finally { $script:Modal = $false; $d.Dispose() }
}

Register-ToolboxPage 'markdown' 'Markdown preview' $Glyph.Document 'markdown md preview render html export readme' {
    param($panel, $st)
    $st.Status = New-TbPage $panel
    $split = New-Object System.Windows.Forms.SplitContainer
    $split.Dock = 'Fill'; $split.BackColor = $C.Line; $split.SplitterWidth = 3
    $split.Panel1.BackColor = $C.Bg; $split.Panel2.BackColor = $C.Bg
    $panel.Controls.Add($split)
    $st.Input = New-TbBox -Mono -Multi -Cue 'Type or paste Markdown here'
    $st.Input.Dock = 'Fill'; $st.Input.WordWrap = $true; $st.Input.ScrollBars = 'Vertical'
    $split.Panel1.Controls.Add($st.Input)
    $wb = New-Object System.Windows.Forms.WebBrowser
    $wb.Dock = 'Fill'; $wb.IsWebBrowserContextMenuEnabled = $false; $wb.ScriptErrorsSuppressed = $true; $wb.AllowWebBrowserDrop = $false
    $wb.add_Navigating({
        param($src, $e)
        $u = [string]$e.Url
        if ($u -eq 'about:blank' -or $u.StartsWith('about:')) { return }
        $e.Cancel = $true
        if ($u -match '^(https?|mailto):') { Start-Process $u }
    })
    $split.Panel2.Controls.Add($wb)
    $st.Browser = $wb
    $bar = New-TbBar $panel
    [void](New-Button 'Open...' 'Open a Markdown file' {
        $s = $TbUI.Pages['markdown'].State
        $d = New-Object System.Windows.Forms.OpenFileDialog; $d.Filter = 'Markdown (*.md;*.markdown;*.txt)|*.md;*.markdown;*.txt|All files|*.*'
        $script:Modal = $true
        try { if ($d.ShowDialog($TbUI.Form) -eq 'OK') { $s.Input.Text = Read-TextFile $d.FileName; $s.Name = [IO.Path]::GetFileNameWithoutExtension($d.FileName) } } finally { $script:Modal = $false; $d.Dispose() }
    } $bar $Glyph.Open 2)
    [void](New-Button 'From clipboard' 'Replace the text with the clipboard' { $s = $TbUI.Pages['markdown'].State; try { $s.Input.Text = [System.Windows.Forms.Clipboard]::GetText() } catch { } } $bar $Glyph.Paste 2)
    [void](New-Button 'Copy HTML' 'Copy the rendered HTML (without the page around it)' { $s = $TbUI.Pages['markdown'].State; Copy-TbText ([DevMarkdown]::ToHtml($s.Input.Text)); Set-TbStatus $s.Status 'HTML copied.' 'ok' } $bar $Glyph.Copy 1)
    [void](New-Button 'Save as...' 'Save as a web page (.html) or as Markdown (.md)' {
        $s = $TbUI.Pages['markdown'].State
        $f = Save-MarkdownHtml $s.Input.Text $(if ($s.Name) { $s.Name } else { 'document' }) $TbUI.Form
        if ($f) { Set-TbStatus $s.Status "Saved $f" 'ok' }
    } $bar $Glyph.Save 2)
    [void](New-Button 'Open in browser' 'Show the page in your web browser' {
        $s = $TbUI.Pages['markdown'].State
        $f = Join-Path ([IO.Path]::GetTempPath()) 'DevTools-markdown-preview.html'
        [IO.File]::WriteAllText($f, [DevMarkdown]::Page($s.Input.Text, $(if ($s.Name) { $s.Name } else { 'Markdown' }), $false), (New-Object System.Text.UTF8Encoding $false))
        Start-Process $f
    } $bar $Glyph.Globe 2)
    $st.Timer = New-TbDebounce 350 { Update-MarkdownTool $TbUI.Pages['markdown'].State }
    $st.Input.add_TextChanged({ $s = $TbUI.Pages['markdown'].State; $s.Timer.Stop(); $s.Timer.Start() })
    $st.SetInput = { param($t) $s = $TbUI.Pages['markdown'].State; $s.Input.Text = $t; Update-MarkdownTool $s }
    $st.Focus = { $TbUI.Pages['markdown'].State.Input.Focus() }
    $st.Input.Text = "# Markdown preview`r`n`r`nType on the left; the preview updates as you go.`r`n`r`n- **bold**, *italic*, ``code``, [links](https://example.com)`r`n- [x] task lists, tables, quotes`r`n`r`n``````powershell`r`nGet-Process | Sort-Object CPU -Descending | Select-Object -First 5`r`n```````r`n"
    $st.Input.Select(0, 0)
    Update-MarkdownTool $st
    $st
}

function Update-MarkdownTool($St) {
    try {
        $St.Browser.DocumentText = Get-MarkdownPage $St.Input.Text
        $words = @([regex]::Matches($St.Input.Text, '\w+')).Count
        Set-TbStatus $St.Status "$words words  $Dot  links open in your browser  $Dot  Save as... writes .html or .md"
    } catch { Set-TbStatus $St.Status $_.Exception.Message 'error' }
}

# ======================================================================================
# Environment variables and PATH (yours, and the system ones when DevTools runs as administrator).
# ======================================================================================
function Test-IsAdmin { ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator) }

function Get-EnvErrorText($Err) {
    $m = if ($Err.Exception.InnerException) { $Err.Exception.InnerException.Message } else { $Err.Exception.Message }
    if ($m -match 'denied|not allowed|Requested registry access') { 'Changing system variables needs administrator rights: start DevTools as administrator.' } else { $m }
}

function Show-EnvVarDialog([string]$Name = '', [string]$Value = '', [bool]$System = $false, [switch]$New) {
    $d = New-Object System.Windows.Forms.Form
    $d.Text = $(if ($New) { 'New variable' } else { 'Edit variable' }); $d.FormBorderStyle = 'Sizable'; $d.MinimizeBox = $false; $d.MaximizeBox = $false
    $d.StartPosition = 'CenterParent'; $d.ShowInTaskbar = $false; $d.BackColor = $C.Panel; $d.ForeColor = $C.Fore; $d.Font = $FontMain
    $d.ClientSize = New-Object System.Drawing.Size((Px (560 * $TextZoom)), (Px 300)); $d.MinimumSize = New-Object System.Drawing.Size((Px 380), (Px 260))
    $tl = New-Object System.Windows.Forms.TableLayoutPanel
    $tl.Dock = 'Fill'; $tl.ColumnCount = 2; $tl.RowCount = 4; $tl.Padding = New-Object System.Windows.Forms.Padding((Px 12)); $tl.BackColor = $C.Panel
    [void]$tl.ColumnStyles.Add((New-Object System.Windows.Forms.ColumnStyle('AutoSize')))
    [void]$tl.ColumnStyles.Add((New-Object System.Windows.Forms.ColumnStyle('Percent', 100)))
    [void]$tl.RowStyles.Add((New-Object System.Windows.Forms.RowStyle('AutoSize')))
    [void]$tl.RowStyles.Add((New-Object System.Windows.Forms.RowStyle('Percent', 100)))
    [void]$tl.RowStyles.Add((New-Object System.Windows.Forms.RowStyle('AutoSize')))
    [void]$tl.RowStyles.Add((New-Object System.Windows.Forms.RowStyle('AutoSize')))
    $l1 = New-Object System.Windows.Forms.Label; $l1.Text = 'Name'; $l1.AutoSize = $true; $l1.Margin = New-Object System.Windows.Forms.Padding(0, (Px 6), (Px 8), 0)
    $nb = New-TbBox -Mono; $nb.Text = $Name; $nb.Dock = 'Fill'; $nb.ReadOnly = -not $New
    $l2 = New-Object System.Windows.Forms.Label; $l2.Text = 'Value'; $l2.AutoSize = $true; $l2.Margin = New-Object System.Windows.Forms.Padding(0, (Px 6), (Px 8), 0)
    $vb = New-TbBox -Mono -Multi; $vb.Text = $Value; $vb.Dock = 'Fill'; $vb.WordWrap = $true; $vb.ScrollBars = 'Vertical'; $vb.AcceptsReturn = $false
    $scope = New-Object System.Windows.Forms.ComboBox
    $scope.DropDownStyle = 'DropDownList'; $scope.FlatStyle = 'Flat'; $scope.BackColor = $C.Bg; $scope.ForeColor = $C.Fore; $scope.Width = Px 260
    [void]$scope.Items.Add('Only for you (user)'); [void]$scope.Items.Add('Everyone on this PC (system, needs admin)')
    $scope.SelectedIndex = [int]$System; $scope.Enabled = [bool]$New
    $btns = New-Object System.Windows.Forms.FlowLayoutPanel; $btns.FlowDirection = 'RightToLeft'; $btns.Dock = 'Fill'; $btns.AutoSize = $true; $btns.BackColor = $C.Panel
    $ok = New-Button 'Save' '' { param($src, $e) $src.FindForm().DialogResult = 'OK' } $btns '' 1
    $cancel = New-Button 'Cancel' '' { param($src, $e) $src.FindForm().DialogResult = 'Cancel' } $btns '' 2
    $tl.Controls.Add($l1, 0, 0); $tl.Controls.Add($nb, 1, 0); $tl.Controls.Add($l2, 0, 1); $tl.Controls.Add($vb, 1, 1)
    $tl.Controls.Add($scope, 1, 2); $tl.Controls.Add($btns, 0, 3); $tl.SetColumnSpan($btns, 2)
    $d.Controls.Add($tl)
    $d.AcceptButton = $ok; $d.CancelButton = $cancel
    Set-ControlTheme $d $null $script:IsDark
    $d.add_Shown({ param($src, $e) [PowerClipHost]::EnsureShown($src.Handle) })
    $script:Modal = $true
    try {
        if ($d.ShowDialog($TbUI.Form) -ne 'OK' -or -not $nb.Text.Trim()) { return $null }
        [pscustomobject]@{ Name = $nb.Text.Trim(); Value = ($vb.Text -replace '\r?\n', ''); System = ($scope.SelectedIndex -eq 1) }
    } finally { $script:Modal = $false; $d.Dispose() }
}

Register-ToolboxPage 'env' 'Environment & PATH' $Glyph.Settings 'environment variables env path edit system user folder missing' {
    param($panel, $st)
    $st.Status = New-TbPage $panel
    $tabs = New-TabSet $panel
    $st.Tabs = $tabs
    # ---- variables
    $vp = Add-ApiTab $tabs 'Variables'
    $lv = New-Object System.Windows.Forms.ListView
    $lv.Dock = 'Fill'; $lv.View = 'Details'; $lv.FullRowSelect = $true; $lv.BorderStyle = 'None'; $lv.HideSelection = $false
    $lv.BackColor = $C.Bg; $lv.ForeColor = $C.Fore
    foreach ($col in @(@('Name', 240), @('Value', 640), @('For', 90))) { [void]$lv.Columns.Add($col[0], (Px ($col[1] * $TextZoom))) }
    $lv.add_DoubleClick({ Edit-EnvVariable })
    $vm = New-Object System.Windows.Forms.ContextMenuStrip -Property @{ Renderer = $MenuRenderer }
    [void](Add-MenuItem $vm 'Copy value' { $s = $TbUI.Pages['env'].State; if ($s.Vars.SelectedItems.Count) { Copy-TbText $s.Vars.SelectedItems[0].SubItems[1].Text } } $Glyph.Copy)
    [void](Add-MenuItem $vm 'Copy as  NAME=value' { $s = $TbUI.Pages['env'].State; if ($s.Vars.SelectedItems.Count) { $i = $s.Vars.SelectedItems[0]; Copy-TbText "$($i.Text)=$($i.SubItems[1].Text)" } } $Glyph.Copy)
    [void](Add-MenuItem $vm 'Edit...' { Edit-EnvVariable } $Glyph.Edit)
    [void](Add-MenuItem $vm 'Delete...' { Remove-EnvVariable } $Glyph.Delete)
    $lv.ContextMenuStrip = $vm
    $vp.Controls.Add($lv)
    $st.Vars = $lv
    $vbar = New-TbBar $vp
    New-TbLabel $vbar 'Filter' -Dim | Out-Null
    $st.Filter = New-TbBox -Cue 'name or value'
    $st.Filter.Width = Px (240 * $TextZoom); $st.Filter.Margin = New-Object System.Windows.Forms.Padding(0, (Px 4), (Px 8), 0)
    $vbar.Controls.Add($st.Filter)
    $st.ShowSys = New-CheckBox $vbar 'System variables too' $true 'Also list the variables for everyone on this PC'
    [void](New-Button 'New...' 'Add a variable' {
        $r = Show-EnvVarDialog -New
        if (-not $r) { return }
        $s = $TbUI.Pages['env'].State
        try { [DevEnv]::Set($r.System, $r.Name, $r.Value); Set-TbStatus $s.Status "Saved $($r.Name). Programs started from now on see it." 'ok' } catch { Set-TbStatus $s.Status (Get-EnvErrorText $_) 'error' }
        Update-EnvVars $s
    } $vbar $Glyph.Add 1)
    [void](New-Button 'Edit...' 'Change the selected variable (double-click works too)' { Edit-EnvVariable } $vbar $Glyph.Edit 2)
    [void](New-Button 'Delete' 'Delete the selected variable' { Remove-EnvVariable } $vbar $Glyph.Delete 2)
    [void](New-Button 'Refresh' 'Read the variables again' { Update-EnvVars $TbUI.Pages['env'].State } $vbar $Glyph.Refresh 2)
    $st.Filter.add_TextChanged({ Update-EnvVars $TbUI.Pages['env'].State })
    $st.ShowSys.add_CheckedChanged({ Update-EnvVars $TbUI.Pages['env'].State })
    # ---- PATH
    $pp = Add-ApiTab $tabs 'PATH'
    $pl = New-Object System.Windows.Forms.ListView
    $pl.Dock = 'Fill'; $pl.View = 'Details'; $pl.FullRowSelect = $true; $pl.BorderStyle = 'None'; $pl.HideSelection = $false; $pl.MultiSelect = $false
    $pl.BackColor = $C.Bg; $pl.ForeColor = $C.Fore; $pl.Font = New-Object System.Drawing.Font('Consolas', (Fz 10.5))
    [void]$pl.Columns.Add('Folder', (Px (700 * $TextZoom))); [void]$pl.Columns.Add('', (Px (200 * $TextZoom)))
    $pl.add_DoubleClick({ Edit-PathEntry })
    $pp.Controls.Add($pl)
    $st.PathList = $pl
    $pbar = New-TbBar $pp
    $st.PathScope = New-TbCombo $pbar @('Your PATH (user)', 'System PATH (needs admin to save)') 250
    [void](New-Button 'Add folder...' 'Add a folder to this PATH' {
        $s = $TbUI.Pages['env'].State
        $d = New-Object System.Windows.Forms.FolderBrowserDialog; $d.Description = 'Folder to add to the PATH'
        $script:Modal = $true
        try { if ($d.ShowDialog($TbUI.Form) -eq 'OK') { $s.PathItems.Add($d.SelectedPath); $s.PathDirty = $true; Update-PathList $s ($s.PathItems.Count - 1) } } finally { $script:Modal = $false; $d.Dispose() }
    } $pbar $Glyph.Add 2)
    [void](New-Button 'Edit...' 'Change the selected entry (you can use %VARIABLES%)' { Edit-PathEntry } $pbar $Glyph.Edit 2)
    [void](New-Button 'Remove' 'Remove the selected entry' { $s = $TbUI.Pages['env'].State; $i = Get-PathIndex $s; if ($i -ge 0) { $s.PathItems.RemoveAt($i); $s.PathDirty = $true; Update-PathList $s ([math]::Min($i, $s.PathItems.Count - 1)) } } $pbar $Glyph.Delete 2)
    [void](New-Button 'Up' 'Move up (earlier folders win)' { Move-PathEntry -1 } $pbar '' 2)
    [void](New-Button 'Down' 'Move down' { Move-PathEntry 1 } $pbar '' 2)
    [void](New-Button 'Clean up' 'Remove folders that do not exist and duplicates' {
        $s = $TbUI.Pages['env'].State
        $seen = @{}; $keep = New-Object System.Collections.Generic.List[string]
        foreach ($p in $s.PathItems) {
            $x = [Environment]::ExpandEnvironmentVariables($p).TrimEnd('\').ToLowerInvariant()
            if (-not $x -or $seen[$x] -or -not (Test-Path -LiteralPath ([Environment]::ExpandEnvironmentVariables($p)))) { continue }
            $seen[$x] = $true; $keep.Add($p)
        }
        $n = $s.PathItems.Count - $keep.Count
        $s.PathItems = $keep; if ($n) { $s.PathDirty = $true }
        Update-PathList $s 0
        Set-TbStatus $s.Status "Removed $n entries. Press Save to keep the change." $(if ($n) { 'warn' } else { '' })
    } $pbar $Glyph.Clear 2)
    $st.PathSave = New-Button 'Save' 'Save this PATH (programs started from now on use it)' { Save-PathList $TbUI.Pages['env'].State } $pbar $Glyph.Save 1
    [void](New-Button 'Undo changes' 'Read the PATH again, dropping unsaved changes' { $s = $TbUI.Pages['env'].State; Read-PathList $s } $pbar $Glyph.Undo 2)
    $st.PathScope.add_SelectedIndexChanged({
        $s = $TbUI.Pages['env'].State
        if ($s.PathDirty -and [System.Windows.Forms.MessageBox]::Show($TbUI.Form, 'Drop your unsaved PATH changes?', 'PATH', 'YesNo', 'Question') -ne 'Yes') { return }
        Read-PathList $s
    })
    Select-ApiTab $tabs 'Variables'
    $st.Focus = { $s = $TbUI.Pages['env'].State; Update-EnvVars $s; if (-not $s.PathItems) { Read-PathList $s } }
    $st.SetInput = { param($t) $TbUI.Pages['env'].State.Filter.Text = $t.Trim() }
    $st
}

function Update-EnvVars($St) {
    $q = $St.Filter.Text.Trim()
    $lv = $St.Vars
    $sel = if ($lv.SelectedItems.Count) { "$($lv.SelectedItems[0].Text)|$($lv.SelectedItems[0].Tag)" } else { '' }
    $lv.BeginUpdate(); $lv.Items.Clear()
    $n = 0
    foreach ($sys in @($false) + @(if ($St.ShowSys.Checked) { $true })) {
        foreach ($kv in [DevEnv]::List($sys).GetEnumerator()) {
            if ($q -and $kv.Key -notlike "*$q*" -and $kv.Value -notlike "*$q*") { continue }
            $it = New-Object System.Windows.Forms.ListViewItem($kv.Key)
            [void]$it.SubItems.Add($kv.Value)
            [void]$it.SubItems.Add($(if ($sys) { 'Everyone' } else { 'You' }))
            $it.Tag = $sys
            if ($sys) { $it.ForeColor = $C.Dim }
            if ("$($kv.Key)|$sys" -eq $sel) { $it.Selected = $true }
            [void]$lv.Items.Add($it); $n++
        }
    }
    $lv.EndUpdate()
    Set-TbStatus $St.Status "$n variables  $Dot  yours can be changed freely; system ones need DevTools to run as administrator$(if (Test-IsAdmin) { ' (it does)' })  $Dot  changes reach programs started afterwards"
}

function Edit-EnvVariable {
    $s = $TbUI.Pages['env'].State
    if (-not $s.Vars.SelectedItems.Count) { return }
    $it = $s.Vars.SelectedItems[0]
    $r = Show-EnvVarDialog $it.Text $it.SubItems[1].Text ([bool]$it.Tag)
    if (-not $r) { return }
    try { [DevEnv]::Set([bool]$it.Tag, $r.Name, $r.Value); Set-TbStatus $s.Status "Saved $($r.Name)." 'ok' } catch { Set-TbStatus $s.Status (Get-EnvErrorText $_) 'error' }
    Update-EnvVars $s
    if ($r.Name -eq 'Path') { Read-PathList $s }
}

function Remove-EnvVariable {
    $s = $TbUI.Pages['env'].State
    if (-not $s.Vars.SelectedItems.Count) { return }
    $it = $s.Vars.SelectedItems[0]
    if ($it.Text -eq 'Path') { Set-TbStatus $s.Status 'PATH is not deleted here; edit it on the PATH tab.' 'warn'; return }
    if ([System.Windows.Forms.MessageBox]::Show($TbUI.Form, "Delete the variable $($it.Text)?", 'Environment', 'YesNo', 'Warning') -ne 'Yes') { return }
    try { [DevEnv]::Set([bool]$it.Tag, $it.Text, $null); Set-TbStatus $s.Status "Deleted $($it.Text)." 'ok' } catch { Set-TbStatus $s.Status (Get-EnvErrorText $_) 'error' }
    Update-EnvVars $s
}

function Read-PathList($St) {
    $raw = [DevEnv]::Get(($St.PathScope.SelectedIndex -eq 1), 'Path')
    $St.PathItems = New-Object System.Collections.Generic.List[string]
    foreach ($p in ([string]$raw -split ';')) { if ($p.Trim()) { $St.PathItems.Add($p.Trim()) } }
    $St.PathDirty = $false
    Update-PathList $St 0
}

function Get-PathIndex($St) { if ($St.PathList.SelectedIndices.Count) { $St.PathList.SelectedIndices[0] } else { -1 } }

function Update-PathList($St, [int]$Select = -1) {
    $lv = $St.PathList
    $lv.BeginUpdate(); $lv.Items.Clear()
    $seen = @{}; $bad = 0
    foreach ($p in $St.PathItems) {
        $x = [Environment]::ExpandEnvironmentVariables($p)
        $key = $x.TrimEnd('\').ToLowerInvariant()
        $it = New-Object System.Windows.Forms.ListViewItem($p)
        $note = if ($seen[$key]) { 'duplicate' } elseif (-not (Test-Path -LiteralPath $x)) { 'missing' } elseif ($x -ne $p) { $x } else { '' }
        if ($note -in 'duplicate', 'missing') { $it.ForeColor = $C.Red; $bad++ }
        [void]$it.SubItems.Add($note)
        $seen[$key] = $true
        [void]$lv.Items.Add($it)
    }
    if ($Select -ge 0 -and $Select -lt $lv.Items.Count) { $lv.Items[$Select].Selected = $true; $lv.EnsureVisible($Select) }
    $lv.EndUpdate()
    $len = ($St.PathItems -join ';').Length
    Set-TbStatus $St.Status "$($St.PathItems.Count) folders  $Dot  $len characters$(if ($bad) { "  $Dot  $bad missing or duplicate (Clean up removes them)" })$(if ($St.PathDirty) { "  $Dot  not saved yet" })" $(if ($St.PathDirty) { 'warn' } else { '' })
}

function Edit-PathEntry {
    $s = $TbUI.Pages['env'].State
    $i = Get-PathIndex $s
    if ($i -lt 0) { return }
    $v = Read-TextDialog 'PATH entry' 'Folder (you can use %VARIABLES%)' $s.PathItems[$i] $TbUI.Form
    if ($null -eq $v -or -not $v.Trim()) { return }
    $s.PathItems[$i] = $v.Trim(); $s.PathDirty = $true
    Update-PathList $s $i
}

function Move-PathEntry([int]$By) {
    $s = $TbUI.Pages['env'].State
    $i = Get-PathIndex $s; $j = $i + $By
    if ($i -lt 0 -or $j -lt 0 -or $j -ge $s.PathItems.Count) { return }
    $x = $s.PathItems[$i]; $s.PathItems[$i] = $s.PathItems[$j]; $s.PathItems[$j] = $x
    $s.PathDirty = $true
    Update-PathList $s $j
}

function Save-PathList($St) {
    $sys = $St.PathScope.SelectedIndex -eq 1
    $value = $St.PathItems -join ';'
    if ($value.Length -gt 32000) { Set-TbStatus $St.Status 'That PATH is too long for Windows.' 'error'; return }
    try {
        [DevEnv]::Set($sys, 'Path', $value)
        $St.PathDirty = $false
        Update-PathList $St (Get-PathIndex $St)
        Set-TbStatus $St.Status "Saved. Programs (and terminals) started from now on use the new PATH." 'ok'
    } catch { Set-TbStatus $St.Status (Get-EnvErrorText $_) 'error' }
}

# ======================================================================================
# Processes and services.
# ======================================================================================
Register-ToolboxPage 'procs' 'Processes & services' $Glyph.Apps 'process task manager kill end memory cpu service start stop restart' {
    param($panel, $st)
    $st.Status = New-TbPage $panel
    $tabs = New-TabSet $panel
    $st.Tabs = $tabs
    # ---- processes
    $pp = Add-ApiTab $tabs 'Processes'
    $lv = New-Object System.Windows.Forms.ListView
    $lv.Dock = 'Fill'; $lv.View = 'Details'; $lv.FullRowSelect = $true; $lv.BorderStyle = 'None'; $lv.HideSelection = $false
    $lv.BackColor = $C.Bg; $lv.ForeColor = $C.Fore
    foreach ($col in @(@('Name', 220), @('PID', 70), @('Memory MB', 100), @('CPU s', 90), @('Threads', 70), @('Window', 380))) { [void]$lv.Columns.Add($col[0], (Px ($col[1] * $TextZoom)), $(if ($col[0] -in 'PID', 'Memory MB', 'CPU s', 'Threads') { 'Right' } else { 'Left' })) }
    $lv.add_ColumnClick({ param($src, $e) $s = $TbUI.Pages['procs'].State; if ($s.PSort -eq $e.Column) { $s.PDesc = -not $s.PDesc } else { $s.PSort = $e.Column; $s.PDesc = $e.Column -in 2, 3, 4 }; Update-ProcList $s })
    $pm = New-Object System.Windows.Forms.ContextMenuStrip -Property @{ Renderer = $MenuRenderer }
    [void](Add-MenuItem $pm 'Copy command line' {
        $s = $TbUI.Pages['procs'].State
        if (-not $s.Procs.SelectedItems.Count) { return }
        $cl = (Get-CimInstance Win32_Process -Filter "ProcessId=$([int]$s.Procs.SelectedItems[0].SubItems[1].Text)" -ErrorAction SilentlyContinue).CommandLine
        if ($cl) { Copy-TbText $cl; Set-TbStatus $s.Status 'Command line copied.' 'ok' } else { Set-TbStatus $s.Status 'Windows did not give the command line (try as administrator).' 'warn' }
    } $Glyph.Copy)
    [void](Add-MenuItem $pm 'Show the program file' {
        $s = $TbUI.Pages['procs'].State
        if (-not $s.Procs.SelectedItems.Count) { return }
        $p = Get-Process -Id ([int]$s.Procs.SelectedItems[0].SubItems[1].Text) -ErrorAction SilentlyContinue
        if ($p -and $p.Path) { Start-Process explorer.exe "/select,`"$($p.Path)`"" } else { Set-TbStatus $s.Status 'Windows did not give the file (try as administrator).' 'warn' }
    } $Glyph.Open)
    [void](Add-MenuItem $pm 'Ports it uses' { $s = $TbUI.Pages['procs'].State; if ($s.Procs.SelectedItems.Count) { Show-Toolbox 'ports' $s.Procs.SelectedItems[0].SubItems[1].Text } } $Glyph.Network)
    [void]$pm.Items.Add('-')
    [void](Add-MenuItem $pm 'End process...' { Stop-SelectedProcess } $Glyph.Delete)
    $lv.ContextMenuStrip = $pm
    $pp.Controls.Add($lv)
    $st.Procs = $lv
    $pbar = New-TbBar $pp
    New-TbLabel $pbar 'Filter' -Dim | Out-Null
    $st.PFilter = New-TbBox -Cue 'name, PID or window title'
    $st.PFilter.Width = Px (260 * $TextZoom); $st.PFilter.Margin = New-Object System.Windows.Forms.Padding(0, (Px 4), (Px 8), 0)
    $pbar.Controls.Add($st.PFilter)
    [void](New-Button 'Refresh' 'Read the process list again' { Update-ProcList $TbUI.Pages['procs'].State -Reload } $pbar $Glyph.Refresh 1)
    [void](New-Button 'End process' 'End the selected process' { Stop-SelectedProcess } $pbar $Glyph.Delete 2)
    $st.PFilter.add_TextChanged({ Update-ProcList $TbUI.Pages['procs'].State })
    $st.PSort = 2; $st.PDesc = $true
    # ---- services
    $sp = Add-ApiTab $tabs 'Services'
    $sv = New-Object System.Windows.Forms.ListView
    $sv.Dock = 'Fill'; $sv.View = 'Details'; $sv.FullRowSelect = $true; $sv.BorderStyle = 'None'; $sv.HideSelection = $false
    $sv.BackColor = $C.Bg; $sv.ForeColor = $C.Fore
    foreach ($col in @(@('Name', 220), @('Display name', 380), @('Status', 100), @('Starts', 110))) { [void]$sv.Columns.Add($col[0], (Px ($col[1] * $TextZoom))) }
    $sv.add_ColumnClick({ param($src, $e) $s = $TbUI.Pages['procs'].State; if ($s.SSort -eq $e.Column) { $s.SDesc = -not $s.SDesc } else { $s.SSort = $e.Column; $s.SDesc = $false }; Update-ServiceList $s })
    $sp.Controls.Add($sv)
    $st.Services = $sv
    $sbar = New-TbBar $sp
    New-TbLabel $sbar 'Filter' -Dim | Out-Null
    $st.SFilter = New-TbBox -Cue 'name or display name'
    $st.SFilter.Width = Px (260 * $TextZoom); $st.SFilter.Margin = New-Object System.Windows.Forms.Padding(0, (Px 4), (Px 8), 0)
    $sbar.Controls.Add($st.SFilter)
    $st.Running = New-CheckBox $sbar 'Running only' $false
    foreach ($a in @(@('Start', 'Start the selected service'), @('Stop', 'Stop the selected service'), @('Restart', 'Restart the selected service'))) {
        $b = New-Button $a[0] $a[1] { param($src, $e) Invoke-ServiceAction $src.Tag } $sbar '' 2
        $b.Tag = $a[0]
    }
    [void](New-Button 'Refresh' 'Read the services again' { Update-ServiceList $TbUI.Pages['procs'].State -Reload } $sbar $Glyph.Refresh 1)
    [void](New-Button 'Services app' 'Open the Windows Services app' { Start-Process services.msc } $sbar $Glyph.Settings 2)
    $st.SFilter.add_TextChanged({ Update-ServiceList $TbUI.Pages['procs'].State })
    $st.Running.add_CheckedChanged({ Update-ServiceList $TbUI.Pages['procs'].State })
    $st.SSort = 0; $st.SDesc = $false
    $tabs.Buttons['Services'].add_Click({ $s = $TbUI.Pages['procs'].State; if (-not $s.SRows) { Update-ServiceList $s -Reload } })
    Select-ApiTab $tabs 'Processes'
    $st.SetInput = { param($t) $TbUI.Pages['procs'].State.PFilter.Text = $t.Trim() }
    $st.Focus = { $s = $TbUI.Pages['procs'].State; Update-ProcList $s -Reload; $s.PFilter.Focus() }
    $st
}

function Update-ProcList($St, [switch]$Reload) {
    if ($Reload -or -not $St.PRows) {
        $St.PRows = @(Get-Process | ForEach-Object {
            $cpu = try { [math]::Round($_.TotalProcessorTime.TotalSeconds, 1) } catch { 0 }
            [pscustomobject]@{ Name = $_.ProcessName; Id = $_.Id; Mem = [math]::Round($_.WorkingSet64 / 1MB, 1); Cpu = $cpu; Threads = $_.Threads.Count; Title = $_.MainWindowTitle }
        })
    }
    $q = $St.PFilter.Text.Trim()
    $rows = @($St.PRows | Where-Object { -not $q -or $_.Name -like "*$q*" -or [string]$_.Id -eq $q -or $_.Title -like "*$q*" })
    $prop = @('Name', 'Id', 'Mem', 'Cpu', 'Threads', 'Title')[$St.PSort]
    $rows = @($rows | Sort-Object -Property @{ Expression = $prop; Descending = [bool]$St.PDesc }, Name)
    $lv = $St.Procs
    $lv.BeginUpdate(); $lv.Items.Clear()
    foreach ($r in $rows) {
        $it = New-Object System.Windows.Forms.ListViewItem($r.Name)
        foreach ($v in $r.Id, $r.Mem.ToString('#,0.0'), $r.Cpu.ToString('#,0.0'), $r.Threads, $r.Title) { [void]$it.SubItems.Add([string]$v) }
        [void]$lv.Items.Add($it)
    }
    $lv.EndUpdate()
    $total = ($St.PRows | Measure-Object Mem -Sum).Sum
    Set-TbStatus $St.Status "$($rows.Count) of $($St.PRows.Count) processes  $Dot  $([math]::Round($total / 1024, 1)) GB in use  $Dot  click a column to sort, right-click for more"
}

function Stop-SelectedProcess {
    $s = $TbUI.Pages['procs'].State
    if (-not $s.Procs.SelectedItems.Count) { return }
    $it = $s.Procs.SelectedItems[0]
    $procId = [int]$it.SubItems[1].Text; $name = $it.Text
    if ($procId -le 4 -or $procId -eq $PID) { Set-TbStatus $s.Status $(if ($procId -eq $PID) { 'That is DevTools itself.' } else { 'That is a Windows system process.' }) 'warn'; return }
    if ([System.Windows.Forms.MessageBox]::Show($TbUI.Form, "End $name (PID $procId)? Unsaved work in it is lost.", 'Processes', 'YesNo', 'Warning') -ne 'Yes') { return }
    try { Stop-Process -Id $procId -Force -ErrorAction Stop; Set-TbStatus $s.Status "Ended $name ($procId)." 'ok' } catch { Set-TbStatus $s.Status "Could not end it: $($_.Exception.Message) (try running DevTools as administrator)" 'error' }
    Start-Sleep -Milliseconds 300
    Update-ProcList $s -Reload
}

function Update-ServiceList($St, [switch]$Reload) {
    if ($Reload -or -not $St.SRows) {
        $St.SRows = @(Get-Service -ErrorAction SilentlyContinue | ForEach-Object {
            $start = try { [string]$_.StartType } catch { '' }
            [pscustomobject]@{ Name = $_.Name; Display = $_.DisplayName; Status = [string]$_.Status; Start = $start }
        })
    }
    $q = $St.SFilter.Text.Trim()
    $rows = @($St.SRows | Where-Object { (-not $St.Running.Checked -or $_.Status -eq 'Running') -and (-not $q -or $_.Name -like "*$q*" -or $_.Display -like "*$q*") })
    $prop = @('Name', 'Display', 'Status', 'Start')[$St.SSort]
    $rows = @($rows | Sort-Object -Property @{ Expression = $prop; Descending = [bool]$St.SDesc }, Name)
    $lv = $St.Services
    $sel = if ($lv.SelectedItems.Count) { $lv.SelectedItems[0].Text } else { '' }
    $lv.BeginUpdate(); $lv.Items.Clear()
    foreach ($r in $rows) {
        $it = New-Object System.Windows.Forms.ListViewItem($r.Name)
        foreach ($v in $r.Display, $r.Status, $r.Start) { [void]$it.SubItems.Add([string]$v) }
        if ($r.Status -eq 'Running') { $it.SubItems[2].ForeColor = $C.Green; $it.UseItemStyleForSubItems = $false } elseif ($r.Start -eq 'Disabled') { $it.ForeColor = $C.Dim }
        if ($r.Name -eq $sel) { $it.Selected = $true }
        [void]$lv.Items.Add($it)
    }
    $lv.EndUpdate()
    Set-TbStatus $St.Status "$($rows.Count) of $($St.SRows.Count) services  $Dot  starting and stopping services needs DevTools to run as administrator$(if (Test-IsAdmin) { ' (it does)' })"
}

function Invoke-ServiceAction([string]$Action) {
    $s = $TbUI.Pages['procs'].State
    if (-not $s.Services.SelectedItems.Count) { Set-TbStatus $s.Status 'Select a service first.' 'warn'; return }
    $name = $s.Services.SelectedItems[0].Text
    if ($Action -ne 'Start' -and [System.Windows.Forms.MessageBox]::Show($TbUI.Form, "$Action the service $name?", 'Services', 'YesNo', 'Question') -ne 'Yes') { return }
    $TbUI.Form.Cursor = 'WaitCursor'
    try {
        switch ($Action) {
            'Start'   { Start-Service -Name $name -ErrorAction Stop }
            'Stop'    { Stop-Service -Name $name -Force -ErrorAction Stop }
            'Restart' { Restart-Service -Name $name -Force -ErrorAction Stop }
        }
        Update-ServiceList $s -Reload
        Set-TbStatus $s.Status "$name - done ($Action)." 'ok'
    } catch {
        $m = $_.Exception.Message
        if ($m -match 'cannot be opened|Access is denied|denied') { $m = 'Windows refused: start DevTools as administrator to control services.' }
        Set-TbStatus $s.Status $m 'error'
    } finally { $TbUI.Form.Cursor = 'Default' }
}

# ======================================================================================
# Timer, stopwatch and Pomodoro. It keeps running when the Toolbox is closed; the tray icon
# shows the time left and a notification pops up when time is up.
# ======================================================================================
$script:Clock = @{ Mode = 'timer'; Running = $false; Started = $null; Done = [TimeSpan]::Zero; Length = [TimeSpan]::FromMinutes(5); Phase = 'work'; Round = 1; Laps = (New-Object System.Collections.Generic.List[string]) }

function Get-ClockElapsed { $Clock.Done + $(if ($Clock.Running) { [datetime]::Now - $Clock.Started } else { [TimeSpan]::Zero }) }

function Format-Clock([TimeSpan]$T, [switch]$Tenths) {
    $neg = $T -lt [TimeSpan]::Zero; $T = $T.Duration()
    $s = if ($T.TotalHours -ge 1) { '{0}:{1:00}:{2:00}' -f [int][math]::Floor($T.TotalHours), $T.Minutes, $T.Seconds } else { '{0:00}:{1:00}' -f $T.Minutes, $T.Seconds }
    if ($Tenths) { $s += '.' + [int][math]::Floor($T.Milliseconds / 100) }
    $(if ($neg) { '-' } else { '' }) + $s
}

function Get-PomodoroLength {
    $m = switch ($Clock.Phase) { 'short' { $Pomodoro.Short } 'long' { $Pomodoro.Long } default { $Pomodoro.Work } }
    [TimeSpan]::FromMinutes($m)
}

function Start-Clock {
    if ($Clock.Running) { return }
    $Clock.Started = [datetime]::Now; $Clock.Running = $true
    $ClockTimer.Start()
    Update-ClockView
}

function Suspend-Clock {
    if (-not $Clock.Running) { return }
    $Clock.Done = Get-ClockElapsed; $Clock.Running = $false
    Update-ClockView
}

function Reset-Clock {
    $Clock.Running = $false; $Clock.Done = [TimeSpan]::Zero; $Clock.Laps.Clear()
    if ($Clock.Mode -eq 'pomodoro') { $Clock.Phase = 'work'; $Clock.Round = 1; $Clock.Length = Get-PomodoroLength }
    Update-ClockView
}

function Set-ClockMode([string]$Mode) {
    $Clock.Mode = $Mode
    if ($Mode -eq 'pomodoro') { $Clock.Phase = 'work'; $Clock.Round = 1 }
    Reset-Clock
    if ($Mode -eq 'timer') { $s = $TbUI.Pages['timer'].State; if ($s) { $Clock.Length = [TimeSpan]::FromSeconds([int]$s.Min.Value * 60 + [int]$s.Sec.Value) } }
    Update-ClockView
}

# Starts a countdown from anywhere (palette, tray).
function Start-Countdown([double]$Minutes) {
    $Clock.Mode = 'timer'; $Clock.Running = $false; $Clock.Done = [TimeSpan]::Zero
    $Clock.Length = [TimeSpan]::FromMinutes($Minutes)
    Start-Clock
    $tray.ShowBalloonTip(2000, 'Timer started', "$(Format-Clock $Clock.Length) - you get a notification when time is up.", 'Info')
}

function Complete-ClockPhase {
    [System.Media.SystemSounds]::Exclamation.Play()
    if ($Clock.Mode -eq 'timer') {
        $Clock.Running = $false; $Clock.Done = $Clock.Length
        $tray.ShowBalloonTip(10000, "Time's up", "Your $(Format-Clock $Clock.Length) timer has finished.", 'Info')
    } else {
        if ($Clock.Phase -eq 'work') {
            $Clock.Phase = if ($Clock.Round % [math]::Max(1, $Pomodoro.Every) -eq 0) { 'long' } else { 'short' }
            $tray.ShowBalloonTip(10000, 'Pomodoro: take a break', "Round $($Clock.Round) done. Break for $(if ($Clock.Phase -eq 'long') { $Pomodoro.Long } else { $Pomodoro.Short }) minutes.", 'Info')
        } else {
            $Clock.Phase = 'work'; $Clock.Round++
            $tray.ShowBalloonTip(10000, 'Pomodoro: back to work', "Round $($Clock.Round): $($Pomodoro.Work) minutes.", 'Info')
        }
        $Clock.Length = Get-PomodoroLength; $Clock.Done = [TimeSpan]::Zero; $Clock.Started = [datetime]::Now
    }
}

$ClockTimer = New-Object System.Windows.Forms.Timer
$ClockTimer.Interval = 200
$ClockTimer.add_Tick({
    if ($Clock.Running -and $Clock.Mode -ne 'stopwatch' -and (Get-ClockElapsed) -ge $Clock.Length) { Complete-ClockPhase }
    Update-ClockView
    if (-not $Clock.Running) { $ClockTimer.Stop() }
})

function Update-ClockView {
    $e = Get-ClockElapsed
    $shown = if ($Clock.Mode -eq 'stopwatch') { $e } else { $Clock.Length - $e }
    if ($shown -lt [TimeSpan]::Zero) { $shown = [TimeSpan]::Zero }
    # tray tooltip while it runs
    if ($tray) {
        $label = switch ($Clock.Mode) { 'stopwatch' { 'Stopwatch' } 'pomodoro' { if ($Clock.Phase -eq 'work') { "Pomodoro $($Clock.Round)" } else { 'Break' } } default { 'Timer' } }
        $want = if ($Clock.Running) { "DevTools - $label $(Format-Clock $shown)" } else { Get-TrayBaseText }
        if ($tray.Text -ne $want) { $tray.Text = $want }
    }
    $s = if ($TbUI.Pages['timer']) { $TbUI.Pages['timer'].State } else { $null }
    if (-not $s -or -not $s.Big -or $s.Big.IsDisposed) { return }
    $s.Big.Text = Format-Clock $shown -Tenths:($Clock.Mode -eq 'stopwatch')
    $s.Big.ForeColor = if ($Clock.Mode -eq 'pomodoro' -and $Clock.Phase -ne 'work') { $C.Green } elseif ($Clock.Running) { $C.Accent } else { $C.Fore }
    $s.Sub.Text = switch ($Clock.Mode) {
        'pomodoro'  { if ($Clock.Phase -eq 'work') { "Round $($Clock.Round)  -  focus" } elseif ($Clock.Phase -eq 'long') { "Long break after round $($Clock.Round)" } else { "Short break after round $($Clock.Round)" } }
        'stopwatch' { if ($Clock.Laps.Count) { "$($Clock.Laps.Count) laps" } else { '' } }
        default     { if ($Clock.Running) { "Ends at $(([datetime]::Now + $shown).ToString('HH:mm:ss'))" } elseif ($e -ge $Clock.Length -and $e -gt [TimeSpan]::Zero) { "Time's up" } else { '' } }
    }
    $s.StartBtn.Text = if ($Clock.Running) { 'Pause' } elseif ($e -gt [TimeSpan]::Zero -and ($Clock.Mode -eq 'stopwatch' -or $e -lt $Clock.Length)) { 'Continue' } else { 'Start' }
    $s.StartBtn.Glyph = if ($Clock.Running) { $Glyph.Pause } else { $Glyph.Play }
    $s.StartBtn.Invalidate()
    $s.Lap.Visible = $Clock.Mode -eq 'stopwatch'
    $s.TimerRow.Visible = $Clock.Mode -eq 'timer'
    $s.PomoRow.Visible = $Clock.Mode -eq 'pomodoro'
    foreach ($b in $s.ModeButtons) { $sel = $b.Tag -eq $Clock.Mode; if ($b.Selected -ne $sel) { $b.Selected = $sel; $b.Invalidate() } }
    if ($s.Laps.Items.Count -ne $Clock.Laps.Count) { $s.Laps.Items.Clear(); foreach ($l in $Clock.Laps) { [void]$s.Laps.Items.Add($l) } }
}

Register-ToolboxPage 'timer' 'Timer & Pomodoro' $Glyph.History 'timer countdown stopwatch pomodoro focus break alarm lap' {
    param($panel, $st)
    $st.Status = New-TbPage $panel
    $st.Laps = New-Object System.Windows.Forms.ListBox
    $st.Laps.Dock = 'Fill'; $st.Laps.BorderStyle = 'None'; $st.Laps.BackColor = $C.Bg; $st.Laps.ForeColor = $C.Fore; $st.Laps.Font = New-Object System.Drawing.Font('Consolas', (Fz 11))
    $panel.Controls.Add($st.Laps)
    $ctl = New-TbBar $panel
    $st.StartBtn = New-Button 'Start' 'Start or pause' { if ($Clock.Running) { Suspend-Clock } else { if ($Clock.Mode -eq 'timer' -and (Get-ClockElapsed) -ge $Clock.Length) { $Clock.Done = [TimeSpan]::Zero }; Start-Clock } } $ctl $Glyph.Play 1
    [void](New-Button 'Reset' 'Back to the start' { Reset-Clock } $ctl $Glyph.Undo 2)
    $st.Lap = New-Button 'Lap' 'Note the current time' { if ($Clock.Mode -eq 'stopwatch') { $Clock.Laps.Insert(0, ('Lap {0,-4} {1}' -f ($Clock.Laps.Count + 1), (Format-Clock (Get-ClockElapsed) -Tenths))); Update-ClockView } } $ctl $Glyph.Add 2
    $st.TimerRow = New-TbBar $panel
    New-TbLabel $st.TimerRow 'Countdown' -Dim | Out-Null
    $st.Min = New-TbNumber $st.TimerRow 5 0 999
    New-TbLabel $st.TimerRow 'min' -Dim | Out-Null
    $st.Sec = New-TbNumber $st.TimerRow 0 0 59
    New-TbLabel $st.TimerRow 's' -Dim | Out-Null
    foreach ($m in 1, 5, 10, 15, 30, 60) {
        $b = New-Button "$m min" "Start a $m-minute countdown" { param($src, $e) $s = $TbUI.Pages['timer'].State; $s.Min.Value = $src.Tag; $s.Sec.Value = 0; Start-Countdown $src.Tag } $st.TimerRow '' 2
        $b.Tag = $m
    }
    $setLen = { $s = $TbUI.Pages['timer'].State; if (-not $Clock.Running -and $Clock.Mode -eq 'timer') { $Clock.Length = [TimeSpan]::FromSeconds([int]$s.Min.Value * 60 + [int]$s.Sec.Value); $Clock.Done = [TimeSpan]::Zero; Update-ClockView } }
    $st.Min.add_ValueChanged($setLen); $st.Sec.add_ValueChanged($setLen)
    $st.PomoRow = New-TbBar $panel
    foreach ($f in @(@('Work', 'Work', 1, 180), @('Short', 'Short break', 1, 60), @('Long', 'Long break', 1, 120), @('Every', 'Long break every', 1, 12))) {
        New-TbLabel $st.PomoRow $f[1] -Dim | Out-Null
        $n = New-TbNumber $st.PomoRow ([int]$Pomodoro[$f[0]]) $f[2] $f[3]
        $n.Tag = $f[0]
        $n.add_ValueChanged({ param($src, $e) $Pomodoro[$src.Tag] = [int]$src.Value; Save-Settings; if (-not $Clock.Running -and $Clock.Mode -eq 'pomodoro' -and (Get-ClockElapsed) -eq [TimeSpan]::Zero) { $Clock.Length = Get-PomodoroLength; Update-ClockView } })
        New-TbLabel $st.PomoRow $(if ($f[0] -eq 'Every') { 'rounds' } else { 'min' }) -Dim | Out-Null
    }
    $st.Sub = New-Object System.Windows.Forms.Label
    $st.Sub.Dock = 'Top'; $st.Sub.Height = $FontMain.Height + (Px 12); $st.Sub.TextAlign = 'MiddleCenter'; $st.Sub.ForeColor = $C.Dim; $st.Sub.Font = New-Object System.Drawing.Font($UiFont, (Fz 12))
    $panel.Controls.Add($st.Sub)
    $st.Big = New-Object System.Windows.Forms.Label
    $st.Big.Dock = 'Top'; $st.Big.Height = Px 150; $st.Big.TextAlign = 'MiddleCenter'
    $st.Big.Font = New-Object System.Drawing.Font('Segoe UI Light', (Fz 60))
    $panel.Controls.Add($st.Big)
    $modes = New-TbBar $panel
    $st.ModeButtons = @()
    foreach ($m in @(@('Timer', 'timer', 'Count down'), @('Stopwatch', 'stopwatch', 'Count up, with laps'), @('Pomodoro', 'pomodoro', 'Focus rounds with short and long breaks'))) {
        $b = New-Button $m[0] $m[2] { param($src, $e) if ($Clock.Running -and [System.Windows.Forms.MessageBox]::Show($TbUI.Form, 'Stop the running clock?', 'Timer', 'YesNo', 'Question') -ne 'Yes') { return }; Set-ClockMode $src.Tag } $modes '' 2
        $b.Tag = $m[1]
        $st.ModeButtons += $b
    }
    # dock order: modes, big time, sub line, settings rows, buttons, laps (fill)
    foreach ($x in $st.Laps, $ctl, $st.PomoRow, $st.TimerRow, $st.Sub, $st.Big, $modes) { $x.SendToBack() }
    $st.Status.SendToBack()
    $st.Focus = { $s = $TbUI.Pages['timer'].State; Update-ClockView; Set-TbStatus $s.Status 'It keeps running when you close the Toolbox; the tray icon shows the time and you are notified when it ends.' }
    $st.SetInput = { param($t) $m = 0.0; if ([double]::TryParse(($t -replace '[^\d.,]', '').Replace(',', '.'), [Globalization.NumberStyles]::Float, [Globalization.CultureInfo]::InvariantCulture, [ref]$m) -and $m -gt 0) { Start-Countdown $m } }
    $st
}


# ======================================================================================
# Mouse mover (keeps you "active": invisible 0-pixel moves, or a 1-pixel nudge) and auto clicker.
# Both run in the background; Esc stops the clicker anywhere.
# ======================================================================================
$Mouse = @{ Mover = $false; Clicker = $false; Moves = 0; Clicks = 0; NextMove = $null; StopAt = $null; LastPos = $null; Started = $null; Countdown = 0 }
$MouseModes = [ordered]@{ 'zero' = 'Move 0 px (nothing visible)'; 'nudge' = 'Nudge 1 px and back'; 'awake' = 'No mouse input, just keep the PC awake' }

function Get-TrayBaseText {
    if ($script:Paused) { 'DevTools (paused)' }
    elseif ($Mouse.Clicker) { 'DevTools - clicking (Esc stops)' }
    elseif ($Mouse.Mover) { 'DevTools - keeping you active' }
    else { 'DevTools - Ctrl+Shift+V' }
}

function Update-MouseTray {
    if (-not $tray -or $Clock.Running) { return }
    $t = Get-TrayBaseText
    if ($tray.Text -ne $t) { $tray.Text = $t }
}

function Start-MouseMover {
    $cfg = $script:MouseCfg
    $Mouse.Mover = $true; $Mouse.Moves = 0; $Mouse.Started = Get-Date
    $Mouse.NextMove = (Get-Date).AddSeconds([int]$cfg.Interval)
    $Mouse.StopAt = if ([int]$cfg.StopMin -gt 0) { (Get-Date).AddMinutes([int]$cfg.StopMin) } else { $null }
    if ($cfg.Awake -or $cfg.Mode -eq 'awake') { [DevMouse]::KeepAwake($true) }
    $MouseTimer.Start()
    Update-MouseTray; Update-MousePage
}

function Stop-MouseMover([string]$Why = '') {
    if (-not $Mouse.Mover) { return }
    $Mouse.Mover = $false
    [DevMouse]::KeepAwake($false)
    if (-not $Mouse.Clicker) { $MouseTimer.Stop() }
    Update-MouseTray; Update-MousePage
    if ($Why) { $tray.ShowBalloonTip(3000, 'Mouse mover stopped', $Why, 'Info') }
}

function Switch-MouseMover { if ($Mouse.Mover) { Stop-MouseMover } else { Start-MouseMover; $tray.ShowBalloonTip(2500, 'Mouse mover on', "Every $($script:MouseCfg.Interval) s: $($MouseModes[$script:MouseCfg.Mode].ToLower()).", 'Info') } }

# Clicker: a short countdown first, so you can point at the target.
function Start-MouseClicker([int]$Delay = 3) {
    if ($Mouse.Clicker) { return }
    $Mouse.Clicker = $true; $Mouse.Clicks = 0; $Mouse.LastPos = $null
    $Mouse.Countdown = $Delay * 1000
    $script:ClickEscOk = $clipHost.AddHotkey(6, 0, [uint32][System.Windows.Forms.Keys]::Escape)
    $ClickTimer.Interval = [math]::Max(50, [int]$script:MouseCfg.ClickMs)
    $MouseTimer.Start()
    if ($Delay -gt 0) { $tray.ShowBalloonTip(2500, 'Clicking starts in 3 s', 'Point at the target. Esc stops the clicker.', 'Info') } else { $ClickTimer.Start() }
    Update-MouseTray; Update-MousePage
}

function Stop-MouseClicker([string]$Why = '') {
    if (-not $Mouse.Clicker) { return }
    $Mouse.Clicker = $false; $Mouse.Countdown = 0
    $ClickTimer.Stop()
    $clipHost.RemoveHotkey(6)
    if (-not $Mouse.Mover) { $MouseTimer.Stop() }
    Update-MouseTray; Update-MousePage
    $tray.ShowBalloonTip(2500, 'Clicker stopped', "$($Mouse.Clicks) clicks$(if ($Why) { " - $Why" })", 'Info')
}

function Invoke-MouseClick {
    $cfg = $script:MouseCfg
    if ($cfg.StopOnMove -and $Mouse.LastPos) {
        $p = [DevMouse]::Cursor()
        if ([math]::Abs($p[0] - $Mouse.LastPos[0]) + [math]::Abs($p[1] - $Mouse.LastPos[1]) -gt 12) { Stop-MouseClicker 'you moved the mouse'; return }
    }
    if ($cfg.Fixed) { [DevMouse]::SetCursor([int]$cfg.X, [int]$cfg.Y) }
    [DevMouse]::Click([string]$cfg.Button, [bool]$cfg.Double)
    $Mouse.Clicks++
    $Mouse.LastPos = if ($cfg.Fixed) { @([int]$cfg.X, [int]$cfg.Y) } else { [DevMouse]::Cursor() }
    if ([int]$cfg.Count -gt 0 -and $Mouse.Clicks -ge [int]$cfg.Count) { Stop-MouseClicker 'done' }
}

$ClickTimer = New-Object System.Windows.Forms.Timer
$ClickTimer.Interval = 500
$ClickTimer.add_Tick({ try { Invoke-MouseClick } catch { Stop-MouseClicker "error: $_" } })

# Once a second: the mover's schedule, the clicker's countdown, the page.
$MouseTimer = New-Object System.Windows.Forms.Timer
$MouseTimer.Interval = 250
$MouseTimer.add_Tick({
    $cfg = $script:MouseCfg
    if ($Mouse.Clicker -and $Mouse.Countdown -gt 0) {
        $Mouse.Countdown -= $MouseTimer.Interval
        if ($Mouse.Countdown -le 0) { $Mouse.Countdown = 0; $ClickTimer.Start() }
    }
    if ($Mouse.Mover) {
        if ($Mouse.StopAt -and (Get-Date) -ge $Mouse.StopAt) { Stop-MouseMover "Stopped after $($cfg.StopMin) minutes." }
        elseif ($cfg.Mode -ne 'awake' -and (Get-Date) -ge $Mouse.NextMove) {
            $Mouse.NextMove = (Get-Date).AddSeconds([int]$cfg.Interval)
            # while you are using the PC yourself nothing is needed
            if (-not $cfg.OnlyIdle -or [DevMouse]::IdleMs() -ge ([int]$cfg.Interval * 1000 - 1500)) {
                if ($cfg.Mode -eq 'nudge') { [DevMouse]::Move(1, 0); [DevMouse]::Move(-1, 0) } else { [DevMouse]::Move(0, 0) }
                $Mouse.Moves++
            }
        }
    }
    Update-MousePage
})

function Update-MousePage {
    $s = if ($TbUI.Pages['mouse']) { $TbUI.Pages['mouse'].State } else { $null }
    if (-not $s -or -not $s.MoverBtn -or $s.MoverBtn.IsDisposed) { return }
    $s.MoverBtn.Text = if ($Mouse.Mover) { 'Stop' } else { 'Start' }
    $s.MoverBtn.Glyph = if ($Mouse.Mover) { $Glyph.Pause } else { $Glyph.Play }
    $s.MoverBtn.Invalidate()
    $s.MoverInfo.Text = if ($Mouse.Mover) {
        $next = if ($script:MouseCfg.Mode -eq 'awake') { 'keeping the PC awake' } else { "next in $([math]::Max(0, [int]($Mouse.NextMove - (Get-Date)).TotalSeconds)) s" }
        "On for $(Format-Clock ((Get-Date) - $Mouse.Started))  $Dot  $($Mouse.Moves) moves  $Dot  $next$(if ($Mouse.StopAt) { "  $Dot  stops at $($Mouse.StopAt.ToString('HH:mm'))" })"
    } else { 'Off' }
    $s.MoverInfo.ForeColor = if ($Mouse.Mover) { $C.Green } else { $C.Dim }
    $s.ClickBtn.Text = if ($Mouse.Clicker) { 'Stop' } else { 'Start (in 3 s)' }
    $s.ClickBtn.Glyph = if ($Mouse.Clicker) { $Glyph.Pause } else { $Glyph.Play }
    $s.ClickBtn.Invalidate()
    $s.ClickInfo.Text = if ($Mouse.Clicker) { if ($Mouse.Countdown -gt 0) { "Starting in $([math]::Ceiling($Mouse.Countdown / 1000)) s - point at the target" } else { "Clicking  $Dot  $($Mouse.Clicks) clicks  $Dot  Esc stops" } } else { "Off$(if ($Mouse.Clicks) { "  $Dot  last run: $($Mouse.Clicks) clicks" })" }
    $s.ClickInfo.ForeColor = if ($Mouse.Clicker) { $C.Accent } else { $C.Dim }
    $s.PointInfo.Text = "x $($script:MouseCfg.X), y $($script:MouseCfg.Y)"
}

function New-MouseRow($Parent) {
    $r = New-Object System.Windows.Forms.FlowLayoutPanel
    $r.AutoSize = $true; $r.WrapContents = $true; $r.BackColor = $Parent.BackColor
    $r.Margin = New-Object System.Windows.Forms.Padding(0, 0, 0, (Px 4))
    $r.MaximumSize = New-Object System.Drawing.Size((Px 1100), 0)
    $Parent.Controls.Add($r)
    $r
}

Register-ToolboxPage 'mouse' 'Mouse mover & clicker' $Glyph.Apps 'mouse mover jiggler keep awake active teams slack idle away status move 0 pixel auto clicker autoclick click' {
    param($panel, $st)
    $st.Status = New-TbPage $panel
    $flow = New-Object System.Windows.Forms.FlowLayoutPanel
    $flow.Dock = 'Fill'; $flow.FlowDirection = 'TopDown'; $flow.WrapContents = $false; $flow.AutoScroll = $true; $flow.BackColor = $panel.BackColor
    $panel.Controls.Add($flow)
    $cfg = $script:MouseCfg
    $save = { Save-Settings }

    # ---- mover
    $r = New-MouseRow $flow
    New-TbLabel $r 'Keep me active (mouse mover)' -Title | Out-Null
    $r = New-MouseRow $flow
    $st.MoverBtn = New-Button 'Start' 'Start or stop the mouse mover' { Switch-MouseMover } $r $Glyph.Play 1
    $st.MoverInfo = New-TbLabel $r 'Off' -Dim
    $r = New-MouseRow $flow
    New-TbLabel $r 'Every' -Dim | Out-Null
    $n = New-TbNumber $r ([int]$cfg.Interval) 5 3600
    $n.add_ValueChanged({ param($src, $e) $script:MouseCfg.Interval = [int]$src.Value; if ($Mouse.Mover) { $Mouse.NextMove = (Get-Date).AddSeconds([int]$src.Value) }; Save-Settings })
    New-TbLabel $r 'seconds' -Dim | Out-Null
    $mode = New-TbCombo $r @($MouseModes.Values) 300
    $mode.SelectedIndex = [math]::Max(0, @($MouseModes.Keys).IndexOf([string]$cfg.Mode))
    $mode.add_SelectedIndexChanged({ param($src, $e) $script:MouseCfg.Mode = @($MouseModes.Keys)[$src.SelectedIndex]; Save-Settings; if ($Mouse.Mover -and $script:MouseCfg.Mode -eq 'awake') { [DevMouse]::KeepAwake($true) } })
    $r = New-MouseRow $flow
    $cb = New-CheckBox $r 'Keep the screen and PC awake' ([bool]$cfg.Awake) 'No screen saver, lock or sleep while it runs'
    $cb.add_CheckedChanged({ param($src, $e) $script:MouseCfg.Awake = $src.Checked; Save-Settings; if ($Mouse.Mover) { [DevMouse]::KeepAwake($src.Checked -or $script:MouseCfg.Mode -eq 'awake') } })
    $cb = New-CheckBox $r 'Only when I''m not using the PC' ([bool]$cfg.OnlyIdle) 'Skip the move while you type or move the mouse yourself'
    $cb.add_CheckedChanged({ param($src, $e) $script:MouseCfg.OnlyIdle = $src.Checked; Save-Settings })
    New-TbLabel $r '   Stop after' -Dim | Out-Null
    $n = New-TbNumber $r ([int]$cfg.StopMin) 0 1440
    $n.add_ValueChanged({ param($src, $e) $script:MouseCfg.StopMin = [int]$src.Value; Save-Settings })
    New-TbLabel $r 'minutes (0 = never)' -Dim | Out-Null
    $r = New-MouseRow $flow
    $h = New-TbLabel $r 'A 0-pixel move doesn''t move the pointer at all, but Windows counts it as you being there: Teams, Slack and Skype stay "Available", and the screen doesn''t lock.' -Dim
    $h.MaximumSize = New-Object System.Drawing.Size((Px 900), 0)

    # ---- clicker
    $r = New-MouseRow $flow
    $r.Margin = New-Object System.Windows.Forms.Padding(0, (Px 18), 0, (Px 4))
    New-TbLabel $r 'Auto clicker' -Title | Out-Null
    $r = New-MouseRow $flow
    $st.ClickBtn = New-Button 'Start (in 3 s)' 'Start clicking after 3 seconds, or stop (Esc stops it anywhere)' { if ($Mouse.Clicker) { Stop-MouseClicker } else { Start-MouseClicker } } $r $Glyph.Play 1
    $st.ClickInfo = New-TbLabel $r 'Off' -Dim
    $r = New-MouseRow $flow
    $btn = New-TbCombo $r @('Left button', 'Right button', 'Middle button') 140
    $btn.SelectedIndex = [math]::Max(0, @('left', 'right', 'middle').IndexOf([string]$cfg.Button))
    $btn.add_SelectedIndexChanged({ param($src, $e) $script:MouseCfg.Button = @('left', 'right', 'middle')[$src.SelectedIndex]; Save-Settings })
    $cb = New-CheckBox $r 'Double-click' ([bool]$cfg.Double)
    $cb.add_CheckedChanged({ param($src, $e) $script:MouseCfg.Double = $src.Checked; Save-Settings })
    New-TbLabel $r '   Every' -Dim | Out-Null
    $n = New-TbNumber $r ([int]$cfg.ClickMs) 50 600000
    $n.Width = Px (90 * $TextZoom); $n.Increment = 50
    $n.add_ValueChanged({ param($src, $e) $script:MouseCfg.ClickMs = [int]$src.Value; $ClickTimer.Interval = [math]::Max(50, [int]$src.Value); Save-Settings })
    New-TbLabel $r 'ms' -Dim | Out-Null
    New-TbLabel $r '   Clicks' -Dim | Out-Null
    $n = New-TbNumber $r ([int]$cfg.Count) 0 1000000
    $n.Width = Px (90 * $TextZoom)
    $n.add_ValueChanged({ param($src, $e) $script:MouseCfg.Count = [int]$src.Value; Save-Settings })
    New-TbLabel $r '(0 = until stopped)' -Dim | Out-Null
    $r = New-MouseRow $flow
    $where = New-TbCombo $r @('Where the mouse is', 'At a fixed point') 180
    $where.SelectedIndex = [int][bool]$cfg.Fixed
    $where.add_SelectedIndexChanged({ param($src, $e) $script:MouseCfg.Fixed = $src.SelectedIndex -eq 1; Save-Settings })
    $st.Where = $where
    $st.PointInfo = New-TbLabel $r '' -Dim
    [void](New-Button 'Pick the point (3 s)' 'Point at the spot within 3 seconds; its position is taken' {
        $s = $TbUI.Pages['mouse'].State
        $s.PickLeft = 3
        $s.PickTimer.Start()
        Set-TbStatus $s.Status 'Point at the spot to click... 3' 'warn'
    } $r $Glyph.View 2)
    $cb = New-CheckBox $r 'Stop when I move the mouse' ([bool]$cfg.StopOnMove) 'Moving the mouse yourself stops the clicker'
    $cb.add_CheckedChanged({ param($src, $e) $script:MouseCfg.StopOnMove = $src.Checked; Save-Settings })
    $st.PickTimer = New-Object System.Windows.Forms.Timer
    $st.PickTimer.Interval = 1000
    $st.PickTimer.add_Tick({
        $s = $TbUI.Pages['mouse'].State
        $s.PickLeft--
        if ($s.PickLeft -gt 0) { Set-TbStatus $s.Status "Point at the spot to click... $($s.PickLeft)" 'warn'; return }
        $s.PickTimer.Stop()
        $p = [DevMouse]::Cursor()
        $script:MouseCfg.X = $p[0]; $script:MouseCfg.Y = $p[1]; $script:MouseCfg.Fixed = $true; Save-Settings
        $s.Where.SelectedIndex = 1
        Update-MousePage
        Set-TbStatus $s.Status "Got it: x $($p[0]), y $($p[1])." 'ok'
    })
    $r = New-MouseRow $flow
    $h = New-TbLabel $r 'Esc stops the clicker in any app. With "Stop when I move the mouse", grabbing the mouse stops it too.' -Dim
    $h.MaximumSize = New-Object System.Drawing.Size((Px 900), 0)

    $st.Close = { $s = $TbUI.Pages['mouse'].State; $s.PickTimer.Dispose() }
    $st.Focus = { Update-MousePage; Set-TbStatus $TbUI.Pages['mouse'].State.Status 'Both keep running when you close the Toolbox. The tray menu has the mouse mover too.' }
    $st
}


# ======================================================================================
# Git: a window for a repository you pick - commit graph, changes, branches, tags, stashes, remotes,
# and any git command. Uses the git.exe already on the PC; without git the window says so and stops.
# ======================================================================================
$GitUI = @{ Form = $null; Exe = $null; Repo = ''; Git = $null; Job = $null; Status = @(); Branch = ''; Busy = $false }

function Get-GitExe { if (-not $GitUI.Exe) { $GitUI.Exe = [DevGit]::Find() }; $GitUI.Exe }

function Write-GitLog([string]$Text, $Color = $null) {
    $o = $GitUI.Log
    if (-not $o -or $o.IsDisposed) { return }
    $o.SelectionStart = $o.TextLength; $o.SelectionLength = 0
    $o.SelectionColor = if ($Color) { $Color } else { $C.Fore }
    $o.AppendText($Text.TrimEnd() + "`n")
    $o.SelectionColor = $C.Fore
    $o.ScrollToCaret()
}

# Runs a quick git command, logs it, and returns the result.
function Invoke-Git([string]$GitArgs, [switch]$Quiet) {
    if (-not $GitUI.Git) { return $null }
    $r = $GitUI.Git.Run($GitArgs)
    if (-not $Quiet -or $r.Code -ne 0) {
        Write-GitLog "> git $GitArgs" $C.Accent
        if ($r.Text) { Write-GitLog $r.Text $(if ($r.Code -ne 0) { $C.Red } else { $null }) }
    }
    $r
}

# Runs a git command that changes something; shows errors; refreshes afterwards.
function Invoke-GitAction([string]$GitArgs, [string]$Done = '') {
    $r = Invoke-Git $GitArgs
    if ($r.Code -ne 0) { Set-GitStatus ("git $(($GitArgs -split ' ')[0]) failed: " + (($r.Err + $r.Out).Trim() -split "`n" | Select-Object -Last 1)) $C.Red }
    elseif ($Done) { Set-GitStatus $Done $C.Green }
    Update-GitAll
    $r
}

# Slow commands (fetch, pull, push, clone) run in the background; the window stays usable.
function Start-GitJob([string]$GitArgs, [string]$Title, [scriptblock]$After = $null, [string]$Dir = '') {
    if ($GitUI.Job) { Set-GitStatus 'Wait for the running git command (or press Stop).' $C.Yellow; return }
    $g = if ($Dir) { New-Object DevGit($GitUI.Exe, $Dir) } else { $GitUI.Git }
    $GitUI.Job = @{ Git = $g; Args = $GitArgs; Title = $Title; After = $After; Started = Get-Date }
    Write-GitLog "> git $GitArgs" $C.Accent
    $g.RunAsync($GitArgs)
    Set-GitStatus "$Title..." $C.Dim
    $GitUI.StopBtn.Visible = $true
    $GitUI.JobTimer.Start()
}

function Complete-GitJob {
    $j = $GitUI.Job
    if (-not $j -or -not $j.Git.Done) {
        if ($j) { Set-GitStatus "$($j.Title)...  $([int]((Get-Date) - $j.Started).TotalSeconds) s" $C.Dim }
        return
    }
    $GitUI.JobTimer.Stop(); $GitUI.Job = $null; $GitUI.StopBtn.Visible = $false
    $r = $j.Git.Last
    if ($r.Text) { Write-GitLog $r.Text $(if ($r.Code -ne 0) { $C.Red } else { $null }) }
    if ($r.Code -eq 0) { Set-GitStatus "$($j.Title): done." $C.Green }
    else {
        $msg = (($r.Err + "`n" + $r.Out).Trim() -split "`n" | Where-Object { $_.Trim() } | Select-Object -Last 2) -join '  '
        if ($msg -match 'could not read Username|Authentication failed|terminal prompts disabled') { $msg = 'Git needs your login for this remote. Sign in once with Git Credential Manager (e.g. run the same command in a terminal), then try again.' }
        Set-GitStatus "$($j.Title) failed: $msg" $C.Red
    }
    if ($j.After) { & $j.After $r }
    if ($GitUI.Git) { Update-GitAll }
}

function Set-GitStatus([string]$Text, $Color) { if ($GitUI.StatusBar) { $GitUI.StatusBar.Text = $Text; if ($Color) { $GitUI.StatusBar.ForeColor = $Color } } }

# ---- opening a repository --------------------------------------------------------------------
function Open-GitRepo([string]$Path) {
    if (-not $Path -or -not (Test-Path -LiteralPath $Path)) { return }
    $probe = New-Object DevGit($GitUI.Exe, $Path)
    $top = $probe.Run('rev-parse --show-toplevel')
    if ($top.Code -ne 0) {
        if ([System.Windows.Forms.MessageBox]::Show($GitUI.Form, "$Path is not a git repository.`n`nCreate one here (git init)?", 'Git', 'YesNo', 'Question') -ne 'Yes') { return }
        $init = $probe.Run('init')
        Write-GitLog "> git init`n$($init.Text)" $C.Accent
        $top = $probe.Run('rev-parse --show-toplevel')
        if ($top.Code -ne 0) { return }
    }
    $root = ($top.Out.Trim()) -replace '/', '\'
    $GitUI.Repo = $root
    $GitUI.Git = New-Object DevGit($GitUI.Exe, $root)
    $script:GitRepos = @(@($root) + @($script:GitRepos | Where-Object { $_ -and $_ -ne $root }) | Select-Object -First 12)
    Save-Settings
    Update-GitRepoCombo
    $GitUI.Form.Text = "Git  -  $root"
    $GitUI.Main.Enabled = $true
    Update-GitAll
}

function Update-GitRepoCombo {
    $cb = $GitUI.RepoBox
    $GitUI.Loading = $true
    try {
        $cb.Items.Clear()
        foreach ($r in $script:GitRepos) { [void]$cb.Items.Add($r) }
        if ($GitUI.Repo) { $cb.SelectedItem = $GitUI.Repo }
    } finally { $GitUI.Loading = $false }
}

# ---- reading the repository -------------------------------------------------------------------
function Update-GitAll {
    if (-not $GitUI.Git -or -not $GitUI.Form) { return }
    $GitUI.Form.Cursor = 'WaitCursor'
    try {
        Update-GitChanges
        Update-GitBranches
        Update-GitGraph
        Update-GitState
    } finally { $GitUI.Form.Cursor = 'Default' }
}

function Get-GitStatusEntries {
    $r = Invoke-Git 'status --porcelain=v1 -b -uall' -Quiet
    $list = @()
    $GitUI.Ahead = 0; $GitUI.Behind = 0; $GitUI.Upstream = ''
    foreach ($line in ($r.Out -split "`n")) {
        if ($line.Length -lt 3) { continue }
        if ($line.StartsWith('## ')) {
            if ($line -match '\.\.\.(\S+)') { $GitUI.Upstream = $Matches[1] }
            if ($line -match 'ahead (\d+)') { $GitUI.Ahead = [int]$Matches[1] }
            if ($line -match 'behind (\d+)') { $GitUI.Behind = [int]$Matches[1] }
            continue
        }
        $x = $line[0]; $y = $line[1]; $path = $line.Substring(3)
        $old = ''
        if ($path -match '^(.*) -> (.*)$') { $old = $Matches[1]; $path = $Matches[2] }
        $path = $path.Trim('"')
        $list += [pscustomobject]@{ X = [string]$x; Y = [string]$y; Path = $path; Old = $old.Trim('"'); Conflict = ("$x$y" -match 'U|AA|DD') }
    }
    $list
}

function Get-GitStatusText([string]$Code) {
    switch ($Code) { 'M' { 'changed' } 'A' { 'added' } 'D' { 'deleted' } 'R' { 'renamed' } 'C' { 'copied' } '?' { 'new' } 'U' { 'conflict' } 'T' { 'type changed' } default { $Code } }
}

function Update-GitChanges {
    $entries = @(Get-GitStatusEntries)
    $GitUI.Status = $entries
    foreach ($pair in @(@($GitUI.Staged, 'staged'), @($GitUI.Unstaged, 'unstaged'))) {
        $lv = $pair[0]
        $sel = @($lv.SelectedItems | ForEach-Object { $_.Tag.Path })
        $lv.BeginUpdate(); $lv.Items.Clear()
        foreach ($e in $entries) {
            $code = if ($pair[1] -eq 'staged') { $e.X } else { $e.Y }
            if ($pair[1] -eq 'staged' -and ($e.X -eq ' ' -or $e.X -eq '?' -or $e.Conflict)) { continue }
            if ($pair[1] -eq 'unstaged' -and $e.Y -eq ' ' -and -not $e.Conflict) { continue }
            if ($e.Conflict) { $code = 'U' }
            $it = New-Object System.Windows.Forms.ListViewItem((Get-GitStatusText $code))
            [void]$it.SubItems.Add($(if ($e.Old) { "$($e.Old) -> $($e.Path)" } else { $e.Path }))
            $it.Tag = $e
            $it.ForeColor = switch ($code) { 'A' { $C.Green } '?' { $C.Green } 'D' { $C.Red } 'U' { $C.Red } default { $C.Fore } }
            if ($sel -contains $e.Path) { $it.Selected = $true }
            [void]$lv.Items.Add($it)
        }
        $lv.EndUpdate()
    }
    $GitUI.StagedLabel.Text = "STAGED ($($GitUI.Staged.Items.Count))"
    $GitUI.UnstagedLabel.Text = "CHANGES ($($GitUI.Unstaged.Items.Count))"
}

function Update-GitBranches {
    $cur = (Invoke-Git 'branch --show-current' -Quiet).Out.Trim()
    if (-not $cur) { $cur = '(detached HEAD) ' + (Invoke-Git 'rev-parse --short HEAD' -Quiet).Out.Trim() }
    $GitUI.Branch = $cur
    $r = Invoke-Git 'for-each-ref --format=%(refname)%1f%(refname:short)%1f%(upstream:short)%1f%(upstream:track)%1f%(committerdate:short)%1f%(objectname:short) refs/heads refs/remotes refs/tags' -Quiet
    $lv = $GitUI.Branches; $tv = $GitUI.Tags
    $lv.BeginUpdate(); $lv.Items.Clear(); $tv.BeginUpdate(); $tv.Items.Clear()
    $locals = @()
    foreach ($line in ($r.Out -split "`n")) {
        $f = $line -split [char]0x1f
        if ($f.Count -lt 6) { continue }
        if ($f[0].StartsWith('refs/tags/')) {
            $it = New-Object System.Windows.Forms.ListViewItem($f[1]); [void]$it.SubItems.Add($f[5]); [void]$it.SubItems.Add($f[4]); $it.Tag = $f[1]
            [void]$tv.Items.Add($it); continue
        }
        if ($f[1] -match '/HEAD$') { continue }
        $remote = $f[0].StartsWith('refs/remotes/')
        $it = New-Object System.Windows.Forms.ListViewItem($(if ($f[1] -eq $cur) { "$([char]0x25CF) $($f[1])" } else { "   $($f[1])" }))
        [void]$it.SubItems.Add($(if ($remote) { 'remote' } else { $f[2] + $(if ($f[3]) { " $($f[3])" }) }))
        [void]$it.SubItems.Add($f[4])
        $it.Tag = [pscustomobject]@{ Name = $f[1]; Remote = $remote; Upstream = $f[2] }
        if ($remote) { $it.ForeColor = $C.Dim } elseif ($f[1] -eq $cur) { $it.Font = New-Object System.Drawing.Font($FontMain, [System.Drawing.FontStyle]::Bold) }
        if (-not $remote) { $locals += $f[1] }
        [void]$lv.Items.Add($it)
    }
    $lv.EndUpdate(); $tv.EndUpdate()
    # branch switcher
    $GitUI.Loading = $true
    try {
        $GitUI.BranchBox.Items.Clear()
        foreach ($b in $locals) { [void]$GitUI.BranchBox.Items.Add($b) }
        if ($locals -contains $cur) { $GitUI.BranchBox.SelectedItem = $cur } else { $GitUI.BranchBox.Text = $cur }
    } finally { $GitUI.Loading = $false }
    # stashes and remotes
    $sv = $GitUI.Stashes
    $sv.BeginUpdate(); $sv.Items.Clear()
    foreach ($line in ((Invoke-Git 'stash list --format=%gd%x1f%s%x1f%cr' -Quiet).Out -split "`n")) {
        $f = $line -split [char]0x1f; if ($f.Count -lt 3) { continue }
        $it = New-Object System.Windows.Forms.ListViewItem($f[0]); [void]$it.SubItems.Add($f[1]); [void]$it.SubItems.Add($f[2]); $it.Tag = $f[0]
        [void]$sv.Items.Add($it)
    }
    $sv.EndUpdate()
    $rv = $GitUI.Remotes
    $rv.BeginUpdate(); $rv.Items.Clear()
    $seen = @{}
    foreach ($line in ((Invoke-Git 'remote -v' -Quiet).Out -split "`n")) {
        if ($line -match '^(\S+)\s+(\S+)\s+\((fetch|push)\)') { if ($seen[$Matches[1]]) { continue }; $seen[$Matches[1]] = 1; $it = New-Object System.Windows.Forms.ListViewItem($Matches[1]); [void]$it.SubItems.Add($Matches[2]); $it.Tag = $Matches[1]; [void]$rv.Items.Add($it) }
    }
    $rv.EndUpdate()
}

function Update-GitGraph {
    $n = @(200, 1000, 5000, 50000)[$GitUI.Depth.SelectedIndex]
    $scope = if ($GitUI.AllRefs.Checked) { '--all' } else { 'HEAD' }
    $r = Invoke-Git "log $scope --topo-order --date=format:`"%Y-%m-%d %H:%M`" `"--format=%H%x1f%h%x1f%P%x1f%an%x1f%ae%x1f%ad%x1f%D%x1f%s%x1e`" -n $n" -Quiet
    $head = (Invoke-Git 'rev-parse HEAD' -Quiet).Out.Trim()
    $keep = if ($GitUI.Graph.Selected -ge 0 -and $GitUI.Graph.Selected -lt $GitUI.Graph.Commits.Count) { $GitUI.Graph.Commits[$GitUI.Graph.Selected].Hash } else { '' }
    $GitUI.Graph.Load($(if ($r.Code -eq 0) { $r.Out } else { '' }), $head)
    if ($keep) { for ($i = 0; $i -lt $GitUI.Graph.Commits.Count; $i++) { if ($GitUI.Graph.Commits[$i].Hash -eq $keep) { $GitUI.Graph.SelectRow($i); break } } }
    Show-GitCommit
}

# merge / rebase / cherry-pick in progress -> banner with Continue / Abort
function Update-GitState {
    $gitDir = (Invoke-Git 'rev-parse --absolute-git-dir' -Quiet).Out.Trim() -replace '/', '\'
    $op = $null
    if (Test-Path (Join-Path $gitDir 'rebase-merge')) { $op = 'rebase' } elseif (Test-Path (Join-Path $gitDir 'rebase-apply')) { $op = 'rebase' }
    elseif (Test-Path (Join-Path $gitDir 'MERGE_HEAD')) { $op = 'merge' } elseif (Test-Path (Join-Path $gitDir 'CHERRY_PICK_HEAD')) { $op = 'cherry-pick' } elseif (Test-Path (Join-Path $gitDir 'REVERT_HEAD')) { $op = 'revert' }
    $GitUI.Op = $op
    $conf = @($GitUI.Status | Where-Object { $_.Conflict }).Count
    $GitUI.Banner.Visible = [bool]$op
    if ($op) { $GitUI.BannerText.Text = "A $op is in progress$(if ($conf) { " - $conf file(s) with conflicts: double-click to open, fix, then Mark resolved" } else { ' - no conflicts left' })." }
    $sync = if ($GitUI.Upstream) { "$Dot  $($GitUI.Upstream)  $([char]0x2191)$($GitUI.Ahead) $([char]0x2193)$($GitUI.Behind)" } else { "$Dot  no upstream (Push sets it)" }
    $GitUI.Info.Text = "On $($GitUI.Branch)  $sync  $Dot  $($GitUI.Status.Count) changed file(s)"
}

function Get-GitSelectedCommit { $g = $GitUI.Graph; if ($g.Selected -ge 0 -and $g.Selected -lt $g.Commits.Count) { $g.Commits[$g.Selected] } else { $null } }

function Show-GitCommit {
    $c = Get-GitSelectedCommit
    $d = $GitUI.Detail; $fl = $GitUI.Files
    $fl.Items.Clear()
    if (-not $c) { $d.Text = ''; return }
    $body = (Invoke-Git "show -s --format=%B $($c.Hash)" -Quiet).Out.Trim()
    $d.Text = "$($c.Hash)`n$($c.Author) <$($c.Email)>   $($c.Date)$(if ($c.Parents.Count -gt 1) { "`nMerge of " + ($c.Parents | ForEach-Object { $_.Substring(0, 7) }) -join ' + ' })$(if ($c.Refs) { "`n$($c.Refs)" })`n`n$body"
    $first = if ($c.Parents.Count) { "$($c.Parents[0])" } else { '' }
    $ns = if ($first) { Invoke-Git "diff --name-status -M $first $($c.Hash)" -Quiet } else { Invoke-Git "show --name-status --format= $($c.Hash)" -Quiet }
    foreach ($line in ($ns.Out -split "`n")) {
        $f = $line -split "`t"; if ($f.Count -lt 2) { continue }
        $it = New-Object System.Windows.Forms.ListViewItem((Get-GitStatusText $f[0].Substring(0, 1)))
        [void]$it.SubItems.Add($(if ($f.Count -ge 3) { "$($f[1]) -> $($f[2])" } else { $f[1] }))
        $it.Tag = [pscustomobject]@{ Path = $f[$f.Count - 1]; Old = $(if ($f.Count -ge 3) { $f[1] } else { $f[1] }) }
        [void]$fl.Items.Add($it)
    }
}

# ---- diffs in the Compare window ---------------------------------------------------------------
function Get-GitBlob([string]$Spec) { $r = Invoke-Git "show $([DevGit]::Q($Spec))" -Quiet; if ($r.Code -eq 0) { $r.Out } else { '' } }

function Show-GitDiff([string]$LeftSpec, [string]$RightSpec, [string]$RightFile = '') {
    $lt = if ($LeftSpec) { Get-GitBlob $LeftSpec } else { '' }
    $rt = if ($RightFile) { if (Test-Path -LiteralPath $RightFile) { Read-TextFile $RightFile } else { '' } } elseif ($RightSpec) { Get-GitBlob $RightSpec } else { '' }
    Show-Compare ([pscustomobject]@{ Kind = 'text'; Text = $lt; Id = '' }) ([pscustomobject]@{ Kind = 'text'; Text = $rt; Id = '' })
}

function Open-GitChangeDiff($Entry, [bool]$Staged) {
    $p = $Entry.Path
    $full = Join-Path $GitUI.Repo $p
    if ($Entry.Conflict) { Start-Process -FilePath $full; return }
    if ($Staged) { Show-GitDiff "HEAD:$(if ($Entry.Old) { $Entry.Old } else { $p })" ":$p" }
    else { Show-GitDiff $(if ($Entry.Y -eq '?') { '' } else { ":$p" }) '' $full }
}

# ---- actions -------------------------------------------------------------------------------------
function Get-GitSelectedPaths($Lv) { @($Lv.SelectedItems | ForEach-Object { $_.Tag.Path }) }
function Join-GitPaths($Paths) { (@($Paths) | ForEach-Object { [DevGit]::Q($_) }) -join ' ' }

function Invoke-GitStage([switch]$All) {
    $paths = if ($All) { @() } else { Get-GitSelectedPaths $GitUI.Unstaged }
    if ($All) { [void](Invoke-GitAction 'add -A') } elseif ($paths) { [void](Invoke-GitAction "add -- $(Join-GitPaths $paths)") }
}
function Invoke-GitUnstage([switch]$All) {
    $paths = if ($All) { @() } else { Get-GitSelectedPaths $GitUI.Staged }
    $hasHead = (Invoke-Git 'rev-parse --verify HEAD' -Quiet).Code -eq 0
    if ($All) { [void](Invoke-GitAction $(if ($hasHead) { 'reset -q HEAD' } else { 'rm -r --cached -q .' })) }
    elseif ($paths) { [void](Invoke-GitAction $(if ($hasHead) { "reset -q HEAD -- $(Join-GitPaths $paths)" } else { "rm --cached -q -- $(Join-GitPaths $paths)" })) }
}
function Invoke-GitDiscard {
    $items = @($GitUI.Unstaged.SelectedItems | ForEach-Object { $_.Tag })
    if (-not $items) { return }
    if ([System.Windows.Forms.MessageBox]::Show($GitUI.Form, "Throw away the changes in $($items.Count) file(s)? New files are deleted. This can't be undone.", 'Git', 'YesNo', 'Warning') -ne 'Yes') { return }
    $new = @($items | Where-Object { $_.Y -eq '?' } | ForEach-Object { $_.Path })
    $tracked = @($items | Where-Object { $_.Y -ne '?' } | ForEach-Object { $_.Path })
    if ($tracked) { [void](Invoke-Git "checkout -- $(Join-GitPaths $tracked)") }
    if ($new) { [void](Invoke-Git "clean -f -- $(Join-GitPaths $new)") }
    Update-GitAll
}

function Invoke-GitCommit([switch]$Push) {
    $msg = $GitUI.Message.Text.Trim()
    $amend = $GitUI.Amend.Checked
    if (-not $msg -and -not $amend) { Set-GitStatus 'Write a commit message first.' $C.Red; [void]$GitUI.Message.Focus(); return }
    if ($GitUI.Staged.Items.Count -eq 0 -and -not $amend) {
        if ($GitUI.Unstaged.Items.Count -eq 0) { Set-GitStatus 'Nothing to commit.' $C.Yellow; return }
        if ([System.Windows.Forms.MessageBox]::Show($GitUI.Form, 'Nothing is staged. Stage all changes and commit them?', 'Git', 'YesNo', 'Question') -ne 'Yes') { return }
        [void](Invoke-Git 'add -A')
    }
    $tmp = [IO.Path]::GetTempFileName()
    [IO.File]::WriteAllText($tmp, $msg, (New-Object System.Text.UTF8Encoding $false))
    try { $r = Invoke-Git "commit $(if ($amend) { '--amend ' })$(if (-not $msg) { '--no-edit' } else { "-F $([DevGit]::Q($tmp))" })" } finally { Remove-Item $tmp -ErrorAction SilentlyContinue }
    if ($r.Code -eq 0) { $GitUI.Message.Text = ''; $GitUI.Amend.Checked = $false; Set-GitStatus 'Committed.' $C.Green; Update-GitAll; if ($Push) { Invoke-GitPush } }
    else { Set-GitStatus "Commit failed: $((($r.Err + $r.Out).Trim() -split "`n")[0])" $C.Red; Update-GitAll }
}

function Invoke-GitPush([switch]$Force) {
    $b = (Invoke-Git 'branch --show-current' -Quiet).Out.Trim()
    if (-not $b) { Set-GitStatus 'You are not on a branch (detached HEAD); create a branch first.' $C.Red; return }
    $hasUp = (Invoke-Git "rev-parse --abbrev-ref $b@{upstream}" -Quiet).Code -eq 0
    $remote = @((Invoke-Git 'remote' -Quiet).Out -split "`n" | Where-Object { $_.Trim() })
    if (-not $remote) { Set-GitStatus 'This repository has no remote. Add one on the Remotes tab.' $C.Red; return }
    $r0 = if ($remote -contains 'origin') { 'origin' } else { $remote[0] }
    $f = if ($Force) { '--force-with-lease ' } else { '' }
    Start-GitJob $(if ($hasUp) { "push $f" } else { "push $f-u $r0 $([DevGit]::Q($b))" }).Trim() 'Pushing'
}

function Read-GitText([string]$Title, [string]$Prompt, [string]$Value = '') { Read-TextDialog $Title $Prompt $Value $GitUI.Form }

function Confirm-Git([string]$Text) { [System.Windows.Forms.MessageBox]::Show($GitUI.Form, $Text, 'Git', 'YesNo', 'Warning') -eq 'Yes' }

function Show-GitCommitMenu($Menu) {
    $Menu.Items.Clear()
    $c = Get-GitSelectedCommit
    if (-not $c) { return }
    $h = $c.Hash; $s = $c.Short
    $Menu.Tag = $c
    [void](Add-MenuItem $Menu "Check out $s (detached)" { $c = $GitUI.Menu.Tag; if (Confirm-Git "Check out $($c.Short)? You will not be on a branch until you create or check out one.") { [void](Invoke-GitAction "checkout $($c.Hash)") } } $Glyph.Open)
    [void](Add-MenuItem $Menu 'Create branch here...' { $c = $GitUI.Menu.Tag; $n = Read-GitText 'New branch' "Branch name (starts at $($c.Short))"; if ($n) { [void](Invoke-GitAction "checkout -b $([DevGit]::Q($n.Trim())) $($c.Hash)" "Now on $($n.Trim()).") } } $Glyph.Add)
    [void](Add-MenuItem $Menu 'Create tag here...' { $c = $GitUI.Menu.Tag; $n = Read-GitText 'New tag' "Tag name (on $($c.Short))" 'v'; if ($n) { [void](Invoke-GitAction "tag $([DevGit]::Q($n.Trim())) $($c.Hash)" "Tagged $($n.Trim()).") } } $Glyph.Add)
    [void]$Menu.Items.Add('-')
    [void](Add-MenuItem $Menu "Merge $s into $($GitUI.Branch)" { $c = $GitUI.Menu.Tag; [void](Invoke-GitAction "merge --no-edit $($c.Hash)") } $Glyph.Compare)
    [void](Add-MenuItem $Menu "Rebase $($GitUI.Branch) onto $s" { $c = $GitUI.Menu.Tag; if (Confirm-Git "Rebase $($GitUI.Branch) onto $($c.Short)? This rewrites its commits.") { [void](Invoke-GitAction "rebase $($c.Hash)") } } $Glyph.Undo)
    [void](Add-MenuItem $Menu "Cherry-pick $s" { $c = $GitUI.Menu.Tag; [void](Invoke-GitAction "cherry-pick $(if ($c.Parents.Count -gt 1) { '-m 1 ' })$($c.Hash)") } $Glyph.Copy)
    [void](Add-MenuItem $Menu "Revert $s" { $c = $GitUI.Menu.Tag; [void](Invoke-GitAction "revert --no-edit $(if ($c.Parents.Count -gt 1) { '-m 1 ' })$($c.Hash)") } $Glyph.Undo)
    $reset = New-Object System.Windows.Forms.ToolStripMenuItem("Reset $($GitUI.Branch) to $s", (New-GlyphImage $Glyph.Undo))
    foreach ($mode in @(@('soft', 'Soft - keep the changes staged'), @('mixed', 'Mixed - keep the changes, unstaged'), @('hard', 'Hard - throw the changes away'))) {
        $it = $reset.DropDownItems.Add($mode[1], $null, { param($src, $e) $c = $GitUI.Menu.Tag; if ($src.Tag -ne 'hard' -or (Confirm-Git "Hard reset to $($c.Short)? Uncommitted changes and later commits on this branch are lost.")) { [void](Invoke-GitAction "reset --$($src.Tag) $($c.Hash)") } })
        $it.Tag = $mode[0]
    }
    $reset.DropDown.Renderer = $MenuRenderer
    [void]$Menu.Items.Add($reset)
    [void]$Menu.Items.Add('-')
    [void](Add-MenuItem $Menu 'Copy hash' { Copy-TbText $GitUI.Menu.Tag.Hash } $Glyph.Copy)
    [void](Add-MenuItem $Menu 'Copy message' { Copy-TbText $GitUI.Menu.Tag.Subject } $Glyph.Copy)
}

function Show-GitBranchMenu($Menu) {
    $Menu.Items.Clear()
    $it = @($GitUI.Branches.SelectedItems)[0]
    if (-not $it) { return }
    $b = $it.Tag; $Menu.Tag = $b
    $name = $b.Name
    if ($b.Remote) {
        $local = $name -replace '^[^/]+/', ''
        [void](Add-MenuItem $Menu "Check out as $local" { $b = $GitUI.Menu.Tag; $l = $b.Name -replace '^[^/]+/', ''; [void](Invoke-GitAction "checkout -b $([DevGit]::Q($l)) --track $([DevGit]::Q($b.Name))" "Now on $l.") } $Glyph.Open)
    } else {
        [void](Add-MenuItem $Menu "Check out $name" { [void](Invoke-GitAction "checkout $([DevGit]::Q($GitUI.Menu.Tag.Name))") } $Glyph.Open)
    }
    if ($name -ne $GitUI.Branch) {
        [void](Add-MenuItem $Menu "Merge $name into $($GitUI.Branch)" { [void](Invoke-GitAction "merge --no-edit $([DevGit]::Q($GitUI.Menu.Tag.Name))") } $Glyph.Compare)
        [void](Add-MenuItem $Menu "Rebase $($GitUI.Branch) onto $name" { if (Confirm-Git "Rebase $($GitUI.Branch) onto $($GitUI.Menu.Tag.Name)? This rewrites its commits.") { [void](Invoke-GitAction "rebase $([DevGit]::Q($GitUI.Menu.Tag.Name))") } } $Glyph.Undo)
    }
    if (-not $b.Remote) {
        [void](Add-MenuItem $Menu 'Rename...' { $o = $GitUI.Menu.Tag.Name; $n = Read-GitText 'Rename branch' 'New name' $o; if ($n -and $n.Trim() -ne $o) { [void](Invoke-GitAction "branch -m $([DevGit]::Q($o)) $([DevGit]::Q($n.Trim()))") } } $Glyph.Edit)
        [void](Add-MenuItem $Menu 'Push this branch' { $n = $GitUI.Menu.Tag.Name; Start-GitJob "push -u origin $([DevGit]::Q($n))" "Pushing $n" } $Glyph.Send)
        [void]$Menu.Items.Add('-')
        [void](Add-MenuItem $Menu 'Delete...' {
            $n = $GitUI.Menu.Tag.Name
            if ($n -eq $GitUI.Branch) { Set-GitStatus 'You can''t delete the branch you are on; check out another one first.' $C.Red; return }
            if (-not (Confirm-Git "Delete the branch $n?")) { return }
            $r = Invoke-Git "branch -d $([DevGit]::Q($n))"
            if ($r.Code -ne 0 -and (Confirm-Git "$n has commits that are not merged anywhere. Delete it anyway (they may be lost)?")) { $r = Invoke-Git "branch -D $([DevGit]::Q($n))" }
            Update-GitAll
        } $Glyph.Delete)
    } else {
        [void]$Menu.Items.Add('-')
        [void](Add-MenuItem $Menu 'Delete on the remote...' { $n = $GitUI.Menu.Tag.Name; $rem = ($n -split '/')[0]; $br = $n.Substring($rem.Length + 1); if (Confirm-Git "Delete the branch $br on $rem?") { Start-GitJob "push $rem --delete $([DevGit]::Q($br))" "Deleting $n" } } $Glyph.Delete)
    }
}

function Show-GitCloneDialog {
    $url = Read-GitText 'Clone a repository' 'Repository URL (https://... or git@...)'
    if (-not $url) { return }
    $d = New-Object System.Windows.Forms.FolderBrowserDialog; $d.Description = 'Folder to clone into (a new subfolder is created)'
    $script:Modal = $true
    try { if ($d.ShowDialog($GitUI.Form) -ne 'OK') { return }; $parent = $d.SelectedPath } finally { $script:Modal = $false; $d.Dispose() }
    $name = ($url.Trim().TrimEnd('/') -split '[/:]')[-1] -replace '\.git$', ''
    $target = Join-Path $parent $name
    $GitUI.CloneTarget = $target
    Start-GitJob "clone --progress $([DevGit]::Q($url.Trim())) $([DevGit]::Q($target))" "Cloning $name" { param($r) if ($r.Code -eq 0) { Open-GitRepo $GitUI.CloneTarget } } $parent
}

# ---- window -------------------------------------------------------------------------------------
function New-GitList($Parent, [string[]]$Cols, [int[]]$Widths) {
    $lv = New-Object System.Windows.Forms.ListView
    $lv.Dock = 'Fill'; $lv.View = 'Details'; $lv.FullRowSelect = $true; $lv.BorderStyle = 'None'; $lv.HideSelection = $false
    $lv.BackColor = $C.Bg; $lv.ForeColor = $C.Fore
    for ($i = 0; $i -lt $Cols.Count; $i++) { [void]$lv.Columns.Add($Cols[$i], (Px ($Widths[$i] * $TextZoom))) }
    $Parent.Controls.Add($lv)
    $lv
}

function Show-Git([string]$Folder = '') {
    Hide-Picker
    if (-not (Get-GitExe)) {
        [void][System.Windows.Forms.MessageBox]::Show("Git isn't installed on this PC, so the Git window is not available.`n`nDevTools doesn't install anything. If you install Git for Windows (git-scm.com) later, this window works straight away.", 'Git', 'OK', 'Information')
        return
    }
    if ($GitUI.Form) { if ($GitUI.Form.WindowState -eq 'Minimized') { $GitUI.Form.WindowState = 'Normal' }; $GitUI.Form.Activate(); if ($Folder) { Open-GitRepo $Folder }; return }

    $f = New-Object System.Windows.Forms.Form
    $f.Text = 'Git'; $f.Icon = $IconActive
    $f.Size = New-Object System.Drawing.Size((Px 1550), (Px 950)); $f.MinimumSize = New-Object System.Drawing.Size((Px 1000), (Px 600))
    $f.StartPosition = 'CenterScreen'; $f.BackColor = $C.Panel; $f.ForeColor = $C.Fore; $f.Font = $FontMain; $f.KeyPreview = $true
    $GitUI.Form = $f

    $main = New-Object System.Windows.Forms.Panel
    $main.Dock = 'Fill'; $main.BackColor = $C.Bg; $main.Enabled = $false
    $f.Controls.Add($main)
    $GitUI.Main = $main

    # bottom: git console + log
    $bottom = New-Object System.Windows.Forms.Panel
    $bottom.Dock = 'Bottom'; $bottom.Height = Px 170; $bottom.BackColor = $C.Panel
    $GitUI.Log = New-TbRtb -ReadOnly; $GitUI.Log.Dock = 'Fill'; $GitUI.Log.Font = New-Object System.Drawing.Font('Consolas', (Fz 9.5))
    $bottom.Controls.Add($GitUI.Log)
    $cbar = New-TbBar $bottom
    New-TbLabel $cbar 'git' -Title | Out-Null
    $GitUI.Cmd = New-TbBox -Mono -Cue 'any git command, e.g.  log --oneline -5   stash push -m wip   bisect start   (Enter runs it)'
    $GitUI.Cmd.Width = Px (700 * $TextZoom); $GitUI.Cmd.Margin = New-Object System.Windows.Forms.Padding(0, (Px 4), (Px 6), 0)
    $cbar.Controls.Add($GitUI.Cmd)
    $GitUI.RunCmd = {
        $t = $GitUI.Cmd.Text.Trim() -replace '^git\s+', ''
        if (-not $t -or -not $GitUI.Git) { return }
        $GitUI.Cmd.Text = ''
        if ($t -match '^(fetch|pull|push|clone|submodule update|lfs)') { Start-GitJob $t "git $($t.Split(' ')[0])" } else { [void](Invoke-GitAction $t) }
    }
    $GitUI.Cmd.add_KeyDown({ param($src, $e) if ($e.KeyCode -eq 'Return') { $e.SuppressKeyPress = $true; & $GitUI.RunCmd } })
    [void](New-Button 'Run' 'Run the git command (Enter)' $GitUI.RunCmd $cbar $Glyph.Play 1)
    [void](New-Button 'Clear' 'Clear the log' { $GitUI.Log.Clear() } $cbar $Glyph.Clear 2)
    $GitUI.StopBtn = New-Button 'Stop' 'Stop the running git command' { if ($GitUI.Job) { $GitUI.Job.Git.Cancel() } } $cbar $Glyph.Cancel 3
    $GitUI.StopBtn.Visible = $false
    $main.Controls.Add($bottom)

    # left: changes / branches / tags / stashes / remotes
    $left = New-Object System.Windows.Forms.Panel
    $left.Dock = 'Left'; $left.Width = Px (370 * $TextZoom); $left.BackColor = $C.Bg
    $tabs = New-TabSet $left
    $pCh = Add-ApiTab $tabs 'Changes'; $pBr = Add-ApiTab $tabs 'Branches'; $pTg = Add-ApiTab $tabs 'Tags'; $pSt = Add-ApiTab $tabs 'Stashes'; $pRm = Add-ApiTab $tabs 'Remotes'
    # changes: staged over unstaged, commit box at the bottom
    $commit = New-Object System.Windows.Forms.Panel
    $commit.Dock = 'Bottom'; $commit.Height = Px 160; $commit.BackColor = $C.Panel; $commit.Padding = New-Object System.Windows.Forms.Padding((Px 6))
    $GitUI.Message = New-TbBox -Multi -Cue 'Commit message (first line = summary)'; $GitUI.Message.Dock = 'Fill'; $GitUI.Message.WordWrap = $true; $GitUI.Message.ScrollBars = 'Vertical'
    $commit.Controls.Add($GitUI.Message)
    $cb2 = New-TbBar $commit 'Bottom'
    [void](New-Button 'Commit' 'Commit the staged changes (Ctrl+Enter)' { Invoke-GitCommit } $cb2 $Glyph.Save 1)
    [void](New-Button 'Commit & push' 'Commit, then push' { Invoke-GitCommit -Push } $cb2 $Glyph.Send 2)
    $GitUI.Amend = New-CheckBox $cb2 'Amend last commit' $false 'Add to the last commit instead of making a new one (empty message keeps its message)'
    $GitUI.Message.add_KeyDown({ param($src, $e) if ($e.Control -and $e.KeyCode -eq 'Return') { $e.SuppressKeyPress = $true; Invoke-GitCommit } })
    $pCh.Controls.Add($commit)
    $chs = New-Object System.Windows.Forms.SplitContainer
    $chs.Dock = 'Fill'; $chs.Orientation = 'Horizontal'; $chs.SplitterWidth = 3; $chs.BackColor = $C.Line; $chs.Panel1.BackColor = $C.Bg; $chs.Panel2.BackColor = $C.Bg
    $pCh.Controls.Add($chs); $chs.BringToFront()
    $GitUI.Staged = New-GitList $chs.Panel1 @('', 'File') @(72, 280)
    $sb1 = New-TbBar $chs.Panel1
    $GitUI.StagedLabel = New-TbLabel $sb1 'STAGED' -Dim
    [void](New-Button 'Unstage' 'Unstage the selected files' { Invoke-GitUnstage } $sb1 '' 2)
    [void](New-Button 'All' 'Unstage everything' { Invoke-GitUnstage -All } $sb1 '' 2)
    $GitUI.Unstaged = New-GitList $chs.Panel2 @('', 'File') @(72, 280)
    $sb2 = New-TbBar $chs.Panel2
    $GitUI.UnstagedLabel = New-TbLabel $sb2 'CHANGES' -Dim
    [void](New-Button 'Stage' 'Stage the selected files (Space)' { Invoke-GitStage } $sb2 '' 2)
    [void](New-Button 'All' 'Stage everything' { Invoke-GitStage -All } $sb2 '' 2)
    [void](New-Button 'Discard' 'Throw away the changes in the selected files' { Invoke-GitDiscard } $sb2 $Glyph.Delete 2)
    foreach ($pair in @(@($GitUI.Staged, $true), @($GitUI.Unstaged, $false))) {
        $pair[0].Tag = $pair[1]
        $pair[0].add_DoubleClick({ param($src, $e) if ($src.SelectedItems.Count) { Open-GitChangeDiff $src.SelectedItems[0].Tag ([bool]$src.Tag) } })
    }
    $GitUI.Unstaged.add_KeyDown({ param($src, $e) if ($e.KeyCode -eq 'Space') { Invoke-GitStage; $e.Handled = $true } })
    $GitUI.Staged.add_KeyDown({ param($src, $e) if ($e.KeyCode -eq 'Space') { Invoke-GitUnstage; $e.Handled = $true } })
    $um = New-Object System.Windows.Forms.ContextMenuStrip -Property @{ Renderer = $MenuRenderer }
    [void](Add-MenuItem $um 'Show the changes' { $i = @($GitUI.Unstaged.SelectedItems)[0]; if ($i) { Open-GitChangeDiff $i.Tag $false } } $Glyph.Compare)
    [void](Add-MenuItem $um 'Stage' { Invoke-GitStage } $Glyph.Add 'Space')
    [void](Add-MenuItem $um 'Mark resolved (stage)' { Invoke-GitStage } $Glyph.Add)
    [void](Add-MenuItem $um 'Open the file' { foreach ($i in $GitUI.Unstaged.SelectedItems) { Start-Process -FilePath (Join-Path $GitUI.Repo $i.Tag.Path) } } $Glyph.Open)
    [void](Add-MenuItem $um 'Show in Explorer' { $i = @($GitUI.Unstaged.SelectedItems)[0]; if ($i) { Start-Process explorer.exe "/select,`"$(Join-Path $GitUI.Repo $i.Tag.Path)`"" } } $Glyph.Folder)
    [void](Add-MenuItem $um 'Add to .gitignore' { foreach ($i in $GitUI.Unstaged.SelectedItems) { Add-Content -LiteralPath (Join-Path $GitUI.Repo '.gitignore') -Value ($i.Tag.Path -replace '\\', '/') }; Update-GitAll } $Glyph.Cancel)
    [void]$um.Items.Add('-')
    [void](Add-MenuItem $um 'Discard changes...' { Invoke-GitDiscard } $Glyph.Delete)
    $GitUI.Unstaged.ContextMenuStrip = $um
    $smn = New-Object System.Windows.Forms.ContextMenuStrip -Property @{ Renderer = $MenuRenderer }
    [void](Add-MenuItem $smn 'Show the changes' { $i = @($GitUI.Staged.SelectedItems)[0]; if ($i) { Open-GitChangeDiff $i.Tag $true } } $Glyph.Compare)
    [void](Add-MenuItem $smn 'Unstage' { Invoke-GitUnstage } $Glyph.Undo 'Space')
    $GitUI.Staged.ContextMenuStrip = $smn
    # branches
    $GitUI.Branches = New-GitList $pBr @('Branch', 'Upstream', 'Date') @(220, 140, 90)
    $bb = New-TbBar $pBr
    [void](New-Button 'New branch...' 'Create a branch from where you are and switch to it' { $n = Read-GitText 'New branch' 'Branch name'; if ($n) { [void](Invoke-GitAction "checkout -b $([DevGit]::Q($n.Trim()))" "Now on $($n.Trim()).") } } $bb $Glyph.Add 2)
    $GitUI.Branches.add_DoubleClick({ $i = @($GitUI.Branches.SelectedItems)[0]; if ($i -and -not $i.Tag.Remote) { [void](Invoke-GitAction "checkout $([DevGit]::Q($i.Tag.Name))") } })
    $bm = New-Object System.Windows.Forms.ContextMenuStrip -Property @{ Renderer = $MenuRenderer }
    $bm.add_Opening({ param($src, $e) $GitUI.Menu = $src; Show-GitBranchMenu $src; if (-not $src.Items.Count) { $e.Cancel = $true } })
    $GitUI.Branches.ContextMenuStrip = $bm
    # tags
    $GitUI.Tags = New-GitList $pTg @('Tag', 'Commit', 'Date') @(200, 90, 100)
    $tb2 = New-TbBar $pTg
    [void](New-Button 'New tag...' 'Tag the current commit' { $n = Read-GitText 'New tag' 'Tag name' 'v'; if ($n) { [void](Invoke-GitAction "tag $([DevGit]::Q($n.Trim()))") } } $tb2 $Glyph.Add 2)
    [void](New-Button 'Push tags' 'Push all tags' { Start-GitJob 'push --tags' 'Pushing tags' } $tb2 $Glyph.Send 2)
    $tm = New-Object System.Windows.Forms.ContextMenuStrip -Property @{ Renderer = $MenuRenderer }
    [void](Add-MenuItem $tm 'Check out' { $i = @($GitUI.Tags.SelectedItems)[0]; if ($i) { [void](Invoke-GitAction "checkout $([DevGit]::Q($i.Tag))") } } $Glyph.Open)
    [void](Add-MenuItem $tm 'Push this tag' { $i = @($GitUI.Tags.SelectedItems)[0]; if ($i) { Start-GitJob "push origin $([DevGit]::Q($i.Tag))" "Pushing $($i.Tag)" } } $Glyph.Send)
    [void](Add-MenuItem $tm 'Delete' { $i = @($GitUI.Tags.SelectedItems)[0]; if ($i -and (Confirm-Git "Delete the tag $($i.Tag) (here, not on the remote)?")) { [void](Invoke-GitAction "tag -d $([DevGit]::Q($i.Tag))") } } $Glyph.Delete)
    $GitUI.Tags.ContextMenuStrip = $tm
    # stashes
    $GitUI.Stashes = New-GitList $pSt @('Stash', 'Message', 'When') @(80, 240, 90)
    $stb = New-TbBar $pSt
    [void](New-Button 'Stash changes...' 'Put your changes aside (new files too) and get a clean working folder' { $n = Read-GitText 'Stash' 'Message (optional)' ''; if ($null -ne $n) { [void](Invoke-GitAction "stash push -u $(if ($n.Trim()) { "-m $([DevGit]::Q($n.Trim()))" })" 'Stashed.') } } $stb $Glyph.Save 2)
    $stm = New-Object System.Windows.Forms.ContextMenuStrip -Property @{ Renderer = $MenuRenderer }
    [void](Add-MenuItem $stm 'Apply (keep the stash)' { $i = @($GitUI.Stashes.SelectedItems)[0]; if ($i) { [void](Invoke-GitAction "stash apply $($i.Tag)") } } $Glyph.Paste)
    [void](Add-MenuItem $stm 'Pop (apply and remove)' { $i = @($GitUI.Stashes.SelectedItems)[0]; if ($i) { [void](Invoke-GitAction "stash pop $($i.Tag)") } } $Glyph.Paste)
    [void](Add-MenuItem $stm 'Show the changes' { $i = @($GitUI.Stashes.SelectedItems)[0]; if ($i) { $r = Invoke-Git "stash show -p --include-untracked $($i.Tag)" -Quiet; Show-Compare ([pscustomobject]@{ Kind = 'text'; Text = $r.Out; Id = '' }) $null } } $Glyph.Compare)
    [void](Add-MenuItem $stm 'Drop' { $i = @($GitUI.Stashes.SelectedItems)[0]; if ($i -and (Confirm-Git "Delete $($i.Tag)? Its changes are lost.")) { [void](Invoke-GitAction "stash drop $($i.Tag)") } } $Glyph.Delete)
    $GitUI.Stashes.ContextMenuStrip = $stm
    # remotes
    $GitUI.Remotes = New-GitList $pRm @('Remote', 'URL') @(110, 300)
    $rb = New-TbBar $pRm
    [void](New-Button 'Add...' 'Add a remote' { $n = Read-GitText 'Add remote' 'Name' 'origin'; if (-not $n) { return }; $u = Read-GitText 'Add remote' 'URL'; if ($u) { [void](Invoke-GitAction "remote add $([DevGit]::Q($n.Trim())) $([DevGit]::Q($u.Trim()))") } } $rb $Glyph.Add 2)
    $rmm = New-Object System.Windows.Forms.ContextMenuStrip -Property @{ Renderer = $MenuRenderer }
    [void](Add-MenuItem $rmm 'Change URL...' { $i = @($GitUI.Remotes.SelectedItems)[0]; if (-not $i) { return }; $u = Read-GitText 'Remote URL' $i.Tag $i.SubItems[1].Text; if ($u) { [void](Invoke-GitAction "remote set-url $($i.Tag) $([DevGit]::Q($u.Trim()))") } } $Glyph.Edit)
    [void](Add-MenuItem $rmm 'Fetch this remote' { $i = @($GitUI.Remotes.SelectedItems)[0]; if ($i) { Start-GitJob "fetch --prune $($i.Tag)" "Fetching $($i.Tag)" } } $Glyph.Refresh)
    [void](Add-MenuItem $rmm 'Copy URL' { $i = @($GitUI.Remotes.SelectedItems)[0]; if ($i) { Copy-TbText $i.SubItems[1].Text } } $Glyph.Copy)
    [void](Add-MenuItem $rmm 'Remove' { $i = @($GitUI.Remotes.SelectedItems)[0]; if ($i -and (Confirm-Git "Remove the remote $($i.Tag)? (Nothing on the server changes.)")) { [void](Invoke-GitAction "remote remove $($i.Tag)") } } $Glyph.Delete)
    $GitUI.Remotes.ContextMenuStrip = $rmm
    Select-ApiTab $tabs 'Changes'
    $main.Controls.Add($left)

    # right: commit details
    $right = New-Object System.Windows.Forms.SplitContainer
    $right.Dock = 'Right'; $right.Width = Px (380 * $TextZoom); $right.Orientation = 'Horizontal'; $right.SplitterWidth = 3
    $right.BackColor = $C.Line; $right.Panel1.BackColor = $C.Bg; $right.Panel2.BackColor = $C.Bg
    $GitUI.Detail = New-TbRtb -ReadOnly; $GitUI.Detail.Dock = 'Fill'; $GitUI.Detail.WordWrap = $true
    $right.Panel1.Controls.Add($GitUI.Detail)
    $GitUI.Files = New-GitList $right.Panel2 @('', 'Files in this commit (double-click: compare)') @(72, 300)
    $GitUI.Files.add_DoubleClick({
        $i = @($GitUI.Files.SelectedItems)[0]; $c = Get-GitSelectedCommit
        if (-not $i -or -not $c) { return }
        $parent = if ($c.Parents.Count) { $c.Parents[0] } else { '' }
        Show-GitDiff $(if ($parent) { "$($parent):$($i.Tag.Old)" } else { '' }) "$($c.Hash):$($i.Tag.Path)"
    })
    $main.Controls.Add($right)

    # centre: the graph
    $center = New-Object System.Windows.Forms.Panel
    $center.Dock = 'Fill'; $center.BackColor = $C.Bg
    $g = New-Object DevGitGraph
    $g.Dock = 'Fill'; $g.UiScale = $Scale * $TextZoom; $g.Font = $FontMain
    $g.Back = $C.Bg; $g.Fore = $C.Fore; $g.Dim = $C.Dim; $g.Sel = $C.Sel; $g.Line = $C.Line; $g.Accent = $C.Accent
    $g.add_SelectionChanged({ Show-GitCommit })
    $g.add_Open({ $i = $GitUI.Files.Items; if ($i.Count) { $GitUI.Files.Items[0].Selected = $true } })
    $gm = New-Object System.Windows.Forms.ContextMenuStrip -Property @{ Renderer = $MenuRenderer }
    $gm.add_Opening({ param($src, $e) $GitUI.Menu = $src; Show-GitCommitMenu $src; if (-not $src.Items.Count) { $e.Cancel = $true } })
    $g.ContextMenuStrip = $gm
    $center.Controls.Add($g)
    $GitUI.Graph = $g
    $gbar = New-TbBar $center
    $GitUI.AllRefs = New-CheckBox $gbar 'All branches' $true 'Show every branch, or only the history of the current one'
    $GitUI.AllRefs.Margin = New-Object System.Windows.Forms.Padding((Px 4), (Px 8), (Px 8), 0)
    $GitUI.AllRefs.add_CheckedChanged({ Update-GitGraph })
    $GitUI.Depth = New-TbCombo $gbar @('200 commits', '1000 commits', '5000 commits', 'all commits') 130
    $GitUI.Depth.SelectedIndex = 1
    $GitUI.Depth.add_SelectedIndexChanged({ if ($GitUI.Git) { Update-GitGraph } })
    $GitUI.Find = New-TbBox -Cue 'find a commit: text, hash, author, branch (Enter = next)'
    $GitUI.Find.Width = Px (330 * $TextZoom); $GitUI.Find.Margin = New-Object System.Windows.Forms.Padding(0, (Px 4), (Px 6), 0)
    $GitUI.Find.add_KeyDown({ param($src, $e) if ($e.KeyCode -eq 'Return') { $e.SuppressKeyPress = $true; $i = $GitUI.Graph.FindNext($src.Text, $GitUI.Graph.Selected); if ($i -ge 0) { $GitUI.Graph.SelectRow($i) } else { Set-GitStatus 'No commit matches.' $C.Yellow } } })
    $gbar.Controls.Add($GitUI.Find)
    # banner for merges / rebases in progress
    $banner = New-TbBar $center
    $banner.BackColor = $C.Yellow; $banner.Visible = $false
    $GitUI.BannerText = New-TbLabel $banner '' -Title
    $GitUI.BannerText.ForeColor = [System.Drawing.Color]::Black
    [void](New-Button 'Continue' 'Continue after fixing the conflicts (and staging them)' { $op = $GitUI.Op; [void](Invoke-GitAction "-c core.editor=true $op --continue") } $banner '' 1)
    [void](New-Button 'Abort' 'Stop and go back to how it was before' { $op = $GitUI.Op; if (Confirm-Git "Abort the $op?") { [void](Invoke-GitAction "$op --abort") } } $banner '' 3)
    $GitUI.Banner = $banner
    $main.Controls.Add($center)
    $center.BringToFront()

    # top bar
    $top = New-Object System.Windows.Forms.FlowLayoutPanel
    $top.Dock = 'Top'; $top.AutoSize = $true; $top.WrapContents = $true; $top.BackColor = $C.Panel
    $top.Padding = New-Object System.Windows.Forms.Padding((Px 8), (Px 6), (Px 8), (Px 4))
    New-TbLabel $top 'Repository' -Dim | Out-Null
    $GitUI.RepoBox = New-TbCombo $top @() 320
    $GitUI.RepoBox.add_SelectedIndexChanged({ param($src, $e) if (-not $GitUI.Loading -and $src.SelectedItem) { Open-GitRepo ([string]$src.SelectedItem) } })
    [void](New-Button 'Open...' 'Open a folder (a new repository can be created there)' {
        $d = New-Object System.Windows.Forms.FolderBrowserDialog; $d.Description = 'Repository folder'
        if ($GitUI.Repo) { $d.SelectedPath = $GitUI.Repo }
        $script:Modal = $true
        try { if ($d.ShowDialog($GitUI.Form) -eq 'OK') { Open-GitRepo $d.SelectedPath } } finally { $script:Modal = $false; $d.Dispose() }
    } $top $Glyph.Folder 2)
    [void](New-Button 'Clone...' 'Clone a repository from a URL' { Show-GitCloneDialog } $top $Glyph.Add 2)
    New-TbLabel $top '   Branch' -Dim | Out-Null
    $GitUI.BranchBox = New-TbCombo $top @() 200
    $GitUI.BranchBox.add_SelectedIndexChanged({ param($src, $e) if (-not $GitUI.Loading -and $src.SelectedItem -and [string]$src.SelectedItem -ne $GitUI.Branch) { [void](Invoke-GitAction "checkout $([DevGit]::Q([string]$src.SelectedItem))" "Now on $($src.SelectedItem).") } })
    [void](New-Button 'Fetch' 'Download what is new on the remotes (doesn''t change your files)' { Start-GitJob 'fetch --all --prune' 'Fetching' } $top $Glyph.Refresh 2)
    [void](New-Button 'Pull' 'Fetch and bring the remote changes into this branch' { Start-GitJob 'pull' 'Pulling' } $top $Glyph.Undo 2)
    [void](New-Button 'Push' 'Send your commits to the remote (sets the upstream the first time)' { Invoke-GitPush } $top $Glyph.Send 1)
    [void](New-Button 'Force push...' 'Overwrite the remote branch (with lease: refuses if someone else pushed meanwhile)' { if (Confirm-Git "Force push $($GitUI.Branch)? Commits on the remote that you don't have are replaced.") { Invoke-GitPush -Force } } $top '' 2)
    [void](New-Button 'Refresh' 'Read everything again (F5)' { Update-GitAll } $top $Glyph.Refresh 2)
    [void](New-Button 'Explorer' 'Open the folder' { if ($GitUI.Repo) { Start-Process explorer.exe $GitUI.Repo } } $top $Glyph.Folder 2)
    [void](New-Button 'Terminal' 'Open a PowerShell window in the folder' { if ($GitUI.Repo) { Start-Process powershell.exe -WorkingDirectory $GitUI.Repo } } $top $Glyph.Code 2)
    $f.Controls.Add($top)
    $info = New-Object System.Windows.Forms.Label
    $info.Dock = 'Top'; $info.Height = $FontMain.Height + (Px 10); $info.TextAlign = 'MiddleLeft'; $info.ForeColor = $C.Fore; $info.BackColor = $C.Panel
    $info.Padding = New-Object System.Windows.Forms.Padding((Px 12), 0, 0, 0)
    $f.Controls.Add($info); $info.BringToFront(); $main.BringToFront()
    $GitUI.Info = $info
    $status = New-Object System.Windows.Forms.Label
    $status.Dock = 'Bottom'; $status.Height = $FontMain.Height + (Px 10); $status.TextAlign = 'MiddleLeft'; $status.ForeColor = $C.Dim; $status.BackColor = $C.Panel
    $status.Padding = New-Object System.Windows.Forms.Padding((Px 10), 0, 0, 0)
    $f.Controls.Add($status)
    $GitUI.StatusBar = $status
    $top.SendToBack(); $status.SendToBack()

    $GitUI.JobTimer = New-Object System.Windows.Forms.Timer
    $GitUI.JobTimer.Interval = 300
    $GitUI.JobTimer.add_Tick({ Complete-GitJob })
    # changes made outside (editor, terminal) show up when you come back to the window
    $f.add_Activated({ if ($GitUI.Git -and -not $GitUI.Job -and -not $script:Modal) { Update-GitChanges; Update-GitState } })
    $f.add_KeyDown({ param($src, $e) if ($e.KeyCode -eq 'F5') { Update-GitAll; $e.Handled = $true } })
    $f.add_FormClosed({ param($src, $e) if ($GitUI.Job) { $GitUI.Job.Git.Cancel() }; $GitUI.JobTimer.Dispose(); $GitUI.Form = $null; $GitUI.Git = $null; $GitUI.Repo = ''; $GitUI.Job = $null; $src.Dispose() })
    Register-ThemedWindow $f

    Write-GitLog "git: $($GitUI.Exe)" $C.Dim
    Update-GitRepoCombo
    $f.Show()
    [PowerClipHost]::EnsureShown($f.Handle)
    $start = if ($Folder) { $Folder } elseif (@($script:GitRepos).Count) { @($script:GitRepos)[0] } else { '' }
    if ($start -and (Test-Path -LiteralPath $start)) { Open-GitRepo $start } else { Set-GitStatus 'Open a repository folder (Open...), or Clone one.' $C.Dim }
    $f.Activate()
}

# ---------------------------------------------------------------------------
# Smart clip actions: recognise what a text clip is (JSON, JWT, URL, GUID, timestamp, colour, cron,
# Base64, file path, email, IP / host) and offer one-click actions for it. Shown as a badge in the
# list, at the top of the right-click menu and behind the Actions button (Ctrl+.).
# ---------------------------------------------------------------------------
$script:SmartCache = @{}

function New-SmartAction([string]$Title, [string]$Icon, [scriptblock]$Run) { [pscustomobject]@{ Title = $Title; Icon = $Icon; Run = $Run } }

# Copies a result; it lands in the history like any other copy.
function Set-SmartResult([string]$Text, [string]$What) {
    if ($null -eq $Text) { return }
    try { [System.Windows.Forms.Clipboard]::SetText($(if ($Text) { $Text } else { ' ' })) } catch { return }
    if ($form.Visible) { $status.Text = "Copied: $What"; $status.ForeColor = $C.Accent }
}

function Get-SmartInfo($Item) {
    if (-not $Item -or $Item.Kind -ne 'text' -or -not $Item.Text) { return $null }
    $key = $Item.Id
    $cached = $script:SmartCache[$key]
    if ($cached -and $cached.Length -eq $Item.Text.Length) { return $cached.Info }
    $info = Find-SmartInfo $Item.Text
    $script:SmartCache[$key] = @{ Length = $Item.Text.Length; Info = $info }
    $info
}

function ConvertTo-TableFormat([string]$Text) { if (($Text -split '\r?\n')[0].Contains("`t")) { 'tsv' } else { 'csv' } }

function Find-SmartInfo([string]$Text) {
    if ($Text.Length -gt 2MB) { return $null }
    $t = $Text.Trim()
    if (-not $t) { return $null }
    $single = $t.IndexOf("`n") -lt 0
    $A = New-Object System.Collections.Generic.List[object]

    # JWT
    $jwt = $t -replace '^(?i)bearer\s+', ''
    if ($single -and $jwt -match '^eyJ[\w-]+\.[\w-]+\.[\w-]*$') {
        $A.Add((New-SmartAction 'Decode JWT' $Glyph.Lock { param($x) Show-Toolbox 'jwt' $x }))
        return @{ Badge = 'JWT'; Actions = $A }
    }
    # JSON
    if (($t.StartsWith('{') -and $t.EndsWith('}')) -or ($t.StartsWith('[') -and $t.EndsWith(']'))) {
        $v = $null
        if ([DevJson]::TryParse($t, [ref]$v)) {
            $A.Add((New-SmartAction 'Copy formatted JSON' $Glyph.Code { param($x) Set-SmartResult ([DevJson]::Format($x, 2)) 'formatted JSON' }))
            $A.Add((New-SmartAction 'Copy minified JSON' $Glyph.Code { param($x) Set-SmartResult ([DevJson]::Minify($x)) 'minified JSON' }))
            $A.Add((New-SmartAction 'Open in the JSON tool' $Glyph.Toolbox { param($x) Show-Toolbox 'json' $x }))
            return @{ Badge = 'JSON'; Actions = $A }
        }
    }
    # Table: tab-separated (Excel, databases, Sheets) or CSV with the same number of columns on every line
    if (-not $single) {
        $tl = @($t -split '\r?\n' | Select-Object -First 30)
        $kind = $null
        foreach ($cand in @(@("`t", 'tsv'), @(',', 'csv'), @(';', 'csv'))) {
            $counts = @($tl | ForEach-Object { $_.Split($cand[0]).Count - 1 } | Sort-Object -Unique)
            if ($counts.Count -eq 1 -and $counts[0] -ge 1) { $kind = $cand[1]; break }
        }
        if ($kind) {
            $A.Add((New-SmartAction 'Copy as JSON' $Glyph.Code { param($x) Set-SmartResult ([DevData]::Write([DevData]::Parse($x, (ConvertTo-TableFormat $x)), 'json', 2, $false)) 'JSON' }))
            $A.Add((New-SmartAction 'Copy as YAML' $Glyph.Code { param($x) Set-SmartResult ([DevData]::Write([DevData]::Parse($x, (ConvertTo-TableFormat $x)), 'yaml', 2, $false)) 'YAML' }))
            $A.Add((New-SmartAction 'Copy as XML' $Glyph.Code { param($x) Set-SmartResult ([DevData]::Write([DevData]::Parse($x, (ConvertTo-TableFormat $x)), 'xml', 2, $false)) 'XML' }))
            if ($kind -eq 'tsv') { $A.Add((New-SmartAction 'Copy as CSV' $Glyph.Code { param($x) Set-SmartResult ([DevData]::Write([DevData]::Parse($x, 'tsv'), 'csv', 2, $false)) 'CSV' })) }
            else { $A.Add((New-SmartAction 'Copy as tab-separated (for Excel)' $Glyph.Code { param($x) Set-SmartResult ([DevData]::Write([DevData]::Parse($x, 'csv'), 'tsv', 2, $false)) 'tab-separated text' })) }
            $A.Add((New-SmartAction 'Copy as a Markdown table' $Glyph.Document { param($x) Set-SmartResult ([DevData]::MarkdownTable($x, $(if ((ConvertTo-TableFormat $x) -eq 'tsv') { [char]9 } else { [char]0 }))) 'Markdown table' }))
            $A.Add((New-SmartAction 'Open in the converter' $Glyph.Toolbox { param($x) Show-Toolbox 'json' $x }))
            return @{ Badge = $kind.ToUpper(); Actions = $A }
        }
    }
    if ($single) {
        # URL
        if ($t -match '^(https?)://[^\s/$.?#][^\s]*$') {
            $A.Add((New-SmartAction 'Open in the browser' $Glyph.Globe { param($x) try { Start-Process $x.Trim() } catch { } }))
            $A.Add((New-SmartAction 'Open in the API tester' $Glyph.Globe { param($x) Open-ApiText $x.Trim() }))
            if ($Matches[1] -eq 'https') { $A.Add((New-SmartAction 'Check its certificate' $Glyph.Lock { param($x) Show-Toolbox 'cert' $x.Trim() })) }
            $A.Add((New-SmartAction 'Copy URL-decoded' $Glyph.Code { param($x) Set-SmartResult ([Uri]::UnescapeDataString($x.Trim())) 'decoded URL' }))
            $A.Add((New-SmartAction 'Make a QR code' $Glyph.Apps { param($x) Show-Toolbox 'qr' $x.Trim() }))
            return @{ Badge = 'URL'; Actions = $A }
        }
        # Email
        if ($t -match '^[^@\s]+@[^@\s]+\.[A-Za-z]{2,}$') {
            $A.Add((New-SmartAction 'Write an email' $Glyph.Send { param($x) try { Start-Process "mailto:$($x.Trim())" } catch { } }))
            return @{ Badge = 'Email'; Actions = $A }
        }
        # GUID
        if ($t -match '^\{?[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}\}?$') {
            $A.Add((New-SmartAction 'Copy in UPPER case' $Glyph.Copy { param($x) Set-SmartResult $x.Trim().ToUpper() 'GUID in upper case' }))
            $A.Add((New-SmartAction 'Copy in lower case' $Glyph.Copy { param($x) Set-SmartResult $x.Trim().ToLower() 'GUID in lower case' }))
            $A.Add((New-SmartAction 'Copy without dashes' $Glyph.Copy { param($x) Set-SmartResult ($x.Trim().Trim('{', '}') -replace '-', '') 'GUID without dashes' }))
            return @{ Badge = 'GUID'; Actions = $A }
        }
        # Unix timestamp (seconds or milliseconds, years 2001-2040)
        if ($t -match '^\d{10}$|^\d{13}$') {
            $n = [long]$t
            $ms = $t.Length -eq 13
            $dto = if ($ms) { [DateTimeOffset]::FromUnixTimeMilliseconds($n) } else { [DateTimeOffset]::FromUnixTimeSeconds($n) }
            if ($dto.Year -ge 2001 -and $dto.Year -le 2040) {
                $local = $dto.LocalDateTime.ToString('yyyy-MM-dd HH:mm:ss'); $utc = $dto.UtcDateTime.ToString('yyyy-MM-ddTHH:mm:ssZ')
                $A.Add((New-SmartAction "Copy as local time  ($local)" $Glyph.History ([scriptblock]::Create("Set-SmartResult '$local' 'local time'"))))
                $A.Add((New-SmartAction "Copy as UTC  ($utc)" $Glyph.History ([scriptblock]::Create("Set-SmartResult '$utc' 'UTC time'"))))
                return @{ Badge = 'Time'; Actions = $A; Tip = "$local ($(Format-Relative $dto.LocalDateTime))" }
            }
        }
        # Colour
        if ($t -match '^#([0-9a-fA-F]{3}|[0-9a-fA-F]{6}|[0-9a-fA-F]{8})$|^(rgba?|hsla?)\(') {
            $col = ConvertFrom-ColorText $t
            if ($col) {
                $fmt = Get-ColorFormats $col
                $A.Add((New-SmartAction 'Open in the colour picker' $Glyph.Color { param($x) Show-Toolbox 'color' $x }))
                $A.Add((New-SmartAction "Copy as $($fmt.RGB)" $Glyph.Copy ([scriptblock]::Create("Set-SmartResult '$($fmt.RGB)' 'RGB colour'"))))
                $A.Add((New-SmartAction "Copy as $($fmt.HEX)" $Glyph.Copy ([scriptblock]::Create("Set-SmartResult '$($fmt.HEX)' 'HEX colour'"))))
                $A.Add((New-SmartAction "Copy as $($fmt.HSL)" $Glyph.Copy ([scriptblock]::Create("Set-SmartResult '$($fmt.HSL)' 'HSL colour'"))))
                return @{ Badge = 'Colour'; Actions = $A; Color = $col }
            }
        }
        # Cron
        if ($t -match '^@(yearly|annually|monthly|weekly|daily|midnight|hourly)$' -or ($t -match '^[\d\*/,\-\?A-Za-z]+(\s+[\d\*/,\-\?A-Za-z]+){4,5}$' -and $t -match '[\*/]')) {
            try {
                $cron = [DevCron]::Parse($t)
                $A.Add((New-SmartAction 'Explain this schedule' $Glyph.History { param($x) Show-Toolbox 'cron' $x }))
                return @{ Badge = 'Cron'; Actions = $A; Tip = $cron.Describe() }
            } catch { }
        }
        # IP address / host:port
        if ($t -match '^(\d{1,3}(\.\d{1,3}){3})(:\d{1,5})?$' -or $t -match '^[A-Za-z0-9-]+(\.[A-Za-z0-9-]+)+:\d{1,5}$') {
            $A.Add((New-SmartAction 'Ping / test in Network tools' $Glyph.Network { param($x) [void](Show-Network $x.Trim()) }))
            $A.Add((New-SmartAction 'Watch it in the host monitor' $Glyph.Globe { param($x) Show-Toolbox 'hosts' $x.Trim() }))
            if ($t -match ':\d+$') { $A.Add((New-SmartAction 'Check its certificate' $Glyph.Lock { param($x) Show-Toolbox 'cert' $x.Trim() })) }
            return @{ Badge = 'Host'; Actions = $A }
        }
        # File / folder path
        if ($t -match '^("?)([A-Za-z]:\\|\\\\)[^<>|*?"]+\1$') {
            $p = $t.Trim('"')
            if (Test-Path -LiteralPath $p) {
                $A.Add((New-SmartAction 'Open' $Glyph.Open { param($x) try { Start-Process -FilePath $x.Trim().Trim('"') } catch { } }))
                $A.Add((New-SmartAction 'Show in Explorer' $Glyph.Folder { param($x) Start-Process explorer.exe "/select,`"$($x.Trim().Trim('"'))`"" }))
                if (Test-Path -LiteralPath $p -PathType Leaf) { $A.Add((New-SmartAction 'Hash this file' $Glyph.Document { param($x) Show-Toolbox 'hash' $x })) }
                else { $A.Add((New-SmartAction 'Find in this folder...' $Glyph.Search { param($x) Show-FindInFiles $x.Trim().Trim('"') })) }
                return @{ Badge = 'Path'; Actions = $A }
            }
        }
        # Base64 (that decodes to readable text)
        if ($t.Length -ge 16 -and $t.Length % 4 -eq 0 -and $t -match '^[A-Za-z0-9+/]+={0,2}$' -and $t -match '[A-Z]' -and $t -match '[a-z0-9]') {
            try {
                $bytes = [Convert]::FromBase64String($t)
                $decoded = [Text.Encoding]::UTF8.GetString($bytes)
                $printable = ($decoded.ToCharArray() | Where-Object { [int]$_ -ge 32 -or $_ -in "`r", "`n", "`t" }).Count
                if ($decoded.Length -gt 0 -and $printable / $decoded.Length -gt 0.95 -and $decoded -notmatch [char]0xFFFD) {
                    $A.Add((New-SmartAction 'Copy decoded text' $Glyph.Code { param($x) Set-SmartResult ([Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($x.Trim()))) 'decoded Base64' }))
                    $A.Add((New-SmartAction 'Open in Transform' $Glyph.Code { param($x) [void](Show-Transform $x) }))
                    return @{ Badge = 'Base64'; Actions = $A; Tip = (Get-Preview $decoded) }
                }
            } catch { }
        }
    }
    $null
}

# Menu items for a clip's smart actions (used by the right-click menu and the Actions button).
function Add-SmartMenuItems($Menu, $Item, [int]$Index = 0) {
    $info = Get-SmartInfo $Item
    if (-not $info) { return 0 }
    $n = 0
    foreach ($a in $info.Actions) {
        $mi = New-Object System.Windows.Forms.ToolStripMenuItem($a.Title, (New-GlyphImage $a.Icon $C.Accent))
        $mi.Tag = @{ Run = $a.Run; Text = $Item.Text }
        $mi.add_Click({ param($src, $e) $t = $src.Tag; try { & $t.Run $t.Text } catch { Write-Log "smart action failed: $_" } })
        $Menu.Items.Insert($Index + $n, $mi)
        $n++
    }
    if ($n) { $sep = New-Object System.Windows.Forms.ToolStripSeparator; $sep.Tag = 'smart'; $Menu.Items.Insert($Index + $n, $sep); $n++ }
    $n
}

function Show-SmartActions {
    $sel = Get-Selected
    if (-not $sel -or $sel.Kind -ne 'text') { $status.Text = 'Smart actions are for text clips.'; $status.ForeColor = $C.Dim; return }
    $m = New-Object System.Windows.Forms.ContextMenuStrip -Property @{ Renderer = $MenuRenderer }
    [void](Add-SmartMenuItems $m $sel 0)
    Add-CleanupMenu $m $sel
    if ($m.Items.Count -gt 0 -and $m.Items[$m.Items.Count - 1] -is [System.Windows.Forms.ToolStripSeparator]) { $m.Items.RemoveAt($m.Items.Count - 1) }
    $script:Modal = $true
    $m.add_Closed({ $script:Modal = $false })
    $m.Show($btnActions, (New-Object System.Drawing.Point(0, $btnActions.Height)))
}

# ---------------------------------------------------------------------------
# Image editor: annotate and fix up copied images and screenshots. Drawn things stay editable
# (select, move, resize, restyle, delete) until you copy or save. Opens with Edit (F2) on an image clip.
# ---------------------------------------------------------------------------
$ImageTools = @(
    @('select', 'Select', [string][char]0xE8B3, 'V', 'Select, move and resize what you drew; drag on empty space to select an area'),
    @('crop', 'Crop', [string][char]0xE7A8, 'C', 'Drag the area to keep, then press Enter or Crop'),
    @('arrow', 'Arrow', [string][char]0xE72A, 'A', 'Arrow (Shift: straight)'),
    @('darrow', 'Both ways', [string][char]0xE8AB, 'D', 'Double-headed arrow'),
    @('line', 'Line', [string][char]0xE738, 'L', 'Straight line (Shift: 45-degree steps)'),
    @('rect', 'Box', [string][char]0xE739, 'R', 'Rectangle (Shift: square; F: filled)'),
    @('ellipse', 'Circle', [string][char]0xEA3A, 'E', 'Ellipse (Shift: circle; F: filled)'),
    @('pen', 'Pen', [string][char]0xE70F, 'P', 'Freehand'),
    @('highlight', 'Marker', [string][char]0xE7E6, 'H', 'See-through highlighter box'),
    @('text', 'Text', [string][char]0xE8D2, 'T', 'Click where the text goes, type, Enter. Double-click a text to change it'),
    @('callout', 'Callout', [string][char]0xE8BD, 'K', 'Speech bubble: drag the box, type (Ctrl+Enter finishes), drag the tail handle'),
    @('step', 'Number', [string][char]0xEA3B, 'N', 'Numbered markers 1, 2, 3 ... (click to place)'),
    @('spotlight', 'Spotlight', [string][char]0xE781, 'S', 'Dims everything except the box you draw'),
    @('magnify', 'Magnifier', [string][char]0xE8A3, 'M', 'Zoomed-in bubble of an area; drag its round handle to move the bubble'),
    @('blur', 'Blur', [string][char]0xE890, 'B', 'Pixelate an area - hides passwords, names, tokens (goes into the picture)'),
    @('picker', 'Pick colour', [string][char]0xEF3C, 'I', 'Eyedropper: click to use a colour from the picture'))
$ImageColors = @('#E81123', '#FF8C00', '#FFD600', '#16C60C', '#0078D4', '#8E44AD', '#111111', '#FFFFFF')

function Update-ImageEditorStatus($St) {
    $ed = $St.Editor
    if (-not $ed.Image -or -not $St.Undo -or -not $St.Status) { return }       # still being built
    $parts = @("$($ed.Image.Width) x $($ed.Image.Height)", "zoom $([int]($ed.CurrentZoom * 100))%")
    if ($ed.Pointer.X -ge 0 -and $ed.Pointer.X -lt $ed.Image.Width -and $ed.Pointer.Y -ge 0 -and $ed.Pointer.Y -lt $ed.Image.Height) { $parts += "pointer $($ed.Pointer.X), $($ed.Pointer.Y)" }
    if (-not $ed.Selection.IsEmpty) { $parts += "area $($ed.Selection.Width) x $($ed.Selection.Height)" }
    if ($ed.SelectedShape) { $parts += "$($ed.SelectedShape.Kind) selected - drag to move, handles to resize, Del to delete" }
    elseif ($ed.Shapes.Count) { $parts += "$($ed.Shapes.Count) drawn item(s) - Select tool (V) to move or change them" }
    $St.Status.Text = $parts -join "   $Dot   "
    $St.Undo.Enabled = $ed.CanUndo; $St.Redo.Enabled = $ed.CanRedo
    $St.CropBtn.Enabled = -not $ed.Selection.IsEmpty
    $St.DeleteBtn.Enabled = [bool]$ed.SelectedShape
    $St.Form.Text = "Edit image  -  $($ed.Image.Width) x $($ed.Image.Height)$(if ($St.Dirty) { '  *' })"
}

function Set-ImageTool($St, [string]$Tool) {
    $St.Editor.CommitText()
    $St.Editor.Tool = $Tool
    if ($Tool -ne 'select' -and $Tool -ne 'crop') { $St.Editor.Selection = [System.Drawing.Rectangle]::Empty }
    $St.Editor.Cursor = switch ($Tool) { 'text' { [System.Windows.Forms.Cursors]::IBeam } 'select' { [System.Windows.Forms.Cursors]::Default } default { [System.Windows.Forms.Cursors]::Cross } }
    foreach ($b in $St.ToolButtons) { $b.Selected = ($b.Tag -eq $Tool); $b.Invalidate() }
    $St.Editor.Invalidate()
    Update-ImageEditorStatus $St
}

# When a drawn item is selected, the style controls show its colour / sizes.
function Sync-ImageStyle($St) {
    $ed = $St.Editor
    $sh = $ed.SelectedShape
    $St.Syncing = $true
    try {
        if ($sh) {
            $ed.Ink = $sh.Ink
            $St.LineWidth.Value = [Math]::Max(1, [Math]::Min(40, [int]$sh.Width))
            $St.TextSize.Value = [Math]::Max(8, [Math]::Min(300, [int]$sh.TextSize))
            $St.FillBtn.Selected = $sh.Filled; $St.DashBtn.Selected = $sh.Dashed
        } else {
            $St.FillBtn.Selected = $ed.Filled; $St.DashBtn.Selected = $ed.Dashed
        }
        $St.LineLabel.Text = "$($St.LineWidth.Value) px"
        $St.FillBtn.Invalidate(); $St.DashBtn.Invalidate(); $St.Swatches.Invalidate(); $St.Preview.Invalidate()
    } finally { $St.Syncing = $false }
    Update-ImageEditorStatus $St
}

# Copies the edited image (or the selected area) to the clipboard; it lands in the history as a new clip.
function Copy-EditedImage($St, [switch]$Selection) {
    $bmp = $St.Editor.Result()
    $sel = $St.Editor.Selection
    if ($Selection -and -not $sel.IsEmpty) { $part = $bmp.Clone($sel, $bmp.PixelFormat); $bmp.Dispose(); $bmp = $part }
    try {
        Set-ClipboardImage $bmp
        $St.Status.Text = "Copied$(if ($Selection -and -not $sel.IsEmpty) { ' the selected area' }) - paste it anywhere; it is also in your clipboard history."
    } catch { $St.Status.Text = "Could not copy: $($_.Exception.Message)" }
    finally { $bmp.Dispose() }
}

function Set-ClipboardImage($Bitmap) {
    $data = New-Object System.Windows.Forms.DataObject
    $data.SetImage($Bitmap)
    $ms = New-Object System.IO.MemoryStream; $Bitmap.Save($ms, [System.Drawing.Imaging.ImageFormat]::Png)
    $data.SetData('PNG', $ms)
    [System.Windows.Forms.Clipboard]::SetDataObject($data, $true, 10, 50)
}

# Saves the edit into the clip history: replaces the clip it came from (keeping its pin).
function Save-EditedImageToHistory($St) {
    $bmp = $St.Editor.Result()
    try {
        $script:IgnoreUntil = (Get-Date).AddMilliseconds(800)
        Add-ClipImage $bmp
        $new = $script:Items[0]
        $orig = $St.Item
        if ($orig -and $new -and $new.Id -ne $orig.Id -and ($script:Items | Where-Object { $_.Id -eq $orig.Id })) {
            $new.Pinned = $orig.Pinned
            Remove-Clip $orig.Id
        }
        Save-History
        if ($form.Visible) { Update-List -SelectIndex 0 }
        $St.Item = $new
        $St.Dirty = $false
        Update-ImageEditorStatus $St
        $St.Status.Text = 'Saved to your clipboard history (it replaces the original clip).'
    } catch { $St.Status.Text = "Could not save: $($_.Exception.Message)" }
    finally { $bmp.Dispose() }
}

# JPEG bytes at a quality (1-100); transparent areas become white.
function ConvertTo-JpegBytes($Bitmap, [int]$Quality) { [PowerClipImageEditor]::Jpeg($Bitmap, $Quality) }

function Save-EditedImageAs($St) {
    $d = New-Object System.Windows.Forms.SaveFileDialog
    $d.Filter = 'PNG image|*.png|JPEG image|*.jpg|BMP image|*.bmp'
    $d.FileName = "image-$(Get-Date -Format 'yyyyMMdd-HHmmss').png"
    $script:Modal = $true
    try {
        if ($d.ShowDialog($St.Form) -ne 'OK') { return }
        $bmp = $St.Editor.Result()
        try {
            switch ([IO.Path]::GetExtension($d.FileName).ToLower()) {
                { $_ -in '.jpg', '.jpeg' } { [IO.File]::WriteAllBytes($d.FileName, (ConvertTo-JpegBytes $bmp 92)) }
                '.bmp' { $bmp.Save($d.FileName, [System.Drawing.Imaging.ImageFormat]::Bmp) }
                default { $bmp.Save($d.FileName, [System.Drawing.Imaging.ImageFormat]::Png) }
            }
            $St.Status.Text = "Saved $($d.FileName)"
        } finally { $bmp.Dispose() }
    } finally { $script:Modal = $false; $d.Dispose() }
}

# Smaller copy for email / chat: pick a width and JPEG quality, see the size, then copy or save.
function Show-SaveSmaller($St) {
    $src = $St.Editor.Result()
    $d = New-Object System.Windows.Forms.Form
    $d.Text = 'Save smaller'; $d.FormBorderStyle = 'FixedDialog'; $d.MaximizeBox = $false; $d.MinimizeBox = $false; $d.StartPosition = 'CenterParent'; $d.ShowInTaskbar = $false
    $d.BackColor = $C.Panel; $d.ForeColor = $C.Fore; $d.Font = $FontMain
    $d.ClientSize = New-Object System.Drawing.Size((Px (460 * $TextZoom)), ($FontMain.Height * 6 + (Px 120)))
    $tbl = New-Object System.Windows.Forms.TableLayoutPanel
    $tbl.Dock = 'Fill'; $tbl.ColumnCount = 2; $tbl.Padding = New-Object System.Windows.Forms.Padding((Px 14))
    [void]$tbl.ColumnStyles.Add((New-Object System.Windows.Forms.ColumnStyle('AutoSize'))); [void]$tbl.ColumnStyles.Add((New-Object System.Windows.Forms.ColumnStyle('Percent', 100)))
    $mk = { param($t) $l = New-Object System.Windows.Forms.Label; $l.Text = $t; $l.AutoSize = $true; $l.Margin = New-Object System.Windows.Forms.Padding(0, (Px 8), (Px 12), 0); $l }
    $width = New-Object System.Windows.Forms.NumericUpDown
    $width.Minimum = 16; $width.Maximum = [Math]::Max(16, $src.Width); $width.Value = [Math]::Min($src.Width, 1280); $width.Width = Px 100
    $fmt = New-Object System.Windows.Forms.ComboBox; $fmt.DropDownStyle = 'DropDownList'; [void]$fmt.Items.AddRange(@('JPEG', 'PNG')); $fmt.SelectedIndex = 0; $fmt.Width = Px 100
    $q = New-Object System.Windows.Forms.TrackBar; $q.Minimum = 10; $q.Maximum = 100; $q.Value = 80; $q.TickStyle = 'None'; $q.Width = Px 200; $q.AutoSize = $false; $q.Height = Px 30
    $info = New-Object System.Windows.Forms.Label; $info.AutoSize = $true; $info.ForeColor = $C.Accent; $info.Margin = New-Object System.Windows.Forms.Padding(0, (Px 10), 0, 0)
    $tbl.Controls.Add((& $mk 'Width (px)'), 0, 0); $tbl.Controls.Add($width, 1, 0)
    $tbl.Controls.Add((& $mk 'Format'), 0, 1); $tbl.Controls.Add($fmt, 1, 1)
    $tbl.Controls.Add((& $mk 'JPEG quality'), 0, 2); $tbl.Controls.Add($q, 1, 2)
    $tbl.Controls.Add($info, 0, 3); $tbl.SetColumnSpan($info, 2)
    $btns = New-Object System.Windows.Forms.FlowLayoutPanel; $btns.FlowDirection = 'RightToLeft'; $btns.Dock = 'Fill'
    $tbl.Controls.Add($btns, 0, 4); $tbl.SetColumnSpan($btns, 2)
    $d.Controls.Add($tbl)
    $state = @{ Src = $src; Width = $width; Fmt = $fmt; Q = $q; Info = $info; Bytes = $null; Dialog = $d; Ed = $St }
    $d.Tag = $state
    $update = {
        param($s)
        $w = [int]$s.Width.Value; $h = [int][Math]::Max(1, [Math]::Round($s.Src.Height * $w / $s.Src.Width))
        $scaled = [PowerClipImageEditor]::Scaled($s.Src, $w, $h)
        try {
            if ($s.Fmt.SelectedIndex -eq 0) { $s.Bytes = ConvertTo-JpegBytes $scaled ([int]$s.Q.Value) }
            else { $ms = New-Object System.IO.MemoryStream; $scaled.Save($ms, [System.Drawing.Imaging.ImageFormat]::Png); $s.Bytes = $ms.ToArray() }
        } finally { $scaled.Dispose() }
        $s.Q.Enabled = $s.Fmt.SelectedIndex -eq 0
        $s.Info.Text = "$w x $h  $Dot  $(Format-Size $s.Bytes.Length)  (now $($s.Src.Width) x $($s.Src.Height))"
    }
    $state.Update = $update
    foreach ($c2 in $width, $q) { $c2.add_ValueChanged({ param($src2, $e) $s = $src2.FindForm().Tag; & $s.Update $s }) }
    $fmt.add_SelectedIndexChanged({ param($src2, $e) $s = $src2.FindForm().Tag; & $s.Update $s })
    $close = New-Object PowerClipButton; $close.Text = 'Close'; $close.Font = $FontButton; $close.AutoSize = $true; $close.DialogResult = 'Cancel'
    $save = New-Object PowerClipButton; $save.Text = 'Save as...'; $save.Font = $FontButton; $save.AutoSize = $true
    $copy = New-Object PowerClipButton; $copy.Text = 'Copy'; $copy.Variant = 1; $copy.Font = $FontButton; $copy.AutoSize = $true
    $btns.Controls.AddRange(@($close, $save, $copy))
    $copy.add_Click({
        param($src2, $e)
        $s = $src2.FindForm().Tag
        $ms = New-Object System.IO.MemoryStream(, $s.Bytes)
        $img = [System.Drawing.Image]::FromStream($ms)
        $data = New-Object System.Windows.Forms.DataObject
        $data.SetImage($img)
        if ($s.Fmt.SelectedIndex -eq 0) { $data.SetData('JFIF', (New-Object System.IO.MemoryStream(, $s.Bytes))) } else { $data.SetData('PNG', (New-Object System.IO.MemoryStream(, $s.Bytes))) }
        [System.Windows.Forms.Clipboard]::SetDataObject($data, $true, 10, 50)
        $s.Info.Text = "Copied ($(Format-Size $s.Bytes.Length))"
    })
    $save.add_Click({
        param($src2, $e)
        $s = $src2.FindForm().Tag
        $sd = New-Object System.Windows.Forms.SaveFileDialog
        $ext = if ($s.Fmt.SelectedIndex -eq 0) { 'jpg' } else { 'png' }
        $sd.Filter = "$($s.Fmt.SelectedItem) image|*.$ext"; $sd.FileName = "image-small.$ext"
        if ($sd.ShowDialog($s.Dialog) -eq 'OK') { [IO.File]::WriteAllBytes($sd.FileName, $s.Bytes); $s.Info.Text = "Saved $($sd.FileName)" }
        $sd.Dispose()
    })
    $d.CancelButton = $close
    Register-ThemedWindow $d
    & $update $state
    $script:Modal = $true
    try { [void]$d.ShowDialog($St.Form) } finally { $script:Modal = $false; $d.Dispose(); $src.Dispose() }
}

# Brightness / contrast with a live preview.
function Show-BrightnessDialog($St) {
    $ed = $St.Editor
    $d = New-Object System.Windows.Forms.Form
    $d.Text = 'Brightness / contrast'; $d.FormBorderStyle = 'FixedDialog'; $d.MaximizeBox = $false; $d.MinimizeBox = $false; $d.StartPosition = 'CenterParent'; $d.ShowInTaskbar = $false
    $d.BackColor = $C.Panel; $d.ForeColor = $C.Fore; $d.Font = $FontMain
    $d.ClientSize = New-Object System.Drawing.Size((Px (420 * $TextZoom)), ($FontMain.Height * 4 + (Px 110)))
    $tbl = New-Object System.Windows.Forms.TableLayoutPanel
    $tbl.Dock = 'Fill'; $tbl.ColumnCount = 2; $tbl.Padding = New-Object System.Windows.Forms.Padding((Px 14))
    [void]$tbl.ColumnStyles.Add((New-Object System.Windows.Forms.ColumnStyle('AutoSize'))); [void]$tbl.ColumnStyles.Add((New-Object System.Windows.Forms.ColumnStyle('Percent', 100)))
    $bars = @()
    $r = 0
    foreach ($name in 'Brightness', 'Contrast') {
        $l = New-Object System.Windows.Forms.Label; $l.Text = $name; $l.AutoSize = $true; $l.Margin = New-Object System.Windows.Forms.Padding(0, (Px 8), (Px 12), 0)
        $tb = New-Object System.Windows.Forms.TrackBar; $tb.Minimum = -100; $tb.Maximum = 100; $tb.Value = 0; $tb.TickStyle = 'None'; $tb.Dock = 'Fill'; $tb.AutoSize = $false; $tb.Height = Px 30
        $tbl.Controls.Add($l, 0, $r); $tbl.Controls.Add($tb, 1, $r); $bars += $tb; $r++
    }
    $btns = New-Object System.Windows.Forms.FlowLayoutPanel; $btns.FlowDirection = 'RightToLeft'; $btns.Dock = 'Fill'
    $cancel = New-Object PowerClipButton; $cancel.Text = 'Cancel'; $cancel.Font = $FontButton; $cancel.AutoSize = $true; $cancel.DialogResult = 'Cancel'
    $ok = New-Object PowerClipButton; $ok.Text = 'Apply'; $ok.Variant = 1; $ok.Font = $FontButton; $ok.AutoSize = $true; $ok.DialogResult = 'OK'
    $btns.Controls.AddRange(@($cancel, $ok))
    $tbl.Controls.Add($btns, 1, $r)
    $d.Controls.Add($tbl)
    $d.Tag = @{ Ed = $ed; Bars = $bars }
    foreach ($tb in $bars) { $tb.add_ValueChanged({ param($src2, $e) $t = $src2.FindForm().Tag; $t.Ed.Preview([PowerClipImageEditor]::BrightnessContrast($t.Bars[0].Value, $t.Bars[1].Value)) }) }
    $d.AcceptButton = $ok; $d.CancelButton = $cancel
    Register-ThemedWindow $d
    $script:Modal = $true
    try { $res = $d.ShowDialog($St.Form) } finally { $script:Modal = $false }
    if ($res -eq 'OK' -and ($bars[0].Value -ne 0 -or $bars[1].Value -ne 0)) { $ed.ApplyMatrix([PowerClipImageEditor]::BrightnessContrast($bars[0].Value, $bars[1].Value)) }
    else { $ed.Preview($null) }
    $d.Dispose()
}

function Show-ImageEditor($Item = $null, $Bitmap = $null) {
    Hide-Picker
    if (-not $Bitmap) {
        if (-not $Item -or $Item.Kind -ne 'image') { return }
        $Bitmap = Read-ImageFile (Get-DataPath $Item.Image)
        if (-not $Bitmap) { Show-Message 'The image file is missing.'; return }
    }
    $st = @{ Item = $Item; Dirty = $false; ToolButtons = @(); Syncing = $false }
    $f = New-Object System.Windows.Forms.Form
    $f.Text = 'Edit image'; $f.Icon = $IconActive
    $f.Size = New-Object System.Drawing.Size((Px (1240 * $TextZoom)), (Px 820))
    $f.MinimumSize = New-Object System.Drawing.Size((Px 760), (Px 480))
    $f.StartPosition = 'CenterScreen'; $f.BackColor = $C.Panel; $f.ForeColor = $C.Fore; $f.Font = $FontMain; $f.KeyPreview = $true
    $f.Tag = $st
    $st.Form = $f

    $scroll = New-Object System.Windows.Forms.Panel
    $scroll.Dock = 'Fill'; $scroll.AutoScroll = $true; $scroll.BackColor = $C.Bg
    $ed = New-Object PowerClipImageEditor
    $ed.Dock = 'Fill'; $ed.BackColor = $C.Bg
    $scroll.Controls.Add($ed)
    $f.Controls.Add($scroll)
    $st.Editor = $ed
    $ed.SetImage($Bitmap)
    $Bitmap.Dispose()
    $ed.add_Changed({ param($src, $e) $s = $src.FindForm().Tag; if ($s) { $s.Dirty = $true; Update-ImageEditorStatus $s } })
    $ed.add_ViewChanged({ param($src, $e) $s = $src.FindForm().Tag; if ($s) { Update-ImageEditorStatus $s } })
    $ed.add_SelectionChanged({ param($src, $e) $s = $src.FindForm().Tag; if ($s -and $s.LineWidth) { Sync-ImageStyle $s } })
    $ed.add_InkPicked({ param($src, $e) $s = $src.FindForm().Tag; if ($s) { $s.Swatches.Invalidate(); $s.Preview.Invalidate(); $s.Status.Text = "Picked colour #{0:X2}{1:X2}{2:X2}" -f $src.Ink.R, $src.Ink.G, $src.Ink.B; Set-ImageTool $s 'arrow' } })
    $scroll.add_Resize({ param($src, $e) $src.Controls[0].UpdateSize() })

    # ---- bottom: results
    $bottom = New-Object System.Windows.Forms.FlowLayoutPanel
    $bottom.Dock = 'Bottom'; $bottom.AutoSize = $true; $bottom.WrapContents = $true; $bottom.BackColor = $C.Panel
    $bottom.Padding = New-Object System.Windows.Forms.Padding((Px 10), (Px 8), (Px 10), (Px 8))
    [void](New-Button 'Copy' 'Copy the result (Ctrl+C; with an area selected, just that part). It also goes into your history.' { param($src, $e) Copy-EditedImage $src.FindForm().Tag -Selection } $bottom $Glyph.Copy 1)
    [void](New-Button 'Save to history' 'Replace the original clip with the edited image (Ctrl+S)' { param($src, $e) Save-EditedImageToHistory $src.FindForm().Tag } $bottom $Glyph.Save)
    [void](New-Button 'Save as file...' 'Save as PNG, JPEG or BMP' { param($src, $e) Save-EditedImageAs $src.FindForm().Tag } $bottom $Glyph.Document)
    [void](New-Button 'Save smaller...' 'Smaller copy for email or chat: width and JPEG quality, with the file size' { param($src, $e) Show-SaveSmaller $src.FindForm().Tag } $bottom ([string][char]0xE73F) 2)
    $st.OcrBtn = New-Button 'Text from image' 'Copy the text in the picture (Windows text recognition)' { param($src, $e) Copy-ImageText $src.FindForm().Tag } $bottom $Glyph.Text 2
    [void](New-Button 'Open in Paint' 'Continue in Microsoft Paint' {
        param($src, $e)
        $s = $src.FindForm().Tag
        $tmp = Join-Path $env:TEMP "devtools-edit-$(Get-Date -Format 'HHmmss').png"
        $bmp = $s.Editor.Result(); $bmp.Save($tmp, [System.Drawing.Imaging.ImageFormat]::Png); $bmp.Dispose()
        try { Start-Process mspaint.exe "`"$tmp`"" } catch { Start-Process $tmp }
    } $bottom $Glyph.Edit 2)
    $st.Status = New-Object System.Windows.Forms.Label
    $st.Status.AutoSize = $true; $st.Status.ForeColor = $C.Dim; $st.Status.BackColor = $C.Panel; $st.Status.Margin = New-Object System.Windows.Forms.Padding((Px 12), (Px 8), 0, 0)
    $bottom.Controls.Add($st.Status)
    $f.Controls.Add($bottom)

    # ---- row 3: picture operations
    $row3 = New-Object System.Windows.Forms.FlowLayoutPanel
    $row3.Dock = 'Top'; $row3.AutoSize = $true; $row3.WrapContents = $true; $row3.BackColor = $C.Panel
    $row3.Padding = New-Object System.Windows.Forms.Padding((Px 10), 0, (Px 10), (Px 6))
    $st.Undo = New-Button '' 'Undo (Ctrl+Z)' { param($src, $e) $src.FindForm().Tag.Editor.Undo() } $row3 $Glyph.Undo 2
    $st.Redo = New-Button '' 'Redo (Ctrl+Y)' { param($src, $e) $src.FindForm().Tag.Editor.Redo() } $row3 ([string][char]0xE7A6) 2
    $st.DeleteBtn = New-Button '' 'Delete the selected drawing (Del)' { param($src, $e) $src.FindForm().Tag.Editor.DeleteSelected() } $row3 $Glyph.Delete 2
    $st.CropBtn = New-Button 'Crop' 'Keep only the selected area (Enter)' { param($src, $e) $s = $src.FindForm().Tag; [void]$s.Editor.Crop(); Set-ImageTool $s 'select' } $row3 ([string][char]0xE7A8) 2
    [void](New-Button 'Auto-trim' 'Cut away the plain border around the picture' { param($src, $e) $s = $src.FindForm().Tag; if (-not $s.Editor.AutoTrim(12)) { $s.Status.Text = 'Nothing to trim: there is no plain border.' } } $row3 '' 2)
    [void](New-Button '' 'Rotate left' { param($src, $e) $src.FindForm().Tag.Editor.Rotate($false) } $row3 ([string][char]0xE7AD) 2)
    [void](New-Button '' 'Rotate right' { param($src, $e) $src.FindForm().Tag.Editor.Rotate($true) } $row3 ([string][char]0xE7AD) 2)
    [void](New-Button 'Flip' 'Mirror left-right' { param($src, $e) $src.FindForm().Tag.Editor.Flip($true) } $row3 '' 2)
    $resize = New-TbCombo $row3 @('Resize...', '25%', '50%', '75%', '150%', '200%') 110
    $resize.add_SelectedIndexChanged({
        param($src, $e)
        if ($src.SelectedIndex -le 0) { return }
        $factor = [double]($src.SelectedItem.TrimEnd('%')) / 100
        $src.FindForm().Tag.Editor.ResizeImage([float]$factor)
        $src.SelectedIndex = 0
    })
    [void](New-Button 'Border' 'Add a white 20-pixel border' { param($src, $e) $src.FindForm().Tag.Editor.AddBorder(20, [System.Drawing.Color]::White) } $row3 '' 2)
    $adj = New-Button 'Adjust' 'Black and white, sepia, invert, brightness / contrast, sharpen, soften' {
        param($src, $e)
        $s = $src.FindForm().Tag
        $m = New-Object System.Windows.Forms.ContextMenuStrip -Property @{ Renderer = $MenuRenderer }
        $m.Tag = $s
        [void](Add-MenuItem $m 'Black and white' { param($a, $b) $a.Owner.Tag.Editor.ApplyMatrix([PowerClipImageEditor]::Grayscale()) })
        [void](Add-MenuItem $m 'Sepia' { param($a, $b) $a.Owner.Tag.Editor.ApplyMatrix([PowerClipImageEditor]::Sepia()) })
        [void](Add-MenuItem $m 'Invert colours' { param($a, $b) $a.Owner.Tag.Editor.ApplyMatrix([PowerClipImageEditor]::Invert()) })
        [void](Add-MenuItem $m 'Brightness / contrast...' { param($a, $b) Show-BrightnessDialog $a.Owner.Tag })
        [void]$m.Items.Add('-')
        [void](Add-MenuItem $m 'Sharpen' { param($a, $b) $a.Owner.Tag.Editor.Convolve($true) })
        [void](Add-MenuItem $m 'Soften (blur everything a little)' { param($a, $b) $a.Owner.Tag.Editor.Convolve($false) })
        $m.Show($src, (New-Object System.Drawing.Point(0, $src.Height)))
    } $row3 ([string][char]0xE793) 2
    [void](New-TbLabel $row3 'Zoom' -Dim)
    [void](New-Button 'Fit' 'Fit the window (Ctrl+0)' { param($src, $e) $src.FindForm().Tag.Editor.SetZoom(1, $true) } $row3 '' 2)
    [void](New-Button '100%' 'Actual pixels (Ctrl+1)' { param($src, $e) $src.FindForm().Tag.Editor.SetZoom(1, $false) } $row3 '' 2)
    [void](New-Button '' 'Zoom in (Ctrl+wheel up, Ctrl++)' { param($src, $e) $ed2 = $src.FindForm().Tag.Editor; $ed2.SetZoom($ed2.CurrentZoom * 1.25, $false) } $row3 ([string][char]0xE8A3) 2)
    [void](New-Button '' 'Zoom out (Ctrl+wheel down, Ctrl+-)' { param($src, $e) $ed2 = $src.FindForm().Tag.Editor; $ed2.SetZoom($ed2.CurrentZoom / 1.25, $false) } $row3 ([string][char]0xE71F) 2)
    $f.Controls.Add($row3)

    # ---- row 2: style (applies to new drawings and to the selected one)
    $row2 = New-Object System.Windows.Forms.FlowLayoutPanel
    $row2.Dock = 'Top'; $row2.AutoSize = $true; $row2.WrapContents = $true; $row2.BackColor = $C.Panel
    $row2.Padding = New-Object System.Windows.Forms.Padding((Px 10), 0, (Px 10), (Px 2))
    $sw = New-Object System.Windows.Forms.Panel
    $sw.Size = New-Object System.Drawing.Size(((Px 28) * $ImageColors.Count + (Px 4)), (Px 30)); $sw.Cursor = 'Hand'; $sw.BackColor = $C.Panel
    $sw.Margin = New-Object System.Windows.Forms.Padding(0, (Px 2), (Px 10), 0)
    $sw.add_Paint({
        param($src, $e)
        $s = $src.FindForm().Tag
        $g = $e.Graphics; $g.SmoothingMode = 'AntiAlias'
        for ($i = 0; $i -lt $ImageColors.Count; $i++) {
            $col = ColorHex $ImageColors[$i]
            $x = $i * (Px 28) + (Px 5); $dd = Px 20
            $b = New-Object System.Drawing.SolidBrush $col; $g.FillEllipse($b, $x, (Px 5), $dd, $dd); $b.Dispose()
            $pen = New-Object System.Drawing.Pen $C.Line; $g.DrawEllipse($pen, $x, (Px 5), $dd, $dd); $pen.Dispose()
            if ($s -and $s.Editor.Ink.ToArgb() -eq $col.ToArgb()) { $pen = New-Object System.Drawing.Pen($C.Accent, [float](Px 2)); $g.DrawEllipse($pen, ($x - (Px 3)), (Px 2), ($dd + (Px 6)), ($dd + (Px 6))); $pen.Dispose() }
        }
    })
    $sw.add_MouseClick({
        param($src, $e)
        $i = [int][Math]::Floor($e.X / (Px 28))
        if ($i -ge 0 -and $i -lt $ImageColors.Count) { $s = $src.FindForm().Tag; $s.Editor.SetInk((ColorHex $ImageColors[$i])); $s.Preview.Invalidate(); $src.Invalidate() }
    })
    $tooltip.SetToolTip($sw, 'Colour (also changes the selected drawing). The eyedropper (I) takes one from the picture.')
    $row2.Controls.Add($sw)
    $st.Swatches = $sw
    [void](New-TbLabel $row2 'Line' -Dim)
    $lw = New-Object System.Windows.Forms.TrackBar
    $lw.Minimum = 1; $lw.Maximum = 40; $lw.Value = 4; $lw.TickStyle = 'None'; $lw.AutoSize = $false
    $lw.Width = Px (130 * $TextZoom); $lw.Height = Px 30; $lw.BackColor = $C.Panel; $lw.Margin = New-Object System.Windows.Forms.Padding(0, (Px 2), 0, 0)
    $tooltip.SetToolTip($lw, 'Line width for arrows, boxes, circles, lines and the pen ([ and ] change it)')
    $row2.Controls.Add($lw)
    $st.LineLabel = New-TbLabel $row2 '4 px'
    $st.LineLabel.AutoSize = $false; $st.LineLabel.Width = Px (46 * $TextZoom)
    $lw.add_ValueChanged({ param($src, $e) $s = $src.FindForm().Tag; $s.LineLabel.Text = "$($src.Value) px"; $s.Preview.Invalidate(); if (-not $s.Syncing) { $s.Editor.SetThickness($src.Value) } })
    $st.LineWidth = $lw
    [void](New-TbLabel $row2 'Text' -Dim)
    $ts = New-TbNumber $row2 28 8 300
    $tooltip.SetToolTip($ts, 'Text size in pixels; also callouts and numbered markers (Ctrl+[ and Ctrl+] change it)')
    $ts.add_ValueChanged({ param($src, $e) $s = $src.FindForm().Tag; if (-not $s.Syncing) { $s.Editor.SetTextSize([float]$src.Value) } })
    $st.TextSize = $ts
    $st.FillBtn = New-Button 'Filled' 'Filled boxes, circles and callouts (F)' { param($src, $e) $s = $src.FindForm().Tag; $v = -not $src.Selected; $src.Selected = $v; $src.Invalidate(); $s.Editor.SetFilled($v) } $row2 '' 2
    $st.DashBtn = New-Button 'Dashed' 'Dashed lines and outlines' { param($src, $e) $s = $src.FindForm().Tag; $v = -not $src.Selected; $src.Selected = $v; $src.Invalidate(); $s.Editor.SetDashed($v) } $row2 '' 2
    $pv = New-Object System.Windows.Forms.Panel
    $pv.Size = New-Object System.Drawing.Size((Px 44), (Px 30)); $pv.BackColor = $C.Panel; $pv.Margin = New-Object System.Windows.Forms.Padding((Px 6), (Px 2), (Px 8), 0)
    $pv.add_Paint({
        param($src, $e)
        $s = $src.FindForm().Tag
        if (-not $s) { return }
        $g = $e.Graphics; $g.SmoothingMode = 'AntiAlias'
        $w = [Math]::Min($src.Height - 4, [Math]::Max(1, $s.LineWidth.Value))
        $pen = New-Object System.Drawing.Pen($s.Editor.Ink, [float]$w); $pen.StartCap = 'Round'; $pen.EndCap = 'Round'
        $g.DrawLine($pen, (Px 6), ($src.Height / 2), ($src.Width - (Px 6)), ($src.Height / 2)); $pen.Dispose()
    })
    $tooltip.SetToolTip($pv, 'Current colour and line width')
    $row2.Controls.Add($pv)
    $st.Preview = $pv
    $f.Controls.Add($row2)

    # ---- row 1: tools
    $row1 = New-Object System.Windows.Forms.FlowLayoutPanel
    $row1.Dock = 'Top'; $row1.AutoSize = $true; $row1.WrapContents = $true; $row1.BackColor = $C.Panel
    $row1.Padding = New-Object System.Windows.Forms.Padding((Px 10), (Px 8), (Px 10), (Px 4))
    foreach ($t in $ImageTools) {
        $b = New-Button $t[1] "$($t[4])  ($($t[3]))" { param($src, $e) Set-ImageTool $src.FindForm().Tag $src.Tag } $row1 $t[2] 2
        $b.Tag = $t[0]
        $b.Margin = New-Object System.Windows.Forms.Padding((Px 1), 0, (Px 1), 0)
        $st.ToolButtons += $b
    }
    $f.Controls.Add($row1)

    $ed.add_MouseWheel({
        param($src, $e)
        if ([System.Windows.Forms.Control]::ModifierKeys -band [System.Windows.Forms.Keys]::Control) {
            $src.SetZoom($src.CurrentZoom * $(if ($e.Delta -gt 0) { 1.2 } else { 1 / 1.2 }), $false)
        }
    })
    $f.add_KeyDown({
        param($src, $e)
        $s = $src.Tag
        if ($s.Editor.IsTyping) { return }                                  # typing a text: its own keys (Ctrl+Z too)
        $k = $e.KeyCode; $handled = $true
        $inField = $src.ActiveControl -is [System.Windows.Forms.ComboBox] -or $src.ActiveControl -is [System.Windows.Forms.UpDownBase]
        $ed2 = $s.Editor
        if ($e.Control -and $k -eq 'Z') { if ($e.Shift) { $ed2.Redo() } else { $ed2.Undo() } }
        elseif ($e.Control -and $k -eq 'Y') { $ed2.Redo() }
        elseif ($e.Control -and $k -eq 'C') { Copy-EditedImage $s -Selection }
        elseif ($e.Control -and $k -eq 'S') { Save-EditedImageToHistory $s }
        elseif ($inField) { $handled = $false }                           # other keys belong to the size boxes
        elseif ($k -eq 'OemOpenBrackets') { if ($e.Control) { $s.TextSize.Value = [Math]::Max($s.TextSize.Minimum, $s.TextSize.Value - 4) } else { $s.LineWidth.Value = [Math]::Max(1, $s.LineWidth.Value - 1) } }
        elseif ($k -eq 'OemCloseBrackets') { if ($e.Control) { $s.TextSize.Value = [Math]::Min($s.TextSize.Maximum, $s.TextSize.Value + 4) } else { $s.LineWidth.Value = [Math]::Min(40, $s.LineWidth.Value + 1) } }
        elseif ($e.Control -and $k -eq 'D0') { $ed2.SetZoom(1, $true) }
        elseif ($e.Control -and $k -eq 'D1') { $ed2.SetZoom(1, $false) }
        elseif ($e.Control -and ($k -eq 'Oemplus' -or $k -eq 'Add')) { $ed2.SetZoom($ed2.CurrentZoom * 1.25, $false) }
        elseif ($e.Control -and ($k -eq 'OemMinus' -or $k -eq 'Subtract')) { $ed2.SetZoom($ed2.CurrentZoom / 1.25, $false) }
        elseif ($k -eq 'Delete' -or $k -eq 'Back') { $ed2.DeleteSelected() }
        elseif ($ed2.SelectedShape -and $k -in 'Left', 'Right', 'Up', 'Down') {
            $n = if ($e.Shift) { 10 } else { 1 }
            switch ($k.ToString()) { 'Left' { $ed2.Nudge(-$n, 0) } 'Right' { $ed2.Nudge($n, 0) } 'Up' { $ed2.Nudge(0, -$n) } 'Down' { $ed2.Nudge(0, $n) } }
        }
        elseif ($k -eq 'Return' -and -not $ed2.Selection.IsEmpty) { [void]$ed2.Crop(); Set-ImageTool $s 'select' }
        elseif ($k -eq 'Escape') {
            if ($ed2.SelectedShape) { $ed2.Deselect() }
            elseif (-not $ed2.Selection.IsEmpty) { $ed2.Selection = [System.Drawing.Rectangle]::Empty; $ed2.Invalidate(); Update-ImageEditorStatus $s }
            else { $src.Close() }
        }
        elseif ($k -eq 'F' -and -not $e.Control) { $s.FillBtn.PerformClick() }
        elseif (-not $e.Control -and -not $e.Alt) {
            $t = $ImageTools | Where-Object { $_[3] -eq $k.ToString() } | Select-Object -First 1
            if ($t) { Set-ImageTool $s $t[0] } else { $handled = $false }
        }
        else { $handled = $false }
        if ($handled) { $e.Handled = $true; $e.SuppressKeyPress = $true }
    })
    $f.add_FormClosing({
        param($src, $e)
        $s = $src.Tag
        if ($s.Dirty -and -not $script:Exiting) {
            $r = [System.Windows.Forms.MessageBox]::Show($src, 'Save the edited image to your clipboard history before closing?', 'Edit image', 'YesNoCancel', 'Question')
            if ($r -eq 'Cancel') { $e.Cancel = $true; return }
            if ($r -eq 'Yes') { Save-EditedImageToHistory $s }
        }
    })
    $f.add_FormClosed({ param($src, $e) $src.Dispose() })
    Register-ThemedWindow $f
    Set-ImageTool $st 'arrow'
    Sync-ImageStyle $st
    $f.Show()
    [PowerClipHost]::EnsureShown($f.Handle)
    $f.Activate()
    [void]$ed.Focus()
    $st
}

# Opens the editor with whatever picture is on the clipboard (or the newest image clip).
function Edit-ClipboardImage {
    $img = $null
    try { if ([System.Windows.Forms.Clipboard]::ContainsImage()) { $img = [System.Windows.Forms.Clipboard]::GetImage() } } catch { }
    if ($img) { [void](Show-ImageEditor $null (New-Object System.Drawing.Bitmap $img)); $img.Dispose(); return }
    $last = $script:Items | Where-Object { $_.Kind -eq 'image' } | Select-Object -First 1
    if ($last) { [void](Show-ImageEditor $last) } else { Show-Message 'There is no picture on the clipboard or in the history yet.' }
}

# ---------------------------------------------------------------------------
# Text from images (OCR) with the text recognition built into Windows 10 / 11.
# ---------------------------------------------------------------------------
$script:OcrReady = $null
function Initialize-Ocr {
    if ($null -ne $script:OcrReady) { return $script:OcrReady }
    try {
        Add-Type -AssemblyName System.Runtime.WindowsRuntime
        $null = [Windows.Media.Ocr.OcrEngine, Windows.Foundation, ContentType = WindowsRuntime]
        $null = [Windows.Graphics.Imaging.BitmapDecoder, Windows.Graphics, ContentType = WindowsRuntime]
        $null = [Windows.Graphics.Imaging.SoftwareBitmap, Windows.Graphics, ContentType = WindowsRuntime]
        $script:AsTaskOp = [System.WindowsRuntimeSystemExtensions].GetMethods() | Where-Object {
            $_.Name -eq 'AsTask' -and $_.GetParameters().Count -eq 1 -and $_.GetParameters()[0].ParameterType.Name -eq 'IAsyncOperation`1' } | Select-Object -First 1
        $script:OcrReady = [bool]$script:AsTaskOp
    } catch { Write-Log "ocr init failed: $_"; $script:OcrReady = $false }
    $script:OcrReady
}

function Wait-WinRt($Operation, [type]$ResultType) {
    $task = $script:AsTaskOp.MakeGenericMethod($ResultType).Invoke($null, @($Operation))
    [void]$task.Wait(30000)
    $task.Result
}

# Returns the recognised text (lines separated by line breaks), or '' when there is none.
function Get-ImageText([System.Drawing.Bitmap]$Bitmap) {
    if (-not (Initialize-Ocr)) { throw 'Text recognition is not available on this PC (it needs Windows 10 or 11 with an OCR language installed).' }
    $engine = [Windows.Media.Ocr.OcrEngine]::TryCreateFromUserProfileLanguages()
    if (-not $engine) { throw 'No text-recognition language is installed (Settings > Time & language > Language: add a language with "Optical character recognition").' }
    # small screenshots recognise much better when enlarged
    $work = $Bitmap
    $factor = if ($Bitmap.Width -lt 1200) { [Math]::Min(3, [Math]::Ceiling(1200 / [double]$Bitmap.Width)) } else { 1 }
    $max = [Windows.Media.Ocr.OcrEngine]::MaxImageDimension
    while ($factor -gt 1 -and ($Bitmap.Width * $factor -gt $max -or $Bitmap.Height * $factor -gt $max)) { $factor-- }
    if ($factor -gt 1) { $work = [PowerClipImageEditor]::Scaled($Bitmap, [int]($Bitmap.Width * $factor), [int]($Bitmap.Height * $factor)) }
    try {
        $ms = New-Object System.IO.MemoryStream
        $work.Save($ms, [System.Drawing.Imaging.ImageFormat]::Png)
        $ms.Position = 0
        $ras = [System.IO.WindowsRuntimeStreamExtensions]::AsRandomAccessStream($ms)
        $decoder = Wait-WinRt ([Windows.Graphics.Imaging.BitmapDecoder]::CreateAsync($ras)) ([Windows.Graphics.Imaging.BitmapDecoder])
        $soft = Wait-WinRt ($decoder.GetSoftwareBitmapAsync()) ([Windows.Graphics.Imaging.SoftwareBitmap])
        $result = Wait-WinRt ($engine.RecognizeAsync($soft)) ([Windows.Media.Ocr.OcrResult])
        (@($result.Lines | ForEach-Object { $_.Text }) -join "`r`n")
    } finally { if ($work -ne $Bitmap) { $work.Dispose() } }
}

# Editor button: copies the text of the picture (or of the selected area).
function Copy-ImageText($St) {
    $bmp = $St.Editor.Result()
    $sel = $St.Editor.Selection
    if (-not $sel.IsEmpty) { $part = $bmp.Clone($sel, $bmp.PixelFormat); $bmp.Dispose(); $bmp = $part }
    $St.Form.Cursor = 'WaitCursor'
    try {
        $text = Get-ImageText $bmp
        if (-not $text.Trim()) { $St.Status.Text = 'No text found in the picture.'; return }
        [System.Windows.Forms.Clipboard]::SetText($text)
        $n = @($text -split "`n").Count
        $St.Status.Text = "Copied $n line(s) of text$(if (-not $sel.IsEmpty) { ' from the selected area' }) - it is also in your history."
    } catch { $St.Status.Text = $_.Exception.Message }
    finally { $St.Form.Cursor = 'Default'; $bmp.Dispose() }
}

# Picker / palette: text of an image clip, or of the picture on the clipboard.
function Copy-ClipImageText($Item = $null) {
    $bmp = $null
    if ($Item -and $Item.Kind -eq 'image') { $bmp = Read-ImageFile (Get-DataPath $Item.Image) }
    elseif (-not $Item) { try { if ([System.Windows.Forms.Clipboard]::ContainsImage()) { $img = [System.Windows.Forms.Clipboard]::GetImage(); $bmp = New-Object System.Drawing.Bitmap $img; $img.Dispose() } } catch { } }
    if (-not $bmp) { Show-Message 'There is no picture to read text from.'; return }
    try {
        $text = Get-ImageText $bmp
        if (-not $text.Trim()) { Show-Message 'No text found in the picture.'; return }
        [System.Windows.Forms.Clipboard]::SetText($text)
        if ($form.Visible) { $status.Text = "Copied $(@($text -split "`n").Count) line(s) of text from the picture"; $status.ForeColor = $C.Accent }
        else { $tray.ShowBalloonTip(3000, 'Text copied', (Get-Preview $text), 'Info') }
    } catch { Show-Message $_.Exception.Message }
    finally { $bmp.Dispose() }
}

# ---------------------------------------------------------------------------
# Screenshot tool (Ctrl+Shift+X anywhere): drag an area, click a window, or press Enter for the whole
# screen. The shot goes into the history and opens in the image editor. Esc cancels.
# ---------------------------------------------------------------------------
function Start-ScreenCapture([int]$DelaySeconds = 0) {
    if ($script:Capturing) { return }
    $script:Capturing = $true
    try {
        Hide-Picker
        if ($DelaySeconds -gt 0) { Start-Sleep -Seconds $DelaySeconds }
        Start-Sleep -Milliseconds 150
        $vs = [System.Windows.Forms.SystemInformation]::VirtualScreen
        $shot = New-Object System.Drawing.Bitmap $vs.Width, $vs.Height
        $g = [System.Drawing.Graphics]::FromImage($shot); $g.CopyFromScreen($vs.Left, $vs.Top, 0, 0, $shot.Size); $g.Dispose()
        $windows = [PowerClipWindows]::Visible([IntPtr]::Zero)
    } catch { $script:Capturing = $false; Write-Log "screenshot failed: $_"; return }
    $pf = New-Object System.Windows.Forms.Form
    $pf.FormBorderStyle = 'None'; $pf.StartPosition = 'Manual'; $pf.Bounds = $vs; $pf.TopMost = $true; $pf.ShowInTaskbar = $false
    $pf.Cursor = [System.Windows.Forms.Cursors]::Cross; $pf.KeyPreview = $true
    $pf.GetType().GetProperty('DoubleBuffered', [Reflection.BindingFlags]'Instance, NonPublic').SetValue($pf, $true, $null)
    $dim = New-Object System.Drawing.Bitmap $shot.Width, $shot.Height
    $g = [System.Drawing.Graphics]::FromImage($dim); $g.DrawImageUnscaled($shot, 0, 0)
    $b = New-Object System.Drawing.SolidBrush ([System.Drawing.Color]::FromArgb(110, 0, 0, 0)); $g.FillRectangle($b, 0, 0, $dim.Width, $dim.Height); $b.Dispose(); $g.Dispose()
    $pf.Tag = @{ Shot = $shot; Dim = $dim; Origin = $vs.Location; Windows = $windows; Down = $null; Rect = [System.Drawing.Rectangle]::Empty; Hover = [System.Drawing.Rectangle]::Empty; Done = $false }
    $pf.add_Paint({
        param($src, $e)
        $t = $src.Tag; $g2 = $e.Graphics
        $g2.DrawImageUnscaled($t.Dim, 0, 0)
        $r = if (-not $t.Rect.IsEmpty) { $t.Rect } else { $t.Hover }
        if (-not $r.IsEmpty) {
            $g2.DrawImage($t.Shot, $r, $r, [System.Drawing.GraphicsUnit]::Pixel)
            $pen = New-Object System.Drawing.Pen ([System.Drawing.Color]::FromArgb(0, 120, 212)), 2; $g2.DrawRectangle($pen, $r); $pen.Dispose()
            $font = New-Object System.Drawing.Font('Segoe UI', 10, [System.Drawing.FontStyle]::Bold)
            $label = "$($r.Width) x $($r.Height)"
            $sz = $g2.MeasureString($label, $font)
            $ly = if ($r.Y -gt 26) { $r.Y - 24 } else { $r.Bottom + 4 }
            $g2.FillRectangle([System.Drawing.Brushes]::Black, $r.X, $ly, ($sz.Width + 8), 22)
            $g2.DrawString($label, $font, [System.Drawing.Brushes]::White, ($r.X + 4), ($ly + 2)); $font.Dispose()
        }
        $hint = 'Drag an area  -  click a window  -  Enter: whole screen  -  Esc: cancel'
        $font = New-Object System.Drawing.Font('Segoe UI', 11)
        $sz = $g2.MeasureString($hint, $font)
        $scr = [System.Windows.Forms.Screen]::FromPoint([System.Windows.Forms.Cursor]::Position).Bounds
        $hx = $scr.X - $t.Origin.X + ($scr.Width - $sz.Width) / 2; $hy = $scr.Y - $t.Origin.Y + 20
        $g2.FillRectangle((New-Object System.Drawing.SolidBrush ([System.Drawing.Color]::FromArgb(200, 20, 20, 20))), ($hx - 12), ($hy - 6), ($sz.Width + 24), ($sz.Height + 12))
        $g2.DrawString($hint, $font, [System.Drawing.Brushes]::White, $hx, $hy); $font.Dispose()
    })
    $pf.add_MouseDown({ param($src, $e) if ($e.Button -eq 'Left') { $src.Tag.Down = $e.Location } elseif ($e.Button -eq 'Right') { Complete-ScreenCapture $src $null } })
    $pf.add_MouseMove({
        param($src, $e)
        $t = $src.Tag
        if ($t.Down) {
            $d = $t.Down
            $t.Rect = [System.Drawing.Rectangle]::FromLTRB([Math]::Min($d.X, $e.X), [Math]::Min($d.Y, $e.Y), [Math]::Max($d.X, $e.X), [Math]::Max($d.Y, $e.Y))
        } else {
            $sp = New-Object System.Drawing.Point(($e.X + $t.Origin.X), ($e.Y + $t.Origin.Y))
            $hit = [System.Drawing.Rectangle]::Empty
            foreach ($w in $t.Windows) { if ($w.Contains($sp)) { $hit = $w; break } }
            if (-not $hit.IsEmpty) { $hit.Offset(-$t.Origin.X, -$t.Origin.Y); $hit = [System.Drawing.Rectangle]::Intersect($hit, (New-Object System.Drawing.Rectangle(0, 0, $t.Shot.Width, $t.Shot.Height))) }
            $t.Hover = $hit
        }
        $src.Invalidate()
    })
    $pf.add_MouseUp({
        param($src, $e)
        $t = $src.Tag
        if ($e.Button -ne 'Left' -or -not $t.Down) { return }
        $r = if ($t.Rect.Width -ge 4 -and $t.Rect.Height -ge 4) { $t.Rect } else { $t.Hover }
        $t.Down = $null
        if (-not $r.IsEmpty) { Complete-ScreenCapture $src $r }
    })
    $pf.add_KeyDown({
        param($src, $e)
        $t = $src.Tag
        if ($e.KeyCode -eq 'Escape') { Complete-ScreenCapture $src $null }
        elseif ($e.KeyCode -eq 'Return' -or $e.KeyCode -eq 'Space') {
            $scr = [System.Windows.Forms.Screen]::FromPoint([System.Windows.Forms.Cursor]::Position).Bounds
            $scr.Offset(-$t.Origin.X, -$t.Origin.Y)
            Complete-ScreenCapture $src $scr
        }
    })
    $pf.Show()
    $pf.Activate()
    [void][PowerClipHost]::SetForegroundWindow($pf.Handle)
}

function Complete-ScreenCapture($Form, $Rect) {
    $t = $Form.Tag
    if ($t.Done) { return }
    $t.Done = $true
    $Form.Close()
    $script:Capturing = $false
    try {
        if ($Rect -and -not $Rect.IsEmpty) {
            $Rect = [System.Drawing.Rectangle]::Intersect($Rect, (New-Object System.Drawing.Rectangle(0, 0, $t.Shot.Width, $t.Shot.Height)))
            $cut = $t.Shot.Clone($Rect, [System.Drawing.Imaging.PixelFormat]::Format32bppArgb)
            $script:IgnoreUntil = (Get-Date).AddMilliseconds(800)
            Add-ClipImage $cut
            $item = $script:Items | Where-Object { $_.Kind -eq 'image' } | Select-Object -First 1
            [void](Show-ImageEditor $item $cut)
        }
    } catch { Write-Log "screenshot failed: $_" }
    finally { $t.Shot.Dispose(); $t.Dim.Dispose(); $Form.Dispose() }
}

# ---------------------------------------------------------------------------
# Combine pictures: the selected image clips side by side or one under the other.
# ---------------------------------------------------------------------------
function Join-ClipImages([switch]$Vertical) {
    $items = @(Get-SelectedAll | Where-Object { $_.Kind -eq 'image' })
    if ($items.Count -lt 2) { Show-Message 'Select two or more picture clips first (Ctrl+click).'; return }
    $bmps = @($items | ForEach-Object { Read-ImageFile (Get-DataPath $_.Image) } | Where-Object { $_ })
    $gap = 12
    if ($Vertical) { $w = ($bmps | Measure-Object Width -Maximum).Maximum; $h = ($bmps | Measure-Object Height -Sum).Sum + $gap * ($bmps.Count - 1) }
    else { $w = ($bmps | Measure-Object Width -Sum).Sum + $gap * ($bmps.Count - 1); $h = ($bmps | Measure-Object Height -Maximum).Maximum }
    $out = New-Object System.Drawing.Bitmap ([int]$w), ([int]$h)
    $g = [System.Drawing.Graphics]::FromImage($out); $g.Clear([System.Drawing.Color]::White)
    $pos = 0
    foreach ($b in $bmps) {
        if ($Vertical) { $g.DrawImageUnscaled($b, [int](($w - $b.Width) / 2), $pos); $pos += $b.Height + $gap }
        else { $g.DrawImageUnscaled($b, $pos, [int](($h - $b.Height) / 2)); $pos += $b.Width + $gap }
        $b.Dispose()
    }
    $g.Dispose()
    [void](Show-ImageEditor $null $out)
}

# ---------------------------------------------------------------------------
# Paste stack: copy several things, then paste them one after another (Ctrl+Alt+Space pastes the next).
# Start it from the palette / tray ("collect what I copy"), or from selected clips in the picker.
# ---------------------------------------------------------------------------
$script:Stack = New-Object System.Collections.Generic.List[object]
$script:StackCollecting = $false

function Show-StackToast {
    if ($script:Stack.Count -eq 0 -and -not $script:StackCollecting) { if ($script:StackToast) { $script:StackToast.Hide() }; return }
    if (-not $script:StackToast -or $script:StackToast.IsDisposed) {
        $t = New-Object PowerClipToast
        $t.BackColor = $C.Card; $t.ForeColor = $C.Fore; $t.Font = $FontMain; $t.Padding = New-Object System.Windows.Forms.Padding(1)
        $inner = New-Object System.Windows.Forms.FlowLayoutPanel
        $inner.Dock = 'Fill'; $inner.FlowDirection = 'TopDown'; $inner.WrapContents = $false; $inner.BackColor = $C.Card
        $inner.Padding = New-Object System.Windows.Forms.Padding((Px 12), (Px 8), (Px 12), (Px 8))
        $title = New-Object System.Windows.Forms.Label; $title.AutoSize = $true; $title.Font = New-Object System.Drawing.Font($UiFont, (Fz 10), [System.Drawing.FontStyle]::Bold); $title.ForeColor = $C.Accent
        $body = New-Object System.Windows.Forms.Label; $body.AutoSize = $true; $body.ForeColor = $C.Dim; $body.Font = $FontSmall; $body.MaximumSize = New-Object System.Drawing.Size((Px 340), 0)
        $stop = New-Object System.Windows.Forms.LinkLabel; $stop.Text = 'Stop'; $stop.AutoSize = $true; $stop.LinkColor = $C.Accent
        $stop.add_LinkClicked({ Stop-PasteStack })
        $inner.Controls.AddRange(@($title, $body, $stop))
        $t.Controls.Add($inner)
        $t.add_Paint({ param($src, $e) $p = New-Object System.Drawing.Pen $C.Line; $e.Graphics.DrawRectangle($p, 0, 0, ($src.Width - 1), ($src.Height - 1)); $p.Dispose() })
        $t.Tag = @{ Title = $title; Body = $body }
        $script:StackToast = $t
    }
    $t = $script:StackToast
    $t.Tag.Title.Text = if ($script:StackCollecting) { "Paste stack: collecting ($($script:Stack.Count))" } else { "Paste stack: $($script:Stack.Count) left" }
    $next = if ($script:Stack.Count) { $script:Stack[0] } else { $null }
    $t.Tag.Body.Text = $(if ($script:StackCollecting) { "Copy the things you need, in order.`n" } else { '' }) + "Ctrl+Alt+Space pastes the next one" + $(if ($next) { ":`n" + $(if ($next.Kind -eq 'text') { Get-Preview $next.Text } else { "[$($next.Kind)]" }) } else { '.' })
    $t.Size = New-Object System.Drawing.Size((Px 370), ($t.Tag.Title.Height + $t.Tag.Body.PreferredHeight + (Px 50)))
    $wa = [System.Windows.Forms.Screen]::PrimaryScreen.WorkingArea
    $t.Location = New-Object System.Drawing.Point(($wa.Right - $t.Width - (Px 16)), ($wa.Bottom - $t.Height - (Px 16)))
    if (-not $t.Visible) { $t.Show() }
    $t.Refresh()
}

function Start-PasteStack([switch]$FromSelection) {
    $script:Stack.Clear()
    if ($FromSelection) {
        $sel = @(Get-SelectedAll)
        [array]::Reverse($sel)                    # the list shows newest first; paste oldest first
        foreach ($i in $sel) { $script:Stack.Add($i) }
        $script:StackCollecting = $false
        Hide-Picker
    } else { $script:StackCollecting = $true }
    Show-StackToast
}

function Stop-PasteStack { $script:Stack.Clear(); $script:StackCollecting = $false; Show-StackToast }

# Called for every new clip while collecting.
function Add-ToPasteStack($Item) {
    if (-not $script:StackCollecting -or -not $Item) { return }
    if ($script:Stack.Count -and $script:Stack[$script:Stack.Count - 1].Id -eq $Item.Id) { return }     # the same copy reported twice
    $script:Stack.Add($Item); Show-StackToast
}

function Invoke-PasteNext {
    if ($script:Stack.Count -eq 0) {
        if ($script:StackCollecting) { return }
        $tray.ShowBalloonTip(2500, 'Paste stack is empty', 'Start one from the tray menu, the command palette or by selecting clips in the picker.', 'Info')
        return
    }
    $script:StackCollecting = $false
    $item = $script:Stack[0]; $script:Stack.RemoveAt(0)
    $target = [PowerClipHost]::GetForegroundWindow()
    for ($i = 0; $i -lt 100 -and [PowerClipHost]::AnyModifierDown(); $i++) { Start-Sleep -Milliseconds 20 }
    $data = New-Object System.Windows.Forms.DataObject
    if ($item.Kind -eq 'image') { $p = Get-DataPath $item.Image; $data.SetImage((Read-ImageFile $p)); $data.SetData('PNG', (New-Object System.IO.MemoryStream(, [IO.File]::ReadAllBytes($p)))) }
    elseif ($item.Kind -eq 'files') { $drop = New-Object System.Collections.Specialized.StringCollection; foreach ($f in $item.Files) { [void]$drop.Add((Get-DataPath $f)) }; $data.SetFileDropList($drop) }
    else { $data.SetText($item.Text, [System.Windows.Forms.TextDataFormat]::UnicodeText) }
    $script:IgnoreUntil = (Get-Date).AddMilliseconds(800)
    try { [System.Windows.Forms.Clipboard]::SetDataObject($data, $true, 10, 50) } catch { return }
    Send-PasteTo $target
    Show-StackToast
    if ($script:Stack.Count -eq 0) { $tray.ShowBalloonTip(2000, 'Paste stack finished', 'Everything was pasted.', 'Info') }
}

# ---------------------------------------------------------------------------
# Text clean-up: one-click fixes for any text clip (the result is copied).
# ---------------------------------------------------------------------------
$TextCleanups = [ordered]@{
    'Trim spaces at the start and end'   = { param($t) $t.Trim() }
    'Join lines (remove line breaks)'    = { param($t) (($t -split '\r?\n' | ForEach-Object { $_.Trim() } | Where-Object { $_ }) -join ' ') }
    'Remove empty lines'                 = { param($t) (($t -split '\r?\n' | Where-Object { $_.Trim() }) -join "`r`n") }
    'Collapse repeated spaces'           = { param($t) (($t -split '\r?\n' | ForEach-Object { ($_ -replace '[ \t]+', ' ').Trim() }) -join "`r`n") }
    'UPPER CASE'                         = { param($t) $t.ToUpper() }
    'lower case'                         = { param($t) $t.ToLower() }
    'Title Case'                         = { param($t) (Get-Culture).TextInfo.ToTitleCase($t.ToLower()) }
    'Sentence case'                      = { param($t) [regex]::Replace($t.ToLower(), '(^\s*|[.!?]\s+)([a-z])', { param($m) $m.Groups[1].Value + $m.Groups[2].Value.ToUpper() }) }
    'Sort lines A-Z'                     = { param($t) (($t -split '\r?\n' | Sort-Object) -join "`r`n") }
    'Sort lines Z-A'                     = { param($t) (($t -split '\r?\n' | Sort-Object -Descending) -join "`r`n") }
    'Remove duplicate lines'             = { param($t) $seen = @{}; (($t -split '\r?\n' | Where-Object { if ($seen.ContainsKey($_)) { $false } else { $seen[$_] = 1; $true } }) -join "`r`n") }
    'Reverse line order'                 = { param($t) $l = @($t -split '\r?\n'); [array]::Reverse($l); ($l -join "`r`n") }
    'Number the lines'                   = { param($t) $n = 0; (($t -split '\r?\n' | ForEach-Object { $n++; "$n. $_" }) -join "`r`n") }
    "Quote lines for SQL IN ('a', 'b')"  = { param($t) '(' + (($t -split '\r?\n' | ForEach-Object { $_.Trim() } | Where-Object { $_ } | ForEach-Object { "'" + $_.Replace("'", "''") + "'" }) -join ', ') + ')' }
    'Join lines with commas'             = { param($t) (($t -split '\r?\n' | ForEach-Object { $_.Trim() } | Where-Object { $_ }) -join ', ') }
    'Split commas into lines'            = { param($t) (($t -split '\s*,\s*' | Where-Object { $_ }) -join "`r`n") }
}

function Add-CleanupMenu($Menu, $Item) {
    if (-not $Item -or $Item.Kind -ne 'text') { return }
    $sub = New-Object System.Windows.Forms.ToolStripMenuItem('Clean up text', (New-GlyphImage $Glyph.Edit))
    $sub.Tag = 'smart'
    foreach ($name in $TextCleanups.Keys) {
        $mi = $sub.DropDownItems.Add($name)
        $mi.Tag = @{ Run = $TextCleanups[$name]; Text = $Item.Text; Name = $name }
        $mi.add_Click({ param($src, $e) $t = $src.Tag; try { Set-SmartResult ([string](& $t.Run $t.Text)) $t.Name } catch { Write-Log "cleanup failed: $_" } })
    }
    [void]$sub.DropDownItems.Add('-')
    $words = @($Item.Text -split '\s+' | Where-Object { $_ }).Count; $lines = @($Item.Text -split '\r?\n').Count
    $info = $sub.DropDownItems.Add("$('{0:N0}' -f $Item.Text.Length) characters, $words words, $lines lines"); $info.Enabled = $false
    $sub.DropDown.Renderer = $MenuRenderer
    $Menu.Items.Insert([Math]::Min($Menu.Items.Count, (@($Menu.Items | Where-Object { $_.Tag -is [hashtable] -and $_.Tag.Run }).Count)), $sub)
}

# ---------------------------------------------------------------------------
# Merge clips: the selected text clips joined into one (copied).
# ---------------------------------------------------------------------------
function Merge-SelectedClips {
    $items = @(Get-SelectedAll | Where-Object { $_.Kind -eq 'text' })
    if ($items.Count -lt 2) { Show-Message 'Select two or more text clips first (Ctrl+click).'; return }
    $d = New-Object System.Windows.Forms.Form
    $d.Text = 'Merge clips'; $d.FormBorderStyle = 'FixedDialog'; $d.MaximizeBox = $false; $d.MinimizeBox = $false; $d.StartPosition = 'CenterParent'; $d.ShowInTaskbar = $false
    $d.BackColor = $C.Panel; $d.ForeColor = $C.Fore; $d.Font = $FontMain
    $d.ClientSize = New-Object System.Drawing.Size((Px (400 * $TextZoom)), ($FontMain.Height * 4 + (Px 110)))
    $tbl = New-Object System.Windows.Forms.TableLayoutPanel
    $tbl.Dock = 'Fill'; $tbl.ColumnCount = 2; $tbl.Padding = New-Object System.Windows.Forms.Padding((Px 14))
    [void]$tbl.ColumnStyles.Add((New-Object System.Windows.Forms.ColumnStyle('AutoSize'))); [void]$tbl.ColumnStyles.Add((New-Object System.Windows.Forms.ColumnStyle('Percent', 100)))
    $l = New-Object System.Windows.Forms.Label; $l.Text = "Join $($items.Count) clips with"; $l.AutoSize = $true; $l.Margin = New-Object System.Windows.Forms.Padding(0, (Px 8), (Px 12), 0)
    $sep = New-Object System.Windows.Forms.ComboBox; $sep.DropDownStyle = 'DropDown'; [void]$sep.Items.AddRange(@('New line', 'Blank line', 'Comma', 'Comma and space', 'Space', 'Tab', ' | ')); $sep.SelectedIndex = 0; $sep.Dock = 'Fill'
    $order = New-Object System.Windows.Forms.CheckBox; $order.Text = 'Oldest first (the order you copied them)'; $order.Checked = $true; $order.AutoSize = $true
    $tbl.Controls.Add($l, 0, 0); $tbl.Controls.Add($sep, 1, 0); $tbl.Controls.Add($order, 0, 1); $tbl.SetColumnSpan($order, 2)
    $btns = New-Object System.Windows.Forms.FlowLayoutPanel; $btns.FlowDirection = 'RightToLeft'; $btns.Dock = 'Fill'
    $cancel = New-Object PowerClipButton; $cancel.Text = 'Cancel'; $cancel.Font = $FontButton; $cancel.AutoSize = $true; $cancel.DialogResult = 'Cancel'
    $ok = New-Object PowerClipButton; $ok.Text = 'Merge and copy'; $ok.Variant = 1; $ok.Font = $FontButton; $ok.AutoSize = $true; $ok.DialogResult = 'OK'
    $btns.Controls.AddRange(@($cancel, $ok)); $tbl.Controls.Add($btns, 0, 2); $tbl.SetColumnSpan($btns, 2)
    $d.Controls.Add($tbl); $d.AcceptButton = $ok; $d.CancelButton = $cancel
    Register-ThemedWindow $d
    $script:Modal = $true
    try { $r = $d.ShowDialog($form) } finally { $script:Modal = $false }
    if ($r -eq 'OK') {
        $s = switch ($sep.Text) { 'New line' { "`r`n" } 'Blank line' { "`r`n`r`n" } 'Comma' { ',' } 'Comma and space' { ', ' } 'Space' { ' ' } 'Tab' { "`t" } default { $sep.Text } }
        if ($order.Checked) { [array]::Reverse($items) }
        Set-SmartResult (($items | ForEach-Object { $_.Text }) -join $s) "$($items.Count) clips merged"
    }
    $d.Dispose()
}

# ---------------------------------------------------------------------------
# Auto-delete rules: clips from some apps, or matching a pattern, delete themselves after a while.
#   app:<process name> <minutes>      text:<regular expression> <minutes>      # comments
# ---------------------------------------------------------------------------
function Get-ExpiryRules {
    foreach ($line in @($script:ExpiryRules)) {
        $t = ([string]$line).Trim()
        if (-not $t -or $t.StartsWith('#')) { continue }
        if ($t -match '^(app|text):(.+?)\s+(\d+)$') { [pscustomobject]@{ Kind = $Matches[1]; Match = $Matches[2].Trim(); Minutes = [int]$Matches[3] } }
    }
}

function Invoke-ExpiryRules {
    $rules = @(Get-ExpiryRules)
    if ($rules.Count -eq 0) { return }
    $now = Get-Date
    $gone = @()
    foreach ($i in $script:Items.ToArray()) {
        if ($i.Pinned) { continue }
        foreach ($r in $rules) {
            if (($now - $i.Time).TotalMinutes -lt $r.Minutes) { continue }
            $hit = if ($r.Kind -eq 'app') { $i.Source -and $i.Source -like $r.Match } else { $i.Kind -eq 'text' -and $(try { [regex]::IsMatch($i.Text, $r.Match) } catch { $false }) }
            if ($hit) { $gone += $i.Id; break }
        }
    }
    if ($gone.Count) {
        foreach ($id in $gone) { Remove-Clip $id }
        Save-History
        if ($form.Visible) { Update-List }
        Write-Log "auto-deleted $($gone.Count) clip(s)"
    }
}

$ExpiryTimer = New-Object System.Windows.Forms.Timer
$ExpiryTimer.Interval = 30000
$ExpiryTimer.add_Tick({ try { Invoke-ExpiryRules } catch { Write-Log "expiry failed: $_" } })
$ExpiryTimer.Start()

# ---------------------------------------------------------------------------
# Sync between PCs through a shared folder (OneDrive, Dropbox, a network share):
# text and picture clips, notes (with folders and pictures) and snippets. Deletions are passed on too.
# The newest version of a note wins. Secrets, settings and API data are not synced.
# ---------------------------------------------------------------------------
$TombstoneFile = Join-Path $DataDir 'sync-deleted.json'
$script:Tombstones = @{}
if (Test-Path $TombstoneFile) { try { $o = ConvertFrom-Json ([IO.File]::ReadAllText($TombstoneFile)); foreach ($p in $o.PSObject.Properties) { $script:Tombstones[$p.Name] = [string]$p.Value } } catch { } }

function Add-Tombstone([string]$Id) {
    if (-not $script:SyncDir -or -not $Id) { return }
    $script:Tombstones[$Id] = (Get-Date).ToUniversalTime().ToString('o')
    $script:TombstonesDirty = $true
}

function Save-Tombstones {
    # forget deletions older than 60 days
    $cut = (Get-Date).ToUniversalTime().AddDays(-60)
    foreach ($k in @($script:Tombstones.Keys)) { try { if ([datetime]::Parse($script:Tombstones[$k]).ToUniversalTime() -lt $cut) { $script:Tombstones.Remove($k) } } catch { $script:Tombstones.Remove($k) } }
    try { Write-JsonFile $TombstoneFile (ConvertTo-Json -InputObject ([pscustomobject]$script:Tombstones)) } catch { }
    $script:TombstonesDirty = $false
}

# Returns the items of a JSON array one by one (PowerShell 5.1 would otherwise hand back the whole array as one item).
function Read-SyncJson([string]$Path) {
    if (-not (Test-Path -LiteralPath $Path)) { return }
    try { ConvertFrom-Json (Read-DataText $Path) | ForEach-Object { $_ } } catch { }
}

function Invoke-Sync([switch]$Quiet) {
    if (-not $script:SyncDir) { return 'Choose a sync folder first.' }
    if ($script:Syncing) { return 'A sync is already running.' }
    $script:Syncing = $true
    try {
        $root = Join-Path $script:SyncDir 'DevTools-sync'
        foreach ($d in $root, (Join-Path $root 'images'), (Join-Path $root 'notes')) { if (-not (Test-Path -LiteralPath $d)) { [void](New-Item -ItemType Directory -Path $d -Force) } }
        if ($NoteUI.Form) { Save-CurrentNote }

        # ---- encryption: every PC must use the same data key; the sync folder carries it (password-protected only)
        $remoteKeys = Join-Path $root 'keys.dat'
        $localId = if ($script:DataKeyBytes) { Get-DataKeyId $script:DataKeyBytes } else { '' }
        if (Test-Path -LiteralPath $remoteKeys) {
            $rid = [string](ConvertFrom-Json ([IO.File]::ReadAllText($remoteKeys))).KeyId
            if ($rid -ne $localId) {
                return $(if ($localId) { 'Not synced: the sync folder uses a different encryption key. In Settings > Encryption choose "Use the key from the sync folder".' }
                         else { 'Not synced: the sync folder is encrypted. In Settings > Encryption choose "Use the key from the sync folder" (needs the master password).' })
            }
        } elseif ($localId) {
            $k = ConvertFrom-Json ([IO.File]::ReadAllText($KeysFile))
            [IO.File]::WriteAllText($remoteKeys, (ConvertTo-Json -InputObject ([ordered]@{ Version = 1; KeyId = $localId; Password = [string]$k.Password })))
        }

        # ---- deletions from everywhere
        $remoteDead = Read-SyncJson (Join-Path $root 'deleted.json')
        if ($remoteDead) { foreach ($p in $remoteDead.PSObject.Properties) { if (-not $script:Tombstones.ContainsKey($p.Name)) { $script:Tombstones[$p.Name] = [string]$p.Value } } }
        $dead = $script:Tombstones

        # ---- clips (text and pictures)
        $changedClips = 0
        $local = @{}; foreach ($i in $script:Items) { $local[$i.Id] = $i }
        foreach ($id in @($local.Keys)) { if ($dead.ContainsKey($id)) { Remove-Clip $id; $local.Remove($id); $changedClips++ } }
        $remote = @(Read-SyncJson (Join-Path $root 'clips.json'))
        foreach ($r in $remote) {
            if (-not $r -or -not $r.Id -or $dead.ContainsKey([string]$r.Id) -or $local.ContainsKey([string]$r.Id)) { continue }
            if ($r.Kind -eq 'text') {
                if (Find-Clip 'text' { param($i) $i.Text -ceq [string]$r.Text }) { continue }
                $it = New-ClipItem 'text' ([string]$r.Text) ([bool]$r.Pinned) $r.Time ([string]$r.Id)
            } elseif ($r.Kind -eq 'image') {
                $src = Join-Path $root "images\$($r.Hash).png"
                if (-not (Test-Path -LiteralPath $src) -or (Find-Clip 'image' { param($i) $i.Hash -eq [string]$r.Hash })) { continue }
                $it = New-ClipItem 'image' '' ([bool]$r.Pinned) $r.Time ([string]$r.Id)
                $it.Image = "images\$($it.Id).png"; Copy-Item -LiteralPath $src -Destination (Get-DataPath $it.Image) -Force
                $it.Width = [int]$r.Width; $it.Height = [int]$r.Height; $it.Hash = [string]$r.Hash; $it.Bytes = [long]$r.Bytes
            } else { continue }
            $it.Source = [string]$r.Source
            $script:Items.Add($it); $local[$it.Id] = $it; $changedClips++
        }
        if ($changedClips) {
            $sorted = @($script:Items | Sort-Object Time -Descending)
            $script:Items.Clear(); foreach ($i in $sorted) { $script:Items.Add($i) }
            Limit-History; Save-History
            if ($form.Visible) { Update-List }
        }
        $out = foreach ($i in $script:Items) {
            if ($i.Kind -eq 'text' -and $i.Text.Length -le 1MB) { [ordered]@{ Id = $i.Id; Kind = 'text'; Text = $i.Text; Pinned = [bool]$i.Pinned; Time = $i.Time.ToString('o'); Source = $i.Source } }
            elseif ($i.Kind -eq 'image' -and $i.Hash) {
                $dst = Join-Path $root "images\$($i.Hash).png"
                if (-not (Test-Path -LiteralPath $dst)) { Copy-Item -LiteralPath (Get-DataPath $i.Image) -Destination $dst -Force -ErrorAction SilentlyContinue }
                [ordered]@{ Id = $i.Id; Kind = 'image'; Pinned = [bool]$i.Pinned; Time = $i.Time.ToString('o'); Hash = $i.Hash; Width = $i.Width; Height = $i.Height; Bytes = $i.Bytes; Source = $i.Source }
            }
        }
        Write-JsonFile (Join-Path $root 'clips.json') (ConvertTo-Json -InputObject @($out) -Depth 3)
        # pictures nobody refers to any more
        $keep = @{}; foreach ($o in $out) { if ($o.Hash) { $keep["$($o.Hash).png"] = 1 } }
        Get-ChildItem -LiteralPath (Join-Path $root 'images') -File -ErrorAction SilentlyContinue | Where-Object { -not $keep.ContainsKey($_.Name) -and $_.LastWriteTime -lt (Get-Date).AddDays(-1) } | Remove-Item -Force -ErrorAction SilentlyContinue

        # ---- notes: the newest copy of each note wins
        $changedNotes = 0
        $rn = Join-Path $root 'notes'
        foreach ($n in @($script:Notes.ToArray())) { if ($dead.ContainsKey($n.Id)) { Remove-NoteFiles $n; [void]$script:Notes.Remove($n); $changedNotes++ } }
        $remoteNotes = @(Read-SyncJson (Join-Path $rn 'index.json'))
        $localById = @{}; foreach ($n in $script:Notes) { $localById[$n.Id] = $n }
        $copyNote = {
            param($Id, $From, $To)
            foreach ($suffix in '.page.json', '.page.enc') {
                $f = Join-Path $From "$Id$suffix"; $t2 = Join-Path $To "$Id$suffix"
                if (Test-Path -LiteralPath $f) { Copy-Item -LiteralPath $f -Destination $t2 -Force } elseif (Test-Path -LiteralPath $t2) { Remove-Item -LiteralPath $t2 -Force }
            }
            foreach ($dir in "$Id.images", $Id) {
                $f = Join-Path $From $dir; $t2 = Join-Path $To $dir
                if (Test-Path -LiteralPath $t2) { Remove-Item -LiteralPath $t2 -Recurse -Force }
                if (Test-Path -LiteralPath $f) { Copy-Item -LiteralPath $f -Destination $t2 -Recurse -Force }
            }
        }
        foreach ($r in $remoteNotes) {
            if (-not $r -or -not $r.Id -or $dead.ContainsKey([string]$r.Id)) { continue }
            $rm = Convert-Time $r.Modified
            $ln = $localById[[string]$r.Id]
            if (-not $ln -or $rm -gt $ln.Modified.AddSeconds(1)) {
                & $copyNote ([string]$r.Id) $rn $NotesDir
                if ($ln) { $ln.Title = [string]$r.Title; $ln.Text = [string]$r.Text; $ln.Modified = $rm; $ln.Folder = [string]$r.Folder; Set-NoteExtras $ln $r }
                else { $ln = New-NoteItem ([string]$r.Title) ([string]$r.Text) $r.Created $r.Modified ([string]$r.Id) ([string]$r.Folder); Set-NoteExtras $ln $r; $script:Notes.Add($ln) }
                if ($ln.Folder) { [void](Add-NoteFolder $ln.Folder) }
                $changedNotes++
                if ($NoteUI.Form -and $NoteUI.Current -and $NoteUI.Current.Id -eq $ln.Id) { Open-Note $ln }
            }
        }
        $remoteById = @{}; foreach ($r in $remoteNotes) { if ($r -and $r.Id) { $remoteById[[string]$r.Id] = $r } }
        foreach ($n in $script:Notes) {
            $r = $remoteById[$n.Id]
            if (-not $r -or $n.Modified -gt (Convert-Time $r.Modified).AddSeconds(1)) { & $copyNote $n.Id $NotesDir $rn }
        }
        foreach ($r in $remoteNotes) { if ($r -and $r.Id -and $dead.ContainsKey([string]$r.Id)) { & $copyNote ([string]$r.Id) (Join-Path $env:TEMP 'devtools-nothing') $rn } }
        $idx = foreach ($n in $script:Notes) { Get-NoteIndexEntry $n }
        Write-JsonFile (Join-Path $rn 'index.json') (ConvertTo-Json -InputObject @($idx) -Depth 3)
        $remoteFolders = @(Read-SyncJson (Join-Path $rn 'folders.json'))
        foreach ($f in $remoteFolders) { if ($f.Name -and -not $dead.ContainsKey("folder:$($f.Name)")) { [void](Add-NoteFolder ([string]$f.Name)) } }
        foreach ($f in $script:NoteFolders.ToArray()) { if ($dead.ContainsKey("folder:$($f.Name)")) { [void]$script:NoteFolders.Remove($f) } }
        Copy-Item -LiteralPath $NoteFoldersFile -Destination (Join-Path $rn 'folders.json') -Force -ErrorAction SilentlyContinue
        Save-NoteFolders
        if ($changedNotes) { Save-NotesIndex; Update-NoteList }

        # ---- snippets
        $remoteSn = @(Read-SyncJson (Join-Path $root 'snippets.json'))
        $have = @{}; foreach ($x in $script:Snippets) { $have[$x.Id] = $x }
        foreach ($x in $script:Snippets.ToArray()) { if ($dead.ContainsKey($x.Id)) { [void]$script:Snippets.Remove($x) } }
        foreach ($x in $remoteSn) { if ($x -and $x.Id -and -not $have.ContainsKey([string]$x.Id) -and -not $dead.ContainsKey([string]$x.Id)) { $script:Snippets.Add([pscustomobject]@{ Id = [string]$x.Id; Name = [string]$x.Name; Text = [string]$x.Text }) } }
        Save-Snippets
        Write-JsonFile (Join-Path $root 'snippets.json') (ConvertTo-Json -InputObject $script:Snippets.ToArray() -Depth 3)

        Write-JsonFile (Join-Path $root 'deleted.json') (ConvertTo-Json -InputObject ([pscustomobject]$script:Tombstones))
        Save-Tombstones
        $script:SyncLast = Get-Date
        Save-Settings
        $msg = "Synced: $changedClips clip change(s), $changedNotes note change(s)."
        Write-Log $msg
        $msg
    } catch {
        Write-Log "sync failed: $_ $($_.InvocationInfo.PositionMessage)"
        "Sync failed: $($_.Exception.Message)"
    } finally { $script:Syncing = $false }
}

function Remove-NoteFiles($Note) {
    foreach ($p in (Get-NoteRtf $Note), (Get-NotePage $Note), (Join-Path $NotesDir "$($Note.Id).page.enc")) { Remove-Item -LiteralPath $p -Force -ErrorAction SilentlyContinue }
    foreach ($p in (Get-NoteImagesDir $Note), (Get-NoteFilesDir $Note)) { Remove-Item -LiteralPath $p -Recurse -Force -ErrorAction SilentlyContinue }
}

$SyncTimer = New-Object System.Windows.Forms.Timer
$SyncTimer.Interval = 30000
$SyncTimer.add_Tick({
    $SyncTimer.Interval = 120000                     # first sync 30 s after start, then every 2 minutes
    if ($script:SyncDir -and (Test-Path -LiteralPath $script:SyncDir)) { [void](Invoke-Sync -Quiet) }
})
$SyncTimer.Start()

# Picker: "Move to secrets" takes a text clip out of the history and into the vault.
function Move-ClipToVault {
    $sel = Get-Selected
    if (-not $sel -or $sel.Kind -ne 'text') { return }
    $VaultUI.Pending = @{ Name = 'From clipboard'; Secret = $sel.Text; ClipId = $sel.Id }
    Show-Vault
}

# ---------------------------------------------------------------------------
# Settings: theme (System / Light / Dark), accent colour, capture limits, start with Windows, data.
# ---------------------------------------------------------------------------
$SetUI = @{}
$StartupLink = Join-Path ([Environment]::GetFolderPath('Startup')) 'DevTools.lnk'

function Set-StartWithWindows([bool]$On) {
    if (-not $On) { if (Test-Path $StartupLink) { Remove-Item -LiteralPath $StartupLink -Force }; return }
    $shell = New-Object -ComObject WScript.Shell
    $lnk = $shell.CreateShortcut($StartupLink)
    $lnk.TargetPath = Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'
    $lnk.Arguments = "-NoProfile -STA -ExecutionPolicy Bypass -WindowStyle Hidden -File `"$PSCommandPath`""
    $lnk.WorkingDirectory = $Root
    $lnk.WindowStyle = 7
    $lnk.Description = 'DevTools - clipboard manager and developer tools'
    $lnk.Save()
    [void][Runtime.InteropServices.Marshal]::ReleaseComObject($shell)
}

# The app used to be called PowerClipboard: move an old Startup shortcut over to the new name.
$OldStartupLink = Join-Path ([Environment]::GetFolderPath('Startup')) 'PowerClipboard.lnk'
if (Test-Path $OldStartupLink) {
    try { Set-StartWithWindows $true; Remove-Item -LiteralPath $OldStartupLink -Force } catch { }
}

function Get-DataSummary {
    $bytes = 0
    try { $bytes = (Get-ChildItem -LiteralPath $DataDir -Recurse -File -Force -ErrorAction SilentlyContinue | Measure-Object -Property Length -Sum).Sum } catch { }
    $pinned = @($script:Items | Where-Object { $_.Pinned }).Count
    "$($script:Items.Count) clips ($pinned pinned)   $Dot   $(Format-Size ([long]$bytes)) on disk"
}

# A titled, rounded card that holds one group of settings.
# ---------------------------------------------------------------------------
# Global shortcuts for any command of the palette (tools, Toolbox pages, actions). Settings > Global shortcuts.
# ---------------------------------------------------------------------------
$script:ToolHotkeyIds = @{}       # hotkey id -> command title
$script:HotkeyFailed = @()

# "Ctrl+Alt+N" -> @{ Mods; Key }, or $null.
function ConvertFrom-HotkeyText([string]$Text) {
    $mods = 0; $key = $null
    foreach ($p in ($Text -split '\+') | ForEach-Object { $_.Trim() } | Where-Object { $_ }) {
        switch ($p) {
            'Ctrl'  { $mods = $mods -bor [PowerClipHost]::MOD_CONTROL }
            'Alt'   { $mods = $mods -bor [PowerClipHost]::MOD_ALT }
            'Shift' { $mods = $mods -bor [PowerClipHost]::MOD_SHIFT }
            'Win'   { $mods = $mods -bor 8 }
            default { try { $key = [System.Windows.Forms.Keys]$p } catch { return $null } }
        }
    }
    if ($null -eq $key) { return $null }
    @{ Mods = [uint32]$mods; Key = [uint32]$key }
}

function Get-HotkeyText([System.Windows.Forms.KeyEventArgs]$E) {
    $k = $E.KeyCode
    if ($k -in 'ControlKey', 'ShiftKey', 'Menu', 'LWin', 'RWin', 'None') { $k = $null }
    $parts = @()
    if ($E.Control) { $parts += 'Ctrl' }
    if ($E.Alt) { $parts += 'Alt' }
    if ($E.Shift) { $parts += 'Shift' }
    if ($k) {
        $name = switch -Regex ([string]$k) { '^D(\d)$' { $Matches[1] } '^NumPad(\d)$' { "NumPad$($Matches[1])" } default { [string]$k } }
        $parts += $name
    }
    $parts -join '+'
}

function Register-ToolHotkeys {
    foreach ($id in @($script:ToolHotkeyIds.Keys)) { $clipHost.RemoveHotkey([int]$id) }
    $script:ToolHotkeyIds = @{}
    $script:HotkeyFailed = @()
    $id = 10
    foreach ($title in @($script:Hotkeys.Keys | Sort-Object)) {
        $p = ConvertFrom-HotkeyText $script:Hotkeys[$title]
        if (-not $p) { continue }
        if ($clipHost.AddHotkey($id, $p.Mods, $p.Key)) { $script:ToolHotkeyIds[$id] = $title } else { $script:HotkeyFailed += $title }
        $id++
    }
    if ($script:HotkeyFailed.Count) { Write-Log "hotkeys not available: $($script:HotkeyFailed -join ', ')" }
}

function Invoke-ToolHotkey([string]$Title) {
    $cmd = $script:PaletteCommands | Where-Object { $_.Kind -eq 'Command' -and $_.Title -eq $Title } | Select-Object -First 1
    if ($cmd) { & $cmd.Action $cmd }
}

function Update-HotkeyList {
    if (-not $SetUI.Form -or -not $SetUI.HotList) { return }
    $l = $SetUI.HotList
    $l.Items.Clear()
    foreach ($title in @($script:Hotkeys.Keys | Sort-Object { $script:Hotkeys[$_] })) {
        $bad = if ($script:HotkeyFailed -contains $title) { '   (taken by another app)' } else { '' }
        [void]$l.Items.Add("$($script:Hotkeys[$title].PadRight(20))$title$bad")
    }
    if ($l.Items.Count -eq 0) { [void]$l.Items.Add('No shortcuts yet - press Add...') }
}

function Show-HotkeyDialog {
    $d = New-Object System.Windows.Forms.Form
    $d.Text = 'Global shortcut'; $d.FormBorderStyle = 'FixedDialog'; $d.MaximizeBox = $false; $d.MinimizeBox = $false
    $d.StartPosition = 'CenterParent'; $d.ShowInTaskbar = $false; $d.BackColor = $C.Panel; $d.ForeColor = $C.Fore; $d.Font = $FontMain
    $d.AutoSize = $true; $d.AutoSizeMode = 'GrowAndShrink'
    $flow = New-Object System.Windows.Forms.FlowLayoutPanel
    $flow.FlowDirection = 'TopDown'; $flow.WrapContents = $false; $flow.AutoSize = $true; $flow.BackColor = $C.Panel
    $flow.Padding = New-Object System.Windows.Forms.Padding((Px 14), (Px 10), (Px 14), (Px 10))
    $d.Controls.Add($flow)
    $l1 = New-Object System.Windows.Forms.Label; $l1.AutoSize = $true; $l1.Text = 'Command'
    $cmd = New-Object System.Windows.Forms.ComboBox
    $cmd.DropDownStyle = 'DropDown'; $cmd.AutoCompleteMode = 'SuggestAppend'; $cmd.AutoCompleteSource = 'ListItems'
    $cmd.FlatStyle = 'Flat'; $cmd.BackColor = $C.Bg; $cmd.ForeColor = $C.Fore; $cmd.Width = Px (380 * $TextZoom); $cmd.MaxDropDownItems = 20
    foreach ($t in @($script:PaletteCommands | Where-Object { $_.Kind -eq 'Command' -and $_.Title -ne 'Clipboard history' } | ForEach-Object { $_.Title } | Sort-Object -Unique)) { [void]$cmd.Items.Add($t) }
    $l2 = New-Object System.Windows.Forms.Label; $l2.AutoSize = $true; $l2.Text = 'Keys (press them here)'; $l2.Margin = New-Object System.Windows.Forms.Padding(0, (Px 10), 0, 0)
    $keys = New-Object System.Windows.Forms.TextBox
    $keys.ReadOnly = $true; $keys.BorderStyle = 'FixedSingle'; $keys.BackColor = $C.Bg; $keys.ForeColor = $C.Fore; $keys.Width = Px (240 * $TextZoom)
    $keys.Font = New-Object System.Drawing.Font('Consolas', (Fz 12))
    $err = New-Object System.Windows.Forms.Label; $err.AutoSize = $true; $err.ForeColor = $C.Red; $err.MaximumSize = New-Object System.Drawing.Size((Px 380), 0)
    $keys.add_KeyDown({
        param($src, $e)
        $e.SuppressKeyPress = $true; $e.Handled = $true
        $t = Get-HotkeyText $e
        $src.Text = $t
        $src.Tag = $null
        if ($t -match '\+[^+]+$' -and $t -match '^(Ctrl|Alt)') { $src.Tag = $t }
        elseif ($t -match '^F\d+$') { $src.Tag = $t }
    })
    $btns = New-Object System.Windows.Forms.FlowLayoutPanel; $btns.AutoSize = $true; $btns.WrapContents = $false; $btns.BackColor = $C.Panel
    $btns.Margin = New-Object System.Windows.Forms.Padding(0, (Px 10), 0, 0)
    $ok = New-Button 'Save' '' {
        param($src, $e)
        $f = $src.FindForm(); $x = $f.Tag
        if ($x.Cmd.Items -notcontains $x.Cmd.Text) { $x.Err.Text = 'Pick a command from the list.'; return }
        if (-not $x.Keys.Tag) { $x.Err.Text = 'Press a key with Ctrl and / or Alt (for example Ctrl+Alt+N), or a function key.'; return }
        $f.DialogResult = 'OK'
    } $btns $Glyph.Save 1
    $cancel = New-Button 'Cancel' '' { param($src, $e) $src.FindForm().DialogResult = 'Cancel' } $btns '' 2
    $flow.Controls.AddRange(@($l1, $cmd, $l2, $keys, $err, $btns))
    $d.Tag = @{ Cmd = $cmd; Keys = $keys; Err = $err }
    $d.CancelButton = $cancel
    Set-ControlTheme $d $null $script:IsDark
    $d.add_Shown({ param($src, $e) [PowerClipHost]::EnsureShown($src.Handle) })
    $script:Modal = $true
    try {
        if ($d.ShowDialog($SetUI.Form) -ne 'OK') { return }
        $title = $cmd.Text; $text = [string]$keys.Tag
        foreach ($t in @($script:Hotkeys.Keys)) { if ($script:Hotkeys[$t] -eq $text) { $script:Hotkeys.Remove($t) } }     # one command per key
        $script:Hotkeys[$title] = $text
        Save-Settings
        Register-ToolHotkeys
        Update-HotkeyList
    } finally { $script:Modal = $false; $d.Dispose() }
}

function New-SettingsCard($Parent, [string]$Title) {
    $head = New-Object System.Windows.Forms.Label
    $head.Text = $Title; $head.AutoSize = $false
    $head.Width = $script:SetCardW; $head.Height = Px 30
    $head.Font = New-Object System.Drawing.Font($UiFont, (Fz 10.5), [System.Drawing.FontStyle]::Bold)
    $head.ForeColor = $C.Fore; $head.BackColor = $C.Bg; $head.TextAlign = 'BottomLeft'
    $head.Margin = New-Object System.Windows.Forms.Padding((Px 4), (Px 10), 0, (Px 4))
    $Parent.Controls.Add($head)
    $card = New-Object System.Windows.Forms.TableLayoutPanel
    $card.ColumnCount = 2; $card.AutoSize = $true; $card.AutoSizeMode = 'GrowAndShrink'
    [void]$card.ColumnStyles.Add((New-Object System.Windows.Forms.ColumnStyle('Percent', 100)))
    [void]$card.ColumnStyles.Add((New-Object System.Windows.Forms.ColumnStyle('AutoSize')))
    $card.MinimumSize = New-Object System.Drawing.Size($script:SetCardW, 0)
    $card.MaximumSize = New-Object System.Drawing.Size($script:SetCardW, 0)
    $card.BackColor = $C.Card
    $card.Padding = New-Object System.Windows.Forms.Padding((Px 14), (Px 8), (Px 12), (Px 8))
    $card.Margin = New-Object System.Windows.Forms.Padding(0, 0, 0, (Px 6))
    $card.add_Paint({
        param($src, $e)
        $e.Graphics.SmoothingMode = 'AntiAlias'
        $p = [PowerClipTheme]::Round((New-Object System.Drawing.RectangleF(0.5, 0.5, ($src.Width - 1.5), ($src.Height - 1.5))), (Px 8))
        $pen = New-Object System.Drawing.Pen $C.Line
        $e.Graphics.DrawPath($pen, $p); $pen.Dispose(); $p.Dispose()
    })
    $Parent.Controls.Add($card)
    $card
}

# One row in a card: a label (with an optional grey hint under it) and a control on the right.
function Add-SettingsRow($Card, [string]$Text, [string]$Hint, $Control) {
    $lbl = New-Object System.Windows.Forms.Label
    $lbl.AutoSize = $true; $lbl.BackColor = $C.Card; $lbl.ForeColor = $C.Fore
    $lbl.Text = $Text
    $lbl.Margin = New-Object System.Windows.Forms.Padding(0, (Px 8), (Px 10), $(if ($Hint) { 0 } else { (Px 8) }))
    $Card.Controls.Add($lbl, 0, $Card.RowCount)
    if ($Control) {
        $Control.Anchor = 'Right'
        $Card.Controls.Add($Control, 1, $Card.RowCount)
        if ($Hint) { $Card.SetRowSpan($Control, 2) }
    }
    $Card.RowCount++
    if ($Hint) {
        $h = New-Object System.Windows.Forms.Label
        $h.AutoSize = $true; $h.BackColor = $C.Card; $h.ForeColor = $C.Dim; $h.Font = $FontSmall; $h.Text = $Hint
        $h.MaximumSize = New-Object System.Drawing.Size((Px 330), 0)
        $h.Margin = New-Object System.Windows.Forms.Padding(0, (Px 1), (Px 10), (Px 8))
        $Card.Controls.Add($h, 0, $Card.RowCount)
        $Card.RowCount++
    }
    $lbl
}

function New-SettingsNumber([double]$Value, [double]$Min, [double]$Max, [int]$Decimals, [scriptblock]$OnChange) {
    $n = New-Object System.Windows.Forms.NumericUpDown
    $n.Minimum = $Min; $n.Maximum = $Max; $n.DecimalPlaces = $Decimals
    $n.Value = [decimal][Math]::Min($Max, [Math]::Max($Min, $Value))
    $n.Width = Px 90; $n.TextAlign = 'Right'; $n.BorderStyle = 'FixedSingle'
    $n.BackColor = $C.Bg; $n.ForeColor = $C.Fore
    $n.add_ValueChanged($OnChange)
    $n
}

function Update-EncryptionSetting([string]$Message = '') {
    if (-not $SetUI.Form -or -not $SetUI.EncInfo) { return }
    $on = [bool]$script:DataKey
    $SetUI.EncInfo.Text = $(if ($Message) { $Message } elseif ($on) { 'Your data files are encrypted.' } else { 'Your data files are plain text.' })
    $SetUI.EncInfo.ForeColor = if ($on) { $C.Green } else { $C.Fore }
    $SetUI.EncOn.Visible = -not $on; $SetUI.EncOff.Visible = $on
    $SetUI.EncSync.Visible = [bool]$script:SyncDir
}

function Update-SettingsState {
    if (-not $SetUI.Form -or $SetUI.Form.IsDisposed) { return }
    foreach ($k in $SetUI.ThemeButtons.Keys) { $SetUI.ThemeButtons[$k].Selected = ($k -eq $script:Theme); $SetUI.ThemeButtons[$k].Invalidate() }
    $SetUI.Swatches.Invalidate()
    $SetUI.ThemeHint.Text = "Following Windows (now $(if ($script:IsDark) { 'dark' } else { 'light' }))"
    $SetUI.ThemeHint.Visible = ($script:Theme -eq 'System')
    $SetUI.Paused.Checked = $script:Paused
}

function Show-Settings {
    if ($SetUI.Form -and -not $SetUI.Form.IsDisposed) {
        Update-SettingsState
        [PowerClipHost]::EnsureShown($SetUI.Form.Handle)
        $SetUI.Form.Activate()
        return
    }
    Hide-Picker
    $f = New-Object System.Windows.Forms.Form
    $f.Text = 'DevTools settings'
    $f.Icon = if ($script:Paused) { $IconPaused } else { $IconActive }
    $f.Size = New-Object System.Drawing.Size((Px (560 * $TextZoom)), (Px 720))
    $f.MinimumSize = New-Object System.Drawing.Size((Px (560 * $TextZoom)), (Px 400))
    $f.MaximumSize = New-Object System.Drawing.Size((Px (560 * $TextZoom)), 4000)
    $f.MaximizeBox = $false; $f.MinimizeBox = $false
    $f.StartPosition = 'CenterScreen'
    $f.BackColor = $C.Bg; $f.ForeColor = $C.Fore; $f.Font = $FontMain
    $f.KeyPreview = $true
    $f.add_KeyDown({ param($src, $e) if ($e.KeyCode -eq 'Escape') { $src.Close() } })
    $SetUI.Form = $f

    $page = New-Object System.Windows.Forms.FlowLayoutPanel
    $page.Dock = 'Fill'; $page.FlowDirection = 'TopDown'; $page.WrapContents = $false; $page.AutoScroll = $true
    $page.BackColor = $C.Bg
    $page.Padding = New-Object System.Windows.Forms.Padding((Px 18), (Px 6), (Px 10), (Px 18))
    $f.Controls.Add($page)
    # Width the cards are laid out for (the page scrolls vertically only).
    $script:SetCardW = $f.ClientSize.Width - (Px 30) - [System.Windows.Forms.SystemInformation]::VerticalScrollBarWidth

    # --- Appearance
    $card = New-SettingsCard $page 'Appearance'
    $seg = New-Object System.Windows.Forms.FlowLayoutPanel
    $seg.AutoSize = $true; $seg.WrapContents = $false; $seg.BackColor = $C.Card; $seg.Margin = New-Object System.Windows.Forms.Padding(0, (Px 4), 0, (Px 4))
    $SetUI.ThemeButtons = [ordered]@{}
    foreach ($t in @(@('System', $Glyph.Settings), @('Light', $Glyph.Sun), @('Dark', $Glyph.Moon))) {
        $b = New-Button $t[0] "Use the $($t[0].ToLower()) theme" {
            param($src, $e)
            $script:Theme = $src.Tag
            Save-Settings
            Set-Theme
            Update-SettingsState
        } $seg $t[1] 2
        $b.Tag = $t[0]; $b.Margin = New-Object System.Windows.Forms.Padding((Px 2), 0, 0, 0)
        $SetUI.ThemeButtons[$t[0]] = $b
    }
    [void](Add-SettingsRow $card 'Theme' 'System follows the Windows light / dark app mode.' $seg)
    $SetUI.ThemeHint = New-Object System.Windows.Forms.Label
    $SetUI.ThemeHint.AutoSize = $true; $SetUI.ThemeHint.Font = $FontSmall; $SetUI.ThemeHint.BackColor = $C.Card; $SetUI.ThemeHint.ForeColor = $C.Accent
    $SetUI.ThemeHint.Margin = New-Object System.Windows.Forms.Padding(0, 0, 0, (Px 6))
    $card.Controls.Add($SetUI.ThemeHint, 0, $card.RowCount); $card.SetColumnSpan($SetUI.ThemeHint, 2); $card.RowCount++

    # Accent swatches, drawn as circles; the current one gets a ring.
    $sw = New-Object System.Windows.Forms.Panel
    $sw.Size = New-Object System.Drawing.Size(((Px 34) * $Accents.Count), (Px 34)); $sw.BackColor = $C.Card; $sw.Cursor = 'Hand'
    $sw.Margin = New-Object System.Windows.Forms.Padding(0, (Px 4), 0, (Px 4))
    $sw.add_Paint({
        param($src, $e)
        $g = $e.Graphics; $g.SmoothingMode = 'AntiAlias'
        $i = 0
        foreach ($name in $Accents.Keys) {
            $col = ColorHex $Accents[$name][$(if ($script:IsDark) { 1 } else { 0 })]
            $x = $i * (Px 34) + (Px 7); $y = Px 7; $d = Px 20
            $b = New-Object System.Drawing.SolidBrush $col
            $g.FillEllipse($b, $x, $y, $d, $d); $b.Dispose()
            if ($name -eq $script:Accent) {
                $pen = New-Object System.Drawing.Pen($col, [float](Px 2))
                $g.DrawEllipse($pen, ($x - (Px 4)), ($y - (Px 4)), ($d + (Px 8)), ($d + (Px 8))); $pen.Dispose()
            }
            $i++
        }
    })
    $sw.add_MouseClick({
        param($src, $e)
        $i = [int][Math]::Floor($e.X / (Px 34))
        $names = @($Accents.Keys)
        if ($i -lt 0 -or $i -ge $names.Count) { return }
        $script:Accent = $names[$i]
        Save-Settings
        Set-Theme
        Update-SettingsState
    })
    $sw.add_MouseMove({
        param($src, $e)
        $i = [int][Math]::Floor($e.X / (Px 34)); $names = @($Accents.Keys)
        if ($i -ge 0 -and $i -lt $names.Count -and $SetUI.SwatchTip -ne $names[$i]) { $SetUI.SwatchTip = $names[$i]; $tooltip.SetToolTip($src, $names[$i]) }
    })
    $SetUI.Swatches = $sw
    [void](Add-SettingsRow $card 'Accent colour' 'Buttons, selection, links and the tray icon.' $sw)

    $seg = New-Object System.Windows.Forms.FlowLayoutPanel
    $seg.AutoSize = $true; $seg.WrapContents = $false; $seg.BackColor = $C.Card; $seg.Margin = New-Object System.Windows.Forms.Padding(0, (Px 4), 0, (Px 4))
    $SetUI.SizeButtons = [ordered]@{}
    foreach ($t in 'Small', 'Medium', 'Large') {
        $b = New-Button $t "$t text" {
            param($src, $e)
            $script:TextSize = $src.Tag
            Save-Settings
            foreach ($k in $SetUI.SizeButtons.Keys) { $SetUI.SizeButtons[$k].Selected = ($k -eq $script:TextSize); $SetUI.SizeButtons[$k].Invalidate() }
            $SetUI.Restart.Visible = $true
        } $seg '' 2
        $b.Tag = $t; $b.Margin = New-Object System.Windows.Forms.Padding((Px 2), 0, 0, 0)
        $b.Selected = ($t -eq $script:TextSize)
        $SetUI.SizeButtons[$t] = $b
    }
    [void](Add-SettingsRow $card 'Text size' 'Size of all text in DevTools. Takes effect after a restart.' $seg)
    $SetUI.Restart = New-Button 'Restart now' 'Restart DevTools to apply the new text size' { Restart-App } $card $Glyph.Refresh 1
    $SetUI.Restart.Visible = $false; $SetUI.Restart.Anchor = 'Right'
    $card.Controls.Add($SetUI.Restart, 1, $card.RowCount); $card.RowCount++

    # --- Capture
    $card = New-SettingsCard $page 'Capture'
    $cb = New-Object System.Windows.Forms.CheckBox
    $cb.AutoSize = $true; $cb.BackColor = $C.Card; $cb.ForeColor = $C.Fore; $cb.Text = 'Paused'
    $cb.Checked = $script:Paused
    $cb.add_CheckedChanged({ param($src, $e) if ($src.Checked -ne $script:Paused) { Set-Paused $src.Checked } })
    $SetUI.Paused = $cb
    [void](Add-SettingsRow $card 'Pause capturing' 'While paused, nothing you copy is saved.' $cb)
    $n = New-SettingsNumber $script:MaxItems 10 100000 0 { param($src, $e) $script:MaxItems = [int]$src.Value; Save-Settings }
    [void](Add-SettingsRow $card 'History size' 'Unpinned clips to keep. Pinned clips are never removed.' $n)
    $n = New-SettingsNumber $script:MaxFileMB 0.1 2048 1 { param($src, $e) $script:MaxFileMB = [double]$src.Value; Save-Settings }
    [void](Add-SettingsRow $card 'Largest image / file (MB)' 'Screenshots and copied files above this size are not stored.' $n)
    $n = New-SettingsNumber $script:MaxTextMB 0.1 2048 1 { param($src, $e) $script:MaxTextMB = [double]$src.Value; Save-Settings }
    [void](Add-SettingsRow $card 'Largest text (MB)' 'Copied text above this size is not stored.' $n)
    $ig = New-Object System.Windows.Forms.TextBox
    $ig.Multiline = $true; $ig.ScrollBars = 'Vertical'; $ig.AcceptsReturn = $true; $ig.BorderStyle = 'FixedSingle'
    $ig.BackColor = $C.Bg; $ig.ForeColor = $C.Fore; $ig.Width = Px (170 * $TextZoom); $ig.Height = $FontMain.Height * 5
    $ig.Text = ($script:IgnoreApps -join "`r`n")
    $ig.add_TextChanged({
        param($src, $e)
        $script:IgnoreApps = @($src.Text -split '[\r\n,;]+' | ForEach-Object { ($_.Trim() -replace '\.exe$', '') } | Where-Object { $_ })
        Save-Settings
    })
    $SetUI.Ignore = $ig
    $xr = New-Object System.Windows.Forms.TextBox
    $xr.Multiline = $true; $xr.ScrollBars = 'Vertical'; $xr.AcceptsReturn = $true; $xr.BorderStyle = 'FixedSingle'; $xr.WordWrap = $false
    $xr.BackColor = $C.Bg; $xr.ForeColor = $C.Fore; $xr.Width = Px (230 * $TextZoom); $xr.Height = $FontMain.Height * 4
    $xr.Font = New-Object System.Drawing.Font('Consolas', (Fz 9))
    $xr.Text = ($script:ExpiryRules -join "`r`n")
    $xr.add_TextChanged({ param($src, $e) $script:ExpiryRules = @($src.Text -split '\r?\n'); Save-Settings })
    [void](Add-SettingsRow $card 'Delete automatically after a while' "One rule per line. app:<app> <minutes> deletes copies from that app; text:<regular expression> <minutes> deletes matching text. Pinned clips are never deleted. Lines starting with # are ignored." $xr)
    [void](Add-SettingsRow $card 'Never save copies from' "One app per line (process name, e.g. chrome or KeePass). Copies from these apps are ignored. Apps that mark copied passwords as private are always skipped. Right-click a clip to add the app it came from." $ig)

    # --- Secrets
    $card = New-SettingsCard $page 'Secrets'
    $n = New-SettingsNumber $script:VaultLockMin 1 240 0 { param($src, $e) $script:VaultLockMin = [int]$src.Value; Save-Settings; Update-VaultStatus }
    [void](Add-SettingsRow $card 'Lock after (minutes idle)' 'The vault locks itself when you have not used it for this long, and always when its window closes.' $n)
    $n = New-SettingsNumber $script:VaultClearSec 5 600 0 { param($src, $e) $script:VaultClearSec = [int]$src.Value; Save-Settings; Update-VaultStatus }
    [void](Add-SettingsRow $card 'Clear copied secrets after (seconds)' 'Copied secrets never go into any clipboard history; the clipboard is emptied after this.' $n)

    # --- Global shortcuts
    $card = New-SettingsCard $page 'Global shortcuts'
    $hp = New-Object System.Windows.Forms.FlowLayoutPanel
    $hp.FlowDirection = 'TopDown'; $hp.WrapContents = $false; $hp.AutoSize = $true; $hp.BackColor = $C.Card
    $hl = New-Object System.Windows.Forms.ListBox
    $hl.BorderStyle = 'FixedSingle'; $hl.BackColor = $C.Bg; $hl.ForeColor = $C.Fore; $hl.IntegralHeight = $false
    $hl.Font = New-Object System.Drawing.Font('Consolas', (Fz 9.5)); $hl.Width = Px (380 * $TextZoom); $hl.Height = $hl.Font.Height * 6 + (Px 4)
    $hp.Controls.Add($hl)
    $SetUI.HotList = $hl
    $hb = New-Object System.Windows.Forms.FlowLayoutPanel; $hb.AutoSize = $true; $hb.WrapContents = $false; $hb.BackColor = $C.Card
    [void](New-Button 'Add...' 'Give a command its own shortcut' { Show-HotkeyDialog } $hb $Glyph.Add 1)
    [void](New-Button 'Remove' 'Remove the selected shortcut' {
        $i = $SetUI.HotList.SelectedIndex
        $titles = @($script:Hotkeys.Keys | Sort-Object { $script:Hotkeys[$_] })
        if ($i -lt 0 -or $i -ge $titles.Count) { return }
        $script:Hotkeys.Remove($titles[$i]); Save-Settings; Register-ToolHotkeys; Update-HotkeyList
    } $hb $Glyph.Delete 2)
    $hp.Controls.Add($hb)
    [void](Add-SettingsRow $card 'Open any tool from anywhere' 'Give any tool, Toolbox page or command-palette action its own keys, e.g. Ctrl+Alt+N for Notes or Ctrl+Alt+T for Transform. They work in every app.' $hp)
    Update-HotkeyList

    # --- Encryption
    $card = New-SettingsCard $page 'Encryption'
    $er = New-Object System.Windows.Forms.FlowLayoutPanel
    $er.AutoSize = $true; $er.WrapContents = $false; $er.BackColor = $C.Card
    $SetUI.EncOn = New-Button 'Encrypt my data files...' 'Encrypt clip history, API tester data, notes and snippets' {
        $SetUI.Form.Cursor = 'WaitCursor'
        try { $r = Enable-DataEncryption } finally { $SetUI.Form.Cursor = 'Default' }
        Update-EncryptionSetting $r
    } $er $Glyph.Lock 1
    $SetUI.EncOff = New-Button 'Turn off' 'Decrypt the data files again (plain text)' {
        if ([System.Windows.Forms.MessageBox]::Show($SetUI.Form, 'Decrypt your data files so they are plain text again?', 'Encryption', 'YesNo', 'Question') -ne 'Yes') { return }
        $SetUI.Form.Cursor = 'WaitCursor'
        try { $r = Disable-DataEncryption } finally { $SetUI.Form.Cursor = 'Default' }
        Update-EncryptionSetting $r
    } $er '' 2
    $SetUI.EncSync = New-Button 'Use the key from the sync folder...' 'Another PC encrypts the synced data: use the same key here (needs the master password)' { Update-EncryptionSetting (Use-SyncDataKey) } $er $Glyph.Refresh 2
    $SetUI.EncInfo = Add-SettingsRow $card '' 'Clip history (with big texts), API tester data, notes, snippets, monitored hosts and colours. This PC opens them with your Windows account; anywhere else (another PC or user, a restored backup, someone you give it to) they open with the Secrets master password. Pictures, copied files and note attachments stay unencrypted.' $er
    Update-EncryptionSetting

    # --- Sync
    $card = New-SettingsCard $page 'Sync between PCs'
    $sr = New-Object System.Windows.Forms.FlowLayoutPanel
    $sr.AutoSize = $true; $sr.WrapContents = $false; $sr.BackColor = $C.Card
    [void](New-Button 'Choose folder...' 'A folder both PCs can reach, e.g. in OneDrive or Dropbox' {
        $d = New-Object System.Windows.Forms.FolderBrowserDialog
        $d.Description = 'Folder to sync through (OneDrive, Dropbox or a network share). DevTools creates DevTools-sync inside it.'
        if ($script:SyncDir) { $d.SelectedPath = $script:SyncDir }
        $script:Modal = $true
        try { if ($d.ShowDialog($SetUI.Form) -eq 'OK') { $script:SyncDir = $d.SelectedPath; Save-Settings; $SetUI.SyncInfo.Text = "Sync folder: $($script:SyncDir)" } }
        finally { $script:Modal = $false; $d.Dispose() }
    } $sr $Glyph.Folder)
    if ($env:OneDrive) { [void](New-Button 'Use OneDrive' "Sync through $env:OneDrive" { $script:SyncDir = $env:OneDrive; Save-Settings; $SetUI.SyncInfo.Text = "Sync folder: $($script:SyncDir)" } $sr $Glyph.Globe 2) }
    [void](New-Button 'Sync now' 'Sync right away (it also runs every 2 minutes)' { $SetUI.Form.Cursor = 'WaitCursor'; try { $SetUI.SyncInfo.Text = Invoke-Sync } finally { $SetUI.Form.Cursor = 'Default' } } $sr $Glyph.Refresh 1)
    [void](New-Button 'Turn off' 'Stop syncing (nothing is deleted)' { $script:SyncDir = ''; Save-Settings; $SetUI.SyncInfo.Text = 'Sync is off.' } $sr '' 2)
    $syncText = if ($script:SyncDir) { "Sync folder: $($script:SyncDir)$(if ($script:SyncLast) { "  $Dot  last sync $(Format-Age $script:SyncLast)" })" } else { 'Sync is off.' }
    $SetUI.SyncInfo = Add-SettingsRow $card $syncText 'Text and picture clips, notes (with folders and pictures) and snippets. Deleting on one PC deletes on the other. For each note the newest version wins. Secrets, settings and API data are not synced (use Backup).' $sr

    # --- Backup
    $card = New-SettingsCard $page 'Backup'
    $bf = New-Object System.Windows.Forms.FlowLayoutPanel
    $bf.AutoSize = $true; $bf.WrapContents = $false; $bf.BackColor = $C.Card
    [void](New-Button 'Back up now' 'Zip the whole data folder into the backup folder' {
        $SetUI.Form.Cursor = 'WaitCursor'
        try { $p = Invoke-Backup; $SetUI.BackupInfo.Text = "Last backup: just now  ($(Split-Path -Leaf $p))" }
        catch { [void][System.Windows.Forms.MessageBox]::Show($SetUI.Form, "Backup failed: $($_.Exception.Message)", 'Backup') }
        finally { $SetUI.Form.Cursor = 'Default' }
    } $bf $Glyph.Save 1)
    [void](New-Button 'Restore...' 'Replace the current data with a backup' { Restore-Backup $SetUI.Form } $bf $Glyph.Undo)
    $last = if ($script:BackupLast) { "Last backup: $(Format-Age $script:BackupLast)" } else { 'No backup yet' }
    $SetUI.BackupInfo = Add-SettingsRow $card $last 'Clips, notes, secrets (still encrypted), API collections and settings.' $bf
    $folderRow = New-Object System.Windows.Forms.FlowLayoutPanel
    $folderRow.AutoSize = $true; $folderRow.WrapContents = $false; $folderRow.BackColor = $C.Card
    [void](New-Button 'Change...' 'Choose the backup folder, e.g. a OneDrive or Dropbox folder to keep a copy in the cloud' {
        $d = New-Object System.Windows.Forms.FolderBrowserDialog
        $d.Description = 'Folder for DevTools backups (a OneDrive / Dropbox folder keeps a copy in the cloud)'
        $d.SelectedPath = Get-BackupDir
        $script:Modal = $true
        try { if ($d.ShowDialog($SetUI.Form) -eq 'OK') { $script:BackupDir = $d.SelectedPath; Save-Settings; $SetUI.BackupDirLabel.Text = 'Backup folder' ; $SetUI.BackupDirHint.Text = $d.SelectedPath } }
        finally { $script:Modal = $false; $d.Dispose() }
    } $folderRow $Glyph.Folder)
    [void](New-Button 'Open' 'Open the backup folder' { $p = Get-BackupDir; if (-not (Test-Path -LiteralPath $p)) { [void](New-Item -ItemType Directory -Path $p -Force) }; Start-Process explorer.exe $p } $folderRow $Glyph.Open 2)
    if ($env:OneDrive -and -not $script:BackupDir) {
        [void](New-Button 'Use OneDrive' "Back up to $env:OneDrive\DevTools backups" {
            $script:BackupDir = Join-Path $env:OneDrive 'DevTools backups'; Save-Settings; $SetUI.BackupDirHint.Text = $script:BackupDir
        } $folderRow $Glyph.Globe 2)
    }
    $SetUI.BackupDirLabel = Add-SettingsRow $card 'Backup folder' (Get-BackupDir) $folderRow
    $SetUI.BackupDirHint = $card.GetControlFromPosition(0, $card.RowCount - 1)
    $every = New-Object System.Windows.Forms.ComboBox
    $every.DropDownStyle = 'DropDownList'; $every.FlatStyle = 'Flat'; $every.BackColor = $C.Bg; $every.ForeColor = $C.Fore; $every.Width = Px (150 * $TextZoom)
    $choices = [ordered]@{ 'Off' = 0; 'Every 6 hours' = 6; 'Every day' = 24; 'Every week' = 168 }
    foreach ($k in $choices.Keys) { [void]$every.Items.Add($k) }
    $every.SelectedItem = @($choices.Keys | Where-Object { $choices[$_] -eq $script:BackupHours })[0]
    if ($every.SelectedIndex -lt 0) { $every.SelectedIndex = 0 }
    $every.Tag = $choices
    $every.add_SelectedIndexChanged({ param($src, $e) $script:BackupHours = $src.Tag[[string]$src.SelectedItem]; Save-Settings })
    [void](Add-SettingsRow $card 'Automatic backup' "Off by default: backups contain your clipboard history. Keeps the newest $($script:BackupKeep)." $every)

    # --- Startup
    $card = New-SettingsCard $page 'Startup'
    $cb = New-Object System.Windows.Forms.CheckBox
    $cb.AutoSize = $true; $cb.BackColor = $C.Card; $cb.ForeColor = $C.Fore; $cb.Text = 'On'
    $cb.Checked = Test-Path $StartupLink
    $cb.add_CheckedChanged({
        param($src, $e)
        try { Set-StartWithWindows $src.Checked }
        catch { [void][System.Windows.Forms.MessageBox]::Show($SetUI.Form, "Could not update the Startup shortcut:`n$($_.Exception.Message)", 'DevTools') }
    })
    [void](Add-SettingsRow $card 'Start with Windows' 'Adds a shortcut to your Startup folder (no admin rights needed).' $cb)

    # --- Data
    $card = New-SettingsCard $page 'Data'
    $dataBtns = New-Object System.Windows.Forms.FlowLayoutPanel
    $dataBtns.AutoSize = $true; $dataBtns.WrapContents = $false; $dataBtns.BackColor = $C.Card
    [void](New-Button 'Open folder' 'Open the data folder in Explorer' { Start-Process explorer.exe $DataDir } $dataBtns $Glyph.Open)
    [void](New-Button 'Clear history' 'Delete all unpinned clips' {
        $script:Modal = $true
        try {
            $count = @($script:Items | Where-Object { -not $_.Pinned }).Count
            if ($count -gt 0 -and [System.Windows.Forms.MessageBox]::Show($SetUI.Form, "Delete all $count unpinned clips? Pinned clips are kept.",
                    'DevTools', 'YesNo', 'Warning') -eq 'Yes') {
                foreach ($i in @($script:Items | Where-Object { -not $_.Pinned })) { Remove-Clip $i.Id }
                Save-History
                Update-List
            }
        } finally { $script:Modal = $false }
        $SetUI.DataInfo.Text = Get-DataSummary
    } $dataBtns $Glyph.Clear 3)
    $SetUI.DataInfo = Add-SettingsRow $card (Get-DataSummary) $DataDir $dataBtns

    # --- Shortcuts
    $card = New-SettingsCard $page 'Keyboard shortcuts'
    $keys = @(
        @('Ctrl+Shift+V', 'Open DevTools (from anywhere)'),
        @('Ctrl+Shift+Space', 'Command palette (from anywhere; Ctrl+K in the picker)'),
        @('Ctrl+Alt+V', 'Paste the clipboard as plain text (from anywhere)'),
        @('Enter / Shift+Enter', 'Paste / copy the selected clip'),
        @('Ctrl+P', 'Pin or unpin'), @('F2', 'Edit text, open image / file'), @('Del', 'Delete'),
        @('Ctrl+1 ... Ctrl+5', 'Filter: all, text, images, files, pinned'),
        @('Ctrl+D', 'Compare (two selected clips, or empty)'), @('Ctrl+N', 'Notes'),
        @('Ctrl+T', 'Transform text'), @('Ctrl+Shift+F', 'Find in files'),
        @('Ctrl+Shift+N', 'Network tools'), @('Ctrl+Shift+A', 'API tester'), @('Ctrl+Shift+S', 'Secrets'),
        @('Ctrl+K', 'Command palette (in the picker)'), @('Ctrl+B', 'Toolbox: JSON, JWT, regex, cron, generators ...'),
        @('Ctrl+.', 'Smart actions for the selected clip'),
        @('Ctrl+,', 'Settings'), @('Esc', 'Hide the window'), @('Ctrl+Q', 'Exit'))
    foreach ($k in $keys) {
        $kl = New-Object System.Windows.Forms.Label
        $kl.AutoSize = $true; $kl.BackColor = $C.Card; $kl.ForeColor = $C.Accent; $kl.Text = $k[0]
        $kl.Font = New-Object System.Drawing.Font($UiFont, (Fz 9), [System.Drawing.FontStyle]::Bold)
        $kl.Margin = New-Object System.Windows.Forms.Padding(0, (Px 3), (Px 14), (Px 3))
        $dl = New-Object System.Windows.Forms.Label
        $dl.AutoSize = $true; $dl.BackColor = $C.Card; $dl.ForeColor = $C.Fore; $dl.Text = $k[1]; $dl.Font = $FontButton
        $dl.Margin = New-Object System.Windows.Forms.Padding(0, (Px 3), 0, (Px 3)); $dl.Anchor = 'Left'
        $card.Controls.Add($dl, 0, $card.RowCount); $card.Controls.Add($kl, 1, $card.RowCount); $card.RowCount++
    }

    $about = New-Object System.Windows.Forms.Label
    $about.AutoSize = $true; $about.ForeColor = $C.Dim; $about.BackColor = $C.Bg; $about.Font = $FontSmall
    $about.Text = "DevTools  $Dot  portable, everything stays in the data folder next to the script"
    $about.Margin = New-Object System.Windows.Forms.Padding((Px 4), (Px 12), 0, 0)
    $page.Controls.Add($about)

    $f.add_FormClosed({ $SetUI.Form = $null })
    Register-ThemedWindow $f
    Update-SettingsState
    $f.Show()
    [PowerClipHost]::EnsureShown($f.Handle)
    $f.Activate()
}

function Set-Paused([bool]$Paused) {
    $script:Paused = $Paused
    Save-Settings
    $icon = if ($Paused) { $IconPaused } else { $IconActive }
    $tray.Icon  = $icon
    $form.Icon  = $icon
    $tray.Text  = Get-TrayBaseText
    $btnPause.Glyph = if ($Paused) { $Glyph.Play } else { $Glyph.Pause }
    if (-not $IconFontName) { $btnPause.Text = if ($Paused) { 'Resume' } else { 'Pause' } }
    $tooltip.SetToolTip($btnPause, $(if ($Paused) { 'Resume capturing (paused now)' } else { 'Pause capturing' }))
    $script:IconTips[$btnPause] = if ($Paused) { 'Resume capturing (paused now)' } else { 'Pause capturing' }
    $btnPause.Variant = if ($Paused) { 1 } else { 2 }
    $btnPause.Invalidate()
    $miPause.Text  = if ($Paused) { 'Resume capturing' } else { 'Pause capturing' }
    $miPause.Checked = $Paused
    Update-Status
    Update-SettingsState
}

function Restart-App {
    $script:Restart = $true
    Exit-App
}

function Exit-App {
    Write-Log "exit (restart=$([bool]$script:Restart)): $((Get-PSCallStack | Select-Object -Skip 1 -First 3 | ForEach-Object { $_.Location }) -join ' <- ')"
    $script:Exiting = $true
    try { $clipHost.Release() } catch { }
    $tray.Visible = $false
    $tray.Dispose()
    $form.Close()
    [System.Windows.Forms.Application]::Exit()
}

