# ---------------------------------------------------------------------------
# Events
# ---------------------------------------------------------------------------
$list.add_DrawItem({
    param($src, $e)
    if ($e.Index -lt 0 -or $e.Index -ge $script:View.Count) { return }
    $item = $script:View[$e.Index]
    $r = $e.Bounds
    $g = $e.Graphics
    $selected = ($e.State -band [System.Windows.Forms.DrawItemState]::Selected) -ne 0
    $brush = New-Object System.Drawing.SolidBrush $C.Bg
    $g.FillRectangle($brush, $r)
    $brush.Dispose()

    # Each clip is a soft rounded card; selected and pinned ones are tinted.
    $card = New-Object System.Drawing.RectangleF(($r.X + (Px 8)), ($r.Y + (Px 2)), ($r.Width - (Px 16) - 1), ($r.Height - (Px 4)))
    $g.SmoothingMode = 'AntiAlias'
    $path = [PowerClipTheme]::Round($card, (Px 7))
    $fillColor = if ($selected) { $C.Sel } elseif ($item.Pinned) { $C.PinBg } else { $C.Bg }
    $brush = New-Object System.Drawing.SolidBrush $fillColor
    $g.FillPath($brush, $path); $brush.Dispose()
    if ($selected) {
        $pen = New-Object System.Drawing.Pen $C.SelLine
        $g.DrawPath($pen, $path); $pen.Dispose()
        $bar = New-Object System.Drawing.SolidBrush $C.Accent
        $g.FillRectangle($bar, ($card.X + (Px 1)), ($card.Y + (Px 9)), (Px 3), ($card.Height - (Px 18))); $bar.Dispose()
    }
    $path.Dispose()
    $g.SmoothingMode = 'Default'

    $x = [int]$card.X + (Px 12)
    $right = [int]$card.Right - (Px 10)
    if ($item.Pinned) {
        $pinRect = New-Object System.Drawing.Rectangle(($right - (Px 20)), ($r.Y + (Px 8)), (Px 20), (Px 20))
        if ($FontRowIcon) { [System.Windows.Forms.TextRenderer]::DrawText($g, $Glyph.Pin, $FontIconSmall, $pinRect, $C.Pin, $TextFlags) }
        else { [System.Windows.Forms.TextRenderer]::DrawText($g, $Star, $FontMain, $pinRect, $C.Pin, $TextFlags) }
        $right -= Px 24
    }

    if ($item.Kind -eq 'image') {
        $boxW = Px 110; $boxH = $r.Height - (Px 16)
        $thumb = Get-Thumb $item $boxW $boxH
        if ($thumb) {
            $tx = $x + [int](($boxW - $thumb.Width) / 2); $ty = $r.Y + (Px 8) + [int](($boxH - $thumb.Height) / 2)
            $g.DrawImage($thumb, $tx, $ty, $thumb.Width, $thumb.Height)
            $g.DrawRectangle($LinePen, $tx, $ty, $thumb.Width - 1, $thumb.Height - 1)
        }
        $x += $boxW + (Px 12)
        $title = "Image   $($item.Width) x $($item.Height)"
        $meta  = "$(Format-Age $item.Time)   $Dot   $(Format-Size $item.Bytes)"
        if ($item.Source) { $meta += "   $Dot   $($item.Source)" }
    } else {
        # Kind badge: a small rounded tile with an icon
        $tile = New-Object System.Drawing.RectangleF($x, ($r.Y + [int](($r.Height - (Px 34)) / 2)), (Px 34), (Px 34))
        $g.SmoothingMode = 'AntiAlias'
        $tp = [PowerClipTheme]::Round($tile, (Px 6))
        $tb = New-Object System.Drawing.SolidBrush $(if ($selected) { $C.Card } else { $C.Panel })
        $g.FillPath($tb, $tp); $tb.Dispose(); $tp.Dispose()
        $g.SmoothingMode = 'Default'
        $isFiles = $item.Kind -eq 'files'
        $tileRect = [System.Drawing.Rectangle]::Round($tile)
        if ($FontRowIcon) {
            $iconColor = if ($isFiles) { $C.Yellow } else { $C.Accent }
            [System.Windows.Forms.TextRenderer]::DrawText($g, $(if ($isFiles) { $Glyph.Document } else { $Glyph.Text }), $FontRowIcon, $tileRect, $iconColor,
                [System.Windows.Forms.TextFormatFlags]'HorizontalCenter, VerticalCenter, NoPrefix, SingleLine, NoPadding')
        } elseif ($isFiles) {
            Draw-FileGlyph $g ($x + (Px 5)) ($tileRect.Y + (Px 4)) (Px 24)
        }
        $x += Px 46
        if ($isFiles) {
            $paths = @($item.Text -split "`n")
            $names = @($paths | ForEach-Object { Split-Path -Leaf $_ })
            $title = if ($names.Count -le 3) { $names -join ', ' } else { "$($names[0..2] -join ', ') +$($names.Count - 3) more" }
            $what  = if ($paths.Count -eq 1) { '1 item' } else { "$($paths.Count) items" }
            $meta  = "$(Format-Age $item.Time)   $Dot   $what, $(Format-Size $item.Bytes)   $Dot   $(Split-Path -Parent $paths[0])"
        } else {
            $title = Get-Preview $item.Text
            # Counting lines of a big text is slow, so it's done once per text.
            $cached = $script:LineCache[$item.Id]
            if (-not $cached -or $cached[0] -ne $item.Text.Length) {
                $cached = @($item.Text.Length, (([regex]::Matches($item.Text, "`n")).Count + 1))
                $script:LineCache[$item.Id] = $cached
            }
            $lines = $cached[1]
            $meta  = "$(Format-Age $item.Time)   $Dot   $('{0:N0}' -f $item.Text.Length) chars"
            if ($lines -gt 1) { $meta += "   $Dot   $lines lines" }
            if ($item.Source) { $meta += "   $Dot   $($item.Source)" }
        }
    }

    # Smart badge (JSON, JWT, URL ...) on the right of text clips
    if ($item.Kind -eq 'text') {
        $smart = Get-SmartInfo $item
        if ($smart) {
            $bw = [System.Windows.Forms.TextRenderer]::MeasureText($smart.Badge, $FontSmall).Width + (Px 14)
            $bh = $FontSmall.Height + (Px 4)
            $by = $r.Y + [int](($r.Height - $bh) / 2)
            $g.SmoothingMode = 'AntiAlias'
            if ($smart.Color) {
                $sb = New-Object System.Drawing.SolidBrush $smart.Color
                $g.FillEllipse($sb, ($right - $bh), $by, $bh, $bh); $sb.Dispose()
                $right -= $bh + (Px 6)
            }
            $pill = [PowerClipTheme]::Round((New-Object System.Drawing.RectangleF(($right - $bw), $by, $bw, $bh)), ($bh / 2))
            $pb = New-Object System.Drawing.SolidBrush ([PowerClipTheme]::Mix($(if ($selected) { $C.Sel } else { $C.Bg }), $C.Accent, 0.16))
            $g.FillPath($pb, $pill); $pb.Dispose(); $pill.Dispose()
            $g.SmoothingMode = 'Default'
            [System.Windows.Forms.TextRenderer]::DrawText($g, $smart.Badge, $FontSmall, (New-Object System.Drawing.Rectangle(($right - $bw), $by, $bw, $bh)), $C.Accent,
                [System.Windows.Forms.TextFormatFlags]'HorizontalCenter, VerticalCenter, NoPrefix, SingleLine')
            $right -= $bw + (Px 8)
        }
    }
    $w = $right - $x
    $th = $FontMain.Height + (Px 3); $mh = $FontSmall.Height + (Px 2)
    $mid = $r.Y + [int](($r.Height - $th - $mh) / 2)
    $top = New-Object System.Drawing.Rectangle($x, $mid, $w, $th)
    [System.Windows.Forms.TextRenderer]::DrawText($g, $title, $FontMain, $top, $C.Fore, $TextFlags)
    $bottom = New-Object System.Drawing.Rectangle($x, ($mid + $th), $w, $mh)
    [System.Windows.Forms.TextRenderer]::DrawText($g, $meta, $FontSmall, $bottom, $C.Dim, $TextFlags)
})

$list.add_MeasureItem({
    param($src, $e)
    $e.ItemHeight = $script:RowH
    if ($e.Index -ge 0 -and $e.Index -lt $script:View.Count -and $script:View[$e.Index].Kind -eq 'image') { $e.ItemHeight = [Math]::Max((Px 86), $script:RowH) }
})

# Empty state: a friendly hint instead of a blank area (a ListBox does not raise Paint).
$emptyHint = New-Object System.Windows.Forms.Label
$emptyHint.Dock = 'Top'; $emptyHint.Height = Px 90; $emptyHint.TextAlign = 'MiddleCenter'
$emptyHint.BackColor = $C.Bg; $emptyHint.ForeColor = $C.Dim; $emptyHint.Visible = $false
$list.Controls.Add($emptyHint)
function Update-EmptyHint {
    $emptyHint.Text = if ($search.TextLength -gt 0) { 'No clips match your search' }
                      elseif ($script:Filter -ne 'All') { "No $($script:Filter.ToLower()) clips" }
                      else { 'Copy something - it will show up here' }
    $emptyHint.Visible = ($list.Items.Count -eq 0)
}

$list.add_SelectedIndexChanged({ Update-Status })
$list.add_DoubleClick({ Invoke-Clip $true })
$list.add_MouseDown({
    param($src, $e)
    if ($e.Button -eq 'Right') {
        $i = $list.IndexFromPoint($e.Location)
        if ($i -ge 0 -and -not $list.GetSelected($i)) { $list.ClearSelected(); $list.SelectedIndex = $i }
    }
})
# Typing while the list has focus goes to the search box.
$list.add_KeyPress({
    param($src, $e)
    if (-not [char]::IsControl($e.KeyChar)) {
        $search.Focus()
        $search.AppendText([string]$e.KeyChar)
        $e.Handled = $true
    }
})
$form.add_Resize({ $list.Invalidate() })

$search.add_TextChanged({ Update-List -SelectIndex 0 })

$form.add_KeyDown({
    param($src, $e)
    $k = $e.KeyCode
    $handled = $true
    if ($k -eq 'Escape') { Hide-Picker }
    elseif ($k -eq 'Return') { Invoke-Clip (-not $e.Shift) }
    elseif ($e.Control -and $k -eq 'P') { Switch-Pin }
    elseif ($e.Control -and $k -eq 'Q') { Exit-App }
    elseif ($e.Control -and $k -eq 'D') { Compare-Selected }
    elseif ($e.Control -and $e.Shift -and $k -eq 'N') { Open-NetworkFromPicker }
    elseif ($e.Control -and $e.Shift -and $k -eq 'A') { Open-ApiFromPicker }
    elseif ($e.Control -and $e.Shift -and $k -eq 'S') { Show-Vault }
    elseif ($e.Control -and $k -eq 'K') { Show-Palette }
    elseif ($e.Control -and $k -eq 'B') { Show-Toolbox }
    elseif ($e.Control -and $k -eq 'OemPeriod') { Show-SmartActions }
    elseif ($e.Control -and $k -eq 'N') { Hide-Picker; Show-Notes }
    elseif ($e.Control -and $e.Shift -and $k -eq 'F') { Show-FindInFiles }
    elseif ($e.Control -and $k -eq 'T') { Open-TransformFromPicker }
    elseif ($e.Control -and $k -eq 'Oemcomma') { Show-Settings }
    elseif ($e.Control -and $k -ge 'D1' -and $k -le 'D5') { Set-Filter (@($ChipButtons.Keys)[[int]$k - [int][System.Windows.Forms.Keys]::D1]) }
    elseif ($k -eq 'F2' -or ($e.Control -and $k -eq 'E')) { Edit-Selected }
    elseif ($k -eq 'Delete' -and (-not $search.Focused -or $search.TextLength -eq 0)) { Remove-Selected }
    elseif ($search.Focused -and ($k -eq 'Down' -or $k -eq 'Up' -or $k -eq 'PageDown' -or $k -eq 'PageUp')) {
        if ($list.Items.Count -gt 0) {
            $page = [Math]::Max(1, [int]($list.ClientSize.Height / $list.ItemHeight) - 1)
            $step = switch ($k.ToString()) { 'Down' { 1 } 'Up' { -1 } 'PageDown' { $page } 'PageUp' { -$page } }
            $next = [Math]::Max(0, [Math]::Min($list.Items.Count - 1, $list.SelectedIndex + $step))
            $list.ClearSelected()
            $list.SelectedIndex = $next
        }
    }
    else { $handled = $false }
    if ($handled) { $e.Handled = $true; $e.SuppressKeyPress = $true }
})

# Hide when the user clicks into another app. Deactivate can fire spuriously while
# the window is being shown, so confirm a moment later that another window has focus
# (including our own Compare and Notes windows).
$hideTimer = New-Object System.Windows.Forms.Timer
$hideTimer.Interval = 150
$hideTimer.add_Tick({
    $hideTimer.Stop()
    if ($form.Visible -and -not $script:Modal -and [PowerClipHost]::GetForegroundWindow() -ne $form.Handle) { Hide-Picker }
})
$form.add_Deactivate({ if (-not $script:Modal) { $hideTimer.Stop(); $hideTimer.Start() } })
$form.add_Activated({ $hideTimer.Stop() })
$form.add_FormClosing({
    param($src, $e)
    if (-not $script:Exiting) { $e.Cancel = $true; Hide-Picker }
})
Register-ThemedWindow $form

# ---------------------------------------------------------------------------
# Tray icon
# ---------------------------------------------------------------------------
$tray = New-Object System.Windows.Forms.NotifyIcon
$tray.Icon = $IconActive
$tray.Text = 'DevTools - Ctrl+Shift+V'
$trayMenu = New-Object System.Windows.Forms.ContextMenuStrip -Property @{ Renderer = $MenuRenderer }
$trayMenu.Renderer = $MenuRenderer
$miOpen = Add-MenuItem $trayMenu 'Open DevTools' { Show-Picker } $Glyph.Paste 'Ctrl+Shift+V'
$miOpen.Font = New-Object System.Drawing.Font($miOpen.Font, [System.Drawing.FontStyle]::Bold)
[void]$trayMenu.Items.Add('-')
[void](Add-MenuItem $trayMenu 'Notes' { Show-Notes } $Glyph.Notes)
[void](Add-MenuItem $trayMenu 'Compare text' { Show-Compare } $Glyph.Compare)
[void](Add-MenuItem $trayMenu 'Compare folders' { Show-FolderCompare } $Glyph.Folder)
[void](Add-MenuItem $trayMenu 'Find in files' { Show-FindInFiles } $Glyph.Search)
[void](Add-MenuItem $trayMenu 'Transform text' { [void](Show-Transform) } $Glyph.Code)
[void](Add-MenuItem $trayMenu 'Network tools' { [void](Show-Network) } $Glyph.Network)
[void](Add-MenuItem $trayMenu 'API tester' { Show-ApiTester } $Glyph.Globe)
[void](Add-MenuItem $trayMenu 'Secrets' { Show-Vault } $Glyph.Lock)
[void](Add-MenuItem $trayMenu 'Snippets' { Show-Snippets } $Glyph.Text)
[void](Add-MenuItem $trayMenu 'Toolbox' { Show-Toolbox } $Glyph.Toolbox)
[void](Add-MenuItem $trayMenu 'Take screenshot' { Start-ScreenCapture } $Glyph.Photo 'Ctrl+Shift+X')
[void](Add-MenuItem $trayMenu 'New reminder...' { New-QuickReminder } $Glyph.History)
[void](Add-MenuItem $trayMenu 'Git...' { Show-Git } $Glyph.Code)
$miMover = Add-MenuItem $trayMenu 'Keep me active (mouse mover)' { Switch-MouseMover } $Glyph.Apps
$trayMenu.add_Opening({ $miMover.Checked = [bool]$Mouse.Mover })
[void](Add-MenuItem $trayMenu 'Paste stack (collect, then paste in order)' { Start-PasteStack } $Glyph.Paste)
[void](Add-MenuItem $trayMenu 'Edit clipboard picture' { Edit-ClipboardImage } $Glyph.Photo)
[void](Add-MenuItem $trayMenu 'Command palette' { Show-Palette } $Glyph.Apps 'Ctrl+Shift+Space')
[void]$trayMenu.Items.Add('-')
$miPause = Add-MenuItem $trayMenu 'Pause capturing' { Set-Paused (-not $script:Paused) } $Glyph.Pause
[void](Add-MenuItem $trayMenu 'Settings...' { Show-Settings } $Glyph.Settings)
[void](Add-MenuItem $trayMenu 'Open data folder' { Start-Process explorer.exe $DataDir } $Glyph.Open)
[void]$trayMenu.Items.Add('-')
[void](Add-MenuItem $trayMenu 'Exit' { Exit-App } $Glyph.Power)
$tray.ContextMenuStrip = $trayMenu
$tray.add_MouseClick({ param($src, $e) if ($e.Button -eq 'Left') { Show-Picker } })
$tray.Visible = $true

# Reminders: clicking the notification opens the note.
$tray.add_BalloonTipClicked({
    if (-not $script:BalloonNoteId) { return }
    $id = $script:BalloonNoteId; $script:BalloonNoteId = $null
    $n = $script:Notes | Where-Object { $_.Id -eq $id } | Select-Object -First 1
    if ($n) { Show-Notes; Open-Note $n; Update-NoteList }
})
$ReminderTimer = New-Object System.Windows.Forms.Timer
$ReminderTimer.Interval = 15000
$ReminderTimer.add_Tick({ Invoke-Reminders })
$ReminderTimer.Start()
$ThemeWatch.Start()

# Debug builds only (POWERCLIP_DEBUG set at launch): run commands written to data\debug-cmd.ps1, so the UI
# can be tested without simulated keyboard / mouse input. Output goes to data\debug-out.txt.
if ($env:POWERCLIP_DEBUG) {
    $DebugCmdFile = Join-Path $DataDir 'debug-cmd.ps1'
    $DebugTimer = New-Object System.Windows.Forms.Timer
    $DebugTimer.Interval = 300
    $DebugTimer.add_Tick({
        if (-not (Test-Path $DebugCmdFile)) { return }
        $code = [IO.File]::ReadAllText($DebugCmdFile); Remove-Item -LiteralPath $DebugCmdFile -Force
        $out = try { (. ([scriptblock]::Create($code)) 2>&1 | Out-String) } catch { "ERROR: $_`n$($_.InvocationInfo.PositionMessage)" }
        [IO.File]::WriteAllText((Join-Path $DataDir 'debug-out.txt'), [string]$out)
    })
    $DebugTimer.Start()
}

# ---------------------------------------------------------------------------
# Hotkey + clipboard listener
# ---------------------------------------------------------------------------
$clipHost = New-Object PowerClipHost(
    ([PowerClipHost]::MOD_CONTROL -bor [PowerClipHost]::MOD_SHIFT),
    [uint32][System.Windows.Forms.Keys]::V)

Write-Log "start: hotkey registered=$($clipHost.HotkeyOk) hook=$($clipHost.UsingHook) listener=$($clipHost.ListenerOk)"

# More global shortcuts: 2 = command palette, 3 = paste as plain text.
$script:PaletteHotkeyOk = $clipHost.AddHotkey(2, ([PowerClipHost]::MOD_CONTROL -bor [PowerClipHost]::MOD_SHIFT), [uint32][System.Windows.Forms.Keys]::Space)
$script:PlainHotkeyOk = $clipHost.AddHotkey(3, ([PowerClipHost]::MOD_CONTROL -bor [PowerClipHost]::MOD_ALT), [uint32][System.Windows.Forms.Keys]::V)
$script:StackHotkeyOk = $clipHost.AddHotkey(5, ([PowerClipHost]::MOD_CONTROL -bor [PowerClipHost]::MOD_ALT), [uint32][System.Windows.Forms.Keys]::Space)
$script:ShotHotkeyOk = $clipHost.AddHotkey(4, ([PowerClipHost]::MOD_CONTROL -bor [PowerClipHost]::MOD_SHIFT), [uint32][System.Windows.Forms.Keys]::X)
Write-Log "extra hotkeys: palette=$($script:PaletteHotkeyOk) plain-paste=$($script:PlainHotkeyOk)"
Register-ToolHotkeys
$clipHost.add_ExtraHotkeyPressed({
    param($id)
    try {
        if ($id -eq 2) { Show-Palette -FromHotkey }
        elseif ($id -eq 3) { Invoke-PlainPaste }
        elseif ($id -eq 4) { Start-ScreenCapture }
        elseif ($id -eq 5) { Invoke-PasteNext }
        elseif ($id -eq 6) { Stop-MouseClicker 'Esc' }
        elseif ($script:ToolHotkeyIds.ContainsKey([int]$id)) { Invoke-ToolHotkey $script:ToolHotkeyIds[[int]$id] }
    } catch { Write-Log "hotkey $id error: $_" }
})
$clipHost.add_HotkeyPressed({
    try {
        Write-Log "hotkey (picker visible=$($form.Visible))"
        # The hotkey only ever opens the picker (or brings it back to the front); Esc closes it.
        if ($form.Visible) {
            $form.Activate()
            [void][PowerClipHost]::SetForegroundWindow($form.Handle)
            $search.Focus()
        } else { Show-Picker -FromHotkey }
    } catch { Write-Log "hotkey error: $_" }
})
$clipHost.add_ClipboardChanged({
    try {
        if ($script:Paused -or (Get-Date) -lt $script:IgnoreUntil) { return }
        $script:CaptureSource = Get-ClipSourceApp
        if ($script:CaptureSource -and ($script:IgnoreApps -contains $script:CaptureSource)) { Write-Log "ignored copy from $($script:CaptureSource)"; return }
        $clip = Read-Clipboard
        if (-not $clip) { return }
        switch ($clip.Kind) {
            'text'  { Add-ClipText $clip.Text }
            'files' { Add-ClipFiles $clip.Files }
            'image' { try { Add-ClipImage $clip.Image } finally { $clip.Image.Dispose() } }
        }
    } catch { Write-Log "clipboard error: $_" }
    finally { $script:CaptureSource = '' }
})

$search.add_HandleCreated({ [PowerClipHost]::SetCueBanner($search.Handle, 'Search...   Enter paste  |  Ctrl+P pin  |  F2 edit  |  Del delete') })
[void]$form.Handle   # create the window now so the first hotkey press is instant
Set-Paused $script:Paused

if (-not $clipHost.HotkeyOk -and -not $clipHost.UsingHook) {
    $tray.ShowBalloonTip(5000, 'DevTools',
        'Ctrl+Shift+V is already taken by another program. Click the tray icon to open DevTools.', 'Warning')
} elseif ($FirstRun) {
    $tray.ShowBalloonTip(4000, 'DevTools is running', 'Copy as usual. Press Ctrl+Shift+V to open your clipboard history.', 'Info')
}

# Log stray UI errors instead of showing the WinForms crash dialog.
[System.Windows.Forms.Application]::add_ThreadException({
    param($src, $e)
    $where = if ($e.Exception.ErrorRecord) { $e.Exception.ErrorRecord.InvocationInfo.PositionMessage } else { $e.Exception.StackTrace }
    Write-Log "ui error: $($e.Exception.Message)`r`n$where"
})

try {
    [System.Windows.Forms.Application]::Run()
} finally {
    try { $clipHost.Release() } catch { }
    $tray.Dispose()
    $mutex.ReleaseMutex()
    $mutex.Dispose()
    if ($script:Restart) {
        Start-Process -FilePath (Get-Process -Id $PID).Path -WindowStyle Hidden -ArgumentList @(
            '-NoProfile', '-STA', '-ExecutionPolicy', 'Bypass', '-WindowStyle', 'Hidden', '-File', "`"$PSCommandPath`"")
    }
}
